const long long p = 998244353;
long long fac[1000000] = {};
long long invfac[1000000] = {};

long long power(long long a, int n) {
    long long l;
    if (a == 1 || n == 0) {
        return 1;
    } else if (n == 1) {
        return a % p;
    } else if (n % 2 == 0) {
        l = power(a, n/2) % p;
        return l * l % p;
    } else {
        l = power(a, n/2) % p;
        return l * l % p * a % p;
    }
}

void makefac(int N) {
    int i;
    fac[0] = fac[1] = 1;
    invfac[0] = invfac[1] = 1;
    for (i = 2; i <= N; i++) {
        fac[i] = fac[i-1] * i % p;
        invfac[i] = power(fac[i], p-2);
    }
}

long long nCr(long long n, long long r) {
    return fac[n] * invfac[r] % p * invfac[n-r] % p;
}

int main() {

    int N, A, B;
    long long K;
    cin >> N >> A >> B >> K;

    makefac(N);

    long long r, b, ans = 0;
    for (r = 0; r <= N; r++) {
        if ((K - r * A) % B != 0) continue;
        b = (K - r * A) / B;
        if (b < 0 || N < b) continue;
        ans = (nCr(N, r) * nCr(N, b) % p + ans) % p;
    }

    cout << ans << endl;

}

