// Math
func gcd(ll a, ll b) { return b ? gcd(b, a % b) : a; }
func lcm(ll a, ll b) { return a * b / gcd(a, b); }

def mod_pow(ll a, ll b) {
    if (b == 0) return 1LL;
    if (b & 1) return (a * mod_pow(a, b - 1)) % MOD;
    ll half = mod_pow(a, b / 2);
    return half * half % MOD;
}

def mod_comb(ll n, ll r) {
    r = min(r, n - r);
    ll sup = 1, sub = 1;
    rep(i, r) {
        sup *= n - i, sub *= i + 1;
        sup %= MOD, sub %= MOD;
    }
    return sup * mod_pow(sub, MOD - 2) % MOD;
}

signed main() {
    ll N, A, B, K, S = 0;
    cin >> N >> A >> B >> K;
    for(ll a = max(0LL, (K - N * B) / A); a * A <= K && a <= N; a++) {
        if((K - a * A) % B == 0) {
            ll b = (K - a * A) / B;
            if(b > N) continue;
            S += mod_comb(N, a) * mod_comb(N, b);
            S %= MOD;
        }
    }
    cout << S << endl;
}

