inline int fpow(int v, int w)
{
    int r = 1;
    while (w > 0)
    {
        if (w & 1)
            r = ((ll)r * v) % mod;
        w >>= 1; v = ((ll)v * v) % mod;
    }
    return r;
}

inline int binom(int n, int k)
{
    int m = ((ll)sil[k] * sil[n - k]) % mod;
    return ((ll)sil[n] * fpow(m, mod - 2)) % mod;
}

