ll pwr(ll a, ll b) {
    ll ans = 1;
    for (; b; b >>= 1, a = a * a % B)
        if (b & 1) ans = ans * a % B;
    return ans;
}

ll f[N], rf[N];

ll c(ll n, ll k) {
    return f[n] * rf[n - k] % B * rf[k] % B;
}

ll gcd(ll &ka, ll a, ll &kb, ll b) {
    if (!b) {
        ka = 1, kb = 0;
        return a;
    }
    ll g = gcd(kb, b, ka, a % b);
    kb -= ka * (a / b);
    assert(ka * a + kb * b == g);
    return g;
}

