// xのp乗を求める。計算量はO(logp)
ll modpow(ll x, ll p) {
    if(p == 0) {
        return 1;
    }
    // pが偶数の時
    if(p%2 == 0) {
        ll halfP = p/2;
        ll half = modpow(x, halfP);
        // x^(p/2)をhalfとしてhalf*halfを計算
        return half * half % mod;
    }
    else {
        // pが奇数の時はpを偶数にするために1減らす
        return x * modpow(x, p-1) % mod;
    }
}

ll Comb(ll x, ll y) {
    if(y > x-y) {
        return Comb(x, x-y);
    }
    ll resMul = 1, resDiv = 1;
    rep(i, y) {
        resMul *= (x-i);
        resDiv *= (i+1);
        resMul %= mod;
        resDiv %= mod;
    }
    // resMul/resDivをresDivの逆元を使って求める
    ll res = resMul * modpow(resDiv, mod-2) % mod;
    return res; 
}

int main() {
