  if ((k % g) != 0) {
    cout << 0 << endl;
    return 0;
  }
  __int128 mul = k / g;
  x *= mul;
  y *= mul;
  __int128 p = x/b;
  x -= p*b;
  y += p*a;
  Mod res = 0;
  while (x <= n && y >= 0) {
