using namespace std;

struct Mod {
    static const int P = 998244353;
    long long k;

    Mod() = default;
    Mod(const long long k) : k(k%P) {}
};

Mod operator+(const Mod a, const Mod b) {
    return a.k + b.k;
}

Mod operator+=(Mod& a, const Mod b) {
    return a = a + b;
}

Mod operator*(const Mod a, const Mod b) {
    return a.k * b.k;
}

Mod operator*=(Mod& a, const Mod b) {
    return a = a * b;
}

Mod power(const Mod a, const int k) {
    if (k == 0) {
        return 1;
    } else if (k % 2 == 0) {
        return power(a*a, k/2);
    } else {
        return a * power(a*a, k/2);
    }
}

Mod inverse(const Mod a) {
    return power(a, Mod::P-2);
}

int main() {
    int N, A, B; long long K;
    cin >> N >> A >> B >> K;

    auto factorials = vector<Mod>(N+1);
    factorials[0] = 1;
    for (int i = 1; i <= N; i++) {
        factorials[i] = factorials[i-1] * i;
    }

    auto inverse_factorials = vector<Mod>(N+1);
    inverse_factorials[N] = inverse(factorials[N]);
    for (int i = N; i >= 1; i--) {
        inverse_factorials[i-1] = i * inverse_factorials[i];
    }

    auto binomial = [&](const int n, const int k) {
        return factorials[n] * inverse_factorials[k] * inverse_factorials[n-k];
    };

    Mod result = 0;
    for (int x = 0; x <= N; x++) {
        const long long L = K - x * A;
        if (L % B != 0) {
            continue;
        }
        const long long y = L / B;

        if (0 <= y && y <= N) {
            result += binomial(N, x) * binomial(N, int(y));
        }
    }

    cout << result.k << endl;
}

