    return y-=(a/b)*x,t;
}
lld inv(lld a){
    lld x,y;
    exgcd(a,P,x,y);
    return (x%P+P)%P;
}
lld binom(lld a,lld b){
    if(a<b)return 0;
    //printf("binom(%lld,%lld):%lld\n",a,b,1ll*fac[a]*fnv[b]%P*fnv[a-b]%P);
    return 1ll*fac[a]*fnv[b]%P*fnv[a-b]%P;
}

int main(){
    scanf("%lld%lld%lld%lld",&n,&a,&b,&k);
    lld g=gcd(a,b);
    if(k%g)return puts("0"),0;
    if(!k)return puts("1"),0;

    fac[0]=1;
    FOR(i,1,n)fac[i]=1ll*fac[i-1]*i%P;
    fnv[n]=inv(fac[n]);
    ROF(i,n,1)fnv[i-1]=1ll*fnv[i]*i%P;

    a/=g,b/=g,k/=g;
    lld x0,y0,ans=0;
    exgcd(a,b,x0,y0);
    //printf("a:%lld,b:%lld\n",a,b);
    x0*=k,y0*=k;
    //printf("x0:%lld,y0:%lld\n",x0,y0);
    lld lt=ceil(-1.0*x0/b),rt=floor(1.0*y0/a);
    //printf("l:%lld,r:%lld\n",lt,rt);
    FOR(t,lt,rt){
        lld x=x0+b*t;
        lld y=y0-a*t;
        //printf("x:%lld,y:%lld\n",x,y);
        ans=(ans+1ll*binom(n,x)*binom(n,y)%P)%P;
    }
    printf("%lld\n",ans);
    return 0;
}

