constexpr int mod = 998244353;

LL pow_(LL x, signed LL n) {
    LL ans = 1;
    while(n) {
        if(n & 1) ans = ans * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return ans;
}
