LL *fact, *fact_inv;
void meguru_init_fact(LL N) {
    fact = new LL[N+1];
    fact_inv = new LL[N+1];
    fact[0] = 1;
    upto(1, N, i) fact[i] = fact[i-1] * i % mod;
    fact_inv[N] = pow(fact[N], mod - 2);
    downto(N, 1, i) fact_inv[i-1] = fact_inv[i] * i % mod;
}

inline LL nCk(LL n, LL k) { return fact[n] * fact_inv[k] % mod * fact_inv[n-k] % mod; }
inline LL nPk(LL n, LL k) { return fact[n] * fact_inv[n-k] % mod; }

