            mp[pair<ll,ll>(i,(k-a*i)/b)]++;
        }
    }
    ll res = 0;
    for(auto x:mp){
        ll tmp = 1;
        tmp *= com.com(n,x.first.first);
        tmp *= com.com(n,x.first.second);
        tmp %= MOD;
        res += tmp;
        res %= MOD;
    }
    cout << res << endl;
    return 0;
}

