const int MOD = 998244353;

ll gcd(ll a, ll b, ll &x, ll &y) {
	if (a == 0) {
		x = 0;
		y = 1;
		return b;
	}
	ll x1, y1;
	ll g = gcd(b % a, a, x1, y1);
	x = y1 - (b / a) * x1;
	y = x1;
	return g;
}

vector<ll> f;

ll poww(ll a, int b) {
	if (b == 0) return 1;
	if (b & 1) return (a * poww(a, b - 1)) % MOD;
	ll tmp = poww(a, b >> 1);
	return (tmp * tmp) % MOD;
}

ll c(int n, int k) {
	return (f[n] * poww((f[n - k] * f[k]) % MOD, MOD - 2)) % MOD;
}

int main() {
	ios::sync_with_stdio(false);
	ll n, a, b, k;
	cin >> n >> a >> b >> k;
	f.resize(n + 1);
	f[0] = 1;
	for (ll i = 1; i <= n; ++i) {
		f[i] = (f[i - 1] * i) % MOD;
	}
	ll x, y;
	ll g = gcd(a, b, x, y);
	if (k % g) {
		cout << 0 << endl;
		return 0;
	}
	x *= k / g;
	y *= k / g;
	ll addx = b / g;
	ll addy = a / g;
	// 0 <= x, y <= n
	// x += b / g; y -= a / g;
	if (x < 0) {
		ll mult = (-x + addx - 1) / addx;
		x += addx * mult;
		y -= addy * mult;
	}
	else {
		ll mult = x / addx;
		x -= addx * mult;
		y += addy * mult;
	}
	if (y < 0) {
		ll mult = (-y + addy - 1) / addy;
		y += addy * mult;
		x -= addx * mult;
	}
	else if (y > n) {
		ll mult = (y - n + addy - 1) / addy;
		y -= addy * mult;
		x += addx * mult;
	}
	ll ans = 0;
	while (x >= 0 && x <= n && y >= 0 && y <= n) {
		ans = (ans + (c(n, x) * c(n, y)) % MOD) % MOD;
		x += addx;
		y -= addy;
	}
	cout << ans << endl;
}

