#define MOD 998244353
long long mi(long long a, long long m) {
    long long m0 = m;
    long long y = 0, x = 1;
    if (m == 1) {
        return 0;
    }
    while (a > 1) {
        long long q = a / m;
        long long t = m;

        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0) {
        x += m0;
    }
    return x;
}
long long ncr(long long n, long long r, vector<long long>& fact) {
    return ((fact[n] * mi(fact[r], MOD) % MOD) * mi(fact[n - r], MOD)) % MOD;
}
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long a, b, n, k;
    cin >> n >> a >> b >> k;
    vector<long long> fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        if (k < i * a || (k - i * a) % b != 0) {
            continue;
        }
        long long red = i, blue = (k - i * a) / b;
        ans += ncr(n, red, fact) * ncr(n, blue, fact) % MOD;
    }
    cout << ans << endl;
}

