    ll n, a, b, k;
    cin >> n >> a >> b >> k;

    // a * i + b * j = k とすると，i を固定したときに，j = (k - a*i) / b
    // もちろん，割り切れる必要がある
    // ここで，r, g, b について，次のことが言える
    // r + g = i, b + g = j 
    // となると，r, g, b について，nCr x nCb で答えを導出できる

    ll ans = 0;
    rep(i, 0, n+1){
        if((k - a*i) % b != 0) continue;
        ll j = (k - a*i) / b;
        ans += (mod_nck(n, i) * mod_nck(n, j)) % mod;
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

