void init()
{
    fac[0] = 1;
    for(int i = 1; i < MAXN; i++)
        fac[i] = fac[i-1] * i % mod;
    inv[MAXN-1] = power(fac[MAXN-1], mod-2);
    for(int i = MAXN-2; i >= 0; i--)
        inv[i] = inv[i+1] * (i+1) % mod;
}
long long combinator(long long n,long long m)
{
    if(n < m)
        return 0;
    return fac[n]*inv[m]%mod*inv[n-m]%mod;
}
