	return x%mod;
}


ll pot(ll z, ll u) {
	if(u == 0) return 1;
	if(u == 1) return z;
	if(u%2 == 0) {
		ll x = pot(z, u/2);
		return mul(x, x);
	}
	return mul(pot(z, u - 1), z);
}

ll dvd(ll z, ll u) {
	u = pot(u, mod - 2);
	z *= u;
	return z%mod;
}

ll pov(ll z) {
	return dvd(fakt[n], mul(fakt[z], fakt[n - z]))%mod;
}

