    if(y < 0 || n < y) continue;
    //cout << "x == "  << x << " y =  " << y << endl;
    //cout << "xa+by = " << x*a + b*y << endl;
    ans += comb(n,x) * comb(n,y) % mod;
  }

  cout << ans << endl;

  return 0;
}

