    if(A<B) swap(A,B);

    ll maxi=K/A;

    ll ans=0ll;

    for (ll i = maxi; i >= 0; --i) {
        if((K-A*i)/B+i>K) break;
        if((K-A*i)%B!=0) continue;
        ll j = (K-A*i)/B;
        //cout<<i<<" "<<j<<endl;
        (ans+=(COM(N,i)*COM(N,j))%MOD)%=MOD;
        //cout<<ans<<endl;
    }
    cout<<ans<<endl;
}

