class combination_mod
{
private:
	std::vector<long long>factorial_mod;
	long long divisor;
public:
	combination_mod(long long div, long long sup_n) :divisor(div), factorial_mod(std::vector<long long>(sup_n + 1))
	{
		factorial_mod[0] = 1;
		for (long long i = 1; i <= sup_n; i++)
		{
			factorial_mod[i] = factorial_mod[i - 1] * i % divisor;
		}
	}
	long long operator()(long long n, long long r)
	{
		long long numerator = factorial_mod[n];
		long long denominator = factorial_mod[r] * factorial_mod[n - r] % divisor;
		long long index = divisor - 2, power = 1;
		while (index > 0)
		{
			if (index & 1 == 1)
			{
				power *= denominator;
				power %= divisor;
			}
			denominator *= denominator;
			denominator %= divisor;
			index >>= 1;
		}
		return numerator * power % divisor;
	}
};
int main()
{
	const long long divisor = 998244353;
	const long long sup_n = 300000;
	combination_mod cm(divisor, sup_n);
	long long n, a, b, k;
	std::cin >> n >> a >> b >> k;
	std::vector<std::pair<long, long>>pairs;
	pairs.reserve(n);
	for (long long x = 0; x <= n; x++)
	{
		if ((k - a * x) % b == 0)
		{
			long long y = (k - a * x) / b;
			if (0 <= y && y <= n)
			{
				pairs.push_back(std::make_pair(x, y));
			}
		}
	}
	long long ans = 0;
	for (auto i : pairs)
	{
		ans += cm(n, i.first) * cm(n, i.second) % divisor;
		ans %= divisor;
	}
	std::cout << ans << std::endl;
	return 0;
}

