typedef long long ll;

const ll MOD = 998244353;

ll bpow(ll a, ll n)
{
    if(n == 0)
        return 1;

    if(n % 2 == 0) {
        ll cur = bpow(a, n / 2);
        return (cur * cur) % MOD;
    }

    return (a * bpow(a, n - 1)) % MOD;
}

void calc(ll N, vector<ll>& fact, vector<ll>& inv)
{
    fact.resize(N + 1);
    inv.resize(N + 1);

    fact[0] = inv[0] = 1;

    ll cur = 1;
    for(ll p = 1; p <= N; p++) {
        cur = (cur * p) % MOD;
        fact[p] = cur;
        inv[p] = bpow(cur, MOD - 2);
    }
}

ll comb(ll n, ll k, const vector<ll>& fact, const vector<ll>& inv)
{
    if(k > n)
        return 0;

    return (fact[n] * ((inv[k] * inv[n - k]) % MOD)) % MOD;
}

int main()
{
    ll N, A, B, K;
    cin >> N >> A >> B >> K;

    vector<ll> fact;
    vector<ll> inv;

    calc(N, fact, inv);

    ll out = 0;

    for(ll a = 0; a <= N; a++) {
        ll t = (K - a * A);
        if(t < 0 || t % B)
            continue;
        ll b = t / B;
        ll cur = (comb(N, a, fact, inv) * comb(N, b, fact, inv)) % MOD;
        out = (out + cur) % MOD;
    }

    cout << out << endl;

    return 0;
}

