}

ll combi(ll n, ll g, ll r, ll b) {
    return fact(n) / (fact(g) * fact(r) * fact(b) * fact(n-g-r-b));
}

ll gcd(ll p, ll q) {
    if ((p == 0) || (q == 0)) {
        return 0;
    }

    while (p != q) {
        if (p > q) {
            p = p - q;
        } else {
            q = q - p;
        }
    }
    return p;
}

int main() {
    int n, a, b;
    ll k;
    scanf("%d %d %d %lld", &n, &a, &b, &k);

    // a <= b
    a = min(a, b);
    b = max(a, b);

    ll r = k % b;
    ll p, q;    // a*p + b*q = k
    for (ll i = 0; i <= k / b; i++) {
        if (r % a == 0) {
            p = r / a;
            q = (k - r) / b;
            break;
        }
        r += b;
    }

    ll ans = 0;
    while (min(p, q) >= 0 && max(p, q) <= n) {
        ll green = min(p, q);
        ll red = p - green;
        ll blue = q - green;

        while (green >= 0 && green + red + blue <= n) {
            ans += (combi(n, green, red, blue) % DIVISOR);
            red++;
            blue++;
            green--;
        }
        ll g = gcd(p, q);
        if (g == 0) { break; }
        ll tp = p, tq = q;
        p = tp + tq / g;
        q = tq - tp / g;
    }

    ans = ans % DIVISOR;
    printf("%lld\n", ans);
    return 0;
}

