const long long MOD = 998244353;
long long exGCD(long long a, long long b, long long& x, long long& y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	long long g = exGCD(b, a % b, x, y);
	long long temp = x;
	x = y;
	y = temp - a / b * y;
	return g;
}
int inverse(long long a, long long m) {
	long long x, y;
	exGCD(a, m, x, y);
	return (x % m + m) % m;
}
long long C(long long n, long long m, long long p) {
	long long ans = 1;
	for (int i = 1; i <= m; ++i) {
		ans = ans * (n - m + i) % p;
		ans = ans * inverse(i, p) % p;
	}
	return ans;
}
int main() {
	long long n, a, b, k;
	scanf("%lld%lld%lld%lld", &n, &a, &b, &k);
	long long ans = 0;
	for (int i = 0; i <= n && i * a <= k; ++i) {
		if ((k - i * a) % b == 0 && (k - i * a) / b <= n) {
			ans = (ans + C(n, i, MOD) * C(n, (k - i * a) / b, MOD) % MOD) % MOD;
		}
	}
	printf("%lld\n", ans);
	return 0;
}

