	if (p == 0) return 1;
	if (p % 2 == 0) {
		//pが偶数の時
		SINT64 halfP = p / 2;
		SINT64 half = modpow(a, halfP);
		//a^(p/2) をhalfとして、half*halfを計算
		return half * half % MOD;
	} else {
		//pが奇数の時は、偶数にするために1減らす
		return a * modpow(a, p - 1) % MOD;
	}
}

SINT64 calcComb(SINT64 a, SINT64 b, SINT64 c) {
	SINT64 ans = data[N-1];
	if (a != 0) {
	ans = ans * data2[a-1] % MOD;
	}
	if (b != 0) {
	ans = ans * data2[b-1] % MOD;
	}
	if (c != 0) {
	ans = ans * data2[c-1] % MOD;
	}
	SINT64 buf = N - a - b - c;
	if (buf > 0) {
	ans = ans * data2[buf-1] % MOD;
	} else if (buf == 0){
	} else {
		ans = 0;
	}
	return ans;
}

