    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

const int MAX = 510000;
// const int MOD = 1000000007;
const ll MOD=998244353ll;

ll fac[MAX], finv[MAX], inv[MAX];

void COMinit(int n) {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i <= n; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll COM(int n, int k){
    // if (n < k) return 0;
    // if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
  	ios::sync_with_stdio(false);
	cin.tie(0);
	int n, a, b;
	ll k;
	cin>>n>>a>>b>>k;
    COMinit(n);
  	ll ans=0;
	for(int i=0; i<=n; ++i){
		if((k-i*a)%b==0){
			int j=(k-i*a)/b;
			if(j>=0 && j<=n){
				ans=(ans+COM(n, i)*COM(n, j)%MOD)%MOD;
			}
		}
	}
	cout<<ans<<'\n';
}

