const int MOD = 998244353;

long long int gcd(long long int a, long long int b){
    if (a % b == 0) return b;
    else return gcd(b, a % b);
}

long long int exp_mod(long long a, long long b, long long int m) {
	long long int res = 1;
	while (b > 0) {
		if (b&1)
			res = (res * a)%m;
		a = (a * a)%m;
		b >>= 1;
	}
	return (long long int)res;
}

long long int fact_mod(long long int n, long long int m) {
	long long int res = 1;
	for (long long int i=n; i>0; --i)
		res = (res * i)%m;
	return (long long int)res;
}

long long int combination(long long int n, long long int r) {
	long long int res = 1;
	for (long long int i=0; i<r; ++i)
		res = (res * (n - i) )%MOD;
	return ( res * exp_mod(fact_mod(r, MOD), MOD-2, MOD) ) % MOD;
}

int main(void){

    long long int n, a, b, k;
    cin >> n >> a >> b >> k;

    // ax + by = k なる (x, y) \in \mathbb N で、x が最小のものを見つける
    // 解がなければ 0
    long long int d = gcd(a, b);
    if(k % d != 0){
        cout << 0 << "\n";
        return 0;
    }
    a /= d; b /= d; k /= d;

    long long int x = 0, y;
    while(1){
        if((k - a*x) % b == 0 && (k - a*x) / b <= n) break;
        x ++;
    }


    // 全整数解について nCx * nCy を計算して和を取る
    long long int sum = 0;
    for(x; x <= n; x += b){
        y = (k - a*x) / b;
        if(y < 0) break;
        (sum += (combination(n, x) * combination(n, y)) % MOD) %= MOD;
    }

    cout << sum << "\n";
}

