class FermatCombination {
 public:
  vector<ll> factrial;
  vector<ll> inverse;
  ll MOD;

  FermatCombination(int size, ll mod) {
    this->factrial = vector<ll>(size + 1);
    this->inverse = vector<ll>(size + 1);
    this->MOD = mod;

    this->factrial[0] = 1;
    this->inverse[0] = 1;

    for (int i = 1; i <= size; i++) {
      factrial[i] = (factrial[i - 1] * i) % MOD;
      inverse[i] = pow(factrial[i], (int)MOD - 2) % MOD;
    }
  }

  ll combine(int n, int k) {
    return factrial[n] * inverse[k] % MOD * inverse[n - k] % MOD;
  }

  ll pow(ll x, int n) {
    ll ans = 1;
    while (n > 0) {
      if ((n & 1) == 1) {
        ans = ans * x % MOD;
      }
      x = x * x % MOD;
      n >>= 1;
    }
    return ans;
  }
};

int main() {
  ll n, a[2], k;
  cin >> n >> a[0] >> a[1] >> k;
  sort(a, a + 2);

  auto c = new FermatCombination(n, mod);

  ll r = 0;
  for (ll i = 0; i <= n && i * a[1] <= k; i++) {
    ll j = (k - i * a[1]) / a[0];
    if (j <= n && i * a[1] + j * a[0] == k) {
      r = (r + c->combine(n, i) * c->combine(n, j)) % mod;
    }
  }
  cout << r << endl;
  return 0;
}

