	long long ans = 1;
	for(int i = 63; i >= 0; i --) {
		ans *= ans;
		ans %= MOD;
		if((b >> i) & 1)
			ans *= a;
		ans %= MOD;
	}
	return ans;
}

int rev(int a)
{
	return pw(a, MOD - 2);
}

int choose(int nn, int kk)
{
	return fact[nn] * rev(fact[kk]) % MOD * rev(fact[nn - kk]) % MOD;
}

