    int ret = 1;

    for (; b > 0; b >>= 1) {
        if (b & 1) {
            ret = (ret * 1ll * a) % mod;
        }

        a = (a * 1ll * a) % mod;
    }

    return ret;
}

void addMod(int &a, int b, int m = mod) {
    a += b;

    if (m <= a) {
        a -= m;
    }
}

void pre() {
    fact[0] = 1;

    for (int i = 1; i <= 300000; ++i) {
        fact[i] = (fact[i - 1] * 1ll * i) % mod;
    }

    for (int i = 0; i <= 300000; ++i) {
        rev[i] = binPow(fact[i], mod - 2);
    }
}

