    return fact[n] * 1ll * rev[k] % mod * rev[n - k] % mod;    
}

int calc(int x, int y) {
    int ret = 0;

    for (int z = max(0, x + y - n); z <= x && z <= y; ++z) {
        int cx = x - z, cy = y - z;
        int cur = C(n, z);

        cur = (cur * 1ll * C(n - z, cx)) % mod;
        cur = (cur * 1ll * C(n - z - cx, cy)) % mod;

        addMod(ret, cur);        
    }

    return ret;
}

