ll mpow(ll x, ll n){
  ll ans = 1;
  while(n != 0){
    if(n&1) ans = ans*x % M;
    x = x*x % M;
    n = n >> 1;
    }
  return ans;
}

ll comb(ll a, ll b){
  if( a == 0 && b == 0) return 1;
  if( a < b || a <  0) return 0;
  ll tmp = ifac[a-b]* ifac[b] % M;
  return tmp*fac[a]%M;
}

