	ll g = gcd(a, b);
	if (k % g != 0) {
		put(0);
		return 0;
	}
	a /= g, b /= g, k /= g;
	P p = extend_euclid(a, b, k);
	if (p.first < 0) {
		ll t = (abs(p.first) + b - 1) / b;
		p.first += t * b;
		p.second -= t * a;
		for (ll i = p.first, j = p.second; j >= 0&&i<=n ; i += b, j -= a) {
			res += comb<mi>(n, i) * comb<mi>(n, j);
		}
	} else if (p.second < 0) {
		ll t = (abs(p.second) + a - 1) / a;
		p.second += t * a;
		p.first -= t * b;
		for (ll i = p.first, j = p.second; i >= 0&&j<=n ; i -= b, j += a) {
			res += comb<mi>(n, i) * comb<mi>(n, j);
		}
	} else {
		ll t = (p.first) / b;
		p.first -= t * b;
		p.second += t * a;
		for (ll i = p.first, j = p.second; j >= 0 && i <= n; i += b, j -= a) {
			res += comb<mi>(n, i) * comb<mi>(n, j);
		}
	}
	put(res);
	return 0;
