const int C = 300500;
int fact[C], revfact[C];
int getC(int n, int k) {
    return fact[n] * revfact[k] % mod * revfact[n - k] % mod;
}

void solve(__attribute__((unused)) bool read) {
    fact[0] = 1;
    for (int i = 1; i < C; ++i) {
        fact[i] = fact[i - 1] * i % mod;
    }
    revfact[C - 1] = binpow(fact[C - 1], mod - 2, mod);
    for (int i = C - 2; i >= 0; --i) {
        revfact[i] = revfact[i + 1] * (i + 1) % mod;
    }
    int res = 0;
    int n, A, B, K;
    cin >> n >> A >> B >> K;
    for (int x = 0; x <= n; ++x) {
        int rest = K - A * x;
        if (rest < 0 || rest % B) {
            continue;
        }
        int y = rest / B;
        if (y < 0 || y > n) {
            continue;
        }
        res += getC(n, x) * getC(n, y);
        res %= mod;
    }
    cout << res << "\n";

}

