const int MAXN = 3e5+5;
ll fakt[MAXN], inv[MAXN];

ll pk (ll x, int k) {
	if (k==0) return 1ll;
	if (k==1) return x;
	ll ret = pk(x,k/2);
	ret = (ret * ret)%mod;
	if (k&1) ret = (ret * x)%mod;
	return ret;
}

void precomp() {
	fakt[0] = fakt[1] = inv[0] = inv[1] = 1ll;
	for (int i=2; i<MAXN; i++) {
		fakt[i] = (fakt[i-1] * (ll)i)%mod;
		inv[i] = pk(fakt[i],mod-2);
	}
}

ll kombin (int v, int k) {
	ll ret = (fakt[v] * inv[v-k])%mod;
	ret = (ret * inv[k])%mod;
	return ret;
}

int n;
ll va, vb, vk;

ll solve () {
	ll ret = 0ll;
	for (int i=0; i<=n; i++) {
		ll need = vk - (va * (ll)i);
		if (need%vb) continue;
		need /= vb;
		if (need>n) continue;
		// printf ("masuk\n");
		// printf ("%d %d %d %d\n", n, i, n, (int)need);
		ret += (kombin(n,i) * kombin(n,(int)need))%mod;
		ret %= mod;
	}
	return ret;
}

