const int MOD = 998244353;

int mod_exp(int N)
{
	int res = 1;
	int exp = MOD-2;
	while (exp > 0) {
		if ((exp & 1LL) == 1LL) {
			res *= N;
			res %= MOD;
		}
		N *= N;
		N %= MOD;
		exp >>= 1LL;
	}
	return res;
}

int binom(int N, int K)
{
	int numerator = 1;
	for (int i = N; i > N-K; --i) {
		numerator *= i;
		numerator %= MOD;
	}
	int denominator = 1;
	for (int i = 1; i <= K; ++i) {
		denominator *= i;
		denominator %= MOD;
	}
	//cout << numerator << " " << denominator << " " << mod_exp(denominator) << endl;
	return (numerator * mod_exp(denominator)) % MOD;
}

