            if (N >= y) {
                ll tmp = com.nCk(N, x);
                tmp *= com.nCk(N, y);
                tmp %= MOD;
                ans += tmp;
                ans %= MOD;
            }


        }
    }

    cout << ans << endl;

    return 0;
}

