  for (int64_t i = 0; i <= n && i*a <= k; i++) {
    int64_t r = (k - i*a) % b;
    int64_t j = (k - i*a) / b;
    if (r == 0 && j <= n) {
      count = (count + com[i] * com[j] % M) % M;
    }
  }
  cout << count << endl;

  return 0;
}

