ll Pow(ll a,ll b){
    ll res = 1;
    while(b){
        if(b % 2) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

vector<ll> Reciprocal(){
    ll inv = Pow(fact[N], MOD - 2);
    vector<ll> v(N + 1, 1);
    v[N] = inv;
    for(ll i = N; i > 1; --i){
        inv *= i;
        inv %= MOD;
        v[i - 1] = inv;
    }
    return v;
}

ll nCr(ll n, ll r){
    return (fact[n] * invs[r] % MOD) * invs[n - r] % MOD;
