// NetworkFlow
namespace Networkflow{
	#define NET 100010
	int S = NET-2;
	int T = NET-1;
	struct Edge{
		int to,cap,rev,cost;
		Edge(){}
		Edge( int ti , int ci , int ri , int coi ){
			to = ti; cap = ci; rev = ri; cost = coi;
		}
	};
	vc<Edge> e[NET];
	void Link( int f , int t , int c , int co ){
		e[f].Pb( Edge( t , c , e[t].size() , co ) );
		e[t].Pb( Edge( f , 0 , e[f].size()-1 , -co ) );
	}

	queue<int> q;
	int dis[NET];
	bool inque[NET];
	int prevdot[NET], prevedge[NET];
	#define PREV(u) e[prevdot[u]][prevedge[u]]
	bool Spfa(){
		Msn(dis,INF);
		Ms(inque);
		q.push(S);
		dis[S] = 0;
		inque[S] = 1;
		while(!q.empty()){
			int u = q.front(); q.pop();
			inque[u] = 0;
			For0(i,e[u].size()){
				Edge nowe = e[u][i];
				if(!nowe.cap) continue;
				int v = nowe.to;
				if( dis[v] > dis[u] + nowe.cost ){
					dis[v] = dis[u] + nowe.cost;
					prevdot[v] = u;
					prevedge[v] = i;
					if(!inque[v]){
						inque[v] = 1;
						q.push(v);
					}
				}
			}
		}
		return dis[T] != INF;
	}
	int Refresh(){
		int u = T;
		int flow = INF;
		while( u != S ){
			Mymin(flow,PREV(u).cap);
			u = prevdot[u];
		}
		u = T;
		while( u != S ){
			PREV(u).cap -= flow;
			e[u][PREV(u).rev].cap += flow;
			u = prevdot[u];
		}
		return flow;
	}
	pii Mincostflow(){
		int ans = 0, flow = 0;
		while(Spfa()){
			int tflow = Refresh();
			int tans = tflow * dis[T];
			ans += tans;
			flow += tflow;
		}
		return Mp(ans,flow);
	}
	#undef PREV
}
