const ll MOD = 998244353;
const int MAXN = (int)3e5 + 1000;

ll gcd(ll a, ll b)
{
    if (a > b)
        swap(a, b);
    if (a == 0)
        return b;
    return gcd(b % a, a);
}

map<pii, ll> dp;

ll c(ll n, ll k)
{
    if (k == 0 || n == k)
        return 1;
    if (k > n)
        return 0;
    ll x = dp[mp(n, k)];
    if (x != 0)
        return x;
    return dp[mp(n, k)] = (c(n - 1, k) + c(n - 1, k - 1)) % MOD;
}

int solve()
{
    ll n, a, b, k;
    cin >> n >> a >> b >> k;
    ll g = gcd(a, b);
    if (k % g != 0)
    {
        cout << 0 << endl;
        return 0;
    }
    ll ans = 0;
    a /= g; b /= g; k /= g;
    if (k == 0)
    {
        cout << 1 << endl;
        return 0;
    }
    for (ll x = 0; a * x <= k && x <= n; x++)
    {
        if ((k - a * x) % b != 0)
            continue;
        ll y = (k - a * x) / b;
        if (y > n)
            continue;
        ll cur = c(n, y) * 1ll * c(n, x);
        cur %= MOD;
        ans += cur;
        if (ans >= MOD)
            ans -= MOD;
    }
    cout << ans << endl;
}

