  long long ans = 1, d = a;
  while (b) {
    if (b & 1)
      ans = ans * d % MOD;
    b >>= 1;
    d = d * d % MOD;
  }
  return ans;
}


long long comb (int n, int k) {
  return fact[n] * logpow(fact[k], MOD - 2) % MOD * logpow(fact[n - k], MOD - 2) % MOD;
}

