    for (int i = 0; i <= N; i++) {
        if (i == 0) {
            fm_table[0] = 1;
            ifm_table[0] = 1;
        } else {
            temp = temp * i % MOD;
            fm_table[i] = temp;
            ifm_table[i] = inv_mod(temp, MOD);
        }
    }
    for (int i = 0; i * 2 <= N; i++) {
        temp = fm_table[N] * ifm_table[i] % MOD
            * ifm_table[N - i] % MOD;
        bm_table[i] = temp;
        bm_table[N - i] = temp;
