lint fact[300001],factinv[300001];

int gcd(lint a,lint b){
    if(a<b) return gcd(b,a);
    if(a%b==0) return b;
    return gcd(b,a%b);
}
pair<lint,lint> euc(lint a,lint b){
    if(a==1) return make_pair(1,0);
    if(b==1) return make_pair(0,1);
    if(a<b){
        auto r=euc(b,a);
        return make_pair(r.second,r.first);
    }
    if(a%b==1){
        return make_pair(1,-a/b);
    }
    lint q=a/b;
    auto r=euc(b,a%b);
    return make_pair(r.second,r.first-q*r.second);
}
lint comb(lint n,lint r){
    return fact[n]*factinv[r]%MOD*factinv[n-r]%MOD;
}
lint powm(lint x,lint e){
    if(e==0) return 1;
    if(e==1) return x%MOD;
    return powm(x*x%MOD,e/2)*(e%2==1?x:1)%MOD;
