long long inverse(long long a){
  long long m = mod, u = 1, v = 0;
  while(m){
    long long t = a / m;
    a -= t * m; swap(a, m);
    u -= t * v; swap(u, v);
  }
  u %= mod;
  if(u < 0) u += mod;
  return u;
}

