	vector<Modint<T>> fact_, finv_;
	constexpr Combination(int n) noexcept : fact_(n+1, 1), finv_(n+1, 1) {
		Type MOD=fact_[0].mod();
		FOR(i, 2, n+1){
			fact_[i]=fact_[i-1]*i;
		}
		finv_[n]=power(fact_[n], MOD-2);
		FORR(i, 3, n+1){
			finv_[i-1]=finv_[i]*i;
