long long mi(long long a, long long m) {
    long long m0 = m;
    long long y = 0, x = 1;
    if (m == 1) {
        return 0;
    }
    while (a > 1) {
        long long q = a / m;
        long long t = m;

        m = a % m;
        a = t;
        t = y;
        y = x - q * y;
        x = t;
    }
    if (x < 0) {
        x += m0;
    }
    return x;
}
long long ncr(long long n, long long r, vector<long long>& fact) {
    return ((fact[n] * mi(fact[r], MOD) % MOD) * mi(fact[n - r], MOD)) % MOD;
}
