long long fstp(long long base, long long p) {
    long long rt = 1;
    while (p) {
        if (p & 1) {
            rt *= base;
            rt %= mod;
        }
        base *= base;
        base %= mod;
        p >>= 1;
    }
    return rt;
}
long long ny(long long x) {
    return fstp(x, mod - 2);
}

long long gcd(long long a, long long b) {
    return b ? gcd(b, a % b) : a;
}

