using ll = long long;

ll mod_power(ll a, ll b, ll p) {
  if (b == 0) {
    return 1;
  } else if (b % 2 == 0) {
    auto d = mod_power(a, b/2, p);
    return (d*d) % p;
  }

  return (a * mod_power(a, b-1, p)) % p;
}

ll mod_factorial(ll a, ll p) {
  if (a<2) return 1;

  ll ret = 1;

  for (; a>1; a--) {
    ret *= a;
    ret %= p;
  }

  return ret;
}

ll mod_comb(ll n, ll k, ll p) {
  if (n<0 || k<0 || n<k) return 0;
  if (n==0 || k==0) return 1;
  auto a=mod_factorial(n, p);
  auto b=mod_factorial(k, p);
  auto c=mod_factorial(n-k, p);
  auto ret=a*mod_power(b, p-2, p);
  ret %= p;
  ret *= mod_power(c, p-2, p);
  ret %= p;
  return ret;
}

