    if (a>b) {
        swap(a,b);
    }

    rep(i,n){
        if ((a+b)*i>k) {
            continue;
        }
        if ((k-(a+b)*i)%a) {
            continue;
        }
        if ((k-(a+b)*i)/a+i>n) {
            continue;
        }
        pair<int, P> l={i,{(k-(a+b)*i)/a,0}};
        ans+=nCk(n,l.first)*nCk(n-l.first,l.second.first)%mod;
        mp[l]=1;
        ans%=mod;
        REP(j,min(l.first,l.second.first)){
            if (l.first+l.second.first+i>n) {
               break;
            }
            if (mp[{l.first-j,{l.second.first-j,j}}]) {
                break;;
            }
            ans+=nCk(n,l.first-j)*nCk(n-l.first+j,l.second.first+j)%mod*nCk(n-l.first-l.second.first,j)%mod;ans%=mod;
            mp[{l.first-j,{l.second.first-j,j}}]=1;
        }
