            continue;
        }
        if ((k-(a+b)*i)/b+i>n) {
            continue;
        }
        pair<int, P> l={i,{0,(k-(a+b)*i)/b}};
        if(!mp[l])ans+=nCk(n,l.first)*nCk(n-l.first,l.second.second)%mod;
        mp[l]=1;
        ans%=mod;
        REP(j,min(l.first,l.second.second)){
            if (l.first+l.second.second+i>n) {
               break;
            }
            if (mp[{l.first-j,{j,l.second.first-j}}]) {
                break;;
            }
            ans+=nCk(n,l.first-j)*nCk(n-l.first+j,l.second.second+j)%mod*nCk(n-l.first-l.second.second,j)%mod;ans%=mod;
            mp[{l.first-j,{j,l.second.first-j}}]=1;
        }
    }

