ll put(ll t,ll exp){
  if(exp==1)return t%MOD;
  ll aux;
  if(exp%2){
    aux=put(t,exp-1);
    return (aux*t)%MOD;
  }
  aux=put(t,exp/2);
  return (aux*aux)%MOD;
}
ll comb(ll na,ll ka){
  if(ka==0)return 1;
  if(na==0)return 1;
  if(ka==1||ka==na-1)return na;
  return (((md[na]*imd[ka])%MOD)*imd[na-ka])%MOD;
}

