ll factorial[N];

void init()
{
    factorial[0] = 1;
    for (int i = 1; i < N; i++)
    {
        factorial[i] = factorial[i - 1] * i % mod;
    }
}

ll powMod(ll n, ll m)
{
    ll ans = 1;
    while (m)
    {
        if (m & 1) ans = ans * n % mod;
        n = n * n % mod;
        m >>= 1;
    }
    return ans;
}

ll C(int n, int k)
{
    return factorial[n] * powMod(factorial[k], mod - 2) % mod *
           powMod(factorial[n - k], mod - 2) % mod;
}
int  main()
{
    ll n, a, b, k;
    cin >> n >> a >> b >> k;
    init();
    ll sum = 0;
    for(ll i = 0; i <= n; i++)
    {
        if(a * i <= k && (k - a * i) % b == 0)
        {
            ll tmp = (k - a * i) / b;
            if(tmp <= n)
            {
                sum += C(n, i) * C(n, tmp);
                if(sum > mod)
                    sum %= mod;
            }
        }
    }
    cout << sum << endl;
    return 0;
}

