    else{ fff(b,a%b,d,y,x); y-=x*(a/b); }
    return d;
}
ll inverse(ll a,ll n){
    ll d,x,y;
    d = fff(a,n,d,x,y);
    return d==1?(x+n)%n:-1;
}
int exgcd(int a,int b,int x,int y)
{
    if(!b)
    {
        x=1;y=0;return a;
    }
    int e=exgcd(b,a%b,x,y);
    int kkz=x;x=y;y=kkz-a/b*y;
    return e;
}
