namespace comb {
    const int N = 300005;
    mint fact[N];
    mint rev[N];

    void init() {
        fact[0] = 1;
        for (int i = 1; i < N; ++i)fact[i] = fact[i - 1] * i;
        for (int i = 0; i < N; ++i)rev[i] = fact[i].inverse();
    }

    mint C(int n, int r) {
        if (n < r)return 0;
        return fact[n] * rev[r] * rev[n - r];
    }

    mint H(int n, int r) {
        return C(n + r - 1, r);
    }

    mint P(int n, int r) {
        assert(n >= r);
        return fact[n] * rev[n - r];
    }

    mint catalan(int n) {
        return fact[2 * n] * rev[n + 1] * rev[n];
    }
}

ll N, A, B, K;

void solve() {
    comb::init();

    cin >> N >> A >> B >> K;
    map<ll, mint> stA, stB;
    rep(x, N + 1) {
        stA[A*x] = comb::C((int)N, x);
        stB[B*x] = comb::C((int)N, x);
    }

    mint re;
    each(pa, stA) {
        ll bx = K - pa.first;
        if (stB.find(bx)!=stB.end()) {
            re += pa.second * stB[bx];
        }
    }
    cout << re << endl;
}

