const int N = 1e7 + 5, P = 998244353;

ll fac[N], inv[N], fnv[N];

void pre() {
	fnv[0] = fnv[1] = fac[0] = fac[1] = inv[0] = inv[1] = 1;
	for(int i = 2; i <= N; ++i) inv[i] = (P - P / i) * 1ll * inv[P % i] % P;
	for(int i = 1; i <= N; ++i) fac[i] = fac[i - 1] % P * i % P, fnv[i] = fnv[i - 1] % P * inv[i] % P;
} 

ll C(ll a, ll b) {
	return fac[a] % P * fnv[b] % P  * fnv[a - b] % P;
}

