}

int pot(int a, int b) {
  if (!b) return 1;
  if (b % 2) return mul(a, pot(a, b - 1));
  int k = pot(a, b / 2);
  return mul(k, k);
}

int inv(int a) {
  return pot(a, MOD - 2);
}

int fak[MAXN];

int choose(int n, int k) {
  return mul(fak[n], inv(mul(fak[k], fak[n - k])));
}

