  FOR(i, 1, MAXN) fak[i] = mul(fak[i - 1], i);
  cin >> n >> a >> b >> k;
  ll sol = 0;
  REP(i, n + 1) {
    ll tream = (k - (ll)i * a) / b;
    if (tream * b != k - (ll)i * a) continue;
    if (tream > n) continue;
    sol = add(sol, mul(choose(n, i), choose(n, tream)));
  }

  cout << sol << endl;
  return 0;
}

