      (c *= (n - (i - 1))) %= MOD;

      (c *= modpow(i, MOD - 2)) %= MOD;

      a[i] = a[n - i] = c;
    }

    return std::move(a);
  };
};


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);
  std::cerr << std::fixed << std::setprecision(6);

  int N;

  ncr_t ncr;

  long long A, B, K;

  std::cin >> N >> A >> B >> K;

  std::vector<long long> a = ncr.compute(N);

  long long C = 0;

  for (long long i = 0; i <= N; i ++) {
    long long r = K - A * i;

    if (r < 0)
      break;

    if (r % B)
      continue;

    long long j = r / B;

    if (j > N)
      continue;

    (C += a[i] * a[j] % MOD) %= MOD;
  }

  std::cout << C << std::endl;

  return 0;
}

