}

long long Div(long long a, long long b, long long p)
{
	return (a*modpow(b, p-2, p))%p;
}

void init(long long p)
{
	fact[0]=1;
	for (int i=1; i<=300000; i++) fact[i]=(1LL*fact[i-1]*i)%p;
	for (int i=0; i<=300000; i++) inv[i]=Div(1, fact[i], p);
}

long long nCrModp (long long n, long long r, long long p)
{
    if (r<0 || r>n) return 0;
    return ((fact[n]*inv[r])%p)*inv[n-r]%p;
}

long long calc (long long n, long long a, long long b)
{
    long long r=nCrModp(n, a, mod)*nCrModp(n, b, mod)%mod;
    return r;
}

