    ll g = gcd(ka, a, kb, b);
    if (k % g != 0) {
        cout << "0\n";
        return 0;
    }
    ka *= k / g, kb *= k / g;
    ll l = a * b / g;
    ll qa = l / a, qb = l / b;
    if (ka < kb)
        swap(a, b), swap(ka, kb), swap(qa, qb);
    if (kb < 0) {
        ll d = (-kb + qb - 1) / qb;
        ka -= qa * d, kb += qb * d;
        if (ka < 0) {
            cout << "0\n";
            return 0;
        }
    }
    if (ka < kb)
        swap(a, b), swap(ka, kb), swap(qa, qb);
    if (ka > n) {
        ll d = ((ka - n) + qa - 1) / qa;
        ka -= qa * d, kb += qb * d;
        if (ka < 0 || kb > n) {
            cout << "0\n";
            return 0;
        }
    }
    if (ka < kb)
        swap(a, b), swap(ka, kb), swap(qa, qb);
    while (ka + qa <= n && kb - qb >= 0) ka += qa, kb -= qb;
    ll ans = 0;
    for (; 0 <= min(ka, kb) && max(ka, kb) <= n; ka -= qa, kb += qb)
        ans = (ans + c(n, ka) * c(n, kb)) % B;
    cout << ans << "\n";

    return 0;
}

