        y-=cnt*d;
        x+=cnt*c;
    }
    if(x<0||y>n)return puts("0")&0;
    if(x>n){
        ll cnt=(x-n+c-1)/c;
        y+=cnt*d;
        x-=cnt*c;
    }
    ll ans=0;
    while (x>=0&&y<=n) {
        ans=(ans+comb[x]*comb[y]%MODD)%MODD;
        x-=c;
        y+=d;
    }
    out(ans);
}

