LL powmod(LL a, LL b) {
  assert(0<=a && a<MOD);
  assert(0<=b);

  LL res=1;
  for(LL mask=1; mask<=b; mask<<=1) {
    if(b&mask) res*=a, res%=MOD;
    a*=a; a%=MOD;
  }
  return res;
}
LL modinv(LL a, LL p=MOD) {
  return powmod(a, p-2);
}
void make() {
	C[0]=1;
	C[1]=N;
	for(int i=2;i<=N; ++i) {
		LL a=C[i-1];
		a*=(N-i+1),a%=MOD;
		a*=modinv(i),a%=MOD;
		C[i]=a;
	}
}

LL solve() {
  LL res=0;
  make();
  REPE(x,N) if((K-A*x)%B==0) {
  	int y=(K-A*x)/B;
//  	dump2(x,y);
  	LL a=C[x]*C[y];
  	a%=MOD;
  	res+=a,res%=MOD;
  }
  return res;
}

