using namespace std;

ll mul_inv(ll a, ll b)
{
	ll b0 = b, t, q;
	ll x0 = 0, x1 = 1;
	if (b == 1) return 1;
	while (a > 1) {
		q = a / b;
		t = b, b = a % b, a = t;
		t = x0, x0 = x1 - q * x0, x1 = t;
	}
	if (x1 < 0) x1 += b0;
	return x1;
}

int main()
{
    ll N, A, B, K;
    scanf("%lli %lli %lli %lli", &N, &A, &B, &K);

    const ll MOD = 998244353;

    ll f [N + 1];
    f[0] = 1;
    for (ll i = 1; i <= N; i++) {
        f[i] = f[i - 1] * i % MOD;
    }

    ll finv [N + 1];
    finv[0] = 1;
    for (ll i = 1; i <= N; i++) {
        finv[i] = finv[i - 1] * mul_inv(i, MOD) % MOD;
    }

    ll max_a = K / A;
    vector<tuple<ll, ll>> ab_patterns = {};
    for (ll a_count = 0; a_count <= max_a; a_count++) {
        ll remaining = K - A * a_count;
        if (remaining % B == 0) {
            ll b_count = remaining / B;
            ab_patterns.push_back(make_tuple(a_count, b_count));
        }
    }

    ll ans = 0;
    for (tuple<ll, ll> abpat : ab_patterns) {
        ll a_count = get<0>(abpat);
        ll b_count = get<1>(abpat);
        ll result = -1;
        for (ll n_greens = min(a_count, b_count); n_greens >= 0; n_greens--) {
            ll n_reds = a_count - n_greens;
            ll n_blues = b_count - n_greens;
            if (n_greens + n_reds + n_blues > N) {
                break;
            }
            ll n_nocolors = N - n_reds - n_greens - n_blues;
            result = f[N] * finv[n_greens] % MOD * finv[n_reds] % MOD * finv[n_blues] % MOD * finv[n_nocolors] % MOD;
            ans += result;
            ans %= MOD;
        }
    }

    cout << ans << endl;

    return 0;
}

