long long inv[MAX_N];
long long factorial[MAX_N];
long long inv_factorial[MAX_N];

void getInv(){
  for (int i = 1; i < MAX_N; i++) {
    if (i == 1) inv[i] = 1;
    else {
      inv[i] = (mod - (mod / i) * inv[mod % i]) % mod;
      if (inv[i] < 0) inv[i] += mod;
    }
  }
}
void getFactorial(){
  factorial[0] = 1; inv_factorial[0] = 1;
  for (int i = 1; i < MAX_N; i++) {
    factorial[i] = factorial[i-1] * i;
    factorial[i] %= mod;
    inv_factorial[i] = inv_factorial[i-1] * inv[i];
    inv_factorial[i] %= mod;
  }
}

long long combination(int n, int r) {
  long long ret = factorial[n] * inv_factorial[r];
  ret %= mod;
  ret *= inv_factorial[n-r];
  return ret % mod;
}


int main(){
  getInv();
  getFactorial();
  long long n, a, b, k; cin >> n >> a >> b >> k;
  long long ans = 0;
  for (int i = 0; i <= n; i++) {
    long long u = k - a * i;
    if (u % b != 0) continue;
    u /= b; if (u > n) continue;
    long long tmp = combination(n, i) * combination(n, u); tmp %= mod;
    ans += tmp;
    ans %= mod;
    //cout << i-j << " " << j << " " << u-j << " " << tmp << endl;
  }
  cout << ans << endl;
  return 0;
}

