void extend_gcd(ll a,ll b,ll &x,ll &y){
	if(b==0){
		x = 1; y = 0;
	}else{
		extend_gcd(b,a%b,y,x);y = y - x*(a/b);
	}
}
ll inv(ll a,ll p){
	ll x,y;
	extend_gcd(a,p,x,y);
	return (x+p)%p;
}
void init(int n){
	f[0] = 1;
	for(int i=1;i<=n + 100;i++){
