ll nod(ll x, ll y)
{
    if (x == 0)
    {
        k1 = 0, k2 = -1;
        return y;
    }
    if (y == 0)
    {
        k1 = 1, k2 = 0;
        return x;
    }
    if (x >= y)
    {
        ll t = nod(x % y, y);
        k2 += k1 * (x / y);
        return t;
    }
    else
    {
        ll t = nod(x, y % x);
        k1 += k2 * (y / x);
        return t;
    }
}

