long long inv(long long x) {
	long long e = p - 2;
	long long result = 1;
	while(e != 0) {
		if(e % 2 == 1) {
			result *= x;
			result %= p;
		}
		e /= 2;
		x *= x;
		x %= p;
	}
	return result;
}

