LL comb(LL n, LL k) {
    LL ret = fact[n];
    ret *= Number::mod_inv(fact[k], MOD);
    ret %= MOD;
    ret *= Number::mod_inv(fact[n - k], MOD);
    ret %= MOD;
    return ret;
}

