size_t combi(size_t n, size_t k)
{
    size_t X = g_FACT[n];
    size_t Y = g_FACT[k] * g_FACT[n - k];
    return moddiv(X, Y, MOD);
}

int main()
{
    int N, A, B, K;
    std::cin >> N >> A >> B >> K;

    g_FACT.reserve(N + 1);
    g_FACT.push_back(1);
    size_t prod = 1;
    for (size_t i = 1; i <= N; i++) {
        prod *= i;
        prod %= MOD;
        g_FACT.push_back(prod);
    }

    int gcd_AB = gcd(A, B);
    int dq = A / gcd_AB;
    int dp = B / gcd_AB;

    //find min P and max Q s.t. PA+QB=K
    int P = 0, Q;
    for (P = 0; ; P++) {
        int QB = K - P * A;
        if (QB % B == 0) {
            Q = QB / B;
            break;
        }
    }



    size_t sum = 0;
    for (; Q >= 0; P += dp, Q -= dq) {
        //X -> Red, Y -> Green, Z -> Blue
        //P=X+Y, Q=Y+Z
        //std::cout << "::" << P << ' ' << Q << std::endl;
        for (int Y = std::max(0, P + Q - N); Y <= std::min(P, Q); Y++) {
            int X = P - Y;
            int Z = Q - Y;
            //std::cout << X << ' ' << Y << ' ' << Z << std::endl;
            size_t c = 1;
            c *= combi(N, X); c %= MOD;
            c *= combi(N - X, Y); c %= MOD;
            c *= combi(N - X - Y, Z); c %= MOD;
            sum += c;
            sum %= MOD;
            //std::cout << c << std::endl;
        }
    }
    std::cout << sum << std::endl;



    return 0;
}

