long long combination(long long n, long long k)
{
    if(0 == k)
    {
        return 1;
    }
    else
    {
        return combination(n, k - 1) * (n - k + 1) / k;
    }
}

int main()
{
    int n, a, b;
    long long k;
    cin >> n >> a >> b >> k;

    int c = a + b;
    long long ans = 0;
    for(long long x = 0; x <= k/a; x++)
    {
        for(long long y = 0; y <= k/b; y++)
        {
            long long z = (k - a * x - b * y) / c;
            if(z >= 0 && k == x * a + y * b + z * c)
            {
                long long temp = 1;
                if(x != 0)
                {
                    temp *= combination(n, x);
                }

                if(y != 0)
                {
                    temp *= combination(n - x, y);
                }

                if(z != 0)
                {
                    temp *= combination(n - x - y, z);

                }
                ans += temp % 998244353;

            }
        }
    }

    cout << ans << endl;
    return 0;
}

