	ll N, A, B, K;
	cin >> N >> A >> B >> K;
	ll i, j;
	ll ans = 0;
	preCalcCombinationMod(N);
	for (i = 0; i <= N; i++){
		if (i*A > K){
			break;
		}
		ll resi = K - i*A;
		if (resi%B == 0){
			j = resi / B;
			ll atmp = calcCombinationMod(N, i);
			ll btmp = calcCombinationMod(N, j);
			ans += atmp * btmp % MOD;
			ans %= MOD;
		}
	}
	cout << ans << endl;

	return 0;
}

