      mul(tmp, fact[red]);
      mul(tmp, fact[blue]);
      mul(tmp, fact[g]);
      mul(tmp, fact[rem]);
      ll tmp2 = inv(tmp, MOD);
      mul(tmp1, fact[N]);
      mul(tmp1, tmp2);
