ll FACT[300005];
ll Fact(ll x)
{
    if (x == 0) return 1LL;
    else if (x == 1) return 1LL;
    else if (FACT[x] != 0) return FACT[x];
    else return FACT[x] = (x * Fact(x-1)) % MOD;
}

ll INV_FACT[300005];
ll InvFact(ll x)
{
    if (INV_FACT[x] != 0) return INV_FACT[x];
    else return INV_FACT[x] = Inv(Fact(x));
}

ll Comb(ll n, ll p)
{
    ll Ret;
    Ret = Fact(n);
    Ret = (Ret * InvFact(p)) % MOD;
    Ret = (Ret * InvFact(n-p)) % MOD;
    return Ret;
}

ll GetGcd(ll A, ll B)
{
    if (A < B) swap(A, B);
    if (B==0) return A;
    else return GetGcd(B, A%B);
}

pll Dioph(ll A, ll B)
{
    if (A >= B) {
        if (B==0) {
            return {K/A, 0};
        }
        pll Tmp = Dioph(B, A%B);
        return {Tmp.second, Tmp.first - A/B * Tmp.second};
    } else {
        if (A==0) {
            return {0, K/B};
        }
        pll Tmp = Dioph(A, B%A);
        return {Tmp.first - B/A * Tmp.second, Tmp.second};
    }
}

int main(int argc, const char * argv[]) {
    cin >> N >> A >> B >> K;

    if (K == 0) {cout << 1 << endl; return 0;}
    ll Gcd = GetGcd(A, B);
    if (K%Gcd != 0) {cout << 0 << endl; return 0;}
    pll P = Dioph(A, B);
    ll dp = abs(B/Gcd);
    ll dq = - A * dp / B;
    ll tmp = P.first/dp;
    P.first = P.first - tmp * dp;
    P.second = P.second - tmp * dq;
    if (P.first < 0) {P.first += dp; P.second += dq;}

    ll Res = 0;
    while (P.first <= N && P.second >= 0) {
        if (P.second <= N) {
            Res = (Res + (Comb(N, P.first) * Comb(N, P.second)) % MOD) % MOD;
        }
        P.first += dp;
        P.second += dq;
    }

    cout << Res << endl;

    return 0;
}

