using namespace std;

int fac[300001] = {1, 1}, inv[300001] = {1, 1};

int power(long long base, int index) {
    long long r = 1;
    while (index) {
        if (index & 1) r = (r * base) % MOD;
        base = (base * base) % MOD;
        index >>= 1;
    }
    return r;
}

int comb(int p, int q) {
	long long r = 1;
	r *= fac[p]; r %= MOD;
	r *= inv[p - q]; r %= MOD;
	r *= inv[q]; r %= MOD;
	return r;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	for (int i = 2; i <= 300000; ++i) {
		fac[i] = ((long long)i * fac[i - 1]) % MOD;
		inv[i] = power(fac[i], MOD - 2);
	}

	long long n, a, b, k;
	cin >> n >> a >> b >> k;

	if (b > a) swap(a, b);

	long long ans = 0;
	long long i, j, ij;
	for (i = 0; i <= n; ++i) {
		long long t = k - a * i;
		if (t < 0) break;
		if (t % b == 0) {
			j = t / b;
			ij = min(i, j);
			int red = i - ij, green = ij, blue = j - ij;
			ij++;
			while (ij--) {
				if (red + green + blue > n) break;
				else {
					long long pos = 1;
					pos *= comb(n, red); pos %= MOD;
					pos *= comb(n - red, blue); pos %= MOD;
					pos *= comb(n - red - blue, green); pos %= MOD;
					ans += pos; ans %= MOD;
				}
				green--; red++; blue++;
			}
		}
	}

