void readData(){
	scanf("%d%lld%lld%lld",&n,&a,&b,&k);
}
int fmi(int x,int y){
	int res=1;
	for(;y;x=1ll*x*x%MOD,y>>=1)
		if(y&1)
			res=1ll*res*x%MOD;
	return res;
}	
void init(){
	fact[0]=fact[1]=1;
	for(int i=2;i<=n;i++) fact[i]=1ll*fact[i-1]*i%MOD;
	iact[0]=iact[1]=1;
	iact[n]=fmi(fact[n],MOD-2);
	for(int i=n-1;i>=2;i--) iact[i]=1ll*iact[i+1]*(i+1)%MOD;
}
inline int C(int n,int m){
	return m<=n?1ll*fact[n]*iact[m]%MOD*iact[n-m]%MOD:0;
}
void solve(){
	int ans=0;
	for(ll x=0,y;x<=n&&a*x<=k;x++)
		if((k-a*x)%b==0){
			y=(k-a*x)/b;
			if(y<=n)
				(ans+=1ll*C(n,x)*C(n,y)%MOD)%=MOD;
		}
	printf("%d\n",ans<0?ans+MOD:ans);
}
int main(){
	readData();
