void expt() {
  rep(a,N+1) {
    ll Av = A * a;
    if( Av > K ) continue;
    if( ( K - Av ) % B ) continue;
    ll b = ( K - Av ) / B;
    ll need = min((ll)a,b) + ((ll)a-min((ll)a,b)) + (b-min((ll)a,b));
    if( need > N ) continue;
    //if( a + b > N ) continue;
    ll Bv = B * b;
    assert( Av + Bv == K );
    /*
