  }
}

// [L,R]
ll calc(ll L,ll  R) {
  ll ret = mfactrs[R];
  if( L-1LL >= 0LL ) ret -= mfactrs[L-1];
  while( ret < 0LL ) ( ret += mod ) %= mod;
  return ret;
}

void expt2() {
  ll sum = 0;
  rep(a,N+1) {
    ll Av = A * a;
    if( Av > K ) continue;
    if( ( K - Av ) % B ) continue;
    ll b = ( K - Av ) / B;
    ll Bv = B * b;
    assert( Av + Bv == K );
    ll costa = 0, costb=0;
    costa = ( mfact[N] * mfactr[N-a] ) % mod;
    costa = ( costa * mfactr[a] ) % mod;
    costb = ( mfact[N] * mfactr[N-b] ) % mod;
    costb = ( costb * mfactr[b] ) % mod;
    ( sum += ( ( costa * costb) % mod ) ) %= mod;
  }
  cout << sum << endl;
}

void compute() {
  mfact[0] = 1 % mod;
  REP(i,1,N+1) mfact[i] = ( mfact[i-1] * (ll)i ) % mod;
  rep(i,N+1) mfactr[i] = mod_inv(mfact[i],mod);
  mfactrs[0] = mfactr[0];
  REP(i,1,N+1) mfactrs[i] = ( mfactrs[i-1] + mfactr[i] ) % mod;
  expt2();
}

