#define MAX_N 300005
ll inv[MAX_N], fac[MAX_N], finv[MAX_N];
void make() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for(int i=2; i<MAX_N; i++) {
    inv[i] = mod - inv[mod%i] * (mod/i) % mod;
    fac[i] = fac[i-1] * (ll)i % mod;
    finv[i] = finv[i-1] * inv[i] % mod;
  }
}
ll perm(ll n, ll r) {
  if(n < 0)       return 0;
  else if(n < r)  return 0;
  else            return (fac[n] * finv[n-r]) % mod;
}
ll comb(ll n, ll r) {
  ll ans = 1;
  ans = perm(n, r);
  ans = (ans * finv[r]) % mod;
  return ans;
}

int main() {
  ll N, A, B, K;
  cin >> N >> A >> B >> K;
  make();
  ll ans = 0;
  repl(i, N+1) {
    if((K-A*i)%B) continue;
    ll j = (K-A*i)/B;
    if(j>N) continue;
    (ans += comb(N, i) * comb(N, j)) %= mod;
  }
  cout << ans << endl;
  return 0;
}

