LL n, a, b, k;
LL ans;
LL f[300000 + 47], g[300000 + 47];

LL qpw(LL a, LL b) {
	LL res = 1;
	while(b) {
		if(b & 1) res = res * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return res;
}

int main() {
	scanf("%lld%lld%lld%lld", &n, &a, &b, &k);
	f[1] = 1;
	for(LL i = 2; i <= n; i++) f[i] = f[i - 1] * i % mod;
	g[n] = qpw(f[n], mod - 2);
	for(LL i = n - 1; i >= 1; i--) g[i] = g[i + 1] * (i + 1) % mod;
	g[0] = 1;
	for(LL i = 0; i <= n + n && i * a <= k; i++) {
		LL num = (k - i * a);
		if(num % b == 0) {
			LL an = i, bn = num / b;
			LL cn = min(an, bn);
			for(LL j = 0; j <= cn; j++) {
				if(an + bn - j <= n) {
					ans += f[n] * g[an - j] % mod * g[bn - j] % mod * g[j] % mod * g[n - an - bn + j] % mod;
				}
				ans = ans >= mod ? ans - mod : ans;
			}
		}
	}
	printf("%lld\n", ans);
}

