using namespace std;

template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }

  static int get_mod() { return mod; }
};

using modint = ModInt< mod >;

template<typename T>
struct Combination{
  //Modint用
  //構築O(N),クエリO(1)
	vector<T>fact,rfact;

	Combination(int n):fact(n+1),rfact(n+1){
		fact[0]=1;fact[1]=1;
		rfact[n]=1;
		for(int i=2;i<=n;++i){
			fact[i]=fact[i-1]*i;
		}
		rfact[n]/=fact[n];
		for(int i=n-1;i>=0;--i){
			rfact[i]=rfact[i+1]*(i+1);
		}
	}

	T C(int n,int r) const{
		if(r<0 || n<r)return 0;
		return fact[n]*rfact[n-r]*rfact[r];
	}
};

void solve()
{
	const ll M=998244353;
	ll n,a,b,k;
	cin>>n>>a>>b>>k;
	ModInt<M>ans=0;
	Combination<ModInt<M>>c(n+5);
	if(a>b)swap(a,b);
	for(ll i=0;i<=n;++i){
		if((k-a*i)%b)continue;
		ll j=(k-a*i)/b;
		if(j>n)continue;
		ans+=c.C(n,i)*c.C(n,j);
	}
	cout<<ans;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

