int func(long n,long k) {
	long s = a * k;
	if ((s - n) % (a - b) != 0) {
		return -1;
	}
	if (((s - n) / (a - b)) > k) {
		return 0;
	}
	return P(k, ((s - n) / (a - b)));
}
int P(int x, int y) {
	int ans;
	ans = 1;
	for (int i = 0; i < y; i++) {
		ans *= (x - i);
	}
	for (int j = 0; j < y; j++) {
		ans /= (j + 1);
	}
	return ans;
}

