long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

void solve() {
    mod = 998244353;
    int n, a, b, k; cin >> n >> a >> b >> k;
    int c = GCD(a, b);
    if (k % c) {
        cout << 0 << endl; return;
    }
    int x, y;
    if (a < b) swap(a, b);
    a /= c; b /= c; k /= c;
    extGCD(a, b, x, y);
    if (x < 0) {
        int cnt = ceill((-x) / b);
        x += b * cnt;
        y -= a * cnt;
        if (y < 0) {
            cout << 0 << endl;
            return;
        }
    } else {
        int cnt = floorl(x / b);
        x -= b * cnt;
        y += a * cnt;
        if (y < 0) {
            cout << 0 << endl;
            return;
        }
    }

    fact fac(300005, 998244353);
    int ans = 0;
    while (x <= n) {
        if (y < 0) break;
        if (y <= n) {
            ans += fac.nCr(n, x) * fac.nCr(n, y);
            ans %= mod;
        }
        x += b, y -= a;
    }
    cout << ans << endl;
}

