 * r*A + b*B + g*(A+B) = K
 */
void Solve(ll) {
  ll n, a, b, k;
  if (not(cin >> n >> a >> b >> k)) return;
  vector<Int> fact(2 * n + 1), ifact(2 * n + 1);
  fact[0] = ifact[0] = 1;
  VEVE(i, 1, SIZE(fact)) {
    fact[i] = fact[i - 1] * i;
    ifact[i] = fact[i].Inv();
  }
  auto choose = [&](ll n, ll k) {
    if (k > n or n < 0)
      return Int();
    return fact[n] * ifact[k] * ifact[n - k];
  };
  vector<Int> choose_sum(n + 1);
  choose_sum[0] = choose(n, 0);
  VEVE(i, 1, n + 1) choose_sum[i] = choose_sum[i - 1] + choose(n, i);
  Int res;
  VEVE(red, 0, n + 1) {
    ll blue = k - red * a;
    if (blue < 0 or blue % b != 0)
      continue;
    blue /= b;
//    Int now = 0;
////    DEBUG(red);
//    // red + blue - g <= n
//    // g >= (red + blue - n)
