using namespace std;

struct Mod {
    static const int N = 998244353;
    long long n;
    Mod() = default;
    Mod(const long long n) : n(n%N) {}
};

Mod operator+(const Mod a, const Mod b) {
    return a.n + b.n;
}

Mod operator+=(Mod& a, const Mod b) {
    return a = a + b;
}

Mod operator*(const Mod a, const Mod b) {
    return a.n * b.n;
}

Mod operator*=(Mod& a, const Mod b) {
    return a = a * b;
}

Mod power(const Mod a, const long long k) {
    if (k == 0) {
        return 1;
    } else if (k % 2 == 0) {
        return power(a*a, k/2);
    } else {
        return a * power(a*a, k/2);
    }
}

Mod inverse(const Mod a) {
    return power(a, Mod::N-2);
}

int main() {
    int N, A, B; long long K;
    cin >> N >> A >> B >> K;

    auto fac = vector<Mod>(N+1);
    fac[0] = 1;
    for (int i = 1; i <= N; i++) {
        fac[i] = fac[i-1] * i;
    }

    auto invfac = vector<Mod>(N+1);
    invfac[N] = inverse(fac[N]);
    for (int i = N; i >= 1; i--) {
        invfac[i-1] = i * invfac[i];
    }

    auto bincoef = [&](const int n, const int k) {
        return fac[n] * invfac[k] * invfac[n-k];
    };

    Mod result = 0;
    for (long long x = 0; x <= N; x++) {
        const long long y = (K - x*A) / B;
        if (0 <= y && y <= N && x*A + y*B == K) {
            result += bincoef(N, int(x)) * bincoef(N, int(y));
        }
    }
    cout << result.n << endl;
}

