vector<ll> fact(300001);
void calc_fact()
{
  fact[0] = 1;
  REP(i, 300000)
  fact[i + 1] = (i + 1) * fact[i] % MOD;
}

ll pow(ll a, ll b)
{
  if (b == 0)
    return 1;
  if (b % 2 == 0)
  {
    ll half = pow(a, b / 2);
    return half * half % MOD;
  }
  else
    return a * pow(a, b - 1) % MOD;
}

ll inv(ll n)
{
  return pow(n, MOD - 2);
}

ll comb(ll n, ll r)
{
  if (n - r < r)
    return comb(n, n - r);
  return fact[n] * inv(fact[n - r] * fact[r] % MOD) % MOD;
}

