  REP1(i, N)
  {
    ll r = (ll)i;
    if ((K - A * r) % B != 0)
      continue;
    ll b = (K - A * r) / B;
    ans += comb(N, r) * comb(N, b) % MOD;
  }
  cout << ans << endl;
  return 0;
}

