    }
    vector<long long> ModTable(N+1), ModInvTable(N+1);
    ModTable[0] = 1;
    REP(i, 1, N+1){
        ModInvTable[i] = MODPOW(i, MOD-2, MOD);
    }
    REP(i, 1, N+1){
        ModTable[i] = ModTable[i-1] * (long long)(N-i+1) % MOD;
        ModTable[i] = ModTable[i] * ModInvTable[i] % MOD;
    }
    for(auto x:C){
        ans += ModTable[x[0]] * ModTable[x[1]] % MOD;
    }
