    COMinit();
    for(long long red=0;red<=n;red++){
        long long m=k-a*red;
        if(m%b!=0) continue;
        long long blue=m/b;
        ans+=COM(n,red)*COM(n,blue);
        ans%=mod;

    }
    cout<<ans<<endl;

}

