void calJc()    //求maxn以内的数的阶乘
{
	Jc[0] = Jc[1] = 1;
	for (LL i = 2; i < maxn; i++)
		Jc[i] = Jc[i - 1] * i % mod;
}

LL pow(LL a, LL n, LL p)    //快速幂 a^n % p
{
	LL ans = 1;
	while (n)
	{
		if (n & 1) ans = ans * a % p;
		a = a * a % p;
		n >>= 1;
	}
	return ans;
}

LL niYuan(LL a, LL b)   //费马小定理求逆元
{
	return pow(a, b - 2, b);
}

LL C(LL a, LL b)    //计算C(a, b)
{
	return Jc[a] * niYuan(Jc[b], mod) % mod
		* niYuan(Jc[a - b], mod) % mod;
}


