ll pow(ll a){
  ll res = 1, n = mod-2;
  while(n > 0){
    if(n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll ;

ll ans;
ll mod = 998244353ll;
ll fact[300001];
ll R[300001];
ll puissance(int a, int n){
    if(!n) return 1 ;
    ll b = puissance(a,n/2);
    b = (b*b)%mod;
    if(n&1) b = (b*a)%mod;
    return b;
}

ll rev(ll a){
    return puissance(a, mod-2);
}

ll C(int n , int k){
    ll ret = (fact[n] * R[k]) % mod;
    ret = (ret * R[n-k]) % mod;
    return ret;
}

int main()
{
//    cout << mod_inverse(2, 6) << endl;

    int n , A , B ;
    ll K;
    cin >> n >> A >> B >> K;
    fact[0]=1;
    R[0]=1;
    for(int i = 1 ;i <= n ; i++){
        fact[i] = (fact[i-1] * i)%mod;
        R[i] = rev(fact[i]);
    }
//    cout <<fact[4] <<  ' ' << C(4,0) <<endl;
    /// X A + Y B = K
    /// X = x + y ;
    /// Y = y + z
    /// look for x , y , z , x + y + z <=n;
    for(ll X = 0; X <= n; X++){
        long long rem = (K - X * A);
        if(rem%B)continue;
        long long Y = rem / B;
//        if(X+Y > n)continue;
//        cout << X << ' ' << Y <<endl;
        for(ll y = 0 ; y <= min(X,Y); y++){
            ll x = X - y;
            ll z = Y - y;

            if(x<0 || y<0 ||  x+y+z>n)continue;
            ans += ( ( (C(n,x) * C(n-x,z))%mod) * C(n-x-z,y)) %mod;
            ans %= mod;
