const int N = 3e5 + 10, MOD = 998244353;
LL C[N];
LL pw(LL x, int k)
{
    LL res = 1LL;
    while(k) 
    {
        if(k&1) res = res * x % MOD;
        x = x * x % MOD;
        k >>= 1;
    }
    return res;
}
void init(int n)
{
    C[0] = 1;
    for(int i = 0;i < n;i ++)
    {
        C[i+1] = C[i] * (n - i) % MOD * pw(i + 1, MOD - 2) % MOD;
    }
}
