    LL ans = 0;
    for(int i = 0;i <= n;i ++)
    {
        if((k - 1ll * i * a) % b == 0)
        {
            int j = (k - 1ll * i * a) / b;
            if(j <= n) ans = (ans + C[i] * C[j] % MOD) % MOD;
        }
    }
    cout << ans << endl;
    return 0;
}

