using namespace std;
int combi(long int n,long int k){
  vector<vector<long int> >vec(n+1,vector<long int>(n+1,0));
  for(int i=0;i<vec.size();i++){
    vec[i][0]=1;
    vec[i][i]=1;
  }
  for(int i=2;i<vec.size();i++){
    for(int j=1;j<i;j++){
      vec[i][j]=(vec[i-1][j-1]+vec[i-1][j])%M;
    }
  }
  return vec[n][k];
}
int main(){
  int n,a,b,k;
  cin>>n>>a>>b>>k;
  int sum=0;
  for(int x=0;x<=n;x++){
    for(int y=0;y<=n;y++){
      if(a*x+b*y==k){
        sum+=(combi(n,x)*combi(n,y))%M
      }
    }
  }
  cout<<sum<<endl;
}

