}

using mint = ModInt<MOD>;

vector<mint> fact, factinv, inv;
void precompute(int n) {
	int m = fact.size();
	if (n < m)return;
	n = min(n, mint::kMod - 1); //  N >= kMod  =>  N! = 0 (mod kMod)
	fact.resize(n + 1);
	factinv.resize(n + 1);
	inv.resize(n + 1);
	if (m == 0) {
		fact[0] = 1;
		m = 1;
	}
	for (int i = m; i <= n; i++)
		fact[i] = fact[i - 1] * i;
	factinv[n] = fact[n].inverse();
	for (int i = n; i >= m; i--)
		factinv[i - 1] = factinv[i] * i; // ((i-1)!)^(-1) = (i!)^(-1) * i
	for (int i = m; i <= n; i++)
		inv[i] = factinv[i] * fact[i - 1];
}

mint C(int n, int k) {
	if (k < 0 || n < k)return 0;
	// Lucas's theorem
	if (n >= mint::kMod)
		return C(n % mint::kMod, k % mint::kMod) * C(n / mint::kMod, k / mint::kMod);
	precompute(n);
	return k > n ? 0 : fact[n] * factinv[n - k] * factinv[k];
}

mint P(int n, int k) {
	if (k < 0 || n < k)return 0;
	precompute(n);
	return k > n ? 0 : fact[n] * factinv[n - k];
}

mint H(int n, int k) {
	if (n == 0 && k == 0)return 1; // H(0,0) = 1 != C(-1,0) = 0
	return C(n + k - 1, k);
}


