LL mpow(LL a, LL b) {
    if(b == 0LL) return 1LL;
    LL aa = mpow(a, b/2LL);
    return aa*aa%MOD*(b%2LL == 1LL ? a : 1LL)%MOD;
}

// 階乗と階乗の逆元
// ARC077D
LL fact[SIZE] = {1LL, 1LL};
LL finv[SIZE] = {1LL, 1LL};

void initFact() {
    // fact
    for(LL i=2LL;i<SIZE;i++){
        fact[i] = fact[i-1LL]*i%MOD;
    }

    // finv
    finv[SIZE-1] = mpow(fact[SIZE-1], MOD-2LL);
    for(LL i=SIZE-1;i>=3;i--){
        finv[i-1] = finv[i]*i%MOD;
    }
}

// 組み合わせの数
// ARC077D
LL comb(LL n, LL r) {
    if(r > n) return 0LL;
    return fact[n]*(finv[r]*finv[n-r]%MOD)%MOD;
}

int main() {
    cin.tie(0);ios::sync_with_stdio(false);
    LL n, a, b, K;
    cin >> n >> a >> b >> K;
    LL ans = 0;
    initFact();
    if(a != b){
        for(LL i=0;i<=n;i++){
            if((K-a*i) < 0) continue;
            if((K-a*i)%b != 0) continue;
            LL j = (K-a*i)/b;
            //cout << i << " " << j << endl;

            for(LL k=0;k<=n;k++){
                if(i-k < 0 || j-k < 0) break;
                if((i-k)+(j-k)+k>n) continue;
                LL l = n-(i-k)-(j-k)-k;
                LL tmp = fact[n]*(finv[i-k]*finv[j-k]%MOD*finv[k]%MOD*finv[l]%MOD)%MOD;
                MODA(ans, tmp);
            }
            //cout << ans << endl;
        }
    }else{
        for(LL k=0;k<=n;k++){
            if((K-(a+b)*k) < 0) continue;
            if((K-(a+b)*k)%a != 0) continue;
            LL m = (K-(a+b)*k)/a;
            if(k+m>n) continue;
            //cout << k << " " << m << " " << finv[k] << " " << finv[m] << endl;
            LL tmp = fact[n]*(finv[k]*finv[m]%MOD*finv[n-k-m]%MOD)%MOD*mpow(2LL, m)%MOD;
            MODA(ans, tmp);
            //cout << k << " " << m << " " << tmp << " " << ans << endl;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

