int fpow(int a, int b) {
	int c = 1;
	for (;b; b >>= 1, a = a*1ll*a%P) {
		if (b & 1) {
			c = c*1ll*a%P;
		}
	}
	return c;
}


int fac[N], inv[N];


int main() {
	ll n, a, b, k;
	cin >> n >> a >> b >> k;
 	ll ans = 0;

 	fac[0] = 1;
 	inv[0] = 1;

 	for (int i = 1; i <= n; ++i) {
 		fac[i] = fac[i-1]*1ll*i%P;
 		inv[i] = inv[i-1]*1ll*fpow(i, P-2)%P;	
 	}

	for (int i = 0; i <= n; ++i) {
		// having i A
		ll at = k - i * 1ll * a;
		if (at % b == 0) {
			at /= b;
			if(at > n) continue;
			for (int j = 0; j <= min(i, (int)at); ++j) {
				int green = j, blue = at-j, red = i-j, none = n - green - blue - red;
				if(green+blue+red > n) continue;
				int at2 = fac[n];
				at2 = at2*1ll*inv[green]%P;
				at2 = at2*1ll*inv[blue]%P;
				at2 = at2*1ll*inv[red]%P;
				at2 = at2*1ll*inv[none]%P;
				ans = ans+at2;
				if(ans >= P) {
					ans -= P;
				}
			}

		}

	}
	cout << ans << endl;

}

