ll modpow(ll b, ll e, ll m) {
	ll r = 1;
	while(e) {
		if(e&1) {
			r *= b;
			r %= m;
		}
		b *= b;
		b %= m;
		e /= 2;
	}
	return r;
}

ll fact[1000000];
ll invfact[1000000];

ll combo(int n, int k) {
	 ll ret = fact[n];
	 ret *= invfact[k];
	 ret %= MOD:
	 ret *= invfact[n-k];
	 ret %= MOD;
	 return ret;
}

