  int ans = 0;
  for( int a = 0; a <= N; a++ ){
    if( a*A > K ) break;
    //割り切れないときは0組
    if( (K-A*a)%B != 0 ) continue;
    int b = (K-A*a)/B;
    //bがN以上になるときも0組
    if( b > N ) continue; 
    ans += (COM(N, a)*COM(N, b))%MOD;
    ans %= MOD;
  }
  cout << ans << endl;

}

