struct Mod {
    static const int N = 998244353;
    long long n;
    Mod() = default;
    Mod(const long long n) : n(n%N) {}
};

Mod operator+(const Mod a, const Mod b) {
    return a.n + b.n;
}

Mod operator+=(Mod& a, const Mod b) {
    return a = a + b;
}

Mod operator*(const Mod a, const Mod b) {
    return a.n * b.n;
}

Mod operator*=(Mod& a, const Mod b) {
    return a = a * b;
}

Mod power(const Mod a, const long long k) {
    if (k == 0) {
        return 1;
    } else if (k % 2 == 0) {
        return power(a*a, k/2);
    } else {
        return a * power(a*a, k/2);
    }
}

Mod inverse(const Mod a) {
    return power(a, Mod::N-2);
}

int main() {
