    invfac[N] = inverse(fac[N]);
    for (int i = N; i >= 1; i--) {
        invfac[i-1] = i * invfac[i];
    }

    auto bincoef = [&](const int n, const int k) {
        return fac[n] * invfac[k] * invfac[n-k];
    };

    Mod result = 0;
    for (int x = 0; x <= N; x++) {
        const long long y = (K - x*A) / B;
