void inpF()
{
	n=rand()%3+1;
	a=rand()%5+1;
	b=rand()%5+1;
	k=rand()%30+1;
}

void inpR()
{
	cin>>n>>a>>b>>k;
}

int solve()
{
	int ans=0;
	fac[0]=1;
	for (int i=1;i<=n;++i) fac[i]=mult(fac[i-1],i);
	for (int i=0;i<=n;++i)
	{
		ll sc=i*1ll*a;
		if (sc>k || (k-sc)%b) continue;
		ll z=(k-sc)/b;
		if (z>n) continue;
		ans=add(ans,mult(c(n,i),c(n,z)));
	}
	return ans;
}

int sB()
{
	int ans=0;
	for (int m=0;m<(1<<(2*n));++m)
	{
		int sc=0;
		for (int i=0;i<n;++i) if (m&(1<<i)) sc+=a;
		for (int i=n;i<2*n;++i) if (m&(1<<i)) sc+=b;
		if (sc==k) ++ans;
	}
	return ans;
}

