using namespace std;

const long long mod = 998244353;
long long fact[1010101];
long long ifact[1010101];
long long inv[1010101];

int main() {
  inv[1] = 1;
  for (int i = 2; i < 1010101; i++) {
    inv[i] = inv[mod % i] * (mod - mod / i) % mod;
  }
  fact[0] = 1;
  ifact[0] = 1;
  for (int i = 1; i < 1010101; i++) {
    fact[i] = i * fact[i - 1] % mod;
    ifact[i] = inv[i] * ifact[i - 1] % mod;
  }
  long long n, a, b, K;
  cin >> n >> a >> b >> K;
  long long ans = 0;
  for (long long i = 0; i <= n; i++) {
    // a*i + b*j = K
    if (K - a * i < 0 || (K - a * i) % b != 0) continue;
    long long j = (K - a * i) / b;
    for (long long k = 0; k <= min(i, j); k++) {
      if (i + j - k <= n) {
        ans += fact[n] * ifact[i - k] % mod * ifact[j - k] % mod * ifact[k] % mod * ifact[n - i - j + k] % mod;
        ans %= mod;
      }
    }
  }
  cout << ans << endl;
}

