long long factrial[1000000]={0};

int fact(int n){
  if(factrial[n] != 0) return factrial[n];
  if(n <= 1)  return 1;
  else return factrial[n] = n * fact(n-1);
}

int main(){
  long long n, a, b, k, ans, sum=0;
  cin >> n >> a >> b >> k;
  long long red = a;
  long long green = a+b;
  long long blue = b;

  REP(i, n+1){
    long long score = red*i;
    if(score > k) break;
    REP(j, n+1){
      score += (green*j);
      if(score > k) break;
      REP(m, n+1){
        score += (blue*m);
        if(k == score){
          sum += (fact(n)/(fact(i)*fact(j)*fact(m)*fact(n-i-j-m)));
        }
        else if(k > score){
          score -= (blue*m);
          continue;
        }else{
          score -= (blue*m);
          break;
        }
      }
      score -= (green*j);
    }
  }
  ans = sum % DEVIDENUM;
  cout << ans << endl;
  return 0;
}

