using namespace std;

typedef long long ll;

const ll M = 300000, R = 998244353; ll factorial[ M + 1 ], inv_factorial[ M + 1 ];

inline ll mod_pow( ll a, ll b )
{
	ll x = 1, y = a;

	while( b > 0 )
    {
		if ( b & 1 )
			x *= y, x %= R;

		y *= y, y %= R, b >>= 1;
	}

	return x % R;
}

int main()
{
    ios_base::sync_with_stdio( false ), cin.tie( nullptr ), cout.tie( nullptr );

    ll A, B, K, N, count = 0; cin >> N >> A >> B >> K;

    const auto mod_inv = [] ( ll n ) { return mod_pow( n, R - 2 ); };

    inv_factorial[ 0 ] = mod_inv( factorial[ 0 ] = 1 );

    for( ll i = 0, j = 1; j <= N; i = j++ )
        inv_factorial[ j ] = mod_inv( factorial[ j ] = j * factorial[ i ] % R );

    const auto C = [] ( ll n, ll k )
    {
        return ( factorial[ n ] * inv_factorial[ k ] % R ) * inv_factorial[ n - k ] % R;
    };

    ll u_min = max( 0LL, ( K - B * N ) / A ), u_max = min( K / A, N );

    for( ll u = u_min, w = K - A * u; u <= u_max; u++, w -= A )
        if ( ( w % B ) == 0 )
            count += C( N, u ) * C( N, w / B ) % R, count %= R;

    cout << count;
}

