ll exgcd(const ll &a, const ll &b, ll &x, ll &y) {
	if (!b) return x = 1, y = 0, a;
	ll g = exgcd(b, a % b, y, x);
	y = y - (a / b) * x;
	return g;
}
inline ll gcd(ll a, ll b) {while(ll t = a % b) a = b, b = t; return b;}
inline ll lcm(ll a, ll b) {return a / gcd(a, b) * b;}
inline ll C(int n, int m) {return fac[n] * inv[m] % mod * inv[n-m] % mod;}
int main(void) {  
  cin >> n >> a >> b >> k;
  if (n * (a+b) < k) return puts("0"), 0;
  ll x, y, g = exgcd(a, b, x, y);
  if (k % g) return puts("0"), 0;
  x *= k / g; y *= k / g;
  ll t = lcm(a, b), dx = t / a, dy = t / b;
  if (x < y) swap(a, b), swap(x, y), swap(dx, dy);
  if (y < 0) {
  	ll d = (dy - 1 - y) / dy;
  	y += dy * d;
  	x -= dx * d;
	}
	if (x > n) {
		ll d = (x - n + dx - 1) / dx;
		x -= dx * d;
		y += dy * d;
	}
	if (x > n || y > n) return puts("0"), 0;
  inv[1] = fac[1] = 1;
  for(int i = 2; i <= n; ++i) fac[i] = fac[i-1] * i % mod;
  ll xx, yy;
	exgcd(fac[n], mod, xx, yy);
	inv[n] = (xx + mod) % mod;
  for(int i = n-1; i >= 0; --i) inv[i] = (inv[i+1] * (i+1)) % mod;
  while(x >= 0 && y <= n) 
  	ans = (ans + C(n, x) * C(n, y) % mod) % mod, x -= dx, y += dy;
	cout << ans;
  return 0;
}

