inline LL Mul(LL x, LL y)
{
	rg LL ret = 0;
	while (y)
	{
		if (y & 1) ret = (ret + x) % p;
		x = (x << 1) % p;
		y >>= 1;
	}
	return ret;
}
inline LL Pow(LL x, LL y)
{
	rg LL ret = 1;
	while (y)
	{
		if (y & 1) ret = Mul(ret, x) % p;
		x = Mul(x, x) % p;
		y >>= 1;
	}
	return ret;
}
