		tmp[i][0] = fact[i];
	}
	for(int i = 1; i < 31; i++){
		for(int j = 0; j <= n; j++){
			tmp[j][i] = (tmp[j][i - 1] * tmp[j][i - 1]) % mod;
		}
	}
	for(int i = 0; i <= n; i++){
		factrev[i] = 1;
