int power(int a, int n) {
  int r = 1;
  while (n > 0) {
    if (n % 2)
      r = (1LL*r*a) % mod;
    a = (1LL*a*a) % mod;
    n /= 2;
  }
  return r;
}

int fact[N], ifact[N];

void prepare() {
  fact[0] = ifact[0] = 1;
  for (int i = 1; i < N; ++i) {
    fact[i] = (1LL*fact[i-1]*i) % mod;
    ifact[i] = power(fact[i], mod-2);
  }
}

int newton(int n, int k) {
  if (k < 0 || n < k)
    return 0;
  int r = fact[n];
  r = (1LL*r*ifact[k]) % mod;
  r = (1LL*r*ifact[n-k]) % mod;
  return r;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  prepare();

  cin >> n >> a >> b >> k;

  int r = 0;

  for (int x = 0; x <= n; ++x) {
    if ((k - 1LL*a*x) % b != 0)
      continue;
    ll y = (k - 1LL*a*x) / b;
    if (y > n)
      continue;
    r = (r + 1LL*newton(n, x)*newton(n, y)) % mod;
  }

  cout << r << '\n';
}

