vector<mint> fact, factinv;
static void fact_reserve(int n)
{
    fact.resize(n + 1);
    factinv.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = (ll)fact[i - 1] * i;
    }
    factinv[n] = fact[n].inv();
    for (int i = n; i >= 1; --i) {
        factinv[i - 1] = (ll)factinv[i] * i;
    }
}

mint P(int n, int k) {
    return fact[n] * factinv[n-k];
}
mint C(int n, int k) {
    return fact[n] * factinv[n-k] * factinv[k];
}
mint H(int n, int k) {
    return C(n+k-1, k);
