    fact[i] = 1ll * fact[i - 1] * i % mod;
  }
  ifact[N] = power(fact[N], mod - 2);
  for (int i = N - 1; i >= 0; --i){
    ifact[i] = 1ll * ifact[i + 1] * (i + 1) % mod;
  }
