long long inverse(long long x) {
    auto ret = 1ll;
    auto k = mod - 2;
    while (k) {
        if (k & 1) ret = ret * x % mod;
        x = x * x % mod;
        k /= 2;
    }
    return ret;
}

long long gcd(long long a, long long b) {
    if (a < b) std::swap(a, b);
    if (a % b) return gcd(b, a % b);
    else return b;
}

