int64_t gcd(int64_t x,int64_t y)
{
	if(x==y)return x;
	if(x<y)return gcd(y,x);
	if(x%y)return gcd(y,x%y);
	return y;
}

int64_t lcm(int64_t x,int64_t y)
{
	return x*y/gcd(x,y);
}

void solve(int64_t A,int64_t B,int64_t& x,int64_t& y,int64_t g)
{
	if(B==0)
	{
		x = g;
		y = 0;
	}
	else if(A<B){
		solve(B,A,x,y,g);
		auto tmp = x;
		x = y;
		y = tmp;
	}
	else
	{
		solve(B,A%B,x,y,g);
		auto nx = y;
		auto ny = ( g - A*nx )/B;
		x = nx;
		y = ny;
	}
}

int64_t min(int64_t x,int64_t y){
	return x<y?x:y;
}

std::map<int64_t,int64_t> factorize(int64_t num){
	std::map<int64_t,int64_t> result;
	int64_t i = 2;
	while(i*i<=num){
		if(num%i){
			++i;
			continue;
		}else{
			auto n = result[i];
			result[i]=n+1;
			num/=i;
		}
	}
	if(num==i)
		result[i]+=1;
	else
		result[num]=1;
	return result;
}

void add(std::map<int64_t,int64_t>& result,std::map<int64_t,int64_t> rhs){
	for(auto& pair:rhs){
		auto n = result[pair.first];
		result[pair.first] = n + pair.second;
	}
}
void sub(std::map<int64_t,int64_t>& result,std::map<int64_t,int64_t> rhs){
	for(auto& pair:rhs){
		auto n = result[pair.first];
		result[pair.first] = n - pair.second;
	}
}

