  for (int i = 1; i <= n; i++) inv[i] = 1ll * t[i] * s[i - 1] % mod;
}

inline ll C(int M, int N) {
  if (N < 0 || N > M) return 0;
  return M(1ll * fac[M] * M(inv[N] * inv[M - N]));
