constexpr long long int mod = 998244353;
constexpr int max_n = 300000;
long long int factorial(int n) {
	static std::vector<long long int> memo(max_n + 1, -1);
	if (n == 0 || n == 1) return 1;
	if (memo[n] == -1) {
		for (auto i = 2; i < n; i += 500) {
			factorial(i);
		}
		memo[n] = (factorial(n - 1) * n) % mod;
	}
	return memo[n];
}
long long int exponent(long long int base, long long int exp) {
	switch (exp) {
	case 0: return 1;
	case 1: return base;
	default:
		auto r = exponent(base, exp / 2);
		return (((r * r) % mod) * exponent(base, exp % 2)) % mod;
	}
}
long long int inverse_factorial(int n) {
	static std::vector<long long int> memo(max_n + 1, -1);
	if (memo[n] == -1) {
		memo[n] = exponent(factorial(n), mod - 2) % mod;
	}
	return memo[n];
}
long long int combination(int n, int r) {
	auto num = factorial(n);
	auto dena = inverse_factorial(n - r);
	auto denb = inverse_factorial(r);
	return (((num * dena) % mod) * denb) % mod;
}
int main() {
	long long int n, a, b, k;
	std::cin >> n >> a >> b >> k;
	long long int sum = 0;
	for (auto red = 0; red <= n && red * a <= k; ++red) {
		if (((k - red * a) % b) == 0) {
			auto blue = ((k - red * a) / b);
			if (blue <= n) {
				sum += (combination(n, red) * combination(n, blue)) % mod;
				sum %= mod;
			}
		}
	}
	std::cout << sum << std::endl;
}

