			ll blue = (k - red) / b;
			if (blue < n + 1 && blue >= 0) {
				v.push_back(make_pair(i, blue));
			}
		}
	}

	REP(i, v.size()) {
		ans += (C(n, v[i].first) * C(n, v[i].second)) % MOD;
	}

