  return tmp * fact[a] % MOD; 
}

int main(){
  ll n,a,b,k;
  cin>>n>>a>>b>>k;

  if(k==0){
    cout<<1<<endl;
    return 0;
  }

  make_factorial();

  ll ans=0;
  for(ll i=0;i<=n;i++){
    if((k-i*a)%b)continue;
    ll x=i;
    ll y=(k-i*a)/b;

    if(y>n)continue;

    ans+=(comb(n,x)*comb(n,y))%MOD;
    ans%=MOD;
  }

  cout<<ans<<endl;
  return 0;
}

