    while (true) {
        ch = getchar();
        if (ch < '0' || ch > '9') break;
        result = result*10 + (ch - '0');
    }
    if (minus1)
        return -result;
    else
        return result;
}

ll fact[MAXN];


ll binpow (ll a, ll n) {
	if (n == 0)
		return 1;
	if (n % 2 == 1)
		return (binpow (a, n-1) * a) % MOD;
	else {
		ll b = binpow (a, n/2) % MOD;
		return (b * b) % MOD;
	}
}


ll C(ll n, ll k) {
	ll res1 = fact[n];
	ll res2 = (fact[k] * fact[n - k]) % MOD;
	return (res1 * binpow(res2, MOD - 2)) % MOD;
}

