const int mod = 998244353;

vector<int> range_mod_inverse(int n, const int mod) {
  vector<int> ret(n + 1);
  ret[1] = 1;
  for (int i = 2; i <= n; i++)
    ret[i] = (long long)(mod - mod / i) * ret[mod%i] % mod;
  return ret;
}

vector<int> getFactorials(int n, const int mod) {
  vector<int> ret(1, 1);
  for (int i = 1; i <= n; i++) ret.push_back((long long)ret.back()*i%mod);
  return ret;
}

vector<int> getInverseFactorials(int n, const int mod) {
  vector<int> invmod(range_mod_inverse(n, mod));
  vector<int> ret(1, 1);
  for (int i = 1; i <= n; i++) ret.push_back((long long)ret.back()*invmod[i] % mod);
  return ret;
}

vector<int> facts, ifacts;

long long comb(int a, int b) {
  if (a < 0 || b < 0 || b > a) return 0;
  unsigned long long d = facts[a];
  d *= (unsigned long long)ifacts[b]; d %= mod;
  d *= (unsigned long long)ifacts[a - b]; d %= mod;
  return d;
}

int main() {
  scanf("%d%d%d", &N, &A, &B);
  scanf("%lld", &K);
  facts = getFactorials(N + 1, mod);
  ifacts = getInverseFactorials(N + 1, mod);
  long long ans = 0;
  for (long long x = 0; x <= N; x++) {
    if (x*A > K) break;
    long long y = (K-x*A) / B;
    if ((K - x*A) % B) continue;
    if (y < 0 || y > N) continue;
    long long c;
    c = comb(N, x);
    c *= comb(N, y);
    ans += c % mod;
  }
  ans %= mod;
  printf("%lld\n", ans);
  return 0;
}

