ll mod_pow(ll a, ll n) {
	ll x = 1;
	while (n > 0) {
		if (n & 1) x = x * a % M;
		a = a * a % M;
		n >>= 1;
	}
	return x;
}


ll combination(int n, int r) {
	if (n == 0 && r == 0) return 1;
	else if (n < r || n < 0) return 0;

	ll com = fact_n[n] * fact_inv[r] % M;
	return com * fact_inv[n - r] % M;
}


