// a>=0, b>=0, x*a+y*b=gcd>=0, a>0,b>0=>abs(y)<=a,abs(x)<=b
LL gcdex(LL a,LL b,LL& x, LL& y){
	LL ax=1,ay=0;
	LL bx=0,by=1;
	while(b){
		LL r=a/b;
		LL t=a-r*b; a=b; b=t;
		LL tx=ax-r*bx; ax=bx; bx=tx;
		LL ty=ay-r*by; ay=by; by=ty;
	}
	x=ax;
	y=ay;
	return a;
}
LL F[3*100*1000+1];
LL Comb(int i,int j,LL p){
	if(i<j){
		return 0;
	}
	LL ret=F[i];
	LL x,y;
	gcdex(F[j],p,x,y);
	ret*=x;
	ret%=p;
	gcdex(F[i-j],p,x,y);
	ret*=x;
	ret%=p;
	if(ret<0){
		ret+=p;
	}
	return ret;
}
const LL M=998244353;
