const ll MOD = 998244353;

ll sqMod(ll x){ 
  return 1LL*x*x%MOD;
}
ll powMod(ll x,ll n){//xのn乗
  if(n==0)return 1;
  else if(n==1)return x;
  if(n%2==0)return (sqMod(powMod(x,n/2)%MOD)%MOD);
  else return ((x*sqMod(powMod(x,n/2)%MOD)%MOD)%MOD);
}
V kaitable,gyakutable;
ll ncr(int n,int r){
  return 1LL * kaitable[n] * gyakutable[n-r] % MOD * gyakutable[r]% MOD;
}
ll nhr(int n,int r){
  return ncr(n+r-1,r);
}
void calcTable(int t){
  kaitable = V(t);
  gyakutable = V(t);
  kaitable[0]=1;
  gyakutable[0]=1;
  FOR(i,1,t){
    kaitable[i] = 1LL * kaitable[i-1] * i % MOD;
    gyakutable[i] = powMod(kaitable[i],MOD-2)%MOD;
  }
}

int main(){
    CIN(n,a,b);ll k;cin>>k;
    //a,b,cがある 決め打ちをしたい

    calcTable(2*n+1);

    ll ans = 0;

    REP(i,2*n+1){
        ll val = k-(1LL * a * i);

        if(val<0||val%b)continue;
        ll j = val/b;

        ll mi = min(1LL*i,j);

        // xは緑
        REP(x,mi+1){
            if(x+(i-x)+(j-x)>n)continue;

            ll pat = ncr(n,x);
            pat %= MOD;
            pat *= ncr(n-x,i-x);
            pat %= MOD;
            pat *= ncr(n-x-(i-x),j-x);
            pat %= MOD;
            ans += pat;
            ans %= MOD;
        }

    }
    COUT(ans);

    return 0;
}

