	if (b != 0) {
	ans = ans * data2[b-1] % MOD;
	}
	if (c != 0) {
	ans = ans * data2[c-1] % MOD;
	}
	SINT64 buf = N - a - b - c;
	if (buf > 0) {
	ans = ans * data2[buf-1] % MOD;
	} else if (buf == 0){
	} else {
		ans = 0;
	}
	return ans;
}

