inline ll mul(ll x, ll y) {
  return x * y % Mod;
}

ll pot(ll b, ll exp) {
  if (exp == 0) return 1;
  if (exp % 2 == 1) return mul(b, pot(b, exp - 1));
  ll t = pot(b, exp/2);
  return mul(t, t);
}

ll inv(ll x) {
  return pot(x, Mod - 2);  
}

ll add(ll x, ll y) {
  return (x + y) % Mod;
}

ll binomN(ll x){
  return mul(fac[N], inv(mul(fac[N-x], fac[x])));
}

void prec() {
  fac[0] = 1;
  FOR(i, 1, N + 5) {
    fac[i] = mul(fac[i-1], i);    
  }
  FOR(i, 0, N + 1) {
    binom[i] = binomN(i);
//    TRACE(i _ binom[i]);
  }
}

void solve() {
  prec();
  ll ret = 0;

  FOR(i, 0, N + 1) {
    if (A * i <= K) {
      ll ost = K - A*i;
      if (ost % B == 0 ) {
        ll j = ost / B;
        if (0 <= j && j <= N)
          ret = add(ret, mul(binom[i], binom[j]));

      }
    }
  }

  cout<<ret<<endl;
}

