long long int power(long long int x, long long int n, long long int M) {
	long long int tmp = 1;

	if (n > 0) {
		tmp = power(x, n / 2, M);
		if (n % 2 == 0) tmp = (tmp*tmp) % M;
		else tmp = (((tmp*tmp) % M)*x) % M;
	}
	return tmp;
}

long long int N, M, K, H, W, L, R;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> L >> R >> K;
	if (max(L, R) < 10)return 0;
	vector<long long int>p(N + 1);
	vector<long long int>r(N + 1);
	p[0] = 1;
	for (int i = 1; i <= N; i++) {
		p[i] = p[i - 1] * i;
		p[i] %= MOD;
	}
	for (int i = 0; i <= N; i++) {
		r[i] = power(p[i], MOD - 2, MOD);
	}
	long long int ans = 0;
	for (int i = 0; i <= N; i++) {
		if (K < L*i)continue;
		if ((K - L * i) % R)continue;
		int box = (K - L * i) / R;
		for (int j = 0; j <= min(i, box); j++) {
			if (i + box - j > N)continue;
			long long int add = p[N];
			add *= r[i - j];
			add %= MOD;
			add *= r[box - j];
			add %= MOD;
			add *= r[j];
			add %= MOD;
			add *= r[N - i - box + j];
			add %= MOD;
			ans += add;
			ans %= MOD;
		}
	}
	cout << ans << endl;
	return 0;
}

