#include <bits/stdc++.h>

using namespace std;
const int mod = 998244353;
int n;
long long A, B, K;
long long fct[500000];
long long rfct[500000];
long long mypow(long long n, long long k) {
    if (k == 0) return 1;
    long long x = mypow(n, k / 2);
    x = x * x % mod;
    if (k & 1) x = x * n % mod;
    return x;
}
long long cnk(long long n, long long k) {
    return ((fct[n] * rfct[n - k]) % mod) * rfct[k] % mod;
}
vector<long long> good[500000];
long long solve(int n, long long K) {
    if (K < 0) return 0;
    int x = K % B;
    if (good[x].size() == 0) return 0;
    if (A == B) {
        if (K % A != 0) return 0;
        long long t = K / A;
        if (t > n) return 0;
        return cnk(n, t) * mypow(2, t) % mod;
    }
    auto it = upper_bound(good[x].begin(), good[x].end(), K);
    if (it == good[x].begin()) return 0;
    it--;
    long long c = 0, f = 0;
    while (1) {
        if (*it / A + (K - *it) / B <= n) {
            f = cnk(n, *it / A);
            f = f * cnk(n - *it / A, (K - *it) / B) % mod;
            c += f;
            if (c >= mod) c -= mod;
        }
        else break;
        if (it == good[x].begin()) break;
        it--;

    }
    return c;
}
int main() {
    ios_base::sync_with_stdio(0);
    cin >> n >> A >> B >> K;
    if (A < B) swap(A, B);
    fct[0] = 1;
    for (int i = 1; i <= n; i++) fct[i] = fct[i - 1] * i % mod;
    rfct[0] = 1;
    for (int i = 1; i <= n; i++) rfct[i] = mypow(fct[i], mod - 2);
    long long ans = 0;
    for (int i = 0; i <= n; i++) good[(A * i) % B].push_back(A * i);

    for (int k2 = 0; k2 <= n; k2++) {
        ans += solve(n - k2, K - (A + B) * k2) * cnk(n, k2) % mod;
        if (ans >= mod) ans -= mod;
    }
    cout << ans << "\n";
    return 0;
}

