long modPow(long x, long y){
    if (y == 0){
        return 1;
    }
    else if(y == 1){
        return x % mod;
    }
    else if(y % 2 == 0){
        long i = modPow(x, y/2);
        return i * i % mod;
    }
    else{
        long i = modPow(x, y/2);
        return i * i * x % mod;
    }
}

long modDiv(long a, long b ){
    return modMul(a, modPow(b, mod-2));
}

long facctorialMethod(long k){
    long sum = 1;
    for (long i = 1; i <= k; ++i)
    {
        sum = modMul(sum, i);
    }
    return sum;
}

long gcd( long m, long n )
{
	// 引数に０がある場合は０を返す
	if ( ( 0 == m ) || ( 0 == n ) )
		return 0;

	// ユークリッドの方法
	while( m != n )
	{
		if ( m > n ) m = m - n;
		else         n = n - m;
	}
	return m;
}//gcd

long lcm( long m, long n )
{
	// 引数に０がある場合は０を返す
	if ( ( 0 == m ) || ( 0 == n ) )
		return 0;

	return ((m / gcd(m, n)) * n); // lcm = m * n / gcd(m,n)
}//lcm

