        return 0;
    }

    a /= d;
    b /= d;

    vector<int64_t> fact(n + 1);
    irep(i, n)
    {
        if (i == 0) {
            fact[i] = 1;
        } else {
            fact[i] = fact[i - 1] * i % MOD;
        }
    }

    int64_t result = 0;
    for (int64_t t = dceil(-x, b); x + b * t <= n; t++) {
        int64_t w = x + b * t, z = y - a * t;
        if (z >= 0 && z <= n) {
            int64_t c1 = fact[n] * inv(fact[n - w]) % MOD * inv(fact[w]) % MOD;
            int64_t c2 = fact[n] * inv(fact[n - z]) % MOD * inv(fact[z]) % MOD;
            result += c1 * c2 % MOD;
            result %= MOD;
        }
    }
    cout << result << endl;

    return 0;
}

