  for(int i=1;i<n;i++) npr[i+1]=(npr[i]*(n-i))%mod;
  gyk[n]=pow(npr[n],mod-2)%mod;
  for(int i=n;i>=1;i--) gyk[i-1]=(gyk[i]*i)%mod;
  for(int i=0;i<=n;i++){
    mod_conb[i]=(npr[i]*gyk[i])%mod;
  }
  ll ans=0;
  for(ll i=0;i<=n;i++){
    if(a*i>k) continue;
    if((k-a*i)%b!=0) continue;
    ll j=(k-a*i)/b;
    ans+=(mod_conb[i]*mod_conb[j])%mod;
    ans%=mod;
  }
  cout<<ans<<endl;
}

