	long long t = powMod(b, e / 2);
	t =  (t * t) % MOD;
	if(e % 2) return (t * b) % MOD;
	return t;
}

long long invMod(long long k) {
	return powMod(k, MOD - 2);
}

long long comb(long long n, long long k) {
	return (f[n] * invMod( ((f[k] * f[n - k]) % MOD)))%MOD;
}

