lli fact[300001];

lli extgcd(lli a, lli b, lli &x, lli &y) {
        lli g = a; x = 1LL; y = 0LL;
        if (b != 0LL) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
        return g;
}

lli mod_inverse(lli a, lli m) {
        lli x, y;
        extgcd(a, m, x, y);
        return (m + x % m) % m;
}

lli mod_fact(lli n, lli p, lli& e) {
        e = 0;
        if (n == 0) return 1LL;

        lli res = mod_fact(n / p, p, e);
        e += n / p;

        if (n / p % 2 != 0) return res * (p - fact[n % p]) % p;
        return res * fact[n % p] % p;
}

lli mod_comb(lli n, lli k, lli p) {
        if (n < 0 || k < 0 || p < 0) return 0LL;

        lli e1, e2, e3;
        lli a1 = mod_fact(n, p, e1),
            a2 = mod_fact(k, p, e2),
            a3 = mod_fact(n - k, p, e3);

        if (e1 > e2 + e3) return 0LL;
        return a1 * mod_inverse(a2 * a3 % p, p) % p;
}

