const ll MOD = 998244353;
const int MAXN = (int)3e5 + 1000;

ll gcd(ll a, ll b)
{
    if (a > b)
        swap(a, b);
    if (a == 0)
        return b;
    return gcd(b % a, a);
}

ll c[MAXN];

ll Pow(ll x, ll y)
{
    if (y == 0)
        return 1;
    ll ans;
    if (y % 2 == 0)
    {
        ans = Pow(x, y / 2);
        return ((ans * ans) % MOD);
    }
    else
        return ((x * Pow(x, y - 1)) % MOD);
}

int solve()
{
    ll n, a, b, k;
    cin >> n >> a >> b >> k;

    c[0] = 1ll;
    for (ll i = 1; i <= n; i++)
    {
        c[i] = (c[i - 1] * 1ll * (n - i + 1)) % MOD;
        c[i] = (c[i] * Pow(i, MOD - 2)) % MOD;
        ///cerr << i << " " << Pow(i, MOD - 2) << endl;
    }

    ll g = gcd(a, b);
    if (k % g != 0)
    {
        cout << 0 << endl;
        return 0;
    }
    ll ans = 0;
    a /= g; b /= g; k /= g;
    if (k == 0)
    {
        cout << 1 << endl;
        return 0;
    }
    for (ll x = 0; a * x <= k && x <= n; x++)
    {
        if ((k - a * x) % b != 0)
            continue;
        ll y = (k - a * x) / b;
        if (y > n)
            continue;
        ll cur = c[x] * c[y];
        cur %= MOD;
        ans += cur;
        if (ans >= MOD)
            ans -= MOD;
    }
    cout << ans << endl;
}

