template<typename T>
void InvMod(T *inv_mod, T n, T r)
{
    inv_mod[0] = 1;
    if(1 <= n)
        inv_mod[1] = 1;
    for(T i = 2; i <= n; ++i)
    {
        inv_mod[i] = r - ((r / i) * inv_mod[r % i] % r);
        ast(((inv_mod[i] * i) % r) == 1);
    }
}

template<typename T>
void InvFactMod(T * inv_fact_mod, const T *inv_mod, T n, T r)
{
    inv_fact_mod[0] = 1;
    if(1 <= n)
        inv_fact_mod[1] = 1;
    for(T i = 2; i <= n; ++i)
    {
        inv_fact_mod[i] = inv_fact_mod[i - 1] * inv_mod[i] % r;
    }
}

template<typename T>
void FactMod(T * fact_mod, T n, T r)
{
    fact_mod[0] = 1;
    if(1 <= n)
        fact_mod[1] = 1;
    for(T i = 2; i <= n; ++i)
    {
        fact_mod[i] = fact_mod[i-1] * i % r;
    }
}

