const uint64_t R = 998244353;
uint64_t N, A, B, K;

template<typename T>
void InvMod(T *inv, T n, T r)
{
    for(T i = 1; i < n; ++i)
    {
        inv[i] = (i == 1) ? 1 : (r - (r / i) * inv[r % i] % r);
        ast(((inv[i] * i) % r) == 1);
    }
}

uint64_t Comb(uint64_t n, uint64_t c, uint64_t r)
{
    vector<uint64_t> mods(n + 1);
    InvMod(mods.data(), n, r);
    uint64_t mul = 1;
    for(uint64_t cur_n = n; (n - c) < cur_n; --cur_n)
    {
        mul *= cur_n;
        mul %= r;
    }
    for(uint64_t i = 2; i <= c; ++i)
    {
        mul *= mods.at(i);
        mul %= r;
    }
    return mul;
}

