    uint64_t sum = 0;
    for(uint64_t a = 0; a <= N; ++a)
    {
        if((K - a * A) % B) continue;
        const int64_t b = (K - a * A) / B;
        if(b < 0) break;
        if(b > N) break;
        sum += Comb(N, a, R) * Comb(N, b, R) % R;
        sum %= R;
    }

    cout << sum << endl;

    return 0;
}

