const int N_MAX = 300000;
ll memo[N_MAX+10][N_MAX+10] = {};
ll combination(ll n, ll r){
    if(memo[n][r] != 0){
        return memo[n][r];
    }
    if (n == r || r == 0)
        return 1;
    else
        return memo[n][r] = combination(n, r - 1) * (n - r + 1) / r;
}

