    FOR(i, 0, N+1){
        ll rest = K - A * i;
        if(rest >= 0 && rest % B == 0){
            ll blueNum = rest / B;
            ll combi0 = combination(N, i) % MOD;
            ll combi1 = combination(N, blueNum) % MOD;
            ll multi = (combi0 * combi1) % MOD;
            sum += multi;
            sum = sum % MOD;
        }
        else{
            continue;
        }
    }

    p(sum);

    return 0;
}

