ll C( ll b , ll a ){
	if( b > a ) return 0;
	ll ret = frac[a];
	ret = ret * inv[b] % MOD;
	ret = ret * inv[a-b] % MOD;
	if(!ret) ret = 1;
	return ret;
}

ll Solve( ll a , ll b ){
	ll ret = 0;
	Forx(c,max(a+b-n,0),min(a,b)){
		if( a+b-c > n ) continue;
		//cout << a-c << " " << c << " " << b-c << endl;
		ll tret = frac[n];
		tret = tret * inv[a-c] % MOD;
		tret = tret * inv[b-c] % MOD;
		tret = tret * inv[c] % MOD;
		tret = tret * inv[n-a-b+c] % MOD;
		ret += tret;
		ret %= MOD;
	}
