template<class T>
T powMod(T a, T b, T p = numeric_limits<T>::max()) {
  T acc = 1;
  while (b > 1) {
    if (b % 2 == 1) {
      acc *= a;
      acc %= p;
    }
    a *= a;
    a %= p;

    b /= 2;
  }

  return (acc * a) % p;
}

