ll comb(ll x, ll y) {
  ll fac1 = 1, fac2 = 1;
  y = max(y, x - y);
  FOR(i, y + 1, x + 1) fac1 = (fac1 * i) % mo;
  FOR(i, 1, x - y + 1) fac2 = (fac2 * i) % mo;
  return (fac1 *mpow(fac2, mo - 2)) % mo;
}

