signed main() {
    ll N, A, B, K; cin >> N >> A >> B >> K;

    ll tmp;
    if (A > B) {
        tmp = A;
        A = B;
        B = tmp;
    }

    ll C = A + B;

    ll g = gcd(A, B);

    if (K % g != 0) {
        print(0);
        return 0;
    }

    if (K == 0) {
        print(1);
        return 0;
    }

    fracinvfrac(N);

    // AX + BY = K -> A'X + B'Y = K' (A'=A/g, B'=B/g, K'=K/g)
    ll Ad = A / g; // A'
    ll Bd = B / g; // B'
    ll Kd = K / g; // K'
    ll d = Ad;
    ll dd = Bd;
    ll x = 1;
    ll xd = 0;
    ll y = 0;
    ll yd = 1;
    while (dd != 0) {
        ll q = d / dd;
        ll pd, pdd, px, pxd, py, pyd;
        pd = d;
        pdd = dd;
        px = x;
        pxd = xd;
        py = y;
        pyd = yd;
        // koushin
        d = pdd;
        dd = pd % pdd;
        x = pxd;
        xd = px - q * pxd;
        y = pyd;
        yd = py - q * pyd;
    }
    // A'x + B'y = 1 (gcd(A', B') = 1)
    // A'K'x + B'K'y = K'
    // X = -B't + K'x, Y = A't + K'y
    // range of t s.t. X>=0 and Y>=0 and X+Y<=2N
    ll t_max = (ll) floor(Kd * x * 1.0 / Bd);
    ll t_min = (ll) ceil(- Kd * y * 1.0 / Ad);
    ll t_bottom = (ll) ceil( ( 2*N - Kd*(x+y) ) * 1.0 / (Ad - Bd) );
    t_min = max(t_min, t_bottom);

    if (t_max < t_min) {
        print(0);
        return 0;
    }

    ll ans = 0;

    for (ll t = t_min; t <= t_max; t++) {
        ll nx = - Bd * t + Kd * x;
        ll ny = Ad * t + Kd * y;
        ll pr = min(nx, ny); // maximum pair
        ll ng = 0; // green
        if (nx + ny > N) {
            ng = nx + ny - N;
            if (ng > pr) {
                continue;
            }
        }
        for (; ng <= pr; ng++) {
//            dump(nx, ny, pr, ng);
            ans = (ans + multiply(frac[N],multiply(invfrac[nx-ng],multiply(invfrac[ny-ng],multiply(invfrac[ng],invfrac[N-nx-ny+ng]))))) % mod;
        }
    }

    print(ans);

    return 0;
}

