typedef long long LL;
const int mod=998244353;
vector<int> prime;
LL binarypow(int a,int b){
	LL ans=1;
	while(b){
		if(b&1){
			ans=ans*a%mod;
		}
		a=a*a;
		b>>=1;
	}
	return ans;
}
int cal(int n,int p){
	int ans=0;
	while(n){
		ans+=n/p;
		n/=p;
	}
	return ans;
}
LL C(LL n,LL m){
	LL ans=1;
	for(int i=2;i<=n;i++){
		if(!prime[i]){
			int c=cal(n,i)-cal(m,i)-cal(n-m,i);
			ans=ans*binarypow(i,c)%mod;
		}
	}
	return ans;
}
int main(){
	LL n,a,b,k,j,ans=0;
	scanf("%lld%lld%lld%lld",&n,&a,&b,&k);
	prime.resize(n+1);
	for(int i=2;i<=n;i++){
		if(prime[i]==0){
			for(int k=i+i;k<=n;k+=i){
				prime[k]=1;
			}
		}
	}
	for(int i=0;i<=n;i++){
		if((k-a*i)%b) continue;
		else{
			j=(k-a*i)/b;
			if(j>n) continue;
			ans=(ans+C(n,i)*C(n,j))%mod;
		}
	}
	cout<<ans<<endl;
	return 0;
}

