int binpow(int a, int b) {
    int res = 1;
    while (b) {
        if (b & 1) {
            res = mul(res, a);
        }
        a = mul(a, a);
        b >>= 1;
    }
    return res;
}

int fact[MAXN];

void init() {
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) {
