#define MOD 998244353
typedef long long ll;

using namespace std;

ll N, A, B, K;
vector<ll> fact;
vector<ll> invs;

vector<ll> Factorial(){
    vector<ll> v{1};
    ll f = 1;
    for(ll i = 1; i <= N; ++i){
        f *= i;
        f %= MOD;
        v.push_back(f);
    }
    return v;
}

ll Pow(ll a,ll b){
    ll res = 1;
    while(b){
        if(b % 2) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

vector<ll> Reciprocal(){
    ll inv = Pow(fact[N], MOD - 2);
    vector<ll> v(N + 1, 1);
    v[N] = inv;
    for(ll i = N; i > 1; --i){
        inv *= i;
        inv %= MOD;
        v[i - 1] = inv;
    }
    return v;
}

ll nCr(ll n, ll r){
    if(r > n) return 0;
    return (fact[n] * invs[r] % MOD) * invs[n - r] % MOD;
}

int main(void){

    cin >> N >> A >> B >> K;

    fact = Factorial();
    invs = Reciprocal();

    ll result = 0;
    for(ll a = 0; a <= N; ++a){
