  cin >> N >> A >> B >> K;

  vector<pll> xys;
  forfl(x, 0, N)
  {
    if ((K - A * x) % B != 0)
      continue;

    ll y = (K - A * x) / B;
    if (0 <= y and y <= N)
      xys.push_back({x, y});
  }

  Modint ans = 0;
  Combination comb(N);
  for (auto xy : xys)
  {
    int x = xy.first;
    int y = xy.second;
    for (int g = max(0, x + y - N); g <= min(x, y); g++)
    {
      int r = x - g;
      int b = y - g;
      int l = N - (r + g + b);
      ans += comb.fact[N] * comb.ifact[r] * comb.ifact[g] * comb.ifact[b] * comb.ifact[l];
    }
  }
  cout << ans << endl;
}

