ll mod=998244353;
ll gyaku(ll n){
  ll u=mod-2;
  ll ret=1;
  ll now=n;
  while(u>0){
    if(u%2==1){
      ret*=now;
      ret%=mod;
    }
    now*=now;
    now%=mod;
    u/=2;
  }
  return ret;
}
ll nck(ll n,ll k){
  if(n<k)swap(n,k);
  if(2*k>n)k=n-k;
  ll ret=1;
  for(ll i=1;i<=k;i++){
    ret*=gyaku(i);
    ret%=mod;
  }
  for(ll i=0;i<k;i++){
    ret*=(n-i);
    ret%=mod;
  }
  return ret;
}
