#define MOD   998244353
#define F_MAX 333333
long long mod_div(long long a, long long b)
{
	if(a % b == 0)
	{
		return a / b;
	}
	/*
	p is prime,(b,p)=1   ⇒   b^(p-1)≡1     (mod p)
	                     ⇒   a*b^(p-1)≡a   (mod p)
	                     ⇒   a*b^(p-2)≡a/b (mod p)
	*/
	long long index = MOD - 2, power = 1;
	while(index > 0)
	{
		if(index & 1)
		{
			power *= b;
			power %= MOD;
		}
		b *= b;
		b %= MOD;
		index >>= 1;
	}
	return a * power % MOD;
}
long long combination(long long n, long long r)
{
	if(n < r || n < 0 || r < 0)
	{
		return -1;
	}
	static std::vector<long long>factorial_mod(F_MAX);
	if(factorial_mod[0] != 1)
	{
		factorial_mod[0] = 1;
		for(long long i = 1; i < F_MAX; i++)
		{
			factorial_mod[i] = (factorial_mod[i - 1] * i) % MOD;
		}
	}
	long long numerator = factorial_mod[n]%MOD;
	long long denominator = (factorial_mod[r] * factorial_mod[n - r]);
	return mod_div(numerator, denominator);
}

