        if (res % B != 0) continue;
        ll m = res / B;
        if (!(0 <= m && m <= N)) continue;
        ans += mul(nCk_gyakugen(N, n, fact, bigmod), nCk_gyakugen(N, m, fact, bigmod));
    }
    cout << ans << endl;

