//参照返し
//ベクトル長も変化する
// O(logn)くらい
void unique(vector<long long> &v) {
	long long n = v.size();
	set<long long> s;
	long long i = 0;
	while(i < n) {
		if(s.count(v.at(i))) {
			erase(v, i);
			n--;
		} else {
			s.insert(v.at(i));
			i++;
		}
	}
	return;
}

