    }
    ModInt<mod> operator() (int n, int r) {
        if (n < 0 or r < 0 or r > n) return 0;
        assert(n < fact.size() and r < fact.size());
        return fact[n] * ifact[n - r] * ifact[r];
    }
    const ModInt<mod> &operator[] (int i) const {
        return fact[i];
    }
};

