// PowMod = base ** index % mod ( natural numbers )
ll PowMod( ll base, ll index, ll modulo = mod ){
    if( index == 0 ) return 1;
    // O( log(index) )
    if( index % 2 ){
        return base * PowMod(base, index - 1, modulo) % modulo;
    }else{
        ll Phalf = index / 2;
        ll half = PowMod(base, Phalf, modulo);
        return half * half % modulo;
    }
}
