            ll j = (K - A * i) / B;
            //cout << Combination(N,i,fact,invFact,MOD) << "," << Combination(N,j,fact,invFact,MOD) << endl;
            count += Combination(N,i,fact,invFact,MOD) * Combination(N,j,fact,invFact,MOD);
            count %= MOD;
        }
    }
    cout << count << endl;
}

