struct Factorial{
    vector<ll> fact;
    vector<ll> factinv;
    Factorial(int n){
        fact = vector<ll>(n+1);
        factinv = vector<ll>(n+1);
        fact[0] = 1;
        REP(i,1,n+1) fact[i] = fact[i-1] * i % mod;
        factinv[n] = mod_inv(fact[n]);
        RREP(i,1,n+1) factinv[i-1] = factinv[i] * i % mod;
    }
    ll C(int n, int k){
        if(k<0 || k>n) return 0;
        return fact[n] * factinv[n-k] % mod * factinv[k] % mod;
    }
    ll P(int n, int k){
        if(k<0 || k>n) return 0;
        return fact[n] * factinv[n-k] % mod;
    }
    ll H(int n, int k){
        if(n==0 && k==0) return 1;
        return C(n+k-1, k);
    }
};

