ll Gcd;

pll Dioph(ll A, ll B)
{
    if (B==0) {
        if (K%A == 0){
            Gcd = A;
            return {K/A, 0};
        }
        else return {0, 0};
    }
    pll Tmp = Dioph(B, A%B);
    return {Tmp.second, Tmp.first - A/B * Tmp.second};
}

int main(int argc, const char * argv[]) {
    cin >> N >> A >> B >> K;

    pll P = Dioph(A, B);
    if (K%Gcd != 0) {cout << 0 << endl; return 0;}
    ll dp = abs(B/Gcd);
    ll dq = - A * dp / B;
    ll tmp = P.first/dp;
    P.first = P.first - tmp * dp;
    P.second = P.second - tmp * dq;
    if (P.first < 0) {P.first += dp; P.second += dq;}

    ll Res = 0;
    while (P.first <= N) {
        if (P.second <= N) {
            Res = (Res + (Comb(N, P.first) * Comb(N, P.second)) % MOD) % MOD;
        }
        P.first += dp;
        P.second += dq;
    }

    cout << Res << endl;

    return 0;
}

#include<bits/stdc++.h>

template<typename Integer = int_fast64_t>
constexpr Integer extgcd(Integer a, Integer b, Integer &x, Integer &y){
    Integer u = 0, v = 1, q = 0, tmp = 0;
    x = v = 1;
    y = u = 0;

    while(b){
        q = a / b;
        x ^= u ^= x ^= u;
        u = u - q * x;
        y ^= v ^= y ^= v;
        v = v - q * y;
        a ^= b ^= a ^= b;
        b = b - q * a;
    }

    return a;
}

template<uint_fast64_t MOD, typename Integer = int_fast64_t>
constexpr Integer modinv(Integer val){
    int_fast64_t ret = 0, tmp = 0;

    extgcd<int_fast64_t>(static_cast<int_fast64_t>(val), static_cast<int_fast64_t>(MOD), ret, tmp);

    return static_cast<Integer>(ret > 0 ? ret % MOD : (MOD - (-ret % MOD)));
}

template<std::size_t N, std::uint_fast64_t MOD>
struct Fact {
    std::uint_fast64_t val[N], v2[N];

    constexpr Fact() : val(), v2() {
        val[0] = 1;
        for (std::size_t i = 1; i < N; ++i) val[i] = val[i - 1] * i % MOD;
    }
};

template<std::size_t N, std::uint_fast64_t MOD, std::uint_fast64_t F>
struct IFact {
    std::uint_fast64_t val[N];

    constexpr IFact() : val() {
        val[N - 1] = F;
        for (std::size_t i = N - 1; i; --i) val[i - 1] = val[i] * i % MOD;
    }
};

constexpr std::uint_fast64_t MOD = 998244353, maxN = 300001;

constexpr auto fact = Fact<maxN, MOD>();
constexpr auto ifact = IFact<maxN, MOD, modinv<MOD>(fact.val[maxN - 1])>();

constexpr std::uint_fast64_t binommod(std::uint_fast64_t n, std::uint_fast64_t r){
    if(r < 0 || r > n)return 0;
    return fact.val[n] * (ifact.val[r] * ifact.val[n - r] % MOD) % MOD;
}

