unsigned int p_fac[300001][101];
unsigned int fac[300001][101];
unsigned int cmb[300001][101];
unsigned int mod = 998244353;
//unsigned int mod = 11;
ull cmb_v[300001];
ull calc_cmb(ull a) {
    ull ret = 1;
    for(int i = 0;i < 101;i++) {
        int cur = cmb[a][i];
        while(cur > 0) {
            ret = (ret * prime[i]) % mod;
            cur--;
        }
    }
    return ret;
}

int main(int argc, const char * argv[]) {
    ull n,a,b,k;
    cin >> n >> a >> b >> k;

    for(int i = 2;i <= n;i++) {
        int cur = i;
        for(int ii = 0;ii < 101;ii++) {
            while(cur % prime[ii] == 0) {
                p_fac[i][ii]++;
                cur = cur / prime[ii];
            }
        }
    }
    for(int i = 2;i <= n;i++) {
        for(int ii = 0;ii < 101;ii++) {
            fac[i][ii] = fac[i-1][ii] + p_fac[i][ii];
        }
    }
    for(int i = 0;i <= n;i++) {
        for(int ii = 0;ii < 101;ii++) {
            cmb[i][ii] = fac[n][ii] - (fac[i][ii] + fac[n-i][ii]);
        }
    }
    for(int i = 0;i <= n;i++) {
        cmb_v[i] = calc_cmb(i);
    }
    ull retval = 0;
    for(int i = 0;i <= n;i++) {
        if((k - (a*i)) % b == 0 && (k - (a*i)) / b <= n && k >= a*i) {
            retval += cmb_v[i] * cmb_v[(k - (a*i)) / b];
            retval = retval % mod;
        }
    }
    cout << retval << endl;
    return 0;
}

