long long pow_mod (long long x, long long m, long long mod) {
    if (m == 0){
        return 1;
    } else { 
        long long temp = pow_mod(x, m/2, mod);
        if (m % 2 == 0) {
            return temp * temp % mod;
        } else {
            return temp * temp % mod * x % mod;
        }
    }
}

long long inv_mod (long long x, long long mod) {
    return pow_mod(x, mod - 2, mod);
}

long long fact_mod (long long x, long long mod){
    long long ret = 1;
    for (long long i = 1; i <= x; i ++) {
        ret = ret * i % mod;
    }
    return ret;
}

long long binom_mod (long long n, long long k, long long mod) {
    return 
        fact_mod(n, mod)
        * inv_mod(fact_mod(k, mod), mod) % mod
        * inv_mod(fact_mod(n - k, mod), mod) % mod;
}

int main() {
    long long N, A, B, K;
    cin >> N >> A >> B >> K;

    long long ret = 0;

    for (long long i = 0; i <= N; i++) {
        long long rest = K - i * A;
        if (rest >= 0 && rest % B == 0){
            long long j = rest / B;
            ret = (ret +
                binom_mod(N, i, MOD) * binom_mod(N, j, MOD) % MOD
            ) % MOD;
        }
    }

    cout << ret;
}

