const int bs0 = 29,bs1 = 31;
const int MOD0 = 998244353,MOD1 = 1000000007;
int T,n;
char buf[N];
int hs0[N],hs1[N],po0[N],po1[N];
inline int hash0(int l,int r)
{
    return (hs0[r] + 1LL * po0[r - l + 1] * (MOD0 - hs0[l - 1])) % MOD0;
}
inline int hash1(int l,int r)
{
    return (hs1[r] + 1LL * po1[r - l + 1] * (MOD1 - hs1[l - 1])) % MOD1;
}
int main()
{
    po0[0] = po1[0] = 1;
    for(int i = 1;i <= 1000000;i++) po0[i] = 1LL * po0[i - 1] * bs0 % MOD0,po1[i] = 1LL * po1[i - 1] * bs1 % MOD1;
    scanf("%d",&T);while(T--)
    {
        scanf("%d",&n);
        scanf("%s",buf + 1);
        if(!(n & 1))
        {
            puts("NOT POSSIBLE");
            continue;
        }
        for(int i = 1;i <= n;++i) hs0[i] = (1LL * hs0[i - 1] * bs0 + (buf[i] - 'A' + 1)) % MOD0,hs1[i] = (1LL * hs1[i - 1] * bs1 + (buf[i] - 'A' + 1)) % MOD1;
        int cnt = 0,id = 0;
        for(int pos = 1,mid = (1 + n) >> 1,his1 = -1,his2 = -1;pos <= n;pos++)
        {
            int l1 = 0,l2 = 0,r1 = 0,r2 = 0;
            if(pos == 1)
            {
                l1 = hash0(2,mid);
                l2 = hash1(2,mid);
                r1 = hash0(mid + 1,n);
                r2 = hash1(mid + 1,n);
            }
            else if(pos == n)
            {
                l1 = hash0(1,mid - 1);
                l2 = hash1(1,mid - 1);
                r1 = hash0(mid,n - 1);
                r2 = hash1(mid,n - 1);
            }
            else if(pos == mid)
            {
                l1 = hash0(1,mid - 1);
                l2 = hash1(1,mid - 1);
                r1 = hash0(mid + 1,n);
                r2 = hash1(mid + 1,n);
            }
            else if(pos < mid)
            {
                int L1 = hash0(1,pos - 1);
                int L2 = hash1(1,pos - 1);
                int R1 = hash0(pos + 1,mid);
                int R2 = hash1(pos + 1,mid);
                r1 = hash0(mid + 1,n);
                r2 = hash1(mid + 1,n);
                l1 = (R1 + 1LL * L1 * po0[mid - pos]) % MOD0;
                l2 = (R2 + 1LL * L2 * po1[mid - pos]) % MOD1;
            }
            else
            {
                int L1 = hash0(mid,pos - 1);
                int L2 = hash1(mid,pos - 1);
                int R1 = hash0(pos + 1,n);
                int R2 = hash1(pos + 1,n);
                l1 = hash0(1,mid - 1);
                l2 = hash1(1,mid - 1);
                r1 = (R1 + 1LL * L1 * po0[n - pos]) % MOD0;
                r2 = (R2 + 1LL * L2 * po1[n - pos]) % MOD1;
            }
            if(l1 == r1 && l2 == r2)
            {
                cnt++;
                if(~his1 && ~his2 && (l1 != his1) && (l2 != his2)) {cnt = -1;break;}
                else id = pos,his1 = l1,his2 = l2;
            }
        }
        if(cnt == 0)
        {
            puts("NOT POSSIBLE");
            continue;
        }
        else if(cnt == -1)
        {
            puts("NOT UNIQUE");
            continue;
        }
        else
        {
            for(int i = 1,nh = (n >> 1);i <= nh;++i)
            {
                if(i == id) nh++;
                else putchar(buf[i]);
            }
            putchar(10);
        }
    }
    return 0;
}

