				ll x = t1 - z;//cout << "y = " << y << endl;
				ll m = n - z - x - y;//cout << "m = " << m << endl;
				if(x < 0 || y < 0 || m < 0)continue;
				ll cnt = C(n, x) % mod;
				cnt *= C(n - x, y);
				cnt %= mod;
				cnt *= C(n - x - y, z);
				cnt %= mod;
				cnt *= C(n - x - y - z, m);
				cnt %= mod;
				//cout << "cnt = " << cnt << endl;
				ans += cnt;
				ans %= mod;
			}
		}
	}
