    while(eks)
    {
        if(eks & 1)
        {
            ret *= trbaza;
            ret %= mod;
        }
        trbaza *= trbaza;
        trbaza %= mod;
        eks >>= 1;
    }
    return ret;
}

llint pov(llint apov, llint bpov)
{
    return fakt[apov] * pot(fakt[bpov] * fakt[apov - bpov] % mod, mod - 2) % mod;
}

