void solve() {
    mod = 998244353;
    int n, a, b, k; cin >> n >> a >> b >> k;
    int c = GCD(a, b);
    if (k % c) {
        cout << 0 << endl; return;
    }
    int x, y;
    if (a < b) swap(a, b);
    extGCD(a, b, x, y);
    x *= k / c; y *= k / c;
    if (x < 0) {
        int cnt = ceili(-x, (b / c));
        // cout << -x << endl;
        // cout << b / c * cnt << endl;
        x += b / c * cnt;
        y -= a / c * cnt;
        // if (y < 0) {
        //     cout << 0 << endl;
        //     return 0;
        // }
    } else {
        int cnt = x / (b / c);
        x -= b / c * cnt;
        y += a / c * cnt;
        // if (y < 0) {
        //     cout << 0 << endl;
        //     return 0;
        // }
    }

    fact fac(300005, 998244353);
    int ans = 0;
    while (x <= n) {
        if (y < 0) break;
