		x = 1, y = 0;
		return a;
	} else {
		ll g = exgcd(b, a%b, y, x);
		y -= x*(a/b);
		return g;
	}
}

bool check( ll x ) {
	return x >= 0 && x <= n;
}

void solve() {
	ll g, x, y;
	g = exgcd(a, b, x, y);
	if( k % g ) {
		puts("0");
		return;
	}
	x *= k/g;
	y *= k/g;
	ll t = b/g;
	x %= t;
	x = (x + t) % t;
	int ans = 0;
	for( ll i = x; i <= n; i += t ) {
		ll j = (k-i*a)/b;
		if( !check(i) || !check(j) ) continue;
		ans = (ans + int(1LL * C[i] * C[j] % MOD)) % MOD;
	}
	printf( "%d\n", ans );
}

