  ll N,A,B,K;
  cin >> N >> A >> B >> K;
  ll sum=0;
  fac[0] = 1;
    ifac[0] = 1;
    for(ll i = 0; i<300000; i++){
        fac[i+1] = fac[i]*(i+1) % M; // n!(mod M)
        ifac[i+1] = ifac[i]*mpow(i+1, M-2) % M; // k!^{M-2} (mod M) ←累乗にmpowを採用
    }
  for(int i=0;i<min(K/A,N);i++){
    ll x=K-A*i;
    if(x>=0 && x%B==0 && x/B<=N){
      sum+=((comb(N,i)%M)*(comb(N,x/B))%M)%M;
      sum=sum%M;
    }
  }
  cout << sum;
}

