const int MAX = 300001;
long long fact[MAX];

void init_fact() {
    fact[0] = 1;
    for (int i = 1; i < MAX; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
}

long long power_func(long long a, long long b) {
    // a^b mod p
    if (b == 0) return 1;
    if (b % 2 == 0) {
        long long d = power_func(a, b / 2);
        return d * d % MOD;
    } else {
        return a * power_func(a, b - 1) % MOD;
    }
}

long long combi(long long n, long long k) {
    if (n < 0 || k < 0 || n < k) return 0;
    if (n == 0 || k == 0) return 1;
    long long a = fact[n];
    long long b = fact[k];
    long long c = fact[n - k];
    return a * power_func(b, MOD - 2) % MOD * power_func(c, MOD - 2) % MOD;
}

