    long long n, a, b, k;
    cin >> n >> a >> b >> k;
    init_fact();

    long long res = 0;
    for (int i = 0; i <= n; i++) {
        long long residual = k - a * i;
        if (residual < 0) continue;
        if (residual % b > 0) continue;
        long long j = residual / b;
        res += combi(n, i) * combi(n, j) % MOD;
        res %= MOD;
    }
    cout << res << endl;
    return 0;
}

