int BE(int b,int e){
    if(e==0){
        return 1;
    }else{
        int sum = BE(b,e/2);
        if(e%2==0){
            return (sum*sum)%MOD;
        }else{
            return (((sum*sum)%MOD)*b)%MOD;
        }
    }
}
