int fp(int a, int p) {
	if (!p) return 1;
	int t = fp(a, p >> 1);
	t = (t * 1ll * t) % mod;
	if (p & 1) t = (t * 1ll * a) % mod;
	return t;
}
ll ncr(int n, int r) {
	return ((fac[n] * 1ll * fp(fac[r], mod - 2)) % mod * 1ll * fp(fac[n - r], mod - 2)) % mod;
}
