const int N = 3e5 + 5;
const int MOD = 998244353;
int inv[N], fac[N];
LL q_pow(LL n, LL k) {
    LL ans = 1;
    while(k) {
        if(k&1) ans = (ans * n) % MOD;
        n = (n * n) % MOD;
        k >>= 1;
    }
    return ans;
}
void init() {
    fac[0] = 1;
    for (int i = 1; i < N; i++) fac[i] = (1LL * fac[i-1] * i) % MOD;
    inv[N-1] = q_pow(fac[N-1], MOD - 2);
    for (int i = N-2; i >= 0; i--) inv[i] = (1LL * inv[i+1] * (i+1)) % MOD;
}
LL C(int n, int k) {
    return 1LL* fac[n] * inv[n-k] % MOD * inv[k] % MOD;
}
int main() {
    int n, a, b;
    LL k;
    init();
    scanf("%d%d%d%lld", &n, &a, &b, &k);
    LL ans = 0;
    for (int x = 0; x <= n; x++) {
        LL t = k - 1LL*x*a;
        if(t < 0) break;
        if(t%b) continue;
        LL y = t/b;
        if(y > n) continue;
        ans += (C(n, x)*C(n, y)) % MOD;
        ans %= MOD;
    }
    printf("%lld\n", ans);
    return 0;
}

