long long binp(long long h,long long j)
{
    if(j==0)
        return 1;
    if(j%2==1)
        return ((binp(h,j-1))%p*h)%p;
    else
    {
        long long u=binp(h,j/2)%p;
        return (u*u)%p;
    }
}
long long C(long long h,long long j)
{
    if(h<j)
        return 0;
    if(j==0 || j==h)
        return 1;
    long long c=h-j;
    c=fac[c];
    h=fac[h];
    j=fac[j];
    j=binp(j,p-2);
    c=binp(c,p-2);
    return (((h*j)%p)*c)%p;
}
