void calc_nCr(long long n, long long **nCr){
	long long i,j;
	for(i=0;i<n;i++){
		nCr[0][i]=0;
		nCr[i][0]=1;
		nCr[i][i]=1;
	}
	for(i=1;i<n;i++){
		for(j=1;j<i;j++){
			nCr[i][j]=(nCr[i-1][j-1]+nCr[i-1][j])%BASE;
		}
	}
}

