typedef long long ll;
ll MOD = 998244353;

using namespace std;

ll kai[300001];
ll gyaku[300001];

//ユークリッド
ll gcd(ll a,ll b)
{
	if(b==0)
		return a;
	else
		return gcd(b,a%b);
}
//拡張ユークリッド
ll extgcd(ll a,ll b,ll &x,ll &y)
{
	ll d=a;
	if(b!=0)
	{
		d=extgcd(b,a%b,y,x);
		y-=(a/b)*x;
	}else{
		x=1;
		y=0;
	}
	return d;
}

//逆元
ll inver(ll a)
{
	ll x,y;
	extgcd(a,MOD,x,y);
	return (MOD+x%MOD)%MOD;
}

//(nCp)*(nCq)を求める
ll combi(ll n,ll p,ll q)
{
	ll ret;
	ret=kai[n]*kai[n];
	ret%=MOD;
	ret*=inver(kai[p]);
	ret%=MOD;
	ret*=inver(kai[q]);
	ret%=MOD;
	ret*=inver(kai[n-p]);
	ret%=MOD;
	ret*=inver(kai[n-q]);
	ret%=MOD;
	while(ret<0)
		ret+=MOD;
	return ret;
}

int main()
{
	int n;
	ll a,b;
	ll k;
	ll g;//gcd
	ll l;//lcm
	ll xx,yy;
	ll ans=0;

	cin>>n>>a>>b>>k;
	g=gcd(a,b);
	l=a*b/gcd(a,b);
	if(k==0)
	{
		cout<<1<<endl;
		return 0;
	}
	if(k%g!=0)
	{
		cout<<0<<endl;
		return 0;
	}
	kai[0]=1;
	gyaku[0]=inver(0);
	for(int i=1;i<300001;i++)
	{
		gyaku[i]=inver(i);
		while(gyaku[i]<0)
			gyaku[i]+=MOD;
		kai[i]=kai[i-1]*i;
		kai[i]%=MOD;
		while(kai[i]<0)
			kai[i]+=MOD;
	}
	extgcd(a,b,xx,yy); //ax+by=gcd(a,b)を解く
	//cerr<<xx<<" "<<yy<<endl;
	xx*=(k/g);
	yy*=(k/g);
	ll d=xx/(l/a)+1LL;
	xx-=d*(l/a);
	yy+=d*(l/b);
	//順番に検証する
	while(yy>0)
	{
		if(xx>0)
		{
			//cerr<<xx<<" "<<yy<<endl;
			if(xx<=n && yy<=n)
			{
				ll temp=combi(n,xx,yy);
				ans+=temp;
				ans%=MOD;
				//cerr<<temp<<endl;
			}
		}
		xx+=(l/a);
		yy-=(l/b);
	}
	while(ans<0)
		ans+=MOD;
	cout<<ans<<endl;
	return 0;
}

