const int MAX = 300001;
const int MOD = 998244353;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
    COMinit();

    i64 n, a, b, k;
    in(n, a, b, k);

    i64 ans = 0;

    for (int i : rep(0, n + 1)) {
        if((k - a * i) % b == 0) {
            int j = (k - a * i) / b;

            if(0 <= j && j <= n) {
                (ans += COM(n, i) * COM(n, j) % MOD) %= MOD;
            }
        }
    }

    out(ans);
}

