//nCrをMODで割ったあまりを返す
long long combination_mod(long long n, long long r, long long mod, long long f_max)
{
	//例外処理
	/*if (n < r || n < 0 || r < 0)
	{
		throw - 1;
	}*/

	//階乗をmodで割ったあまりを計算する
	static std::vector<long long>factorial_mod(f_max);
	if (factorial_mod[0] != 1)
	{
		factorial_mod[0] = 1;
		for (long long i = 1; i < f_max; i++)
		{
			factorial_mod[i] = factorial_mod[i - 1] * i % mod;
		}
	}

	long long numerator = factorial_mod[n];
	long long denominator = factorial_mod[r] * factorial_mod[n - r] % mod;//積はMODを超えているかもしれないからもう一回剰余算する

	/*
	nCr ＝ n!/(n-r)!/r!
		≡ (n! % p)*((n-r)! r! % p)^(p-2) (mod p) (但しpは素数)

	証明:

	*/

	////割り切れる場合は普通に返す
	//if (numerator % denominator == 0)
	//{
	//	return numerator / denominator;
	//}
	////割り切れない時
	//else
	{
		long long index = mod - 2, power = 1;
		while (index > 0)
		{
			if (index & 1)
			{
				power *= denominator;
				power %= mod;
			}
			denominator *= denominator;
			denominator %= mod;
			index >>= 1;
		}
		return numerator * power % mod;
	}
}

signed main()
{
	const long long mod = 998244353;
	const long long f_max = 333333;

	long long n, a, b, k;
	std::cin >> n >> a >> b >> k;
	std::vector<std::pair<long, long>>pairs;
	pairs.reserve(n);
	for (long long x = 0; x <= n; x++)
	{
		if ((k - a * x) % b == 0)
		{
			long long y = (k - a * x) / b;
			if (0 <= y && y <= n)
			{
				pairs.push_back(std::make_pair(x, y));
			}
		}
	}
	long long ans = 0;
	for (auto i : pairs)
	{
		ans += combination_mod(n, i.first, mod, f_max) * combination_mod(n, i.second, mod, f_max) % mod;
		ans %= mod;
	}
	std::cout << ans << std::endl;
	return 0;
}

