  if(2*k>n)k=n-k;
  ll ret=1;
  for(ll i=1;i<=k;i++){
    ret*=gyaku(i);
    ret%=mod;
  }
  for(ll i=0;i<k;i++){
    ret*=(n-i);
    ret%=mod;
  }
  return ret;
}
