template <ll MOD>
class Combination {
private:
    ll N;
    V<ll> factv, ifactv;

public:
    Combination<MOD>(ll N) : N(N), factv(N + 1, 1), ifactv(N + 1) {
        for(ll i = 1; i <= N; i++) factv[i] = factv[i - 1] * i % MOD;
        ifactv.back() = inv(factv.back());
        for(ll i = N - 1; 0 <= i; i--) ifactv[i] = (i + 1) * ifactv[i + 1] % MOD;
    }

    ll fact(ll n) { return factv[n]; }

    ll ifact(ll n) { return ifactv[n]; }

    ll pow(ll a, ll b) { return b ? (b & 1 ? a : 1) * pow(a * a % MOD, b / 2) % MOD : 1; }

    ll inv(ll a) { return pow(a, MOD - 2); }

    ll comb(ll n, ll k) { return factv[n] * ifactv[n - k] % MOD * ifactv[k] % MOD; }
};

const ll mod = 998244353;
Combination<mod> C(1e6);

int main() {
    ll N, A, B, K;
    cin >> N >> A >> B >> K;
    ll ans = 0;
    for(ll red = 0; red <= N; red++) {
        ll rest = K - red * A;
        if(rest < 0) break;
        if(rest % B) continue;
        ll blue = rest / B;
        if(N < blue) continue;
        (ans += C.comb(N, red) * C.comb(N, blue) % mod) %= mod;
    }
    cout << ans << endl;
    return 0;
}

#include<iostream>
using namespace std;
#define N 300007
#define MAX 300000
#define mod 998244353
long long fac[N];
long long inv[N];
long long quick_power(long long p,long long t)//快速幂 
{
	long long sum=1;
	while(t)
	{
		if(t&1) sum=sum*p%mod;
		p=p*p%mod;
		t>>=1;
	}
	return sum;
}

void pre()//阶乘取模，阶乘逆元取模 
{
	fac[0]=1;
	for(long long i=1;i<=MAX;++i)
		fac[i]=(i*fac[i-1])%mod;
	inv[MAX]=quick_power(fac[MAX],mod-2);
	for(long long i=MAX-1;i>=0;--i)
		inv[i]=inv[i+1]*(i+1)%mod;
}

long long Cc(long long a,long long b)
{
	return fac[a]*inv[b]%mod*inv[a-b]%mod;
}

int main()
{
	pre();
	long long n,a,b,k;
	cin>>n>>a>>b>>k;
	long long sum=0; 
	for(long long i=0;i<=n&&i*a<=k;++i)
	{
		long long left=k-i*a;
		if(left<0)
			break;
		if(left%b==0&&(left/b)<=n)
		{
			long long j=left/b;
			sum=sum+Cc(n,i)*Cc(n,j)%mod; 
		}
	}
	cout<<sum<<endl;
	return 0;
 }

