typedef long long ll;

using namespace std;

vector<ll> memoFact, memoInvFact;
map< ll, map<ll, ll> > memoComb;

ll addMod(ll a, ll b) {
    return (a + b) % MOD;
}

ll subMod(ll a, ll b) {
    return (a + MOD - b) % MOD;
}

ll mulMod(ll a, ll b) {
    return ((a % MOD) * (b % MOD)) % MOD;
}

ll mulMod(vector<ll> v) {
    if (v.size() == 0) return 1;
    ll a = v.back();
    v.pop_back();
    return mulMod(a, mulMod(v));
}

ll powMod(ll a, ll b) {
    if (b < 0) return 0;
    if (b == 0) return 1;
    if (b % 2) return mulMod(a, powMod(a, b - 1));
    ll c = powMod(a, b / 2);
    return mulMod(c, c);
}

ll divMod(ll a, ll b) {
    if (b < 0) return divMod(a, b + MOD);
    if (b == 0) throw runtime_error("Zero Division Occured!");
    if (b == 1) return a;
    return mulMod(a, powMod(b, MOD - 2));
}

ll factMod(ll a) {
    if (a < 0) throw runtime_error("Undefined value: factorial for negative number");
    if (memoFact.at(a)) return memoFact.at(a);
    if (a < 2) return memoFact.at(a) = 1;
    return memoFact.at(a) = mulMod(a, factMod(a - 1));
}

ll invFactMod(ll a) {
    if (a < 0) throw runtime_error("Undefined value: factorial for negative number");
    if (memoInvFact.at(a)) return memoInvFact.at(a);
    if (a == memoInvFact.size() - 1) return memoInvFact.at(a) = divMod(1, factMod(a));
    return memoInvFact.at(a) = mulMod(a + 1, invFactMod(a + 1));
}

ll combMod(ll a, ll b) {
    if (b * 2 > a) return combMod(a, a - b);
    if (a < b || b < 0) return 0;
    if (b == 0) return 1;
    if (memoComb[a][b]) return memoComb.at(a).at(b);
    return memoComb[a][b] = mulMod({factMod(a), invFactMod(b), invFactMod(a - b)});
}

int main() {
    ll n, a, b, k, ans = 0;
    cin >> n >> a >> b >> k;
    memoFact.resize(n + 1);
    memoInvFact.resize(n + 1);
    for (ll i = 0; a * i <= k; ++i) {
        ll j = k - a * i;
        if (j < 0 || j % b) continue;
        j /= b;
        ans = addMod(ans, mulMod(combMod(n, i), combMod(n, j)));
    }
    cout << ans << endl;
    return 0;
}

