    ll nblue = nb - ngreen;
    if (ngreen + nred + nblue <= n) {
      ll perms = (facs[n] * invs[n - (ngreen + nred + nblue)]) % MOD;
      ll reps = (((invs[ngreen] * invs[nred]) % MOD) * invs[nblue]) % MOD;
      ll add = (perms * reps) % MOD;
      res = (res + add) % MOD;
    }
  }
  return res;
}


