typedef long long ll;

const int N_MAX = 300000;

//------------------------------------------------------------------------------
ll mod_pow(ll x, ll n, ll mod) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) {
      res = res * x % mod;
    }
    x = x * x % mod;
    n >>= 1;
  }
  return res;
}

ll mod_inverse(ll x, ll mod) {
  return mod_pow(x, mod - 2, mod);
}

ll fact[N_MAX + 1];    // mod_fact tbl

void init_fact(ll n, ll mod) {
  fact[0] = 1;
  FOR(i, 1, n) fact[i] = fact[i - 1] * i % mod;
}

ll mod_comb_fast(ll n, ll k, ll mod) {
  if (n < 0 || k < 0 || n < k) return 0;
  ll a = fact[n];
  ll b = fact[k] * fact[n - k] % mod;
  return a * mod_inverse(b, mod) % mod;
}

//------------------------------------------------------------------------------

const ll MOD = 998244353;

ll N, A, B;
ll K;

void solve() {
  init_fact(N, MOD);
  ll ans = 0;
  for (ll xy = 0; xy <= N; xy++) {
    ll v = K - A * xy;
    if (v < 0) break;
    if (v % B > 0) continue;
    ll yz = v / B;
    for (ll y = max(xy + yz - N, 0LL); y <= min(xy, yz); y++) {
      ll x = xy - y;
      ll z = yz - y;
      ll w = N - x - y - z;
      // printf("x: %lld, y: %lld, z: %lld, w: %lld\n", x, y, z, w);
      ll m = 1;
      m = (m * mod_comb_fast(N, x, MOD)) % MOD;
      m = (m * mod_comb_fast(N - x, y, MOD)) % MOD;
      m = (m * mod_comb_fast(N - xy, z, MOD)) % MOD;
      ans = (ans + m) % MOD;
    }
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%lld%lld%lld%lld", &N, &A, &B, &K);
}

int main() {
  input();
  solve();
  return 0;
}

