#define ZOHE 998244353
#define int long long

int fact[ZOHE + 10];

int extgcd(int a, int b, int &x, int &y) {
  int g = a; x = 1; y = 0;
  if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
  return g;
}

int mod_inverse(int a, int m) {
    int x, y;
    extgcd(a, m, x, y);
    return (m + x % m) % m;
}

int mod_fact(int n, int p, int &e) {
    e = 0;
    if (n == 0) return 1;

    int res = mod_fact(n / p, p, e);
    e += n / p;

    if (n / p % 2 != 0) return res * (p - fact[n % p]) % p;
    return res * fact[n % p] % p;
}

int mod_comb(int n, int k, int p) {
    if (n < 0 || k < 0 || n < k) return 0;
    int e1, e2, e3;
    int a1 = mod_fact(n, p, e1), a2 = mod_fact(k, p, e2), a3 = mod_fact(n - k, p, e3);
    if (e1 > e2 + e3) return 0;
    return a1 * mod_inverse(a2 * a3 % p, p) % p;
}

signed main(void) {
    int n, a, b, k, ans = 0;
    cin >> n >> a >> b >> k;

    fact[0] = 1;

    for (int i = 0; i <= ZOHE; i++)
        fact[i + 1] = fact[i] * (i + 1) % ZOHE;


    for (int i = 0; i <= n * 2; i++) {
        long long tsuru = 0, kame = 0;
        kame = (k - (a * i)) * (b - a); tsuru = i - kame;

        if (tsuru < 0 || kame < 0 || a * tsuru + b * kame != k)
            continue;


        for (int green = 0; green <= min(tsuru, kame); green++) {
            int red = tsuru - green, blue = kame - green;
            if (red + blue + green <= n)
                ans += mod_comb(n, red + blue + green, ZOHE) * mod_comb(red + blue + green, red + blue, ZOHE) % ZOHE * mod_comb(red + blue, red, ZOHE) % ZOHE;
        }

        ans %= ZOHE;
    }

    cout << ans << endl;
}

