int power(int x, int y)
{
  int ret = 1;
  while (y)
    {
      if (y & 1ll)
	ret = ret * x % M;
      x = x * x % M;
      y >>= 1;
    }
  return ret;
}

int c(int x, int y)
{
  return ((f[x] * rf[y]) % M * rf[x - y]) % M;
}

int32_t main()
{
  ios::sync_with_stdio(0); cin.tie(0);

  f[0] = 1;
  for (int i = 1; i < maxn; i ++)
    f[i] = f[i - 1] * i % M;
  rf[maxn - 1] = power(f[maxn - 1], M - 2);
  for (int i = maxn - 1; i --;)
    rf[i] = rf[i + 1] * (i + 1) % M;

  cin >> n >> a >> b >> k;

  for (int j, i = 0; i <= n; i ++)
    {
      int s = i * a;
      if (s <= k)
	{
	  s = k - s;
	  if (s % b == 0)
	    {
	      j = s / b;
	      if (j <= n)
		ans = (ans + c(n, i) * c(n, j) % M) % M;
	    }
	}
    }

  cout << ans << endl;

  return 0;
}

