int binPow (int x, int y) {
    int ans = 1;
    while (y) {
        if (y & 1) ans = (ans * x) % mod;

        x = (x * x) % mod;
        y /= 2;
    }

    return ans;
}

int C (int n, int k) {
    if (k > n) return 0;
    if (k < 0) return 0;

    int ans = 1;
    ans *= fact[n]; ans %= mod;
    ans *= inv_fact[k]; ans %= mod;
    ans *= inv_fact[n - k]; ans %= mod;

    return ans;
}

