            }
            ans+=nCk(n,l.first-j)*nCk(n-l.first+j,l.second.second+j)%mod*nCk(n-l.first-l.second.second,j)%mod;ans%=mod;
            mp[{l.first-j,{j,l.second.first-j}}]=1;
        }
    }

    cout<<ans<<endl;
}

