// numer/denom、もしくはそれと合同(MODを法として)なものを返す
long long devide_mod(long long numer, long long denom)
{
	// 割り切れる場合は普通に返す
	if (numer % denom == 0)
	{
		return numer / denom;
	}
	/* フェルマーの小定理
	* p is prime,(b,p)=1 ⇒   b^(p-1)≡1   (mod p)
	*                    ⇒ a*b^(p-1)≡a   (mod p)
	*                    ⇒ a*b^(p-2)≡a/b (mod p) ← これを畳み込み累乗を使って計算して返す
	*/
	long long index = MOD - 2, power = 1;
	while (index > 0)
	{
		if (index & 1)
		{
			power *= denom;
			power %= MOD;
		}
		denom *= denom;
		denom %= MOD;
		index >>= 1;
	}
	return numer * power % MOD;
}
// nCrをMODで割ったあまりを返す
long long combination_mod(long long n, long long r)
{
	//　例外処理
	/*if (n < r || n < 0 || r < 0)
	{
		throw - 1;
	}*/
	//　階乗(をMODで割ったあまり)を計算する
	static std::vector<long long>factorial_mod(F_MAX);
	if (factorial_mod[0] != 1)
	{
		factorial_mod[0] = 1;
		for (long long i = 1; i < F_MAX; i++)
		{
			factorial_mod[i] = (factorial_mod[i - 1] * i) % MOD;
		}
	}

	//long long numerator = factorial_mod[n];
	//long long denominator = (factorial_mod[r] * factorial_mod[n - r]) % MOD;
  return factorial_mod[n]/factorial_mod[r] / factorial_mod[n - r]%MOD;
	//return devide_mod(numerator, denominator);
}

