ll pow1(ll n, ll p){
    ll res, cur;
    res = 1;
    cur = n;
    while(p){
        if(p & 1){
            res *= cur;
            res %= MOD;
        }
        p /= 2;
        cur *= cur;
        cur %= MOD;
    }
    return res;
}

void init(){
    inv[0] = 1;
    fact[0] = 1;
    for(int i = 1;i < 300001;i++){
        fact[i] = fact[i-1] * i % MOD;
        inv[i] = pow1(fact[i], MOD - 2);
    }
}

ll cnk(ll n, ll k){
  if(k > n)return 0;
  return fact[n] * inv[k] % MOD * inv[n-k] % MOD;
}

