const int mod = 998244353;
int f[300001];
int inv[300001];

int calc (int a, int b, int n, int g) {
	a -= g;
	b -= g;
	int x = n - a - b - g;
	if (x < 0) return 0ll;
	int res = (inv[a] * inv[b]) % mod;
	int ser = (inv[x] * inv[g]) % mod;
	return (res * ser) % mod;
}             

int bp (int a, int b) {
	int res = 1;
	while (b) {
		if (b & 1) {
			res = (res * a) % mod;
		}
		b >>= 1;
		a = (a * a) % mod;
	}
	return res;
}

 main () {	
	ios_base::sync_with_stdio (0);
	cin.tie (0), cout.tie (0);
	int n, a, b, k;
	cin >> n >> a >> b >> k;
	f[0] = 1;
	inv[0] = 1;
	for (int i = 1;i <= n;i ++) {
		f[i] = (f[i - 1] * i) % mod;
		inv[i] = bp (f[i], mod - 2);
	}
	int ans = 0;
	for (int i = 0;i <= n;i ++) {
		int first = i;
		int re = k - (first * a);
		if (re < 0) continue;
		if (re % b != 0) continue;
		int second = re / b;
		for (int j = min (first, second);j >= 0;j --) {
			if (first + second - j * 2 > n) break;
			ans = (ans + (f[n] * calc (first, second, n, j)) % mod) % mod;
		}        	
	}
	cout << ans;
	return 0;
}

