	for (int i = 1; i <= a; ++i) {
		fact[i] = mul_mod(fact[i - 1], i);
	}
}

void cmbset(int a) {  // 1~a までの階乗と階乗数の逆元のmod(mod)を用意 O(a)
	factset(a);
	invfact[a] = pow_mod(fact[a], mod - 2);
	invfact[0] = 1;
	for (int i = a - 1; i >= 1; --i) {
		invfact[i] = mul_mod(invfact[i + 1], i + 1);
	}
}

