lli extgcd(lli a, lli b, lli &x, lli &y) {
    lli g = a;
    x = 1;
    y = 0;
    if (b != 0) {
        g = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }
    return g;
}

lli modinv(lli a, lli m) {
    lli x, y;
    extgcd(a, m, x, y);
    return (x % m + m) % m;
}

lli fact[MOD];
void init_facts(lli n) {
    fact[0] = 1;
    for (lli i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
}

lli mod_fact(lli n, lli p, lli &e) {
    e = 0;
    if (n == 0) return 1;

    lli res = mod_fact(n / p, p, e);
    e += n / p;

    if (n / p % 2 != 0) return res * (p - fact[n % p]) % p;
    return res * fact[n % p] % p;
}

lli mod_comb(lli n, lli k, lli p) {
    if (n < 0 || k < 0 || n < k) return 0;
    lli e1, e2, e3;
    lli a1 = mod_fact(n, p, e1), a2 = mod_fact(k, p, e2), a3 = mod_fact(n - k, p, e3);
    if (e1 > e2 + e3) return 0;
    return a1 * modinv(a2 * a3 % p, p) % p;
}

