		inv[i] = power(fact[i], MOD - 2);
	}
}

int efraz(int a, ll k) {
	if (k < 0)
		return 0;
	if (k % a)
		return 0;
	ll p = k / a;
	if (p > n)
		return 0;
	return (ll)chose(p, n);
}

int RGB_Coloring() {
	int ans = 0;
	for(int i = 0; i <= n; i++) {
		ll p = k - (ll)i * a;
//		cerr << b << ' ' << p << ' ' << efraz(b, p) << endl;
		ans += (ll)efraz(b, p) * chose(i, n) % MOD;
		ans %= MOD;
	}
	return ans;
}

int chose(int k, int n) {
	return (ll)fact[n] * inv[n - k] % MOD * inv[k] % MOD;
}

