const int mo=998244353;
int mc[N],inv[N];
ll power(ll x,int y)
{
	ll res=1;
	for(;y;x=x*x%mo,y>>=1)if(y&1)res=res*x%mo;
	return res;
}
int C(int x,int y){return (ll)mc[x]*inv[y]%mo*inv[x-y]%mo;}
int sum[N],ans;
int cal(int i)
{
	ll res=K-A*i;
	if(res<0)return 0;
	else 
	{
		if(res%B)return 0;
		return C(n,res/B);
	}
}
void work()
{
	mc[0]=inv[0]=1;
	For(i,1,n)mc[i]=(ll)mc[i-1]*i%mo;
	inv[n]=power(mc[n],mo-2);
	Fordown(i,n-1,1)inv[i]=(ll)inv[i+1]*(i+1)%mo;
	Fordown(i,n,0)sum[i]=(sum[i+1]+C(n,i))%mo;
	For(i,0,n)
	{
		ans=(ans+1ll*C(n,i)*cal(i)%mo)%mo;
		//cout<<i<<' '<<cal(i)<<' '<<C(n,i)<<' '<<sum[cal(i)]<<endl;
	}
	write(ans,'\n');
}
