    /*
     * n!        (n-g)!         (n-r)!
     * ----      ------         -----------------
     * g! (n-g)! (r-g)! (n-r)!  (b-g)! (n-r-b+g)!
     */
    res += choose(n, red) * choose(n, blue);
  }
  cout << res << endl;
}

