LL fact[300005];
LL DIV = 998244353;

LL modpow(LL ori, LL po) {
	LL res = 1;
	while (po > 0) {
		if (po & 1) {
			res *= ori;
			res %= DIV;
		}
		ori *= ori;
		ori %= DIV;
		po >>= 1;
	}
	return res;
}

LL combination2(LL m, LL n) {
	LL ret = fact[m];
	ret *= modpow(fact[m - n], DIV - 2);
	ret %= DIV;
	ret *= modpow(fact[n], DIV - 2);
	ret %= DIV;
	return ret;
}

LL combination(LL n, LL r) {
	if (r * 2 > n) r = n - r;
	LL dividend = 1;
	LL divisor = 1;
	for (LL i = 1; i <= r; ++i) {
		dividend *= (n - i + 1);
		divisor *= i;
	}
	return dividend / divisor;
}

int main() {
	FAST_IO;
	bool dbgF = true; // for D_OUT(str, value)  ... cout<< str <<" : "<< value <<endl;

	LL N, A, B, K;
	cin >> N >> A >> B >> K;
	LL ans = 0;

	// 赤色と青色に塗る。
	// 同じブロックに赤青両方OK（＝緑）。
	// Ax + By = K
	// 0<= x,y<= N
	// NCx * NCyの和をzで割る
	// x,yを全探索すれば良いが、xを定めればy=(K-Ax)/B で求まる

	// comb計算準備
	fact[0] = 1;
	for (long long i = 1; i <= N; i++) {
		fact[i] = fact[i - 1] * i;
		fact[i] %= DIV;
	}

	// solve
	FOR(x, 0, N + 1) {
		if ((K - A*x) % B != 0)continue;
		LL y = (K - A*x) / B;
		if (y<0 || y>N)continue;
		ans += (combination2(N, x) * combination2(N, y)) % DIV;
		ans %= DIV;
	}
	O(ans);

	return 0;
}

