	for(int i=z-2;i>=0;i--) fact_invmod[i]=fact_invmod[i+1]*(i+1)%MOD;
}

ll nCr_mod(int n,int r){
	return fact_mod[n] * fact_invmod[r]%MOD * fact_invmod[n-r]%MOD;
}

