int inv[MAX_N];

void init(int n = MAX_N, int m = MOD) {
  fac[0] = 1;
  for (int i = 1; i < n; i++) fac[i] = fac[i - 1] * i % m;
  ifac[n - 1] = inv_mod(fac[n - 1]);
  for (int i = n - 2; i >= 0; i--) ifac[i] = ifac[i+1] * (i + 1) % m;
  for (int i = 1; i < n; i++) inv[i] = ifac[i] * fac[i - 1] % m;
}

int nPr(int n, int r, int m = MOD) {
  if (r < 0 || n < r) return 0;
  return fac[n] * ifac[n - r] % m;
}

int nCr(int n, int r, int m = MOD) {
  if (r < 0 || n < r) return 0;
  return fac[n] * ifac[r] % m * ifac[n - r] % m;
}

int nHr(int n, int r, int m = MOD) {
  if (n < 0 || r < 0) return 0;
  return r == 0 ? 1 : nCr(n + r - 1, r);
}

