    ModCombination MC(N);
    mint ans = 0;
    for (ll i = 0; i <= N; i++) {
        ll p = K - A*i;
        if (p < 0 || p%B != 0) continue;
        ll j = p/B;
        ans += MC.get(N,i)*MC.get(N,j);
    }

