modint_t modpow(long long x, long long y)
{
  long long p = 1;

  for ( ; y; (x *= x) %= MOD, y >>= 1)
    if (y & 1)
      (p *= x) %= MOD;

  return modint_t(p);
}

modint_t modncr(int n, int r)
{
  assert(n >= 0);
  assert(r >= 0);

  if (n == 0)
    return r == 0 ? 1 : 0;

  if (r > n)
    return 0;

  modint_t c = 1;

  int dm = std::min(r, n - r);
  int dp = std::max(r, n - r);

  for (int i = dp + 1; i <= n; i ++)
    c *= i;

  for (int i = 2; i <= dm; i ++)
    c *= modpow(i, MOD - 2);

  return c;
}

class modncr_t {
public:
  std::vector<modint_t> compute(int n) const {
    std::vector<modint_t> a(n + 1);

    a[0] = a[n] = 1;

    for (int i = 1; i <= n / 2; i ++)
      a[i] = a[n - i] = a[i - 1] * (n - (i - 1)) * modpow(i, MOD - 2);

    return std::move(a);
  };
};


