		a0 += da * (b0 - b0 % db) / db;
		b0 -= (b0 - b0 % db);
	}
	else if(b0 < 0){
		a0 -= (b0 % db - b0 + db) / db * da;
		b0 += (b0 % db - b0 + db);
	}
