class Combination {
 private:
  vector<mint> f, invf;

 public:
  Combination(int n = 10000000) : f(n + 1, 1), invf(n + 1, 1) {
    for (int i = 1; i < n + 1; i++) {
      f[i] = f[i - 1] * i;
    }
    invf[n] /= f[n];
    for (int i = n; i > 0; i--) {
      invf[i - 1] = invf[i] * i;
    }
  }

  // nCr
  const mint combination(int n, int r) const {
    if (r < 0 || n < r) return 0;
    return f[n] * invf[r] * invf[n - r];
  }

  const mint combination_with_repetition(int n, int r) const { return combination(n + r - 1, r); }
};

