#include <bits/stdc++.h>
using namespace std;

const int MAX = 510000;
const int MOD = 998244353;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
    COMinit();

    long long N,A,B,K;
    cin >> N >> A >> B >> K;

    long long res = 0;
    for(long long x=0; x<=N; ++x) {
        if(K - A * x < 0 || (K - A * x) % B != 0) continue;
        long long y = (K - A * x) / B;
        res += COM(N, x) * COM(N, y) % MOD;
        res %= MOD;
    }
    cout << res << endl;
}

