#include <stdio.h>
constexpr long N = 300000;
constexpr long mod = 998244353;

long mpow(long a, long p){
    long x=a;
    long y=1;
    while(p>0){
        if(p&1){
            y=x*y%mod;
        }
        x=x*x%mod;
        p>>=1;
    }
    return y;
}

long minv(long a){
    return mpow(a, mod-2);
}

long fact[N+1];
void init_fact(){
    long t=1;
    for(long i=1; i<=N; i++){
        t=t*i%mod;
        fact[i]=t;
    }
}

long mcomb(long n, long r){
    return fact[n]*minv(fact[n-r]*fact[r]%mod)%mod;
}

int main(void){
    long n, a, b, k;
    scanf("%ld %ld %ld %ld", &n, &a, &b, &k);
    init_fact();
    long sum = 0;
    for(long i=0; i<=k/a+1; i++){
        long q=(k-a*i)/b;
        long m=(k-a*i)%b;
        if(m==0){
            if(i<=n && q<=n){
                sum = (sum+mcomb(n,i)*mcomb(n,q))%mod;
            }
        }
    }
    if(sum==0)sum++;
