INT dp(int n, int r)
{
    memset(C, 0, sizeof(C));
    C[0] = 1;
    for (int i = 1; i <= n; i++)
    {
        for (int j = min(i, r); j > 0; j--)
            C[j] = (C[j] + C[j-1])%P;
    }
    return C[r];
}
INT f(int n, int r)
{
    if (r==0) return 1;
    INT ni = n%P, ri = r%P;
    return (f(n/P, r/P)*dp(ni, ri)) % P;
}
int main()
{
