#include <bits/stdc++.h>
using namespace std;
#define ll long long

ll mod = 998244353;

ll modpower(ll a, ll r){ //a^r
    ll x = 1;
    while (r > 0) {
        if (r & 1) x = x * a % mod;
        r >>= 1;
        a = a * a % mod;
    }
    return x;
}

ll modinv(ll a){
    return modpower(a, mod-2);
}

vector<ll> fact(300001, 1);
vector<ll> invfact(300001, 1);
ll modconv(ll n, ll k){
	if (k > n || k < 0) return 0;
	return fact[n] * invfact[k]%mod * invfact[n-k] % mod;
}

ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll d = extgcd(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

int main(){
    ll N, A, B, K;
    cin >> N >> A >> B >> K;
    ll X, Y;
    ll G = extgcd(A, B, X, Y);
    if (K % G != 0) {
        cout << 0 << endl;
        return 0;
    }
    X *= (K/G);
    Y *= (K/G);

    //cout << X << " " << Y << endl;

    for (int i = 2; i <= 300000; i++) fact[i] = (fact[i-1]*i)%mod;
    for (int i = 2; i <= 300000; i++) invfact[i] = modinv(fact[i]);
    ll s = X, t = Y;
    ll ans = 0;
    while (s >= 0) {
        if (t >= 0) {
            ans = (ans+(modconv(N, s) * modconv(N, t))) % mod;
        }
        s -= B/G;
        t += A/G;
    }
    s = X+B/G;
    t = Y-A/G;
    while (t >= 0) {
        if (s >= 0) {
            ans = (ans+(modconv(N, s) * modconv(N, t)))%mod;
        }
        s += B/G;
        t -= A/G;
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long lint;
typedef unsigned long long ulint;
const lint MOD=998244353;

lint fact[300001],factinv[300001];

int gcd(lint a,lint b){
    if(a<b) return gcd(b,a);
    if(a%b==0) return b;
    return gcd(b,a%b);
}
pair<lint,lint> euc(lint a,lint b){
    if(a==1) return make_pair(1,0);
    if(b==1) return make_pair(0,1);
    if(a<b){
        auto r=euc(b,a);
        return make_pair(r.second,r.first);
    }
    if(a%b==1){
        return make_pair(1,-a/b);
    }
    lint q=a/b;
    auto r=euc(b,a%b);
    return make_pair(r.second,r.first-q*r.second);
}
lint comb(lint n,lint r){
    return fact[n]*factinv[r]%MOD*factinv[n-r]%MOD;
}
lint powm(lint x,lint e){
    if(e==0) return 1;
    if(e==1) return x%MOD;
    return powm(x*x%MOD,e/2)*(e%2==1?x:1)%MOD;
}

int main(){
    lint N,A,B,K;
    cin >> N >> A >> B >> K;

    fact[0]=1;
    for(int i=1;i<=N;i++) fact[i]=i*fact[i-1]%MOD;
    for(int i=0;i<=N;i++) factinv[i]=powm(fact[i],MOD-2);

    if(A<B){
        lint tmp=A;
        A=B;
        B=tmp;
    }
    lint C=gcd(A,B);
    if(K%C!=0){
        cout << 0 << endl;
        return 0;
    }
    A/=C;
    B/=C;
    K/=C;
    pair<lint,lint> p=euc(A,B);
    lint x=p.first,y=p.second;
    assert(A*x+B*y==1);
    x*=K; y*=K;

    if(x>0){
        lint cnt=x/B+1;
        x-=B*cnt;
        y+=A*cnt;
    }
    while(x<0){
        x+=B;
        y-=A;
    }

    assert(A*x+B*y==K && x>=0 && x-B<0);

    lint ans=0;
    while(0<=x && x<=N){
        if(0<=y && y<=N){
            ans+=comb(N,x)*comb(N,y)%MOD;
        }
        x+=B;
        y-=A;
    }
    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
