typedef long long  LL;
const int N=300010,mo=998244353;
int n,a,b,fac[N],ifac[N],ans;
LL k;

int qpow(int a,int b)
{
	int x=a;  a=1;
	while (b)
		{
			if (b&1)  a=1LL*a*x%mo;
			x=1LL*x*x%mo,b>>=1;
		}
	return a;
}

int C(int n,int m){return 1LL*fac[n]*ifac[m]%mo*ifac[n-m]%mo;}

void work()
{
	scanf("%d %d %d %lld",&n,&a,&b,&k),fac[0]=1;
	for (int i=1; i<=n; i++)  fac[i]=1LL*fac[i-1]*i%mo;
	ifac[n]=qpow(fac[n],mo-2);
	for (int i=n; i; i--)  ifac[i-1]=1LL*ifac[i]*i%mo;
	for (int i=0,j; i<=n; i++)
		if ((k-1LL*a*i)%b==0)
			{
				j=(k-1LL*a*i)/b;
				if ((0<=j)&&(j<=n))
					ans=(ans+1LL*C(n,i)*C(n,j))%mo;
			}
	printf("%d",ans);
}

int main()
{
	work();
	return 0;
}

