    }

    inv[MAXN - 1] = mod_pow(fact[MAXN - 1], MOD-2);
    for(long long i=MAXN - 2; i>=0; i--) {
        inv[i] = (inv[i+1] * (i+1)) % MOD;
    }
}

long long comb(long long n, long long r) {
