    ll a = poww( x,y/2 )%mod;
    ll res=a*a;
    res%=mod;
    if( y%2==1 ) res*=x;
    return res%mod;
}

ll inv( ll x )
{
    return poww( x,mod-2 );
}

ll binom( ll n, ll k )
{
    if(k>n) return 0;
    ll br = fac[n];
    ll naz = fac[k]*fac[n-k];
    naz%=mod;
    naz = inv( naz );
    ll ans = (br*naz)%mod;
    return ans;
}

