    if (n & 1) {
      b = prod(a, b);
    }
    a = prod(a, a);
    n /= 2;
  }
  return b;
}

int inv(int a) {
  return power(a, P - 2);
}

int div(int a, int b) {
  return prod(a, inv(b));
}

int C(const vector<int> &fact, int n, int k) {
  return div(fact[n], prod(fact[k], fact[n - k]));
}

bool solve() {
  int n, a, b;
  ll k;
  if (scanf("%d%d%d%lld", &n, &a, &b, &k) != 4) { return false; }

  vector<int> fact(n + 1);
  fact[0] = 1;
  for (int i = 1; i <= n; ++i) {
    fact[i] = prod(fact[i - 1], i);
  }

  int res = 0;
  for (ll x = 0; x <= n; ++x) {
    if ((k - x * a) % b != 0) {continue; }
    ll y = (k - x * a) / b;
    if (y > n || y < 0) { continue; }
    add(res, prod(C(fact, n, x), C(fact, n, (int)y)));
  }
  printf("%d\n", res);
  return true;
}

int main() {
  while (solve());
  return 0;
}

