const int O = 998244353;
int add(int a, int b)
{
	return (a + b) % O;
}
int sub(int a, int b)
{
	return (a + O - b) % O;
}
int mul(int a, int b)
{
	return (a * b) % O;
}

int pow(int a, int b)
{
	if (b == 0)
	{
		return 1;
	}
	else if (b == 1)
	{
		return a % O;
	}
	else if (b % 2 == 0)
	{
		int p = pow(a, b / 2);
		return (p * p) % O;
	}
	else
	{
		int p = pow(a, b / 2);
		p = (p * p) % O;
		return (p * a) % O;
	}
}

int divide(int a, int b)
{
	return mul(a, pow(b, O - 2));
}

int N, A, B, K;

signed main()
{
	cin >> N >> A >> B >> K;

	int p = 1;
	C[0] = 1;
	for (int i = 1; i <= N; i++)
	{
		p = divide(mul(p, (N - i + 1)), i);
		C[i] = p;
	}

	int ans = 0;
	int init_a = MIN(N, K / A);
	for (int a = init_a; a >= 0; a--)
	{
		int ama = K - (a * A);
		if (ama % B == 0)
		{
			int b = ama / B;
			if (a <= N && b <= N)
			{
				int n = C[a];
				n = mul(n, C[b]);
				ans = add(ans, n);
			}
		}
	}

	cout << ans << endl;
}

