map<lint, lint> memo;
int emod(lint x, lint p = MOD) {
  return (x % p + p) % p;
}
lint extgcd(lint a, lint b, lint& x, lint& y) {
  lint d = a;
  if (b != 0) {
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  } else {
    x = 1; y = 0;
  }
  return d;
}
lint power(lint x, lint n, lint mod = numeric_limits<lint>::max()) {
  assert(n >= 0);
  if (n == 0) return 1;
  return power(x * x % mod, n / 2, mod) * (n % 2 ? x : 1) % mod;
}
lint inv(lint x, lint p = MOD) {
  assert((x %= p) != 0);
  return power(x, p - 2, p);
}
lint comb(lint n, lint r, lint mod = 0) {
  assert(n >= 0 and r >= 0);
  if (memo.count(r)) return memo[r];
  if (r > n) return 0;
  r = min(r, n - r);
  lint res = 1;
  if (mod) for (lint i = 0; i < r; i++) res = res * (n - i) % mod * inv(i + 1) % mod;
  else for (lint i = 0; i < r; i++) res = res * (n - i) / (i + 1);
  return memo[r] = res;
}
