#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll mod = 998244353;

ll fac[300001],ifac[300001];

// x^n = (bit(i)?x^(2^i):1)の総乗
ll mpow(ll x,ll n){
    ll res = 1;
    while(n != 0){
        if(n&1) res = res*x % mod;
        x = x*x % mod;
        n = n >> 1; 
    }
    return res;
}
ll comb(ll a,ll b){
    if(a==0 && b==0) return 1;
    if(a<b || a<0) return 0;
    ll tmp = ifac[a-b]*ifac[b] % mod;
    return tmp*fac[a] % mod;
}

ll gcd(ll a,ll b){
   if(b<a) swap(a,b);
   ll r = a%b;
   while(r){
       a = b;
       b = r;
       r = a%b;
   }
   return b;
}

// ax + by = gcd(a,b) の特殊解(x,y)を返す 
pair<ll,ll> particular_solution(ll a,ll b){

    if(!b) return make_pair(1,0);

    pair<ll,ll> p = particular_solution(b,a%b);
    ll x1 = p.first,y1 = p.second;

    return make_pair(y1,x1-(a/b)*y1);
}

int main(){
    ll n,a,b,k,ans=0,d;
    cin >> n >> a >> b >> k;
    d = gcd(a,b);

    fac[0] = 1;
    ifac[0] = 1;
    for(int i = 0;i < 300000;i ++){
        fac[i+1] = fac[i]*(i+1) % mod;
        ifac[i+1] = ifac[i]*mpow(i+1,mod-2) % mod;
    }

    if(k==0) ans = 1;
    else if(k%d) ans = 0;
    else{
        pair<ll,ll> p = particular_solution(a,b);
        ll x0 = p.first,y0 = p.second;
        for(ll i = -(k*y0)/a+(y0>0&&k*y0%a?1:0);i <= (k*x0)/b;i ++){
            ll x,y;
            x = (k*x0-b*i)/d;
            y = (k*y0+a*i)/d;

            if(max(x,y)>n) continue;

            ans += comb(n,x)*comb(n,y);
            ans %= mod;
        }
    }
    cout << ans << endl;
    return 0;
}

