ll memo_fact_mod[MAX_N + 1];
ll memo_fact_inverse_mod[MAX_N + 1];
ll mod_pow(ll x, ll n){
	if(n == 0) return 1;
	ll res = mod_pow(x * x % MOD, n / 2);
	if(n % 2 == 1) res = res * x % MOD;
	return res;
}
ll fact_mod(ll n){
	ll res = 1;
	for(ll i = 1; i <= n; i++){
		res *= i;
		res %= MOD;
	}
	return res;
}
ll fact_inverse_mod(ll n){
	ll res = mod_pow(fact_mod(n), MOD - 2);
	return res;
}
ll combination(ll n, ll r){
	return (((fact_mod(n) * fact_inverse_mod(r)) % MOD) * fact_inverse_mod(n - r)) % MOD;
}
ll combination_with_memo(ll n, ll r){
	if(r == 0 || r == n) return 1;
	else return (((memo_fact_mod[n] * memo_fact_inverse_mod[r]) % MOD) * memo_fact_inverse_mod[n - r]) % MOD;
}

int main(){
	memo_fact_mod[0] = 0; memo_fact_mod[1] = 1LL;
	for(int i = 2; i <= MAX_N; i++){
		memo_fact_mod[i] = (memo_fact_mod[i - 1] * i) % MOD;
	}
	for(int i = 0; i <= MAX_N; i++){
		memo_fact_inverse_mod[i] = mod_pow(memo_fact_mod[i], MOD - 2);
	}
	cin >> N >> A >> B >> K;
	ll ans = 0;
	for(ll i = 0; i <= N; i++){
		if(i * A > K) break;
		if((K - A * i) % B != 0) continue;
		ll j = (K - A * i) / B;
		if(j > N) continue;
		ans += (combination_with_memo(N, i) * combination_with_memo(N, j)) % MOD;
		ans %= MOD;
	}
	cout << ans << endl;
	return 0;
}

