ll MOD = 998244353;

ll fact(int x, vector<ll> memo){
    if(x==0) return 1;
    if(x==1) return 1;
    if(memo[x]>0) return memo[x];
    memo[x] = x * fact(x-1, memo) % MOD;
    return memo[x];
}

template <typename T>
T modpow(T base, T exp, T modulus) {
  base %= modulus;
  T result = 1;
  while (exp > 0) {
    if (exp & 1) result = (result * base) % modulus;
    base = (base * base) % modulus;
    exp >>= 1;
  }
  return result;
}

ll combination(int n, int r, vector<ll> memo) {
    return fact(n, memo) * modpow(fact(r, memo), MOD-2, MOD)* modpow(fact(n-r, memo), MOD-2, MOD) % MOD;
}

