long int expbkp(long int b,long int k,long int p){
  long int qb = b;
  b = DP[b];
  vector<long int> modp(1,b % p);
  long int q = b % p,ans = 1;
  for(long int i = 1;pow(2,i) <= k;i++){
    q = (q*q)%p;
    modp.push_back(q);
  }
  for(long int i = 0;pow(2,i) <= k;i++){
    q = pow(2,i);
    if(k & q)ans = (ans * modp[i])%p;
  }
  memoexpbkp[qb] = ans;
  return ans;
}

long int nckmodp(long int n,long int k,long int p){
  if(memonckmodp[k])return memonckmodp[k];
  long int ans = (((DP[n] * expbkp(k,p-2,p))%p) * expbkp(n-k,p-2,p))%p;
  memonckmodp[k] = ans;
  return ans;
}

long int G(long int A,long int B){
  long int ans = 1,i = 2;
  while(i <= A && i <= B){
    while(1){
      if(A%i == 0 && B%i == 0 && i <= A && i <= B){
        A /= i;
        B /= i;
        ans *= i;
      }
      else break;
    }
    i++;
  }
  return ans;
}

vector<long int> first(long int N,long int A,long int B,long int K){
