llint pow(llint a, llint n)
{
	if(n == 0) return 1;
	if(n % 2){
		return ((a%mod) * (pow(a, n-1)%mod)) % mod;
	}
	else{
		return pow((a*a)%mod, n/2) % mod;
	}
}

void make_fact()
{
	llint val = 1;
	fact[0] = 1;
	for(int i = 1; i < 300005; i++){
		val *= i;
		val %= mod;
		fact[i] = val;
	}
	for(int i = 0; i < 300005; i++){
		fact_i[i] = pow(fact[i], mod-2);
	}
}

llint comb(llint n, llint k)
{
	llint ret = 1;
	ret *= fact[n];
	ret *= fact_i[k], ret %= mod;
	ret *= fact_i[n-k], ret %= mod;
	return ret;
}

llint N, A, B, K;

int main(void)
{
	make_fact();
	cin >> N >> A >> B >> K;

	llint ans = 0;
	for(int y = 0; y <= N; y++){
		if(K - B*y < 0 || (K - B*y) % A) continue;
		llint x = (K - B*y) / A;
		if(x < 0 || x > N) continue;
		//cout << x << " " << y << endl;
		llint tmp = comb(N, x);
		tmp *= comb(N, y);
		tmp %= mod;
		ans += tmp, ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

