ll solve(ll N, ll A, ll B, ll K) {
  ll ans = 0;
  ll start = max(0LL, K-N*B);
  for(ll a = 0; a <= N; a++) {
    if(a*A > K) break;
    ll b = (K-(a*A))/B;
