}

ll f(ll N, ll x, ll y, ll z) {
	ll ret = fact[N] * fact_inv[x - z] % mod;
	ret *= fact_inv[z];
	ret %= mod;
	ret *= fact_inv[y - z];
	ret %= mod;
	ret *= fact_inv[N - (x + y - z)];
	ret %= mod;
	return ret;
}

void init() {
	fact[0] = fact_inv[0] = 1;

	for(int i = 1; i <= 300010; i++) {
		fact[i] = (fact[i - 1] * i) % mod;
		fact_inv[i] = pow_mod(fact[i], mod - 2, mod) % mod; // フェルマーの小定理で逆元を求める
	}
}

ll inv(ll x) {
	return pow_mod(x, mod - 2, mod) % mod;
}


int main() {
	ll N, A, B, K;
	cin >> N >> A >> B >> K;

	init();

	ll ans = 0;
	for(ll x = 0; x <= N; x++) {
		if (K < A * x) continue;
		if ((K - A * x) % B != 0) continue;

		ll y = (K - A * x) / B;
		if (y > N) continue;

		ll z_min = max(x + y - N, 0LL);
		ll z_max = min(x, y);
		if (z_min == 0 || N - (x + y - z_min) == 0) {

			//cout << "plus(f): " << f(N, x, y, z_min) << endl;
			ans += f(N, x, y, z_min);
			ans %= mod;
			z_min++;
		}
		if (z_min > z_max) continue;

		//cout << x << ", " << y << ", " << z_min << ", " << z_max << endl;

		ll a = f(N, x, y, z_min);
		//cout << "a:" << a << endl;

		ll r_ue = ((x - z_min) * (y - z_min)) % mod;
		ll r_sita = ((z_min * N % mod - (z_min * (x + y - z_min)) % mod) + mod * mod) % mod;
		ll r = r_ue * inv(r_sita) % mod;

		//cout << "r: " << r_ue << "/" << r_sita << ": " << r << endl;
		ll n = (z_max - z_min + 1 + mod) % mod;

		if (r == 1) {
			ans += a * n;
			ans %= mod;
			continue;
		}
		ll plus = (pow_mod(a, n, mod) - pow_mod(a, n, mod) * pow_mod(r, n, mod) + mod * mod) % mod * inv((1 - r + 2 * mod) % mod) % mod;

		//cout << "--plus: " << plus << endl;
