        long long r=1,b=fac[i],e=MOD-2;
        while(e){
            if(e&1){
                r=(r*b)%MOD;
            }
            b=(b*b)%MOD;
            e >>=1;
        }
        facIE.push_back(r);
    }
    for(int i=0;i<=N;i++){
        long long r=fac[N];
        r = (r*facIE[i])%MOD;
        r = (r*facIE[N-i])%MOD;
        comb.push_back(r);
    }
    return comb;
}



signed main(void){
    long long N,A,B,K;
    cin >> N >> A >> B >> K;
    vector<long long> nC;
    nC = binomial_coefficient(N);

    const long long MOD = 998244353;
    long long Ans=0;

    //REP(i,N+1){cout << nC[i] << " ";}cout << endl;

    REP(i,N+1){
        long long b=K-A*i;
        if(b>=0 && b%B==0 && b/B<=N){
            b/=B;
            Ans+=nC[i]*nC[b];
            Ans%=MOD;
        }
    }
    cout << Ans << endl;
    return 0;
}

