LL qpw(LL a, LL b) {
	LL res = 1;
	while(b) {
		if(b & 1) res = res * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return res;
}

LL gcd(LL a, LL b) {
	return b ? gcd(b, a % b) : a;
}

int main() {
