	f[1] = 1;
	for(LL i = 2; i <= n; i++) f[i] = f[i - 1] * i % mod;
	g[n] = qpw(f[n], mod - 2);
	for(LL i = n - 1; i >= 1; i--) g[i] = g[i + 1] * (i + 1) % mod;
	g[0] = 1;
	int s = b / gcd(a, b);
	for(LL i = 0; i <= n + n;i++)
		if((k - i * a) % b == 0) {
			tot = i; break;
		}
	for(LL i = tot; i <= n + n && i * a <= k; i += s) {
		LL num = (k - i * a);
		if(num % b == 0) {
			LL an = i, bn = num / b;
			LL cn = min(an, bn);
			for(LL j = 0; j <= cn; j++) {
				if(an + bn - j <= n) {
					ans += f[n] * g[an - j] % mod * g[bn - j] % mod * g[j] % mod * g[n - an - bn + j] % mod;
				}
				ans = ans >= mod ? ans - mod : ans;
			}
		}
	}
	printf("%lld\n", ans);
}

