    {
        assert(n < size);
        return fact[n];
    }
    ll inverse(const int n) const
    {
        assert(n < size);
        return inv[n];
    }
    ll inverseFactorial(const int n) const
    {
        assert(n < size);
        return inv_fact[n];
    }
    ll permutation(const int n, const int k) const
    {
        assert(n < size);
        assert(k <= n);
        return (fact[n] * inv_fact[n - k]) % mod;
    }
    ll combination(const int n, const int k) const
    {
        assert(n < size);
        assert(k <= n);
        return (((fact[n] * inv_fact[k]) % mod) * inv_fact[n - k]) % mod;
    }
    ll homogenious(const int n, const int k) const { return (n == 0 and k == 0 ? 1 : combination(n + k - 1, k)); }

private:
