ll GCD(ll A,ll B){
  if(B==0){
    return A;
  }else{
    return GCD(B,A%B);
  }
}
//
ll LCM(ll A,ll B){
  ll G=GCD(A,B);
  return A/G*B;
}
//
//
ll pow(ll x,ll n,ll mod){
  ll res=1;
  if(n>0){
    res=pow(x,n/2,mod);
    if(n%2==0){
      res=(res*res)%mod;
    }else{
      res=(((res*res)%mod)*x)%mod;
    }
  }
  return res;
}
//
ll inv(ll n,ll mod){
  return pow(n,mod-2,mod);
}
//
ll nCk(ll n,ll k,ll mod){
  ll res=1;
  for(int i=n;i>n-k;i--){
    (res*=i)%=mod;
  }
  for(int i=k;i>=1;i--){
    (res*=inv(i,mod))%=mod;
  }
  return res;
}
