size_t gcd(size_t x, size_t y)
{
    if (x > y) {
        std::swap(x, y);
    }

    while (y % x != 0) {
        size_t mod = y % x;
        y = x;
        x = mod;
    }

    return x;
}


size_t modpow(size_t a, size_t n, size_t m)
{
    if (n == 0) {
        return 1;
    } else if (n == 1) {
        return a % m;
    } else if (n % 2 == 0) {
        size_t sq = modpow(a, n / 2, m);
        return (sq * sq) % m;
    } else {
        return (modpow(a, n - 1, m) * a) % m;
    }
}

size_t moddiv(size_t x, size_t y, size_t mod)
{
    return (x * modpow(y, mod - 2, mod)) % mod;
}

