#define MAXN 300000
#define LL long long
#define MO 998244353
LL fac[MAXN+5],inv[MAXN+5];
LL powmod(LL a,LL b)
{
	LL ret=1;
	while(b)
	{
		if(b&1) ret=ret*a%MO;
		a=a*a%MO;
		b>>=1;
	}
	return ret;
}
void Init()
{
	fac[0]=inv[0]=1;
	for(int i=1;i<=MAXN;i++)
		fac[i]=i*fac[i-1]%MO;
	inv[MAXN]=powmod(fac[MAXN],MO-2);
	for(int i=MAXN-1;i>=1;i--)
		inv[i]=(i+1)*inv[i+1]%MO;
}
void gcd(LL a,LL b,LL &x,LL &y,LL &d)
{
	if(b==0)
	{
		x=1;y=0;d=a;
		return;
	}
	gcd(b,a%b,y,x,d);
	y-=(a/b)*x;
}
LL n,A,B,k,x,y,d,tot;
LL Solve(int x1,int x2,int x3)
{
	return fac[n]*inv[x1]%MO*inv[x2]%MO*inv[x3]%MO*inv[n-x1-x2-x3]%MO;
}
int main()
{
	Init();
	scanf("%lld%lld%lld%lld",&n,&A,&B,&k);
	gcd(A,B,x,y,d);
	if(k%d)
	{
		printf("0\n");
		return 0;
	}
	A/=d,B/=d,k/=d;
	x*=k,y*=k;
	LL ad1=B,ad2=A;
	LL ans=0;
	LL j=x/ad1*ad2+y;
	LL i=x%ad1;
	for(;i<=n&&j>=0;i+=ad1,j-=ad2)
	{
		LL m=i+j;
		for(LL c=min(i,j);c>=0&&m-c<=n;c--)
		{
			ans=(ans+Solve(i-c,j-c,c))%MO;
		}
	}
	printf("%lld\n",ans);
}

