using namespace std;

template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }

  static int get_mod() { return mod; }
};

using modint = ModInt< mod >;


void solve()
{
	const ll M=998244353;
	ll n,a,b,k;
	cin>>n>>a>>b>>k;
	if(k%gcd(a,b)!=0){
		cout<<0<<"\n";
		return;
	}
	if(k/(a+b)>n){
		cout<<0<<"\n";
		return;
	}
	ll x=gcd(a,b);
	a/=x;b/=x;k/=x;
	vector<map<ll,ModInt<M>>>dp(2);
	dp[0][0]=1;
	rep(i,n){
		ll x=gcd(a,b);
		for(auto j=dp[i%2].begin();j!=dp[i%2].end();++j){
			if(j->first+(a+b)*(n-i)<k)continue;
			if((k-j->first)%x!=0)continue;
			if(j->first+a<=k){
				dp[(i+1)%2][j->first+a]=0;
			}
			if(j->first+b<=k){
				dp[(i+1)%2][j->first+b]=0;
			}
			if(j->first+a+b<=k){
				dp[(i+1)%2][j->first+a+b]=0;
			}
			dp[(i+1)%2][j->first]=0;
		}
		for(auto j=dp[i%2].begin();j!=dp[i%2].end();++j){
			if(j->first+(a+b)*(n-i)<k)continue;
			if((k-j->first)%x!=0)continue;
			if(j->first+a<=k){
				dp[(i+1)%2][j->first+a]+=dp[i%2][j->first];
			}
			if(j->first+b<=k){
				dp[(i+1)%2][j->first+b]+=dp[i%2][j->first];
			}
			if(j->first+a+b<=k){
				dp[(i+1)%2][j->first+a+b]+=dp[i%2][j->first];
			}
			dp[(i+1)%2][j->first]+=dp[i%2][j->first];
		}
	}
	cout<<dp[n%2][k]<<"\n";
}

