const ll mod = 998244353;
int main(){
	int n;
	ll a,b;
	ll k;
	scanf("%d%lld%lld%lld",&n,&a,&b,&k);
	ll inv[300010];
	ll jun[300010];
	ll gyaku[300010];
	inv[1] = 1;
	for(ll i=2;i<=n;i++){
		inv[i] = mod - (mod/i) * inv[mod%i] % mod;
	}
	for(ll i=1;i<=n;i++){
		if(i==1){
			jun[i] = 1;
			gyaku[i] = 1;
		}else{
			jun[i] = (jun[i-1] * i) % mod;
			gyaku[i] = (gyaku[i-1] * inv[i]) % mod;
		}
	}
	ll ans = 0;
	for(ll i=0;i<=n;i++){
		if(k-a*i>=0&&(k-a*i)%b==0){
			ll j = (k-a*i) / b;
			ll l,r;
			if(i==0||i==n) l = 1;
			else l = ((jun[n] * gyaku[i]) % mod) * gyaku[n-i] % mod;
			if(j==0||j==n) r = 1;
			else r = ((jun[n] * gyaku[j]) % mod) * gyaku[n-j] % mod;
			ans += l * r % mod;
			ans %= mod;
		}
	}
	printf("%lld\n",ans);
}

