const int SET_FACT_MAX = 300005;
mint fact[SET_FACT_MAX];
mint revFact[SET_FACT_MAX];

void setFact() {
	const int N = SET_FACT_MAX;
	fact[0] = 1;
	for (int i = 1; i < N; i++) {
		fact[i] = fact[i - 1] * i;
	}
	revFact[N - 1] = fact[N - 1] ^ (mod - 2);
	for (int i = N - 2; i >= 0; i--) {
		revFact[i] = revFact[i + 1] * (i + 1);
	}
}

mint nPr(int n, int r) { return n >= r ? fact[n] * revFact[n - r] : 0; }
mint nCr(int n, int r) { return nPr(n, r) * revFact[r]; }

void Main() {
	int n = ri();
	ll a = ri(), b = ri(), k = ri();

	setFact();
	mint ans = 0;

	rep(i, n+1) {
		ll sum_a = a * i;
		ll rest = k - sum_a;
		if (rest >= 0 && rest % b == 0) {
			int j = rest / b;
			ans += nCr(n, i) * nCr(n, j);
		}
	}
	print(ans);

}

