const int MOD = 998244353;

void mul(long long& a, long long b) {
	a *= b;
	a %= MOD;
}

long long prod(long long a, long long b) {
	return (a * b) % MOD;
}

long long binpow(long long a, long long b) {
	long long res = 1;
	while (b) {
		if (b & 1)
			mul(res, a);
		b >>= 1;
		mul(a, a);
	}
	return res;
}

long long inv(long long a) {
	return binpow(a, MOD - 2);
}

const int N = 3e5 + 1;
long long factorial[N];
long long invfactorial[N];

void add(long long& a, long long b) {
	a += b;
	if (a >= MOD)
		a -= MOD;
}

long long choose(long long n, long long k) {
	return prod(factorial[n],
				prod(invfactorial[k], 
					 invfactorial[n - k])
				);
}

int main() {
	int n = readInt(), a = readInt(), b = readInt();
	long long k = readInt<long long>();
	factorial[0] = 1;
	invfactorial[0] = 1;
	for (int i = 1; i <= n; ++i) {
		factorial[i] = i;
		mul(factorial[i], factorial[i - 1]);
		invfactorial[i] = inv(factorial[i]);
	}
	long long ans = 0;
	for (int i = 0; i <= n; ++i, k -= a) {
		if (k < 0)
			break;
		if (k % b != 0) 
			continue;
		long long other = k / b;
		if (other > n) continue;
		long long there = prod(choose(n, i), choose(n, other));
		add(ans, there);
	}
	cout << ans << endl;
	return 0;
}

