ll lt(ll x)
{
    if (x==1) return 1;
    ll res=1;
    int y =modprime -2;
    while (y>0)
    {
        if (y&1) res=(res*x)%modprime;
        y=y>>1;
        x=(x*x)%modprime;
    }
    return res;
}

ll compute(ll x, ll y)
{
    if (y>=x) return 1;
    if (y==0) return 1;
    ll inv1=lt(fact[y]);


    ll inv2=lt(fact[x-y]);
    ll ans = (fact[x]*inv1)%modprime;
    ans=(ans*inv2)%modprime;

    return (ans);

}

