ll MOD = 998244353;
ll Inv[MAX], fact[MAX], factInv[MAX];

void calc_modinv() {
    Inv[1] = 1;
    for(ll i=2; i<=MAX; i++) {
        Inv[i] = (MOD - MOD / i) * Inv[MOD%i] % MOD;
    }
}

void calc_factinv() {
    fact[0] = factInv[0] = 1;
    for(ll i=1; i<=MAX; i++) {
        fact[i] = (fact[i-1] * i) % MOD;
        factInv[i] = (factInv[i-1] * Inv[i]) % MOD;
    }
}

long long nCr(ll n, ll r) { 
    if(n - r >= 0 && r >= 0) return fact[n] * factInv[r] % MOD * factInv[n - r] % MOD;
    else return 0;
}

int main(void) {
