    for(na=0; na<=K/a; na++) {
        if((K-na*a)%b) continue;
        nb = (K-na*a)/b;
        for(nc=0; nc<=min(na,nb); nc++) {
            ans += nCr(N, na+nb-nc) * nCr(na+nb-nc, nc) % MOD * nCr(na+nb-2*nc, na-nc) % MOD;
            ans %= MOD;
        }
    }

    return !printf("%lld\n", ans);
}

