    ll n, a, b, k;
    cin >> n >> a >> b >> k;
    ll ans = 0;
    for (ll red = 0; red <= n; red++) {
        if ((k - red) % b != 0) {
            continue;
        }
        ll blue = (k - red) / b;
        ans += nCk(n, red) * nCk(n, blue);
    }
    cout << (ans % 998244353);
    return 0;
}

