void solve(long long N, long long A, long long B, long long K) {
    mod_fact(MAX_P, MOD);
    ll res = 0;
    rep(i, N + 1) {
        if ((K - A * i) % B != 0) continue;
        ll bc = (K - A * i) / B;
        if (bc < 0 || bc > N) continue;
        res = (res + (mod_comb(N, i, MOD) * mod_comb(N, bc, MOD)) % mod) % mod;
    }
