int solve_s(int a,int b,li k,li& x,li& y){
  x=y=k/(a+b);
  k=k-(a+b)*x;
  li xx[2]{1,0},yy[2]{0,1},s[2]{a,b};
  if(df) printf("%ld %ld %ld ",xx[0],yy[0],s[0]);
  if(df) printf("q:%ld %ld %ld rem:%d\n",x,x,y,k);
  while(s[1]){
    li q=s[0]/s[1], temp;
    temp=xx[0]-xx[1]*q;
    xx[0]=xx[1]; xx[1]=temp;
    temp=yy[0]-yy[1]*q;
    yy[0]=yy[1]; yy[1]=temp;
    temp=s[0]-s[1]*q;
    s[0]=s[1]; s[1]=temp;
    q=k/s[0];
    x+=q*xx[0];
    y+=q*yy[0];
    k-=q*s[0];
    if(df) printf("%ld %ld %ld ",xx[0],yy[0],s[0]);
    if(df)printf("q:%ld %ld %ld rem:%d\n",q,q*xx[0],q*yy[0],k);
  }
  if(k){
    if(df) printf("rem:%d",k);
    return 0;
  }
  return s[0];
}

li binom(int n,li r){
  static vector<li> fact(n+1,0),fi(n+1,0),inv(n+1,0);
  if(r<0 or r>n) return 0;
  if(fact.at(0)==0){
    fact.at(0)=fi.at(0)=1;
    fact.at(1)=fi.at(1)=inv.at(1)=1;
    repa(i,2,n+1){
      fact.at(i)=fact.at(i-1)*i%MOD;
      inv.at(i)=(MOD-(MOD/i))*inv.at(MOD%i)%MOD;
      fi.at(i)=fi.at(i-1)*inv.at(i)%MOD;
    }
    // if(df){
    //   print(fact,"fct");
    //   print(fi,"f-1");
    //   print(inv,"inv");
    // }
  }
  li s=fact.at(n);
  (s*=fi.at(r))%=MOD;
  (s*=fi.at(n-r))%=MOD;
  return s;
}

li calc(li x, li y, int n){
  return binom(n,x)*binom(n,y)%MOD;
}

