int MOD = 998244353;
constexpr int MAX_N = 303030;

int fact[MAX_N];
int ifact[MAX_N];

int power(int x, int n) {
	int res = 1LL;
	while (n > 0) {
		if (n & 1) (res *= x) %= MOD;
		(x *= x) %= MOD;
		n >>= 1;
	}
	return res % MOD;
}

int inv(int x) {
	return power(x, MOD - 2);
}

int nCr(int n, int r) {
	if (n < 0 || r < 0 || r > n) return 0;
	if (r > n / 2) r = n - r;
	return fact[n] * ifact[r] % MOD * ifact[n - r] % MOD;
}

signed main(){
  int n,a,b,k;cin>>n>>a>>b>>k;
	fact[0] = ifact[0] = 1;
	for(int i=1;i<MAX_N;++i) {
		(fact[i] = fact[i - 1] * i) %= MOD;
		ifact[i] = inv(fact[i]);
	}

  int ans = 0;
  for(int aa=0;aa<=n;++aa){
    int bb = (k-aa*a)/b;
    if((k-aa*a)%b!=0) continue;
    if(!(aa>=0&&bb>=0)) continue;

    int aaa = aa;
    for(int ab=0;aaa>=0 && bb>=0;){
      int res = nCr(n,aaa) % MOD;
      // cerr << "(a,b)" << "(" << aaa << "," << bb << ")" << endl;
      (res *= nCr(n-aaa,bb)) %= MOD;
      (res *= nCr(n-aaa-bb,ab)) %= MOD;
      // cerr << res << endl;
      (ans += res) %= MOD;
      --aaa;--bb;++ab;
    }
  }
  cout<<ans<<endl;

  return 0;
}

