}

ll minv(ll a){
    return mpow(a, MOD-2);
}

ll fact[333333];
ll ncr[333333];
void init_ncr(ll n){
    ll t=1;
    fact[0] = 1;
    for(ll i=1;i <= n;i++){
        t = (t * i) % MOD;
        fact[i] = t;
    }
    for(ll r=0;r <= n/2;r++){
        ncr[r] = fact[n] * minv(fact[n-r]*fact[r]%MOD) %MOD;
    }
    for(ll r=0;r <= n/2;r++){
        ncr[n-r] = ncr[r];
    }
}

