typedef long long ll;

ll n,a,b,k,ansf;
ll md[MAX],imd[MAX];
ll put(ll t,ll exp){
  if(t==0)return 0;
  if(exp==0)return 1;
  if(exp==1)return t%MOD;
  ll aux;
  if(exp%2){
    aux=put(t,exp-1);
    return (aux*t)%MOD;
  }
  aux=put(t,exp/2);
  return (aux*aux)%MOD;
}
ll comb(ll na,ll ka){
  if(na*ka==0)return 1;
  if(ka==1||ka==na-1)return na;
  return (((md[na]*imd[ka])%MOD)*imd[na-ka])%MOD;
}

