const ll MOD = 998244353LL;

long long mod_inverse(long long x) {
	long  long ret = 1; long long n = MOD - 2;
	while (n) {
		if (n & 1)ret = ret * x%MOD;
		x = x * x%MOD; n >>= 1;
	}
	return ret;
}

ll fact[300300], fact_inv[300300];

ll comb(ll n, ll r) {
	ll ret = ((fact[n] * fact_inv[n - r]) % MOD )* fact_inv[r] % MOD;
	return ret;
}

