int C(int n, int m, int mod) {
    if (m < n) return 0;
    // printf("C(%lld, %lld) is %lld\n", n, m,
    //        (inv[n] * ((inv[m - n] * fac[m]) % mod)) % mod);
    return (inv[n] * ((inv[m - n] * fac[m]) % mod)) % mod;
}

