long long int conbi(long long int n,long long int k){
  long long int f=1;
  long long int g=1;
  if(k==0) return 1;
  else{
  for(long long int i=1;i<=k;i++) f*=i;
  for(long long int i=0;i<=k-1;i++) g*=n-i;
  return g/f;
  }
}
