#define P 998244353
#define M 400000
int n, A, B; ll m;
int F[M], IF[M];

void gcd(int a,int b,int &x,int &y) {
  if(b==0){x=1,y=0;return;}
  gcd(b,a%b,y,x),y-=a/b*x;
}
int inv(int n) {
  int x,y;gcd(n,P,x,y);
  if(x<0)x+=P;return x;
}

int C(int n, int k) {
	return (ll)F[n]*IF[k]%P*IF[n-k]%P;
}

int main() {
	F[0]=1;for(int i=1;i<M;i++)F[i]=(ll)F[i-1]*i%P;
	IF[M-1]=inv(F[M-1]);for(int i=M-1;i;i--)IF[i-1]=(ll)IF[i]*i%P;
	cin >> n >> A >> B >> m;
	int S = 0;
	for (int i = 0; i <= n; i ++) {
		ll r = m-(ll)i*A;
		if (r < 0) continue;
		if (r%B != 0) continue;
		r /= B;
		if (r > n) continue;
		S = (S+(ll)C(n, i)*C(n, r)%P)%P;
	}
	cout << S << endl;
	return 0;
}

