const int MOD = 998244353;
ll N, A, B, K;

ll fact[300001], fact_i[300001];

ll power(int x, int y) {
    if (y == 1) return x;
    ll p = power(x, y >> 1);
    if (y & 1) return p * p % MOD * x % MOD;
    else return p * p % MOD;
}

ll inv(ll n) {
    return power(n, MOD - 2);
}

void init() {
    fact[0] = 1;
    REP(i, N) fact[i + 1] = fact[i] * (i + 1) % MOD;
    fact_i[N] = inv(fact[N]);
    REP(i, N) fact_i[N - i - 1] = fact_i[N - i] * (N - i) % MOD;
}

ll nCr(ll n, ll r) {
    return fact[n] * fact_i[r] % MOD * fact_i[n - r] % MOD;
}

int main() {
    cin >> N >> A >> B >> K;
    init();

    ll ans = 0;
    REP(x, N + 1) {
        int rest = K - A * x;
        if (rest < 0 || rest > B * N || rest % B) continue;

        int y = rest / B;
        ans += nCr(N, x) * nCr(N, y) % MOD;
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

