class CombLib {
private:
	int mMax, mMod;
	vector<ll> fac, finv, inv;
public:
	CombLib(int modNum = 1000000007, int maxSize = 510000) {
		mMax = maxSize, mMod = modNum;
		fac = vector<ll>(maxSize);
		finv = vector<ll>(maxSize);
		inv = vector<ll>(maxSize);
	    fac[0] = fac[1] = 1;
    	finv[0] = finv[1] = 1;
    	inv[1] = 1;
    	for (int i = 2; i < mMax; i++){
	        fac[i] = fac[i - 1] * i % mMod;
    	    inv[i] = mMod - inv[mMod%i] * (mMod / i) % mMod;
        	finv[i] = finv[i - 1] * inv[i] % mMod;
    	}
	}

	ll calc(int n, int k){
    	if (n < k) return 0;
    	if (n < 0 || k < 0) return 0;
    	return fac[n] * (finv[k] * finv[n - k] % mMod) % mMod;
	}
};

int main(void)
{
	cin.tie(0); ios::sync_with_stdio(0); cout << fixed << setprecision(20);

	ll N, A, B, K; cin >> N >> A >> B >> K;
	CombLib cl(998244353);
	ll ans = 0;
	ll anum = K / A + 1;
	for (ll i = 0; i < anum; ++i) {
		ll xa = i * A;
		ll rest = K - xa;
		if (rest < 0) continue;
		if (rest % B != 0) continue;
		ll bnum = rest / B;
		if ((i * A + bnum * B) == K) ans += cl.calc(N, i) * cl.calc(N, bnum);
		ans %= 998244353;
	}

	cout << ans << endl;

	return 0;
}

