const int mod=998244353;
const int maxn=3e5+7;

ll fac[maxn],inv[maxn];

ll power(ll a,ll b){
    ll ans=1;
    while(b){
        if(b&1) ans=ans*a%mod;
        b>>=1;
        a=a*a%mod;
    }
    return ans;
}

void init(){
    fac[0]=1,fac[1]=1;
    for(int i=2;i<=maxn;i++) fac[i]=fac[i-1]*i%mod;
    inv[maxn]=power(fac[maxn],mod-2);
    for(int i=maxn-1;i>=0;i--) inv[i]=inv[i+1]*(i+1)%mod;
}

ll c(ll n,ll m){
    if(n<m) return 0;
    if(n==m) return 1;
    return fac[n]*inv[m]%mod*inv[n-m]%mod;
}


int main (){
    init();
    ll n,a,b;
    ll k,ans=0;
    scanf("%lld %lld %lld %lld",&n,&a,&b,&k);
    for(ll x=1;x<=n;x++){
        if((k-a*x)%b) continue;
        ll y=(k-a*x)/b;
        ans=(ans+c(n,x)*c(n,y))%mod;
    }
    printf("%lld\n",ans);
    return 0;
}

#include <bits/stdc++.h>
