const ll MOD = 998244353;

const int MAXN = 301000;

vl fact(MAXN);
vl rfact(MAXN);

ll mod_pow(ll x, ll p, ll M = MOD) {
	ll a = 1;
	while (p) {
		if (p % 2)
			a = a * x%M;
		x = x * x%M;
		p /= 2;
	}
	return a;
}

ll mod_inverse(ll a, ll M = MOD) {
	return mod_pow(a, M - 2, M);
}

void set_fact(ll n, ll M = MOD) {
	fact[0] = fact[1] = rfact[0] = rfact[1] = 1;
	for (ll i = 2; i <= n; i++) {
		fact[i] = i * fact[i - 1] % M;
		rfact[i] = mod_inverse(fact[i], M);
	}
}

ll nCr(ll n, ll r, ll M = MOD) {
	ll ret = fact[n];
	ret = (ret*rfact[r]) % M;
	ret = (ret*rfact[n - r]) % M;
	return ret;
}

int main() {
	ll n, a, b, k;
	cin >> n >> a >> b >> k;
	set_fact(n + 10);
	vector<pll> pos;
	rep(i, n + 1) {
		if ((k - i * a) % b == 0) {
			ll x = i, y = (k - i * a) / b;
			if (y <= n) {
				pos.push_back(pll(x, y));
			}
		}
	}
	ll ans = 0;
	rep(i,pos.size()){
		ll temp = 1;
		ll x = pos[i].first, y = pos[i].second;
		temp *= nCr(n, x);
		temp %= MOD;
		temp *= nCr(n, y);
		temp %= MOD;
		ans += temp;
		ans %= MOD;
	}
	cout << ans << endl;
}

