	cin >> n >> a >> b >> k;
	if(k == 0){
		cout << 1 << endl;
		return 0;
	}
	for(ll i = 1; i <= n; i++){

		if(!((k - a * i) % b)){
			ll t1 = i;
			ll t2 = ((k - a * i) / b); 
			ll cnt = C(n, t1);
			cnt %= mod;
			cnt *= C(n, t2);
			cnt %= mod; 
			ans += cnt;
			ans %= mod;
		}
	}
	cout << ans << endl;
	return 0;
}

