using namespace std;
const int mod = 998244353, N = 3 * 1e5 + 1;
long long fact[N], invfact[N];

int fp(long long a, int p)
{
    long long ans = 1;
    while(p)
    {
        if(p % 2)
            ans *= a, ans %= mod;
        a *= a;
        a %= mod;
        p /= 2;
    }
    return ans;
}

long long cnt(int k, int n)
{
    return fact[n] * invfact[k] % mod * invfact[n - k] % mod;
}

int main()
{
    int n, a, b;
    long long ans(0), k;
    cin >> n >> a >> b >> k;
    if(!k)
        return cout << 1, 0;
    fact[0] = 1; invfact[1] = 1; invfact[0] = 1;
    for(int i = 1; i <= N; i++)
        fact[i] = fact[i - 1] * i % mod;
    for(int i = 2; i <= N; i++)
        invfact[i] = fp(fact[i], mod - 2);
