long long powmod(long long n, long long k){
    if (k == 0) return 1;
    else if (k % 2 == 0){
        long long tmp = powmod(n, k / 2);
        return tmp * tmp % mod;
    }
    else return powmod(n, k - 1) * n % mod;
}

long long inverse(long long n) {
    return powmod(n, mod - 2);
}

vector<long long> init_fact(long long n) {
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
        inv_fact[i] = inverse(fact[i]);
    }
    return fact;
}

long long nCk(long long n, long long k) {
    if (n - k < k) k = n - k;
    return (fact[n] * (inv_fact[n - k] * inv_fact[k]) % mod) % mod;
    //return (fact[n] * ((inverse(fact[n - k]) % mod) * (inverse(fact[k]) % mod)) % mod) % mod;
}


