using namespace std;

const int MOD = 998244353;

long long power(long long x, int n)
{
	if (n == 0) {
		return 1;
	}
	else if (n % 2 == 0) {
		long long t = power(x, n / 2);
		return (t * t) % MOD;
	}
	else {
		return (x * power(x, n - 1)) % MOD;
	}
}

long long inv(long long x)
{
	return power(x, MOD - 2);
}

vector<long long> make_fact(int N)
{
	vector<long long> fact(N + 1);
	fact[0] = 1;
	for (int i = 1; i <= N; ++i) {
		fact[i] = (fact[i - 1] * i) % MOD;
	}
	return fact;
}

vector<long long> make_ifact(int N)
{
	auto fact = make_fact(N);
	vector<long long> ifact(N + 1);
	for (int i = 0; i <= N; ++i) {
		ifact[i] = inv(fact[i]);
	}
	return ifact;
}


int main()
{
	int N;
	long long A, B, K;
	cin >> N >> A >> B >> K;

	auto fact = make_fact(N);
	auto ifact = make_ifact(N);

	auto c = [&](int n, int r)
	{
		return fact[n] * ifact[n - r] % MOD * ifact[r] % MOD;
	};

