ll C[N_MAX];

ll ext_gcd(ll a, ll b, ll&x, ll&y){
    if(b == 0){
        x = 1; y = 0; return a;
    }
    ll q = a / b;
    ll g = ext_gcd(b, a-q*b, x, y);
    ll z = x - q * y;
    x = y; y = z;
    return g;
}

ll invmod(ll a, ll m){
    ll x, y;
    ext_gcd(a, m, x, y);
    x %= m;
    if(x < 0) x += m;
    return x % CONST;
}


