#define MOD 998244353LL
#define MAXN 300010
#define ld double

int n;
ll A,B,k;
ll ans = 0;

ll frac[MAXN];
ll inv[MAXN];
void Calfrac(){
	frac[0] = 1;
	For(i,n)
		frac[i] = frac[i-1]*(ll)i%MOD;
}
ll Pow( ll a , ll b ){
	ll ret = 1;
	while(b){
		if(b&1){
			ret = ret*a%MOD;
		}
		a = a*a%MOD;
		b >>= 1;
	}
	return ret;
}
ll Inv( ll a ){
	return Pow(a,MOD-2);
}
void Calinv(){
	inv[0] = 1;
	inv[1] = 1;
	Forx(i,2,n)
		inv[i] = Inv(frac[i]);
}

ll C( ll b , ll a ){
	if( b > a ) return 0;
	ll ret = frac[a];
	ret = ret * inv[b] % MOD;
	ret = ret * inv[a-b] % MOD;
	if(!ret) ret = 1;
	return ret;
}


ll Solve( ll a , ll b ){
	ll ret = 1;
	ret = ret * C(a,n) % MOD;
	ret = ret * C(b,n) % MOD;
	return ret;
}

