ll mod_pow(ll k, ll pow) {
  ll ans = 1;
  while (pow > 0) {
    if (pow & 1) ans = ans * k % MOD;
    k = k * k % MOD;
    pow >>= 1;
  }
  return ans;
}

ll get_ways(ll n, ll na, ll nb) {
  ll nca = (facs[n] * ((invs[n - na] * invs[na]) % MOD)) % MOD;
  ll ncb = (facs[n] * ((invs[n - nb] * invs[nb]) % MOD)) % MOD;
  return (nca * ncb) % MOD;
}

