class binomial{
    private:
    const long long MOD = 998244353;
    std::vector<long long> fac;
    std::vector<long long> facIE;

    long long inv(int b){
        long long r=1,e=MOD-2;
        while(e){
            if(e&1){
                r=(r*b)%MOD;
            }
            b=(b*b)%MOD;
            e >>=1;
        }
        return r;
    }

    public:
    void precalc(long long N){
        fac.resize(N+1);
        facIE.resize(N+1);
        fac[0]=1;
        for(long long i=0;i<N;i++){
            fac[i+1]=((i+1)*fac[i])%MOD;
        }

        facIE[N] = inv(fac[N]);
        for(int i=N-1;i>=0;i--){
            facIE[i]=((i+1)*facIE[i+1])%MOD;
        }
    }

    long long get(long long n,long long r){
        if(r<0 || n<r)return 0;
        long long R = fac[n];
        R = (R*facIE[r])%MOD;
        R = (R*facIE[n-r])%MOD;
        return R;
    }

};


