ll nCr(ll n, ll r) {
	ll an = 1;
	for (ll i = n; i > n - r; --i) {
		an = an * i;
	}
	for (ll i = 1; i < r + 1; ++i) {
		an = an / i;
	}
	return an;
}

ll ggd(ll number1, ll number2) {
	ll m = number1;
	ll n = number2;

	if (number2 > number1) {
		m = number2;
		n = number1;
	}

	while (m != n) {
		ll temp = n;
		n = m - n;
		m = temp;
	}

	return m;
}


ll lcm(ll number1, ll number2) {
	return number1 * number2 / ggd(number1, number2);
}

