ll n, k, a, b;
ll fact[M], invfact[M];

ll exp(ll x, ll k) {
	if (k == 0)
		return 1;
	if (k%2 == 1)
		return x*exp(x, k-1)%p;
	ll y = exp(x, k/2);
	return y*y%p;
}

ll inv(ll x) { return exp(x, p-2); }

ll comb(ll x, ll y) {
	if (x < 0 || y < 0 || x < y)
		return 0;
	return fact[x]*invfact[y]%p*invfact[x-y]%p;
}

int main() {
	cin >> n >> a >> b >> k;
	fact[0] = invfact[0] = 1;
	for (int i = 1; i < M; ++i) {
		fact[i] = i*fact[i-1]%p;
		invfact[i] = inv(fact[i]);
	}

	ll ans = 0;

	for (int i = 0; i <= n; ++i) {
		//how many a's used?
		if (k-a*i < 0)
			continue;
		if ((k-a*i)%b != 0)
			continue;
		ll t = (k-a*i)/b;
		ans = (ans + comb(n, i)*comb(n, t))%p;
	}

