const int pr = 998244353;

long long invv(long long x){
    int lft = pr - 2;
    long long gop = x, ret = 1;
    while(lft){
        if(lft&1) ret = (ret * gop) % pr;
        lft >>= 1;
        gop = (gop * gop) % pr;
    }
    return ret;
}

