    for(int i=1;i<=n;i++){
        fact[i] = (fact[i-1] * i) % pr;
        inv[i] = invv(fact[i]);
    }
    long long gcdd = __gcd(a, b);
    if(k % gcdd){
        printf("0\n");
        return 0;
    }
    a /= gcdd; b /= gcdd; k /= gcdd;
    long long aa, bb;
    aa = -1;
    for(int i=0;i<=b;i++){
        if(k < a * i) break;
        if((k - (a * i)) % b == 0){
            aa = i;
            bb = (k - (a * i)) / b;
        }
    }
    if(aa == -1){
