            cal1 = (cal1 * inv[aa]) % pr;
            cal1 = (cal1 * inv[n-aa]) % pr;
            cal2 = (cal2 * inv[bb]) % pr;
            cal2 = (cal2 * inv[n-bb]) % pr;
            cal1 = (cal1 * cal2) % pr;
