ll factrial[MAX_N], inverse[MAX_N], q[MAX_N]{};

ll power(ll x, ll n, ll m = MOD) {
    ll ans = 1;
    while (n > 0) {
        if ((n & 1) == 1) {
            ans = ans * x % m;
        }
        x = x * x % m;
        n >>= 1;
    }
    return ans;
}

void init(ll n) {
    factrial[0] = 1;
    inverse[0] = 1;
    for (ll i = 1; i <= n; i++) {
        factrial[i] = (factrial[i - 1] * i) % MOD;
        inverse[i] = power(factrial[i], MOD - 2) % MOD;
    }
}

ll nCr(ll n, ll k) {
    return factrial[n] * inverse[k] % MOD * inverse[n - k] % MOD;
}
ll gcd(ll p, ll q){
    if(p<q)return gcd(q,p);
    if(p%q==0)return q;
    else return gcd(q,p%q);
}

ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll d = a;
    if (b == 0) {
        x = 1;
        y = 0;
    } else {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }
    return d;
}

ll mod_inv(ll a, ll m) {
    ll a_, q;
    extgcd(a, m, a_, q);
    return a_;
}

int main() {
    ll N, A, B, K, g;
    cin >> N >> A >> B >> K;
    if(K==0){
        cout << 1 << endl;
        return 0;
    }
    g = gcd(A,B);
    if(g!=1){
        if(K%g!=0){
            cout << 0 << endl;
            return 0;
        }
        else{
            A/=g;
            B/=g;
            K/=g;
        }
    }
    init(N+1);
    for(ll i=1;i<=N;i++){
        ll r0 = 0, b0, C = (A+B)*i-K, m;
        r0 = C*mod_inv(B,A)%A;
        while(C-B*r0 >=0 && (C-B*r0)/A + r0 > i){
            r0+=A;
        }
        if(C-B*r0 < 0)continue;
        b0 = (C-B*r0)/A;
        m = (C-B*r0)/(A*B);
        for(ll j=0;j<=m;j++){
            q[i] += nCr(i,r0+A*j) * nCr(i-r0-A*j,b0-j) % MOD;
            q[i] %= MOD;
        }
    }
    ll ans = 0;
    for(ll i = 1;i<=N;i++){
        ans += q[i] * nCr(N,i) % MOD;
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

