pii S[10000000];

LL CountingSolution(int x, int y) {
    LL res = 0;
    LL zero = 0;
    for (int c2 = max(x+y-N,zero); c2 <= min(x,y); c2++) {
        int c1 = x-c2;
        int c3 = y-c2;
        int c0 = N-c1-c2-c3;
        LL nWays = combination(N, c0) * combination(N-c0, c1);
        nWays %= MOD;
        nWays *= combination(c2+c3, c2);
        nWays %= MOD;
        res += nWays;
        res %= MOD;
    }
    return res;
}

