ll com(ll a,ll b,ll c) {
  ll d=1, e=(b*c)%mod, m_=mod-2;
  while(m_ != 0) {
    if (m_&1) d = (d*e)%mod;
    e = e*e%mod;
    m_ = m_ >> 1;
  }
  return (a*d)%mod;
}

