#include<bits/stdc++.h>
using namespace std;

using I = long long;
const I M = 998244353;

I power(I m, I n) {
  if(!n) return 1;
  return (n & 1) ? (power(m, n - 1) * m % M) : power(m * m % M, n >> 1);
}
I factorial(I n) {
  static std::vector<I> memo = {1};
  while(I(memo.size()) <= n) memo.emplace_back(memo.back() * I(memo.size()) % M);
  return memo.at(n);
}

I inverse(I n) {
  return power(n, M - 2);
}
I combination(I n, I r) {
  if(!n) return 1;
  if(n < r) return 0;
  return (factorial(n) * inverse(factorial(n - r)) % M) * inverse(factorial(r)) % M;
}

int main() {
  I N, A, B, K;
  cin >> N >> A >> B >> K;

  I ans = 0;
  for(I a=0; a<=N; ++a) {
    auto k = a * A;
    if(K < k) continue;
    auto b = (K - k) / B;
    if(N < b) continue;
    if(a * A + b * B != K) continue;
    (ans += combination(N, a) * combination(N, b) % M) %= M;
  }
  cout << ans << endl;
}

