long long mod = 998244353;
vector<long long> fact;
vector<long long> factinv;

void initfact(long long n) {
    fact.push_back(1);
    for (long long i = 1; i < n+1; i++) {
        fact.push_back((fact.back()*static_cast<long long>(i))%mod);
    }
}

long long sqr(long long n) {
    return static_cast<long long>(n)*n%mod;
}

long long bipow(long long c, long long n) {
    if (n == 0) {
        return 1;
    } else if(n == 1) {
        return c;
    } else if(n%2 == 0) {
        return sqr(bipow(c, n/2))%mod;
    } else {
        return (static_cast<long long>(c)*sqr(bipow(c, (n-1)/2)))%mod;
    }
}

void initfactinv() {
    factinv.push_back(bipow(fact.back(), mod-2));
    for (long long i = fact.size()-1; i > 0; i--) {
        factinv.push_back((factinv.back()*static_cast<long long>(i))%mod);
    }
    reverse(factinv.begin(), factinv.end());
}

long long C(long long n, long long m) {
    if (n < m) {
        return 0;
    }
    return (((static_cast<long long>(fact[n])*factinv[m])%mod)*factinv[n-m])%mod;
}

void solve(long long N, long long A, long long B, long long K){
    initfact(N + 10);
    initfactinv();
    long long ret = 0;
    for (int i = 0; i < N; i++) {
        long long r = i;
        long long rest = K - A*r;
        if (rest%B != 0) {
            continue;
        }
        long long b = rest/B;
        long long w, x, y, z, t;
        w = min(r, b);
        x = 0;
        y = max(r, b);
        z = N - r - b;
        if (z < 0) {
            if (y+z < 0 || w+z < 0) {
                continue;
            }
            t = C(N, y + z);
            t *= C(N, w + z);
        } else {
