void solve() {
  int n, a, b;
  ll k;
  cin >> n >> a >> b >> k;

  vector<int> f(n + 1), rf(n + 1);
  f[0] = 1;
  for (int i = 1; i <= n; ++i) {
    f[i] = f[i - 1] * 1ll * i % mod;
  }
  rf[n] = power(f[n], mod - 2);
  for (int i = n - 1; i >= 0; --i) {
    rf[i] = rf[i + 1] * 1ll * (i + 1) % mod;
  }

  auto cnk = [&](int n, int k) {
    if (n < k) {
      return 0ll;
    }
    return (f[n] * 1ll * rf[n - k] % mod) * rf[k] % mod;
  };

  int ans = 0;
  for (int rc = 0; rc <= n; ++rc) {
    ll rem = k - a * 1ll * rc;
    if (rem < 0 || rem % b != 0 || rem / b > n) {
      continue;
    }
    int bc = rem / b;
    if (bc > n) {
      continue;
    }
    (ans += (cnk(n, rc) * cnk(n, bc) % mod)) %= mod;
  }
  cout << ans << "\n";
}

