lld N, A, B, K;
const lld mod = 998244353;
lld fact[300005], factinv[300005];

lld expo(lld a, lld b)
{
	a %= mod;
	lld ans = 1LL;
	while(b)
	{
		if(b&1)
		{
			ans = (ans%mod)*(a%mod);
			ans %= mod;
		}
		a *= a;
		a %= mod;
		b>>=1;
	}
	return ans;
}

void init()
{
	int i;
	fact[0] = fact[1] = 1;
	fu(i, 2, 300005)
		fact[i] = (fact[i-1] * i) % mod;
	fr(i, 300005)
		factinv[i] = expo(fact[i], mod-2);
}



lld comb(lld n, lld r)
{
	lld ans = 0LL;
	if(n-r>=0 and r>=0)
	{

		ans = fact[n]%mod * factinv[r]%mod * factinv[n-r]%mod;
		ans %= mod;
		if(ans < 0)
			ans+= mod;
	}
	return ans;
}

lld solve()
{
	int i;
	lld temp, a, b;
	lld ans = 0LL;
	fe(a, N)
	{
		temp = K - (a * A);
		if(temp % B != 0)
			continue;
		b = temp / B;
		if(b<0 or b>N)
			continue;
		// cout<<a<<" "<<b<<endl;
		ans += comb(N, a) * comb(N, b);
		ans %= mod;
		if(ans < 0)
			ans += mod;
	}
	return ans;
}

