ll modpow(ll x, ll n, ll mod=MOD) {
    ll ans=1;
    for (; n; n/=2) {
        if (n%2) ans=ans*x%mod;
        x=x*x%mod;
    }
    return ans;
}

ll fact(int n) {
    static vi cache{1};
    for (ll i=cache.size(); i<=n; i++)
        cache.pb(cache.back()*i%MOD);
    return cache[n];
}

ll invfact(int n) {
    static vi cache{1};
    for (ll i=cache.size(); i<=n; i++)
        cache.pb(modpow(fact(i), MOD-2, MOD));
    return cache[n];
}

ll binomial(ll n, ll k) {
    if (k<0 || k>n) return 0;
    return fact(n)*invfact(k)%MOD*invfact(n-k)%MOD;
}

