long int nckmodp(long int n,long int k,long int p){
  if(memonckmodp[k] )return memonckmodp[k];
  long int ans = (((DP[n] * expbkp(k,p-2,p))%p) * expbkp(n-k,p-2,p))%p;
  memonckmodp[k] = ans;
  memonckmodp[n-k] = ans;
  return ans;
}

long int G(long int A,long int B){
  long int ans = 1,i = 2;
  while(i <= A && i <= B){
    while(1){
      if(A%i == 0 && B%i == 0 && i <= A && i <= B){
        A /= i;
        B /= i;
        ans *= i;
      }
      else break;
    }
    i++;
  }
  return ans;
}

