long long modpow(long long x, long long y)
{
  long long p = 1;

  for ( ; y; (x *= x) %= MOD, y >>= 1)
    if (y & 1)
      (p *= x) %= MOD;

  return p;
}


std::map<std::pair<int, int>, long long> memo;


long long modncr(int n, int r)
{
  assert(n >= 0);
  assert(r >= 0);

  std::pair<int, int> key(n, r);

  if (memo.count(key))
    return memo[key];

  if (n == 0)
    return r == 0 ? 1 : 0;

  if (r > n)
    return 0;

  long long c = 1;

  int dm = std::min(r, n - r);
  int dp = std::max(r, n - r);

  for (int i = dp + 1; i <= n; i ++)
    (c *= i) %= MOD;

  for (int i = 2; i <= dm; i ++)
    (c *= modpow(i, MOD - 2)) %= MOD;

  return memo[key] = c;
}

class modint_t {
  friend std::ostream& operator<<(std::ostream& ofs, const modint_t a);

public:
  modint_t(long long xx = 0) : x(xx % MOD) {};

public:
  bool operator==(long long a) const {
    return x == a;
  };

public:
  modint_t operator+(const modint_t& a) const {
    return (x + a.x) % MOD;
  };

  modint_t operator-(const modint_t& a) const {
    return (x - a.x) % MOD;
  };

  modint_t operator*(const modint_t& a) const {
    return x * a.x % MOD;
  };

  modint_t operator/(const modint_t& a) const {
    return (*this) * a.inverse();
  };

  // Note that operator^'s priority is quite low in C++...
  modint_t operator^(long long i) const {
    return modint_t(modpow(x, i));
  };

public:
  modint_t& operator+=(const modint_t& a) {
    (x += a.x) %= MOD;

    return *this;
  };

  modint_t& operator-=(const modint_t& a) {
    (x -= a.x) %= MOD;

    return *this;
  };

  modint_t& operator*=(const modint_t& a) {
    (x *= a.x) %= MOD;

    return *this;
  };

  modint_t& operator/=(const modint_t& a) {	// Not tested
    (x *= a.inverse().x) %= MOD;

    return *this;
  };

public:
  bool operator!=(const modint_t& a) const {
    return x != a.x;
  };

public:
  modint_t inverse() const {
    assert(x % MOD);

    return modint_t(modpow(x, MOD - 2));
  };

public:
  modint_t normalized() const {
    return modint_t(x % MOD + MOD);
  };

private:
  long long x;
};

modint_t operator+(long long a, const modint_t& b)
{
  return modint_t(a) + b;
}

modint_t operator-(long long a, const modint_t& b)
{
  return modint_t(a) - b;
}

modint_t operator*(long long a, const modint_t& b)
{
  return modint_t(a) * b;
}

modint_t operator/(long long a, const modint_t& b)
{
  return modint_t(a) / b;
}

std::ostream& operator<<(std::ostream& ofs, const modint_t a)
{
  ofs << a.x;

  return ofs;
}


