long long BinPow(long long x,long long n){
    if(n==0)
        return 1;
    else if(n==1)
        return x;
    else{
        long long sum = BinPow(x,n/2);
        sum*=sum; sum%=mod;
        if(n%2!=0)
            sum*=x;
        sum%=mod;
        return sum;
    }
}

long long C(long long s,long long k){
    return (((pref[s]*suff[k])%mod)*suff[s-k])%mod;
}

int main(){
