enum { NUM_FACTORIAL = 1012345 };
ll f[NUM_FACTORIAL];
ll f_inv[NUM_FACTORIAL];
ll MOD = 998244353;

// MODが素数以外でも使えるバージョン。階乗の逆元を求める。
ll extgcd(ll a, ll b, ll& x, ll& y)
{
	ll d = a;
	if (b != 0)
	{
		d = extgcd(b, a%b, y, x);
		y -= (a / b)*x;
	}
	else
	{
		x = 1;
		y = 0;
	}
	return d;
}

// 逆元を求める
ll mod_inverse(ll a, ll m)
{
	ll x, y;
	extgcd(a, m, x, y);
	return (m + x%m) % m;
}

void mod_factorial_init()
{
	f[0] = 1;
	for (int i = 1; i < NUM_FACTORIAL; ++i)
	{
		f[i] = f[i - 1] * i;
		f[i] %= MOD;
	}

	for (int i = 0; i < NUM_FACTORIAL; ++i)
	{
		f_inv[i] = mod_inverse(f[i], MOD);
	}
}

// 組み合わせを求める。事前計算O(n)で、0～nまでと範囲も広いので、MODつきならパスカルの三角形よりも良い。最有力。
ll mod_comb(ll n, ll k) {
	if (k > n)
	{
		return 0;
	}

	return ((f[n] * f_inv[k]) % MOD * f_inv[n - k]) % MOD;
}


int main()
{
	mod_factorial_init();

	ll N, A, B, K;
	cin >> N >> A >> B >> K;

	ll ans = 0;

	for (ll r = 0; r <= N; r++)
	{
		if ((K - r * A) % B == 0)
		{
			ll b = (K - r * A) / B;
			if (b >= 0)
			{
				ll tmp = (mod_comb(N, r) * mod_comb(N, b)) % MOD;
				ans += tmp;
				ans %= MOD;
			}
		}
	}

	cout << ans << endl;


	return 0;
}

