static const int MOD = 998244353;

int extgcd(int a, int b, int& x, int& y){
  int d = a;
  if (b == 0){
    x = 1; y = 0;
  } else {
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  }
  return d;
}

unsigned int modpow(const unsigned int n, unsigned int r){
  if (r == 0){return 1;}
  unsigned long long rtn =  modpow(n, r / 2);
  rtn *= rtn;
  if (r % 2 == 1){rtn *= n;}
  return rtn;
};
unsigned int modinv(unsigned int rem){
  int x, y;
  assert(extgcd((int) rem, (int) MOD, x, y) == 1);
  return (x + MOD) % MOD;
};
unsigned int modadd() { return 0;}
template<typename Head, typename... Tail> unsigned int modadd(const Head& head, const Tail&... tail) { return (head + modadd(tail...)) % MOD; }
template<typename Head, typename... Tail> unsigned int modsub(const Head& head, const Tail&... tail) { return (head + MOD - modadd(tail...)) % MOD; }
unsigned int modmul() { return 1;}
template<typename Head, typename... Tail> unsigned int modmul(const Head& head, const Tail&... tail) { return ((unsigned long long)head * modmul(tail...)) % MOD; }
template<typename Head, typename... Tail> unsigned int moddiv(const Head& head, const Tail&... tail) { return modmul(head, modinv((unsigned int)(modmul(tail...))));
}

static const unsigned int MAXF = 3e5+2;
unsigned int f0[1 + MAXF], f1[1 + MAXF];

void init(){
  f0[0] = 1;
  for(unsigned int i = 1; i <= MAXF; i++){f0[i] = modmul(i, f0[i - 1]);}
  f1[MAXF] = modinv(f0[MAXF]);
  for(unsigned int i = MAXF; 0 < i; i--){f1[i - 1] = modmul(i, f1[i]);}
}

unsigned int modf(unsigned int n){
  return f0[n];
}
unsigned int modp(unsigned int n, unsigned int r){
  return modmul(f0[n], f1[n - r]);
}
unsigned int modc(unsigned int n, unsigned int r){
  return modmul(f0[n], f1[n - r], f1[r]);
}

int main(){
  init();
  ui ans = 0;
  INT(n); LL(a); LL(b); LL(k);
  ll x = max(a, b), y = min(a, b);
  vector<int> v(2 * n + 1, -1);
  auto calc = [&](int p, int q, int r){
    ui rtn;
    if (0 <= p && 0 <= q && 0 <= r && 0 <= n - p - q - r){
      rtn = modc(n, p);
      rtn = modmul(rtn, modc(n - p, q));
      rtn = modmul(rtn, modc(n - p - q, r));
    } else {
      rtn = 0;
    }
    return rtn;
  };
  REP(p, 2 * n + 1){
    int q = (k - x * p) / y;
    if (x * p + y * q == k && 0 <= q && p + q <= 4 * n){
      ans = modadd(ans, calc(p, q, 0));
      if ((x + y) % y == 0){
        int d = (x + y) / y;
        REP(r, 1, n + 1){
          if (q < r * d){break;}
          ans = modadd(ans, calc(p, q - d * r, r));
          v[p] = p;
        }
      }
      REP(r, 1, n + 1){
        if (p < r || q < r){break;}
        if (v[p - r] == p - r){continue;}
