typedef long long ll;

using namespace std;

ll N, A, B, K;
map<ll, ll> memo_modinv;

const ll MOD_N = 998244353;

ll gcd(ll a, ll b) {
    return b != 0 ? gcd(b, a % b) : a;
}

ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll g = a; x = 1; y = 0;
    if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}

ll modinv(ll a, ll m) {
    if (memo_modinv.count(a) == 1) return memo_modinv[a];

    ll x, y;
    if (extgcd(a, m, x, y) == 1) {
        memo_modinv[a] = (x + m) % m;
        return (x + m) % m;
    } else {
        return 0;
    } // unsolvable
}

// nCr mod m = modc(n,r,m)
ll modc(ll a, ll b, ll m) {
    ll c = 1;
    REP(i, 0, b) {
        c = c * (a - i) % m;
        c = c * modinv(i + 1, m) % m;
    }
    return c;
}

void solve() {
    // K = A * a + B * b, 0 <= a,b <= N
    // answer = N C a + N C b

    ll answer = 0;

    REP(a,0,N) {
        if (K - A * a < 0 || (K - A * a) % B != 0) continue;

        ll b = (K - A * a) / B;

        answer += modc(N, a, MOD_N) * modc(N, b, MOD_N) % MOD_N;
        answer %= MOD_N;
    }

    printf("%lld\n", answer);

    return;
}

int main() {
    // to shorten execution time for iostream
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> A >> B >> K;
    solve();
    return 0;
}

