ll fac[N], ifac[N];

ll qpow(ll a, ll n){
	if(n==1) return a;

	ll t = qpow(a, n/2);
	ll t2 = (t*t)%MOD;
	return n%2==0 ? t2 : (t2*a)%MOD;
}

ll calc(int n, int a){
	ll ans = fac[n];
	ans = (ans*ifac[a])%MOD;
	ans = (ans*ifac[n-a])%MOD;

	return ans;
