long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}
bool judge(int i){
    bool flag=false;
    if(k-a*i>=0){
        if(k-a*i<=(n-i)*(a+b)){
            if((k-a*i)%b==0){
                flag=true;
                int num=(k-a*i)/b;
                if(num>n)flag=false;
            }
        }
    }
    return flag;
}
int comv(vector<int> const& kaijo,int n,int kk){
    int res=kaijo[n];
    res*=modinv(kaijo[kk],MOD);
    res%=MOD;
    res*=modinv(kaijo[n-kk],MOD);
    res%=MOD;
    return res;
}
int solve(vector<int> const& kaijo,int i){
    int res=0;
    int r,bb;
    r=i;bb=(k-a*i)/b;
    if(bb<0)return 0;
    int buf=comv(kaijo,n,r);
