lld power(lld a, lld b)
{
	a %= mod;
	lld ans = 1LL;
	while(b)
	{
		if(b&1)
		{
			ans = (ans%mod)*(a%mod);
			ans %= mod;
		}
		a *= a;
		a %= mod;
		b>>=1;
	}
	return ans;
}

lld comb(lld n, lld r)
{
	if(r > n)
		return 0LL;
	if(r==0 or r==n)
		return 1LL;
	if(r > n/2)
		r = n-r;

	lld ans, factn, invfactr, invfactnr;
	factn = fact[n];
	invfactr = power(fact[r], mod-2);
	invfactnr = power(fact[n-r], mod-2);
	ans = (factn*invfactr)% mod;
	ans = (ans*invfactnr) % mod;
	if(ans < 0)
		ans += mod;
	return ans;
}

