using namespace std;
typedef long long ll;

ll n, a, b, k;
ll ncr[300050];
ll gcd(ll a, ll b, ll &x, ll &y){
	if(a % b == 0){
		x = 0, y = 1;
		return b;
	}
	ll x1, y1;
	ll ans = gcd(b, a%b, x1, y1);
	x = y1;
	y = x1-y1*(a/b);
	return ans;
}
ll inv(ll a){
	ll x, y; 
	if(gcd(a,mod,x,y) == 1) return (x+mod)%mod;
	else return -1;
}

int main(){
	//freopen("rgbcoloring.in", "r", stdin);
	cin >> n >> a >> b >> k;
	// jb == k - ia
	ncr[0] = 1;
	for(ll i = 1; i<=n; i++){
		ncr[i] = ncr[i-1];
		ncr[i] *= (n-(i-1));
		ncr[i] %= mod;
		ncr[i] *= inv(i);
		ncr[i] %= mod;
	}
	ll ans = 0;
	for(ll i = 0; i*a<=k and i<=n; i++){
		if((k-i*a) % b == 0){	
			ans += (ncr[i]*ncr[(k-i*a)/b])%mod;
		}
	}
	cout << ans;
}

