}

long long int mod_fact(long long int n, long long int p, long long int& e) {
	e = 0;
	if (n == 0) return 1;

	long long int res = mod_fact(n / p, p, e);
	e += n / p;

	if (n / p % 2 != 0) return res * (p - fact[n%p]) % p;
	return res * fact[n%p] % p;
}

long long int mod_comb(long long int n, long long int k, long long int p) {
	if (n < 0 || k < 0 || n < k) return 0;
	long long int e1, e2, e3;
	long long int a1 = mod_fact(n, p, e1), a2 = mod_fact(k, p, e2), a3 = mod_fact(n - k, p, e3);
	if (e1 > e2 + e3) return 0;
	return a1 * mod_inverse(a2 * a3 % p, p) % p;
}


