ll div_mod(int a){
  return pow_mod(a,mod-2);
}

// factを前計算
void calcFact(){
  fact[0]=1;
  for(int i=1;i<MAX_FACT;i++)
    fact[i]=(fact[i-1]*i)%mod;
}

// aCbのmodを計算
// 計算量はO(log(fact[a])+log(fact[a-b]))程度
ll comb(ll a,ll b){
  if(a<0||b<0)return 0;
  else if(a<b)return 0;
  else if(b==0)return 1;
  ll res=fact[a];
  res=(res*div_mod(fact[b]))%mod;
  res=(res*div_mod(fact[a-b]))%mod;
  return res;
}

int main(){

    calcFact();
    cin >> N >> A >> B >> K;
    ll ans = 0;
    for(ll i = 0; i * A <= K; i++){
        if((K - i * A) % B == 0){
            ll j = (K - i * A) / B;
            // C(N, i) * C(N, j)
            ans += comb(N, i) * comb(N, j);
            ans %= mod;
        }
    }
    cout << ans << endl;

    return 0;
}

