template<class T>class Combi {
	int Max; T Mod;
	vector<T> fac, finv, inv;
public:
	constexpr Combi(int _Max = 300009, T _Mod = 1000000007)
		: Max(_Max), Mod(_Mod)
		, fac(_Max), finv(_Max), inv(_Max) {
		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for (int i = 2; i < Max; ++i) {
			fac[i] = fac[i - 1] * i % Mod;
			inv[i] = MOD - inv[Mod % i] * (Mod / i) % Mod;
			finv[i] = finv[i - 1] * inv[i] % Mod;
		}
	}
	constexpr T P(int n, int r) { // n P r
		return (n < r || n < 0 || r < 0) ? 0 : fac[n] * finv[n - r] % MOD;
	}
	constexpr T C(int n, int r) { // n C r
		return (n < r || n < 0 || r < 0) ? 0 : fac[n] * (finv[r] * finv[n - r] % Mod) % Mod;
	}
	constexpr T H(int n, int r) { // n H r
		return (n < 0 || r < 0) ? 0 : r == 0 ? 1 : C(n + r - 1, r);
	}
};

