        : mod(mod_),
          len(1010101),
          f(std::vector<ll>(len)),
          rf(std::vector<ll>(len)) {
        f[0] = 1;
        for (int i = 0; i < len - 1; i++) f[i + 1] = f[i] * (i + 1) % mod;
        for (int i = 0; i < len; i++) rf[i] = inv(f[i]);
    }
    ll c(int n, int k) {
        ll a = f[n];
        ll b = rf[n - k];
        ll c = rf[k];

        ll bc = (b * c) % mod;
        return (a * bc) % mod;
    }
