ll gcd(ll a, ll b)
{
  if (b==0) return a;
  else return gcd(b, a%b);
}

ll ex_gcd(ll a, ll b, ll &x, ll &y)
{
    if (b == 0)
    {
        x = 1;
        y = 0;
        return a;
    }
    ll r = ex_gcd(b, a%b, x, y);
    ll t = x;
    x = y;
    y = t-(a/b)*y;
    return r;
}

ll ksm(ll x, ll y)
{
  ll res = 1;
  while(y)
  {
    if (y&1) res=(res*(ll)x)%mod;
    y>>=1;
    x=(x*x)%mod;
  }
  return res%mod;
}

ll f(int x, int y)
{
  return ((F[x]*InvF[y])%mod *(InvF[x-y])%mod)%mod;
}

ll cal(int x, int y)
{
  return (f(n, x)%mod*f(n, y)%mod)%mod;
}

