const int MaxN = 300000;

int N, A, B;
LL K;
LL Bin[MaxN + 5];

LL qwr(LL x, LL y) {
	LL res = 1LL;
	while(y > 0) {
		if(y & 1) res = (res * x) % MOD;
		x = (x * x) % MOD;
		y = y >> 1;
	}
	return res;
}

void Prepare() {
	Bin[0] = 1LL;
	for(int i = 1; i <= MaxN; i++)
		Bin[i] = Bin[i - 1] * 1LL * i % MOD;
}

LL C (LL N, LL M) {
	LL res = (Bin[N] * qwr(Bin[M], MOD - 2) % MOD) * qwr(Bin[N - M], MOD - 2) % MOD;
	return res;
}

int main()
{
	Prepare();
	while(scanf("%d %d %d %lld", &N, &A, &B, &K) != EOF)
	{
		LL ans = 0LL;
		for(int i = 0; i <= N; i++) {
			LL x = (LL)i;
			LL y = (K - A * x) / B;
			if(x >= 0 && y >= 0 && A * x + B * y == K) 
				ans = (ans + C(N, x) * C(N, y)) % MOD;
		}
		printf("%lld\n", ans);
	}
    return 0;
}

