// 前処理
void preCalcCombinationMod(ll N){
	ll i;
	fact[0] = 1;
	fact[1] = 1;
	for (i = 2; i <= N; i++){
		fact[i] = (fact[i - 1] * i) % MOD;
	}
	ll nFactInv = compME(fact[N], MOD - 2, MOD);
	inv[N] = nFactInv;
	for (i = N - 1; i > 0; i--){
		inv[i] = (inv[i + 1] * (i + 1)) % MOD;
	}
	inv[0] = 1;
}

ll calcCombinationMod(ll n, ll m){
	ll ans = fact[n];
	ans = (ans * inv[m]) % MOD;
	ans = (ans * inv[n - m]) % MOD;
	return ans;
}

int main(){
	ll N, A, B, K;
	cin >> N >> A >> B >> K;
	ll i, j;
	ll ans = 0;
	preCalcCombinationMod(N);
	for (i = 0; i <= N; i++){
		if (i*A > K){
			break;
		}
		ll resi = K - i*A;
		if (resi%B == 0){
			j = resi / B;
			ll atmp = calcCombinationMod(N, i);
			ll btmp = calcCombinationMod(N, j);
			ans += atmp * btmp % MOD;
			ans %= MOD;
		}
	}
	cout << ans << endl;

	return 0;
}

