ll poW(ll x, ll r) {
	ll temp;
	if (r == 0LL)return 1LL;
	else if (r == 1LL)return x % mod;
	temp = poW(x, r / 2);
	return (temp*temp%mod)*poW(x, r % 2) % mod;
}

void init() {
	func[0] = 1;
	for (int i = 1; i <= n; i++) {
		func[i] = func[i - 1] * i%mod;
	}
	inv[n] = poW(func[n], mod - 2);
	for (int i = n - 1; i >= 0; i--) {
		inv[i] = inv[i + 1] * (i + 1) % mod;
	}
}

