inline int quick (int a , int p) {
	int res = 1 ;
	while ( p ) {
		if ( p & 1 ) res = ( res * a ) % mod ;
		a = ( a * a ) % mod ; p >>= 1 ;
	}
	return res ;
}

inline int inv (int x) { return quick ( x , mod - 2 ) ; }

inline int C (int n , int m) {
	if ( ! m || n == m ) return 1 ;
	if ( n < m ) return 0 ;
	return ( g[n] * inv ( g[m] ) % mod * inv ( g[n-m] ) % mod ) % mod ;
}

