int mod_sum(int a, int b) {
	int res = a + b;
	if (res >= MOD)
		res -= MOD;
	return res;
}
int mod_mult(int a, int b) {
	return (a * 1LL * b) % MOD;
}

int mod_power(int a, int b) {
	int res = 1;
	while (b > 0) {
		if (b % 2 == 1)
			res = mod_mult(res, a);
		a = mod_mult(a, a);
		b = b / 2;
	}
	return res;
}

int inverse(int x) {
	return mod_power(x, MOD-2);
}

