	for (int i = 1; i < MX; i++)
		fact[i] = mod_mult(fact[i-1], i);

	in_fact[MX-1] = inverse(fact[MX-1]);
	for (int i = MX-2; i >= 0; i--) {
		in_fact[i] = mod_mult(in_fact[i+1], i+1);
	}
}

