int main(void) {
    constexpr long MOD = 998244353;

    long n, a, b, k;
    cin >> n >> a >> b >> k;

    auto inv = [&](){
        map<long,long> c;

        return [&, c](long a) mutable {
            long k = a;
            if(c.count(k)) return c[k];

            long r = 1, b = MOD-2;
            while(b) {
                if(b&1) r *= a, r %= MOD;
                a *= a, a %= MOD;
                b >>= 1;
            }
            return c[k] = r;
        };
    }();

    auto comb = [&](){
        map<pair<long,long>,long> c;

        return [&, c](long a, long b) mutable {
            if(c.count({a,b})) return c[{a,b}];
            long r = 1;
            for(long i=0; i<b; i++)
                r *= a-i, r %= MOD, r *= inv(i+1), r %= MOD;
            return c[{a,b}] = r;
        };
    }();

    long r = 0;
    for(long x=0; x<=2*n; x++) {
        if((k-x*a)%b) continue;
        long y = (k - x*a)/b;
        if(y < 0) continue;

        // ax + by == k
        r += (comb(n, x) * comb(n ,y)) % MOD;
        r %= MOD;
    }
    cout << r << endl;
}

