ll modexp(ll b,ll e,ll m){
	ll r = 1;
	while(e > 0){
		if((e & 1) == 1){
			r = (r * b) % m;
		}
		e = e / 2;
		b = (b * b) % m;
	}
	return r;
}

ll kombin(ll atas,ll bawah){
	if(bawah > atas){
		return 0;
	}
	if(bawah == atas){
		return 1;
	}

	ll c = (fakt[atas] * modexp(fakt[bawah], mod - 2, mod)) % mod;
	c = (c * modexp(fakt[atas - bawah], mod - 2, mod)) % mod;
	return c;
}

