lli extGcd(lli a, lli b, lli &x, lli &y)
{
    if (b == 0)
    {
        x = 1;
        y = 0;
        return a;
    }
    else
    {
        lli d = extGcd(b, a % b, y, x);
        y -= a / b * x;
        return d;
    }
}
