		LL r=K-A*i;
		if(r>=0&&r%B==0){
			LL j=r/B;
			if(i<=N&&j<=N){
				ret+=Comb(N,i,M)*Comb(N,j,M)%M;
				ret%=M;
			}
		}
	}
	cout << ret << endl;


	return 0;
}

