long long int conbination(int N,int i,int j,int k,int l){
  long long int sum=1;
  int Max=i;
  if(Max<j)
    Max=j;
  if(Max<k)
    Max=k;
  if(Max<l)
    Max=l;
  while(N>Max){
    sum=sum*N;
    N--;
  }
  while(i>1&&i!=Max){
    sum=sum/i;
    i--;
  }
  while(j>1&&j!=Max){
    sum=sum/j;
    j--;
  }
  while(k>1&&k!=Max){
    sum=sum/k;
    k--;
  }
  while(l>1&&l!=Max){
    sum=sum/l;
    l--;
  }
  return sum;
}

