const ll MOD = 998244353LL;
ll add(ll &a, ll b) {return a=(a+b)%MOD;}
ll mul(ll &a, ll b) {return a=(a*b)%MOD;}

const int SIZE = 300000+10;

ll fact[SIZE];

ll inv(ll a, ll p) {
  return ( a == 1LL ? 1LL : (1LL - p*inv(p%a, a)) / a + p );
}

ll solve(ll N, ll A, ll B, ll K) {
  ll ans = 0;
  for(ll a = 0; a <= N; a++) {
    if(a*A > K) break;
    ll b = (K-(a*A))/B;
    if(a*A+b*B != K) continue;
    if(b > N) continue;
    ll tmp = 1LL;
    mul(tmp, fact[N]);
    mul(tmp, inv(fact[a], MOD));
    mul(tmp, inv(fact[N-a], MOD));
    mul(tmp, fact[N]);
    mul(tmp, inv(fact[b], MOD));
    mul(tmp, inv(fact[N-b], MOD));
    add(ans, tmp);
  }
  return ans;
}

