ll calc(ll L,ll  R) {
  ll ret = mfactrs[R];
  if( L-1LL >= 0LL ) ret -= mfactrs[L-1];
  while( ret < 0LL ) ( ret += mod ) %= mod;
  return ret;
}

void expt2() {
  ll sum = 0;
  rep(a,N+1) {
    ll Av = A * a;
    if( Av > K ) continue;
    if( ( K - Av ) % B ) continue;
    ll b = ( K - Av ) / B;
    ll Bv = B * b;
    assert( Av + Bv == K );
    if( b > N ) continue;
    ll costa = 0, costb=0;
    costa = ( mfact[N] * mfactr[N-a] ) % mod;
    costa = ( costa * mfactr[a] ) % mod;
    costb = ( mfact[N] * mfactr[N-b] ) % mod;
    costb = ( costb * mfactr[b] ) % mod;
    ( sum += ( ( costa * costb) % mod ) ) %= mod;
  }
