  rep(i,N+1) mfactr[i] = mod_inv(mfact[i],mod);
  mfactrs[0] = mfactr[0];
  REP(i,1,N+1) mfactrs[i] = ( mfactrs[i-1] + mfactr[i] ) % mod;
