	for(int i = 2;i <= n;i++) inv[i] = mod - inv[mod % i] * (mod / i) % mod;
	for(int i = 2;i <= n;i++) inv[i] = (inv[i] * inv[i - 1]) % mod,fac[i] = (fac[i - 1] * i) % mod;
}
