	for(long long x = 0; x <= n; x++)
	{
		if((k - a * x) % b == 0)
		{
			long long y = (k - a * x) / b;
			if(0 <= y && y <= n)
			{
				pairs.push_back(std::make_pair(x, y));
			}
		}
	}
	long long ans = 0;
	for(auto i : pairs)
	{
		ans += combination(n, i.first) * combination(n, i.second) % MOD;
		ans %= MOD;
	}
	std::cout << ans << std::endl;
	return 0;
}

