vector<long int> DP(300001,1);


long int expbkp(long int b,long int k,long int p){
  vector<long int> modp(1,b % p);
  long int q = b % p,ans = 1;
  for(long int i = 1;pow(2,i) <= k;i++){
    q = (q*q)%p;
    modp.push_back(q);
  }
  for(long int i = 0;pow(2,i) <= k;i++){
    q = pow(2,i);
    if(k & q)ans = (ans * modp[i])%p;
  }
  return ans;
}

long int nckmodp(long int n,long int k,long int p){
  long int ans = (((DP[n] * expbkp(DP[k],p-2,p))%p) * expbkp(DP[n-k],p-2,p))%p;
  return ans;
}

long int G(long int A,long int B){
  long int ans = 1,i = 2;
  while(i <= A && i <= B){
    while(1){
      if(A%i == 0 && B%i == 0 && i <= A && i <= B){
        A /= i;
        B /= i;
        ans *= i;
      }
      else break;
    }
    i++;
  }
  return ans;
}

int main() {
  long int N,A,B,K,sum = 0,p = 998244353;
  for(long int i = 1;i <= 300000;i++)DP[i] = (DP[i - 1] * i)%p;
  cin >> N >> A >> B >> K;
  long int g = 1;
  for(long int i = 0;i <= N && A * i <= K;i += g){
    if((K - A * i)%B == 0 && (K - A * i + B - 1)/B <= N){
      sum += (nckmodp(N,i,p) * nckmodp(N,(K - A * i)/B,p))%p;
      sum %= p;
      g = G(A,B);
    }
  }
  cout << sum << endl;
}

