ll binpow(ll x, ll p) {
    if (p == 0) {
        return 1;
    }

    if (p % 2 == 1) {
        ll b = binpow(x, p - 1) * x;
        if (b > MOD) {
            b %= MOD;
        }
        return b;
    } else {
        ll b = binpow(x, p / 2);
        if (b > MOD) {
            b %= MOD;
        }
        return b * b % MOD;
    }
}

