	while(e != 0) {
		if(e % 2 == 1) {
			result *= x;
			result %= p;
		}
		e /= 2;
		x *= x;
		x %= p;
	}
	return result;
}

long long comb(long long n, long long r) {
	return (((fact[n] * inv(fact[(((n - r) % p) + p) % p])) % p) * inv(fact[r])) % p;
}

