}

ll COM3(ll N, ll R, ll G, ll B) {
   ll ans = 1;
   ll tmp1 = COM(N, R) % MOD;
   ll tmp2 = COM(N - R, G) % MOD;
   ll tmp3 = COM(N - R - G, B) % MOD;
   ans *= tmp1;
   ans *= tmp2;
   ans %= MOD;
   ans *= tmp3;
   ans %= MOD;
   return ans;
}

