	ll i, j;
	ll ans = 0;
	COMinit();
	for (i = 0; i <= N; i++){
		if (i*A > K){
			break;
		}
		ll resi = K - i*A;
		if (resi%B == 0){
			j = resi / B;
			ll atmp = COM(N, i);
			ll btmp = COM(N, j);
			ans = (ans + 1LL * atmp * btmp % MOD) % MOD;
		}
	}
	cout << ans << endl;

	return 0;
}

