const ll MOD = 998244353;
const ll MAX_N = 3e5 + 10;
ll Inv[MAX_N];
ll fact[MAX_N];
ll factInv[MAX_N];
void Inv_init(){
    Inv[1] = 1;
    for(int i = 2; i < MAX_N; i++) {
        Inv[i] = Inv[MOD%i] * (MOD - MOD/i) % MOD;
    }
}
void fact_init(){
    fact[0] = fact[1] = factInv[0] = factInv[1] = 1;
    for(int i = 2; i < MAX_N; i++){
        fact[i] = (fact[i-1] * i) % MOD;
        factInv[i] = (factInv[i-1] * Inv[i])%MOD;
    }
}

// a^b % MOD;
ll powmod(ll a,ll b) {ll res=1;a%=MOD; for(;b;b>>=1){if(b&1)res=res*a%MOD;a=a*a%MOD;}return res;}
// 逆元 1/a % MOD
ll inversemod(ll a) { return powmod(a,MOD - 2);}
ll nCr(ll n,ll r) {
    if(n < r) return 0;
    return (fact[n] * (factInv[r] * factInv[n-r] % MOD)) % MOD;
}

void init(){
    Inv_init();
    fact_init();
}

inline ll gcd(ll a, ll b) { return b ? gcd(b, a%b) : a; }
inline ll lcm(ll a, ll b) { return a / gcd(a, b)*b; }

/* 拡張ユークリッドの互除法 extgcd */
ll extgcd(ll a, ll b, ll& x, ll& y){
    ll g = a; x = 1; y = 0;
    if(b!=0) { g = extgcd(b, a%b, y, x); y -= (a/b)*x;}
    return g;
}

ll solve(){
    ll res = 0;
    ll N,A,B,K; cin >> N >> A >> B >> K;
    if(A > B) swap(A,B);
    for(ll G = 0; G <= N; G++){
        ll k = K - (A+B)*G;
        if(k < 0) break;
        ll GCD = gcd(A,B);
        if(k%GCD != 0) continue;
        ll n = N - G;
        ll a = A/GCD,b = B/GCD;
        k = k/GCD;
        ll x,y;
        extgcd(a,b,x,y);
        x *= k; y *= k;
        ll LCM = lcm(a,b);
        // |x| +|y| が最小
        ll dx = LCM/a, dy = LCM/b;
        ll cntG = nCr(N,G)%MOD;

        if(x + y > n){
            ll dif = x + y - n;
            ll tmp = dx - dy;
            x -= dif/tmp*dx;
            y += dif/tmp*dy;
        }
        ll _x = x,_y = y;
        while(_x >= 0){
            if(_x+_y<=n){
                ll T = nCr(n,_x)*nCr(n-_x,_y);
                T%=MOD;
                (res += T*cntG)%=MOD;
            }
            _x -= dx;
            _y += dy;
        }
        _x = x+dx;_y = y-dy;
        while(_x+_y<=n){
            if(_y < 0) break;
            ll T = nCr(n,_x)*nCr(n-_x,_y);
            T%=MOD;
            (res += T*cntG)%=MOD;
            _x += dx;
            _y -= dy;
        }
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    init();
    cout << solve() << endl;
    return 0;
}

