    rep(i, 0, K + 1) {
        if (K < A * i) break;
        if (K - A * i >= 0 && (K - A * i) % B == 0) {

            int y = (K - A * i) / B;

            if (!(i <= N && y <= N)) continue;

            ll add = com.nCk(N, i);
            add *= com.nCk(N, y);
            add %= MOD;

            ans += add;
            ans %= MOD;
        }
    }

    cout << ans << endl;


    return 0;
}

