llint mod_pow(llint a, llint n, llint m) {
  llint b, t;
  //----  初期条件
  if ( n == 0 ) { return 1; }    
  //----  事前計算
  a %= m; b = a*a; b %= m;
  //----  再帰呼出
  t = mod_pow(b, n/2, m);                // nが偶数のとき
  //----  事後計算
  if ( n%2 != 0 ) { t *= a; t %= m; }    // nが奇数のときの補正
  //----  結果返却
  return t;                              // 剰余の返却(t＜mを保障)
}

llint memo[400000] = {};
llint C(llint r) {
    if (n / 2 < r) r = n - r;
    if (r == 0) return 1;
    if (memo[r] == -1) memo[r] = C(r - 1) * (n - r + 1) % mod * mod_pow(r, mod - 2, mod) % mod;
    return memo[r];
}

