const ll MOD = 998244353;

ll N, A, B;
ll K;

void solve() {
  init_fact(N, MOD);
  ll ans = 0;
  for (ll xy = 0; xy <= min(K / A, N); xy++) {
    ll v = K - A * xy;
    if (v % B > 0) continue;
    ll yz = v / B;
    for (ll y = max(xy + yz - N, 0LL); y <= min(xy, yz); y++) {
      ll x = xy - y;
      ll z = yz - y;
      ll w = N - x - y - z;
      // printf("x: %lld, y: %lld, z: %lld, w: %lld\n", x, y, z, w);
      ll m = 1;
      m = (m * mod_comb_fast(N, x, MOD)) % MOD;
      m = (m * mod_comb_fast(N - x, y, MOD)) % MOD;
      m = (m * mod_comb_fast(N - xy, z, MOD)) % MOD;
      ans = (ans + m) % MOD;
    }
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%lld%lld%lld%lld", &N, &A, &B, &K);
}

int main() {
  input();
  solve();
  return 0;
}

