    fact[i] = (lint)i * fact[i - 1] % mod;
  vector<int> inv_fact(maxn + 1);
  inv_fact[maxn] = inv(fact[maxn], mod);
  for (int i = maxn - 1; i >= 0; --i)
    inv_fact[i] = (lint)inv_fact[i + 1] * (i + 1) % mod;
  auto binom = [&](int a, int b) -> int {
    if (!(0 <= b && b <= a)) return 0;
    return (lint)fact[a] * inv_fact[a - b] % mod * inv_fact[b] % mod;
