    long long x = mypow(n, k / 2);
    x = x * x % mod;
    if (k & 1) x = x * n % mod;
    return x;
}
long long cnk(long long n, long long k) {
    return ((fct[n] * rfct[n - k]) % mod) * rfct[k] % mod;
}
vector<long long> good[500000];
long long solve(int n, long long K) {
    if (K < 0) return 0;
    int x = K % B;
    if (good[x].size() == 0) return 0;
    auto it = upper_bound(good[x].begin(), good[x].end(), K);
    if (it == good[x].begin()) return 0;
    it--;
    long long c = 0, f = 0;
    while (1) {
        if (*it / A + (K - *it) / B <= n) {
            f = cnk(n, *it / A);
            f = f * cnk(n - *it / A, (K - *it) / B) % mod;
            c += f;
            if (c >= mod) c -= mod;
        }
        else break;
        if (it == good[x].begin()) break;
        it--;

    }
    return c;
}
