    FOR(i, 1, N + 1) {
        fact[i] = mul(i, fact[i - 1]);
    }
    rep(n, N + 1) {
        ll res = K - (ll) A * n;
        if (res % B != 0) continue;
        ll m = res / B;
        if (!(0 <= m && m <= N)) continue;
        ans = add(ans,mul(nCk_gyakugen(N, n, fact, bigmod), nCk_gyakugen(N, m, fact, bigmod)));
    }
    cout << ans << endl;

    return 0;
}

