struct Combinatorics{
public:
    int n;
    vector<mint> fact;
    vector<mint> fact_inv;

    explicit Combinatorics(int n) : n(n){
        fact.resize(n+1, 1);
        fact_inv.resize(n+1, 1);
        for(int i=2;i<=n;++i) fact[i] = fact[i-1] * i;
        fact_inv[n] = fact[n].inv();
        for(int i=n;2<=i;--i) fact_inv[i-1] = fact_inv[i] * (i);
    }

    mint comb(int n, int r) const {
        if(r<0 or n<r) return 0;
        return fact[n] * fact_inv[n-r] * fact_inv[r];
    }

    mint perm(int n, int r) const {
        if(r<0 or n<r) return 0;
        return fact[n] * fact_inv[n-r];
    }
};

