// ユークリッドの互除法
LL extgcd(LL a, LL b, LL &x, LL &y)
{
	LL g = a; x = 1; y = 0;
	if (b != 0)
	{
		g = extgcd(b, a%b, y, x);
		y -= (a / b)*x;
	}
	return g;
}

// 逆元
LL mod_inverse(LL a, LL m)
{
	LL x, y;
	extgcd(a, m, x, y);
	return (m + x % m) % m;
}

// 階乗
std::vector<LL>fact;
void mod_fact(LL n, LL m)
{
	fact.resize(n + 1);
	fact[0] = 1;
	for (LL i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i%m;
}

// nCk mod p
LL mod_comb(LL n, LL k, LL m)
{
	if (n < k) return 0;
	return fact[n] * mod_inverse(fact[k] * fact[n - k] % m, m) % m;
}

int main()
{
	in >> N >> A >> B >> K;
	mod_fact(N, mod);
	for (LL x = 0; x <= N; ++x)
	{
		LL y = (K - A * x) / B;
		if (y < 0 || N < y) continue;
		if (A*x + B * y == K)
		{
			ans += (mod_comb(N, x, mod)*mod_comb(N, y, mod)) % mod;
			ans %= mod;
		}
	}
	out << ans << std::endl;
