void solve(){
	int N;
	LL A,B,K;
	cin>>N>>A>>B>>K;

	const LL mod = (LL)998244353;//prime
	LL ans = 0;

	vector<LL> kai_inv(N+1);
	kai_inv[0] = 1;
	for(int i=1;i<=N;++i){
		kai_inv[i] = kai_inv[i-1] * powMod(i,mod-2,mod);
		kai_inv[i] %= mod;
	}

	LL kai_N=1;
	for(int i=1;i<=N;++i){
		kai_N*=i;
		kai_N%=mod;
	}
	for(LL a=0;a<=N;++a){//3*10^5
		LL nokori = K - A*a;
		if(nokori<0){
			break;
		}
		if( nokori%B ){//割り切れない
			continue;
		}
		LL b = nokori/B;

		//Aがa個,Bがb個
		//if(max(a,b) > N){continue;}//
		for(int c=min(a,b);c>=0;--c){
			if(a+b-c>N){
				break;
			}

			LL res = (kai_N*kai_inv[a-c]) % mod;
			res = (res*kai_inv[b-c]) % mod;
			res = (res*kai_inv[c]) % mod;
			res = (res*kai_inv[N-(a+b-c)]) % mod;
			ans += res;
			ans %= mod;
			if(ans<0){
				cout<<endl;
			}
		}
	}
	cout << ans << endl;
}

