constexpr int64 MOD = 998244353;
constexpr int MAX_N = 300005;

int64 factorial[MAX_N];

int64 powMod(int64 a, int64 n)
{
    int64 res = 1, p = a % MOD;
    while (n > 0)
    {
        if (n & 1)
        {
            (res *= p) %= MOD;
        }
        (p *= p) %= MOD;
        n >>= 1;
    }
    return res;
}

int64 choose(int x, int y)
{
    if (y > x) return 0;
    int64 res = (factorial[x] * powMod(factorial[y], MOD - 2)) % MOD;
    (res *= powMod(factorial[x - y], MOD - 2)) %= MOD;
    return res;
}

int main()
{
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int64 N, A, B, K;
    cin >> N >> A >> B >> K;

    factorial[0] = 1;
    for (int n = 1; n <= N; n++)
    {
        (factorial[n] = n * factorial[n - 1]) %= MOD;
    }

    int64 ans = 0;
    for (int64 acnt = 0; acnt <= N; acnt++)
    {
        if (K - acnt * A < 0 or (K - acnt * A) % B != 0) continue;
        int64 bcnt = (K - acnt * A) / B;

        (ans += (choose(N, acnt) * choose(N, bcnt) % MOD)) %= MOD;
    }
    cout << ans << endl;

    return 0;
}

