inline int Power(int n,int e,int mod){
	long long res=1;
	long long pow=n;
	while(e){
		if(e&1) res=(res*pow)%mod;
		pow=(pow*pow)%mod;
		e>>=1;
	}
	return res;
}

int Rev[300003],Stair[300003];

inline int Comb(int n,int r,int mod){
	if(n<r||min(n,r)<0) return 0;
	return ((ll)Stair[n]*Rev[r])%mod;
}

