	rep(i,N) Stair[i+1]=((ll)Stair[i]*(i+1))%Mod; 
	rep(i,N+1) Rev[i]=Power((ll)Stair[i]*Stair[N-i]%Mod,Mod-2,Mod); 
	rep(i,N+1) memo[i]=Comb(N,i,Mod);
