	if(K_ < 0) break;
	if(K_ == 0){
	  ++ans;
	  ans %= MOD;
	  continue;
	}

	d = ext_gcd(A, B, x, y);
	if(K_ % d != 0) continue;
	LL mul = K_ / d;

	K_ *= mul;
	LL a = A;
	LL b = B;
	x *= mul;
	y *= mul;

	LL ub = 1e15, lb = -1e15;
	if(a != b){
	  mini(ub, flr(N_ - (x+y), b - a));
	  maxi(lb, cl(-x - y, b-a));
	}
	else if(x + y < 0 || N_ < x + y)
	  continue;
	mini(ub, flr(N_ - x, b));
	maxi(lb, cl(-x, b));
	mini(ub, flr(y, a));
	maxi(lb, cl(y - N_, a));

	if(lb <= ub){
	  FOR(k,lb,ub+1){
		LL xx = x + b*k;
		LL yy = y - a*k;
		(ans += fact[N] * facti[xx] %MOD* facti[yy] %MOD* facti[z]%MOD * facti[N-xx-yy-z]%MOD) %= MOD;
	  }
	}
  }
  cout << ans << endl;

  return 0;
}

