//ここから編集する
class Combination {

public:
    vector<ll> fact;

    Combination(int max_n) {
        //1 ~ n!までの階乗modを求める
        int n = max_n;
        vector<ll> fact(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        this->fact = fact;
    }

    template<typename T>
    //templateをつかってみｔか
    ll pow(T x, int y) {
        if (y == 0) return 1;
        if (y == 1) return x;
        if (y == 2) return (x * x) % MOD;
//        if (y % 2 == 1) return pow(x, y / 2) * pow(x, y / 2) % MOD;
        if (y % 2 == 1) return pow(pow(x, y / 2), 2) * x % MOD;
//        return pow(x, y / 2) * pow(x, y / 2) % MOD;
        return pow(pow(x, y / 2), 2) % MOD;
    }

    ll nCk(int n, int k) {
//        return (fact[n] * pow(fact[n-k],MOD-2) * pow(fact[k],MOD-2)) % MOD;
        return (((fact[n] * pow(fact[n - k], MOD - 2)) % MOD) * pow(fact[k], MOD - 2)) % MOD;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);


    ll N,A,B,K;
    cin >> N >> A >> B >> K;

    Combination com(N + 5);

    ll ans = 0ll;
    for(ll i = 0; i <= N; i++){
        ll x = i;
        if(K - A * x >= 0 && (K - A * x) % B == 0){
            ll y = (K - A * x) / B;
            if(N < x || N < y) break;

            ll tmp = com.nCk(N,x);
            tmp *= com.nCk(N,y);
            tmp %= MOD;
            ans += tmp;
            ans %= MOD;
        }
    }

    cout << ans << endl;

    return 0;
}

