typedef long long LL;
const int mod = 998244353;
LL f[300005], rf[300005];
LL inv(LL a, LL b){
	LL res = 1;
	while(b){
		if(b%2) res = (res*a)%mod;
		a = (a*a)%mod;
		b/=2;
	}
	return res;
}
LL ncr(LL a, LL b){
	return f[a]*rf[b]%mod*rf[a-b]%mod;
}
int main(){
	LL n, a, b, k;
	scanf("%lld%lld%lld%lld", &n, &a, &b, &k);
	f[0] = 1;
	for(int i=1;i<=n;i++) f[i] = (f[i-1]*i)%mod;
	for(int i=0;i<=n;i++) rf[i] = inv(f[i], mod-2);
	if(k == 0){
		printf("1\n");
		return 0;
	}
	LL ans = 0;
	for(int i=0;i<=n;i++){
		LL ca = i;
		LL cb = (k-ca*a);
		if(cb%b != 0) continue;
		cb /= b;
		if(max(ca, cb) > n) continue;
		ans = (ans + ncr(n, ca)*ncr(n, cb))%mod;
	}
	printf("%lld\n", ans);
}

