const int MOD = 998244353;
const ll LINF = 1e18;
const ll NMAX = 1e6;
ll fac[NMAX + 1], inv[NMAX + 1], finv[NMAX + 1];
ll N, A, B, K;

void cominit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    FOR(i, 2, NMAX + 1) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll comb(ll n, ll k) {
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll d = a;
    if(b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

int main() {
    cin >> N >> A >> B >> K;
    if(K == 0) cout << 1 << "\n";
    cominit();
    ll ans = 0;
    REP(n, N + 1) {
        if((K - A * n) % B || K - A * n < 0) {
            continue;
        } else {
            ll m = (K - A * n) / B;
            ans += (comb(N, n) * comb(N, m)) % MOD;
            ans %= MOD;
        }
    }
    cout << ans << "\n";
    return 0;
}

