#include <iostream>
typedef long long ll;
using namespace std;
const int MOD =998244353;
const int N = 300003;
ll fact[N], inv[N];


ll modularExponentiation(ll x,ll n,int M)
{
    if(n==0)
        return 1;
    else if(n%2 == 0)        //n is even
        return modularExponentiation((x*x)%M,n/2,M);
    else                             //n is odd
        return (x*modularExponentiation((x*x)%M,(n-1)/2,M))%M;

}

ll bin(ll n, ll m){
    if(m==1) return n;
    n%=MOD;
    if(m%2==0){
        return bin((n*n)%MOD,m/2);
    }
    return (n* bin((n*n)%MOD,m/2))%MOD;
}

void fun(){
    fact[0] =1;
    for(int i=1;i<N;i++){
        fact[i] = (i*fact[i-1])%MOD;
    }
    inv[0] = 1;
    for(int i=1;i<N;i++){
        inv[i] = bin(fact[i],MOD-2);
    }

    for(int i=1;i<=10;i++){
        //cout<<fact[i]<<" "<<inv[i]<<"\n";
    }
}

ll ncr(int n,int r){

    return ((fact[n]*inv[r])%MOD*inv[n-r])%MOD;
    //return fact[n]/(fact[r] * fact[n-r]);
}

