    fun();
    //cout<<bin(6,MOD-2)<<endl;
    cin>>n>>a>>b>>k;
    for(int i=0;i<=n;i++){
        int rem = k-(a*i);
        if(rem%b==0){
            rem/=b;
        } else continue;
        ans+=(ncr(n,i)*ncr(n,rem))%MOD;
    }
    cout<<ans;
}

