const int Maxv = 300005, Mod = 998244353; 
long long inv[Maxv], fac[Maxv], ans, a, b, n, k, tmp; 

long long Pow(long long c, int d){
    long long res = 1; 
    while (d) {
        if (d & 1) {
            res = res * c % Mod; 
        }
        c = c * c % Mod; 
        d >>= 1; 
    }
    return res; 
}

long long C(long long c, long long d){
    return fac[c] * inv[d] % Mod * inv[c - d] % Mod; 
}

int main(){
    scanf("%lld%lld%lld%lld", &n, &a, &b, &k); 
    fac[0] = inv[0] = 1; 
    for (int i = 1; i < Maxv; i++) {
        fac[i] = fac[i - 1] * i % Mod; 
        inv[i] = Pow(fac[i], Mod - 2); 
    }
    for (int i = 0; i * a <= k && i <= n; i++) {
        tmp = k - i * a; 
        if (tmp % b == 0) {
            tmp /= b; 
            if (tmp <= n) {
                ans = (ans + C(n, i) * C(n, tmp)) % Mod; 
            }
        }
    }
    printf("%lld\n", ans); 
    return 0; 
}

