using namespace std;
void pas(vector<vector<long int> >vec){
  for(int i=0;i<vec.size();i++){
    vec[i][0]=1;
    vec[i][i]=1;
  }
  for(int i=1;i<vec.size();i++){
    for(int j=1;j<i;j++){
      vec[i][j]=(vec[i-1][j-1]+vec[i-1][j])%M;
    }
  }
}
int combi(long int n,long int k){
  vector<vector<long int> >v(n+1,vector<long int>(n+1,0));
  pas(v);
  return v[n][k];
}
int main(){
  int n,a,b,k;
  cin>>n>>a>>b>>k;
  int sum=0;
  for(int x=0;x<=n;x++){
    for(int y=0;y<=n-x;y++){
      if((k-a*x-(a+b)*y)%b==0 && (k-a*x-(a+b)*y)>=0){
        int z=(k-a*x-(a+b)*y)/b;
        sum+=(combi(n,x)*combi(n-x,y)*combi(n-x-y,z))%M;
      }
    }
  }
  cout<<sum<<endl;
}

