int inv(int x) {
   int pw = mod - 2;
   int sol = 1;
   for(; pw; pw /= 2) {
      if(pw & 1) {
         sol = 1LL * sol * x % mod;
      }
      x = 1LL * x * x % mod;
   }
   return sol;
}
int comb(int x, int y) {
   if(a > b)return 0;
   int v1 = fa[x];
   v1 = 1LL * v1 * inv(fa[y]) % mod;
   v1 = 1LL * v1 * inv(fa[x - y]) % mod;
   return v1;
}
int32_t main() {

