   long long ans = 0;

   for(int ca = 0; ca <= n; ++ca) {
      long long cb = (k - ca * a) / b;
      if(cb<0)continue;
      if((k - ca * a) % b)continue;
      if(ca>n||cb>n)continue;
      ans = (ans + 1LL * comb( n, ca) * comb(n, cb)) % mod;
   }
