#include <bits/stdc++.h>
#define int long long
using namespace std;
int MOD = 998244353;
vector<int> fact;
int pw(int a, int b){
    if (b==0) return 1;
    if (b == 1) return a%MOD;
    if (b%2) return (a*pw(a, b-1)) % MOD;
    int rs = pw(a, b/2);
    return (rs*rs)%MOD;
}
int C(int n, int k){
    int X = fact[n];
    int Y = (fact[k] * fact[n-k]) % MOD;
    return (X * pw(Y, MOD-2)) % MOD;
}
signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n, a, b, k;
    cin >> n >> a >> b >> k;
    fact.push_back(1);
    for (int i=1; i < 5e5; i++) fact.push_back((fact.back() * i)%MOD);
    int ans = 0;
    for (int i=0; i <= n; i++){
        int rest = k-a*i;
        if (rest%b) continue;
        int j = rest / b;
        if (j < 0 || j > n) continue;
        ans += (C(n, i) * C(n, j));
        ans %= MOD;
    }
    cout << ans;
    return 0;
}

