typedef pair<li, li> PI;

// a x + b y = gcd(a, b)
inline li extgcd(li a, li b, li &x, li &y) {
    li g = a; x = 1; y = 0;
    if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}

inline li invMod(li a, li m) {
    li x, y;
    if (extgcd(a, m, x, y) == 1) return (x + m) % m;
    else                         return 0; // unsolvable
}

li fact[300300];

inline li combi(li n, li k) {
    return (((fact[n] * invMod(fact[k], MOD)) % MOD) * invMod(fact[n - k], MOD)) % MOD;
}

inline li calc(li r, li g, li b, li n) {
    li res = combi(n, r);
    res = (res * combi(n - r, g)) % MOD;
    res = (res * combi(n - r - g, b)) % MOD;
    return res;
}

int main() {
    li n, a, b, k;
    fact[0] = 1;
    repp(i, 1, 300100) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    cin >> n >> a >> b >> k;
    vector<PI> candidates;
    rep(i, n + 1) {
        li nn = k - a * i;
        if (nn % b == 0) {
            candidates.pb({i, nn / b});
        }
    }

    li res = 0;
    rep(i, sz(candidates)) {
        rep(j, min(candidates[i].F, candidates[i].S) + 1) {
            if (candidates[i].F + candidates[i].S - j > n) {
                continue;
            }
            res = (res + calc(j, candidates[i].F - j, candidates[i].S - j, n)) % MOD;
        }
    }
    cout << res << endl;

    return 0;
}

#include <iostream>
using namespace std;

const long long p = 998244353;
long long fac_cache[1000000] = {};
long long invfac_cache[1000000] = {};

long long power(long long a, int n) {
    long long l;
    if (a == 1) {
        return 1;
    } if (n == 0) {
        return 1;
    } else if (n == 1) {
        return a % p;
    } else if (n % 2 == 0) {
        l = power(a, n/2);
        return l * l % p;
    } else {
        return (long long)power(a, n-1) * a % p;
    }
}

void makefac(int N) {
    int i;
       fac_cache[0] =    fac_cache[1] = 1;
    invfac_cache[0] = invfac_cache[1] = 1;
    for (i = 2; i <= N; i++) {
           fac_cache[i] = fac_cache[i-1] * i % p;
        invfac_cache[i] = power(fac_cache[i], p-2);
    }
}

long long fac(int n) {
    return fac_cache[n];
}

long long invfac(int n) {
    return invfac_cache[n];
}

int main() {

    long long N, A, B, K;
    cin >> N >> A >> B >> K;

    makefac(N);

    long long r, g, b, ans = 0, cc;
    for (r = 0; r < N; r++) {
        if (r * A > K) break;
        for (g = 0; g < N-r; g++) {
            if (r * A + g * (A + B) > K) break;
            if ((K - r * A - g * (A + B)) % B == 0) {
                b = (K - r * A - g * (A + B)) / B;
                if (!(r | g | b)) continue;
                cout << r << "," << g << "," << b << " -> ";
                cc = fac(N)
                    * invfac(r) % p
                    * invfac(g) % p
                    * invfac(b) % p
                    * invfac(N-r-g-b) % p;
                cout << cc << endl;
                ans = (ans + cc) % p;
            }
        }
    }

    cout << ans << endl;

}

