long int expbkp(long int b,long int k,long int p){
  vector<long int> modp(1,b % p);
  long int q = b % p,ans = 1;
  for(long int i = 1;pow(2,i) <= k;i++){
    q = (q*q)%p;
    modp.push_back(q);
  }
  for(long int i = 0;pow(2,i) <= k;i++){
    q = pow(2,i);
    if(k & q)ans = (ans * modp[i])%p;
  }
  return ans;
}

long int nckmodp(long int n,long int k,long int p){
  long int ans = (((DP[n] * expbkp(DP[k],p-2,p))%p) * expbkp(DP[n-k],p-2,p))%p;
  return ans;
}

long int G(long int A,long int B,long int K){
  long int ans = 1,i = 2;
  while(i <= A && i <= B && i <= K){
    while(1){
      if(A%i == 0 && B%i == 0 && K%i == 0 && i <= A && i <= B && i <= K){
        A /= i;
        B /= i;
        K /= i;
        ans *= i;
      }
      else break;
    }
    i++;
  }
  return ans;
}

long int first(long int N,long int A,long int B,long int K){
  for(long int i = 0;i <= N && A * i <= K;i++){
    if((K - A * i)%B == 0 && (K - A * i + B - 1)/B <= N){
      return i;
    }
  }
  flag = 0;
  return N + 1;
}

int main() {
  long int N,A,B,K,sum = 0,p = 998244353;
  for(long int i = 1;i <= 300000;i++)DP[i] = (DP[i - 1] * i)%p;
  cin >> N >> A >> B >> K;
  long int g = G(A,B,K);
  for(long int i = first(N,A,B,K);i <= N && A * i <= K;i += g){
    if((K - A * i)%B == 0 && (K - A * i + B - 1)/B <= N){
      sum += (nckmodp(N,i,p) * nckmodp(N,(K - A * i)/B,p))%p;
      sum %= p;
    }
  }
  if(flag)cout << sum << endl;
  else cout << 1 << endl;
}

