void solve(Int N, Int A, Int B, Int K){
	mod_int ans = 0;
	for(int a = 0;a<=N;a++){
		Int b = K - a*A;
		if(b<0 or b%B!=0)continue;
		b/=B;
		if(b>N)continue;
		ans += binom(N,a)*binom(N,b);
	}
	fout<<ans<<endl;
}

