long long int Inv(long long int a, long long int m) {
  int c[50];
  long long int e[50];  
  c[0] = (m-2) % 2, e[0] = (m-2) / 2; 
  for (int i = 0; i < 50; ++i){
     c[i+1] = e[i] % 2;
     e[i+1] = e[i] / 2;  
  }
  long long int d[50]; 
  d[0] = a; 
  for (int j = 0; j < 50; ++j){
     d[j+1] = (d[j] * d[j]) % m; 
  }
  long long int Q; 
  Q = 1; 
  for(int k = 0; k < 50; ++k){
  if (c[k] == 0) Q = Q; 
  if (c[k] == 1) Q = (Q * d[k]) % m; 
  }
 return Q;
}
long long int Fac(long long int a) {
  long long int f[314159]; 
  f[0] = 1; 
  for (int i = 1; i < 314159; ++i){
     f[i] = (f[i-1] * i) % 998244353;  
  }
 return f[a];
}
int main() {
    long long int N, A, B, K; 
    cin >> N >> A >> B >> K;
    long long int p = 998244353; 
    long long int S = 0; 
    for (int m = 0; m <= N; ++m){
    if((K- A * m) % B == 0 
       && K-A * m>= 0 && (K-A * m) / B <= N){ 
    int n = (K- A * m) / B;
    long long int 
      U = (Fac(N-n) * Fac(n)) % p; 
    long long int 
      V = (Fac(N-m) * Fac(m)) % p; 
    long long int
      W = Inv((U * V) % p, p); 
    S = (S + W) % p;
    }
    }
    cout << (((Fac(N) * Fac(N)) % p) * S) % p << endl;
}

