ll MOD = 998244353;
ll num[300010];
ll powmod(ll x,ll n){
    if(n == 0)return 1;
    ll ans = powmod(x*x%MOD,n/2);
    if(n % 2)ans = ans * x % MOD;
    return ans;
}

ll divmod(ll a,ll b){
    return ((a%MOD) * (powmod(b,MOD-2)%MOD)) % MOD;
}

void combi(ll n,ll r){
    for(ll i = 1;i <= r;i++){
        num[i] = divmod((n-i+1)*num[i-1],i);
    }
}
main(){
    ll N,A,B,K;
    cin >> N >> A >> B >> K;
    num[0] = 1;
    combi(N,N);
    ll ans = 0;
    rep(i,N){
        if((K - A*i) % B != 0)continue;
        int x = i,y = (K - A*i) / B;
        if(y < 0 || y > N)continue;
        ans += num[x] * num[y] % MOD;
        ans %= MOD;
    }
    cout << ans << endl;
}

