  modint ans = 0;
  rep(i,N + 1){
    ll L = K - A * i;
    if(L < 0) break;
    if(L % B != 0) continue;
    ll j = L / B;
    //trc(i , j);
    ll cur = COM(N , i) * COM(N , j) % MOD;
    ans += cur;
  }
  out(ans);
}

