const ll MAX_N = 3 * 100000 + 1;
ll N, A, B, K;
ll ncr[MAX_N];

const ll MOD_N = 998244353;

ll gcd(ll a, ll b) {
    return b != 0 ? gcd(b, a % b) : a;
}

ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll g = a; x = 1; y = 0;
    if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}

ll modinv(ll a, ll m) {
    ll x, y;
    if (extgcd(a, m, x, y) == 1) {
        return (x + m) % m;
    } else {
        return 0;
    } // unsolvable
}

// nCr mod m = modc(n,r,m)
ll modc(ll a, ll b, ll m) {
    ll c = 1;
    REP(i, 0, b) {
        c = c * (a - i) % m;
        c = c * modinv(i + 1, m) % m;
    }
    return c;
}

void solve() {
    // K = A * a + B * b, 0 <= a,b <= N
    // answer = N C a + N C b

    ll answer = 0;

    // nCr+1 = (n-r / r+1) * nCr
    // nCr   = (n-r+1)/r * nC(r-1)
    ncr[0] = 1;
    ncr[1] = N;
    REP(i,2,N) {
        ncr[i] = ((N - i + 1) * modinv(i, MOD_N) % MOD_N) * ncr[i-1] % MOD_N;
    }

    REP(a,0,N) {
        if (K - A * a < 0 || (K - A * a) % B != 0) continue;

        ll b = (K - A * a) / B;

        answer += ncr[a] * ncr[b] % MOD_N;
        answer %= MOD_N;
    }

    printf("%lld\n", answer);

    return;
}

