ll solve() {
    ll N, A, B, K;
    cin >> N >> A >> B >> K;
    const ll MOD = 998244353;
    auto Add = [&](ll& x, ll y, ll m) { x = ( x + y % m ) % m; };
    auto Mul = [&](ll& x, ll y, ll m) { x = ( x * y % m ) % m; };
    auto Pow = [&](ll x, ll n, ll m) -> ll {
        ll t = x % m, r = 1;
        while ( n > 0 ) {
            if ( n & 1 ) Mul(r, t, m);
        Mul(t, t, m);
        n >>= 1;
        }
        return r;
    };
    auto Inv = [&](ll a, ll m) -> ll {
        return Pow(a, m - 2, m);
    };
    auto gcd = [](ll a, ll b) {
        while ( b != 0 ) {
            ll t = b;
            b = a % b;
            a = t;
        }
        return a;
    };
    ll g = gcd(A,B);
    if ( K % g != 0 ) return 0;
    if ( (A+B)*N < K ) return 0;
    A /= g;
    B /= g;
    K /= g;
    if ( A > B ) swap(A,B);
    ll AB = A*B;
    // A!=Bのとき
    ll ia = 1, ib = 1;
    for ( ; ia < B; ia++ ) {
        if ( ia * A % B == 1 ) break;
    }
    for ( ; ib < A; ib++ ) {
        if ( ib * B % A == 1 ) break;
    }
    ll a = K % B, b = K % A;
    Mul(a, ia, B);
    Mul(b, ib, A);
    ASSERT((a*A+b*B)%AB == K%AB, a, b, a*A+b+B, K%(A*B));
    while ( a*A+b*B > AB ) a -= B;
    a += K / AB * B;
    ASSERT(a*A+b*B == K, a, b, a*A+b+B);
    if ( a > N ) {
        ll k = (a-N)/B;
        a -= k * B;
        b += k * A;
    }
    vector<ll> C(N+1);
    ll c = 1;
    C[0] = c;
    for ( ll i = 1; i <= N; i++ ) {
        Mul(c, N-i+1, MOD);
        Mul(c, Inv(i, MOD), MOD);
        C[i] = c;
    }
    ll ans = 0;
    while ( a >= 0 && b <= N ) {
        if ( a <= N ) {
            ll w = 1;
            Mul(w, C[a], MOD);
            Mul(w, C[b], MOD);
            Add(ans, w, MOD);
        }
        a -= B;
        b += A;
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

