template<i64 N>
ModInt (&factorial_table())[N] {
    static ModInt fac[N] {};

    if(fac[0] != 1) {
        fac[0] = 1;
        FOR(i, 1, N) {
            fac[i] = i * fac[i-1];
        }
    }
    return fac;
}

template<i64 N>
ModInt (&ifactorial_table())[N] {
    static ModInt ifac[N] {};

    if(ifac[0] != 1) {
        decltype(auto) fac = factorial_table<N>();
        ifac[N-1] = fac[N-1].inv();
        for(i64 i = N-2; i >= 0; --i)
            ifac[i] = (i+1) * ifac[i+1];
    }
    return ifac;
}

ModInt comb(i64 n, i64 r, const ModInt* fac, const ModInt* ifac) {
    if(n < r) return 0;
    return fac[n] * ifac[r] * ifac[n-r];
}

