}
ll c(ll a, ll b) {
    return f[a] * inv[b] % mod * inv[a-b] % mod;
}
ll gao(ll x, ll y, ll z) {
    return c(n, x) * c(n-x, y) % mod * c(n-x-y, z) % mod;
}
