const uint32_t M = 998244353;

struct modint {
	uint32_t v;
	modint(int x) : v(x % M) {}
	modint pow(uint32_t p) {
		modint x = 1, a = v;
		while (p) {
			if (p & 1) {
				x = x * a;
			}
			a = a * a;
			p >>= 1;
		}
		return x;
	}
	modint() : modint(0) {}
	modint operator+(modint x) { uint32_t s = v + x.v; return s > M ? s - M : s; }
	modint operator-() { return v ? M - v : 0; }
	modint operator*(modint x) { return (uint64_t)v * x.v % M; }
	modint operator/(modint x) { return operator*(x.pow(M - 2)); }
};

const int N = 3e5 + 64;
modint fa[N];

modint cnk(int n, int k) {
	assert(0 <= k && k <= n && n < N);
	return fa[n] / (fa[k] * fa[n - k]);
}

