pair<ull,ull> f(pair<ull,ull> a) {
    bool sw = true;
    if(a.first == 0 || a.second == 0)
        return make_pair(1,1);
    if(a.first < a.second) {
        sw = !sw;
        ull s = a.second;
        a.second = a.first;
        a.first = s;
    }
    pair<ull,ull> c;
    c.first = a.second;
    c.second = a.first % a.second;
    pair<ull,ull> ret = f(c);
    ret.first -= ret.second * (ull)(a.first / a.second);
    if(sw) {
        ull s = ret.second;
        ret.second = ret.first;
        ret.first = s;
    }
    return ret;
}

