const int MOD = 998244353;
const int MAX = 300001;
long long fac[MAX], finv[MAX], inv[MAX];
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
long long N, A, B, K;
int f(int na, int nb)
{
    long long ans = 0;
    for (int g = max(0LL, na + nb - N); g <= min(na, nb); g++) {
        int r = na - g;
        int b = nb - g;
        int n = N - r - g - b;
        ans += fac[N] * finv[r] % MOD * finv[g] % MOD * finv[b] % MOD * finv[n] % MOD;
    }
    return ans % MOD;
}
