using namespace std;
typedef long long ll;

#define MAX_N 300005
ll factorial[MAX_N];

void make_factorial_tableMOD(){
    factorial[0] = 1;
    for(int i = 1; i < MAX_N; i++){
        factorial[i] = factorial[i-1]*i%MOD;
    }
}

ll bisection_powerMOD(ll x,ll y){
    if(y==0)        { return 1; }
    ll t = bisection_powerMOD(x*x%MOD,y/2);
    if(y%2==1)      { t = t*x%MOD; }
    return t;
}

ll nCrMOD(int n, int r){
    assert(r >= 0);
    ll a = factorial[n];
    ll b = a*bisection_powerMOD(factorial[r],(MOD-2))%MOD;
    ll c = b*bisection_powerMOD(factorial[n-r],MOD-2)%MOD;
    return c % MOD;
}

int main(){
    ll n, a, b, k;
    cin >> n >> a >> b >> k;
    ll ans = 0;
    make_factorial_tableMOD();

    for(int i = 0; i < n+1; i++){
        ll anum = (ll)i;
        ll r = k - anum*a;
        ll bnum = r/b;
        if(r % b == 0LL && bnum <= n){
            ans += (nCrMOD(n,anum)*nCrMOD(n,bnum))%MOD;
        }
    }

    cout << ans%MOD << endl;
    return 0;
}

