	for(int i=0;i<=n;i++)
		if((k-a*i)%b==0&&(k-a*i>=0))
		{
			int t=(k-a*i)/b;
			f[i]=(calc(n,i)*calc(n,t))%mod;
			ans=(ans+f[i])%mod;
		}
	printf("%lld\n",ans);
