const int setModMax = k6;
bool was_set_mod = 0;
mint *fac, *finv, *inv;
void setMod() {
    was_set_mod = 1;
    int mo = MOD;
    fac = (mint *) malloc(setModMax * sizeof(mint));
    finv = (mint *) malloc(setModMax * sizeof(mint));
    inv = (mint *) malloc(setModMax * sizeof(mint));
    fac[0] = fac[1] = 1;
    finv[0] = 1;
    finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < setModMax; i++) {
        fac[i] = fac[i - 1] * i;
        inv[i] = -inv[mo % i] * (mo / i);
        finv[i] = finv[i - 1] * inv[i];
    }
}
mint com(ll n, ll r) {
    if (n < r || r < 0)return 0;
    if (!was_set_mod)setMod();
    return fac[n]() * finv[r]()%MOD * finv[n - r];
}
