	int res = bpow(mult(x, x), y / 2);
	if (y % 2 == 1) {
		res = mult(res, x);
	}
	return res;
}

int inv(int x) {
	return bpow(x, M - 2);
}

int cnk(int n, int k) {
	return mult(fact[n], mult(ifact[k], ifact[n - k]));
}

