		}
	}
	int ans = 0;
	while (base_x <= n) {
		int64 base_y = (k - base_x * (int64) a) / b;
		if (base_y <= n) {
			ans = (ans + cnk(n, base_x) * (int64) cnk(n, base_y)) % M;
		}
		base_x += b;
	}
