long long powMod(long long x, long long y) {
  long long r = 1, a = x % mod;
  while (y) {
    if (y & 1) r = (r * a) % mod;
    a = (a * a) % mod;
    y /= 2;
  }
  return r;
}

void setFact() {
  const int N = FACT_MAX;
  fact[0] = 1;
  for (int i = 1; i < N; i++) {
    fact[i] = fact[i - 1] * i;
    fact[i] %= mod;
  }
  revFact[N - 1] = powMod(fact[N - 1], mod - 2);
  for (int i = N - 2; i >= 0; i--) {
    revFact[i] = revFact[i + 1] * (i + 1);
    revFact[i] %= mod;
  }
}

long long getC(int a, int b) {
  if (a < b) return 0;
  return (((fact[a] * revFact[b]) % mod) * revFact[a - b]) % mod;
}

