ll exp(ll b, ll e){
	if(e == 0)
		return 1;
	if(e % 2 == 0){
		ll r = exp(b, e/2);
		return (r*r) % MOD;
	}
	return (b*exp(b, e-1)) % MOD;
}

ll modInv(ll a){
	return exp(a, MOD-2);
}

ll BC(ll n, ll k){
	if(k == 0)
		return 1;

	ll r = 0;
	r += F[n];
	r = (r *modInv(F[k])) % MOD;
	r = (r *modInv(F[n-k])) % MOD;
	return r;
}

int main(){
	cin >> N >> A >> B >> K;
	F[0] = 1;
	for(int i = 1; i <= N; ++i){
		F[i] = (F[i-1] * i) % MOD;
	}
	ll C = 0;
	for(int i = 0; i <= N; ++i){
		ll K2 = K - i*A;
		if(K2 % B == 0){
			ll j = K2/B;
			if(j <= N){
				//cout << "BC i: " << N << ", "<< i <<": "<< BC(N, i) << endl;
				//cout << "BC j: " << N << ", "<< j <<": "<< BC(N, j) << endl;
				C = (C + BC(N, i)*BC(N, j)) % MOD;
			}
		}
	}

	cout << C << endl;
	return 0;
}

