using namespace std;
long long f[300001];
int N,A,B;
long long K,Ans = 0;
void factorial()
{
   f[0] = 1LL;
   for(int i = 1;i <= 300000;i++)
   {
      f[i] = (long long)(f[i - 1] * i * 1LL)% mod;
   }
}
long long power(int u,int v)
{
   if(v == 0) return 1LL;
   if(v == 1) return u*1LL;
   long long X = power(u,v/2) % mod;
   if(v % 2 == 0) return X * X % mod;
   else return ((X * X) % mod * u) % mod;
}
long long C(int k,int n)
{
   //printf("C(%lld,%lld) = %lld\n",k,n,nume*power(deno,powmod) % mod);n
   long long _n = f[n];
   long long _k = f[k];
   long long _t = f[n - k];
   long long deno = power(_k,powmod) * power(_t,powmod) % mod;
   long long nume = _n;
   return nume * deno % mod;
}
signed main()
{ 
    factorial();
   cin >> N >> A >> B >> K;
   //cout << "Snap!";
