   {
      if((K - A*i) % B == 0LL)
      {
         long long j = (K - A*i)/B;
         if(j > N || j < 0LL) continue;
         Ans += C(i,N) * C(j,N) % mod;
      }
   }
   cout << Ans % mod;
}

