	cin >> N >> A >> B >> K;

	//Kが0の場合は1通り
	if( K==0 ){
		cout << 1 << endl;
		return 0;
	}
	//AとBが同じで、KがAの倍数ではない場合は0通り
	if( ( A == B && K%A != 0 ) ){
		cout << 0 << endl;
		return 0;
	}

	// A>Bにしたい

	if( A < B ){
		swap(A, B);
	}


	long long int i = K / A;
	while( i >= 0 ){
		if( ( K - i * A ) % B == 0 ){
			break;
		}
		i--;
	}
	if( i == -1 ){
		cout << 0 << endl;
		return 0;
	}
	long long int j = ( K - i * A ) / B;
	long long int ans = 0;

	long long int gcdv = gcd(A, B);
