#define Nmax 300010
class Cmod{
private:
    ll a[Nmax],b[Nmax],c[Nmax],m;
public:
    void Init(ll x){
	m=x,a[1]=b[0]=c[0]=1;
	for(int i=1;i<Nmax;i++){
	    if(i>1)a[i]=m-m/i*a[m%i]%m;
	    b[i]=b[i-1]*i%m,c[i]=c[i-1]*a[i]%m;
	}
    }
    ll C(int n,int k){
	return b[n]*c[k]%m*c[n-k]%m;
    }
};

