void gcd(LL a,LL b,LL &x,LL &y,LL &d)
{
	if(b==0)
	{
		x=1;y=0;d=a;
		return;
	}
	gcd(b,a%b,y,x,d);
	y-=(a/b)*x;
}
LL n,A,B,k,x,y,d,tot;
LL Solve(int x1,int x2,int x3)
{
	return inv[x1]*inv[x2]%MO*inv[x3]%MO*inv[n-x1-x2-x3]%MO;
}
