	x*=k,y*=k;
	LL ad1=B,ad2=A;
	LL Ans=0;
	LL j=x/ad1*ad2+y;
	LL i=x%ad1;
	for(;i<=n&&j>=0;i+=ad1,j-=ad2)
	{
		LL m=i+j;
		LL ans=0;
		for(LL c=min(i,j);c>=0&&m-c<=n;c--)
		{
			ans=ans+Solve(i-c,j-c,c);
			if(ans>=MO) ans-=MO;
		}
		Ans=Ans+ans;
		if(Ans>=MO) Ans-=MO;
	}
	printf("%lld\n",Ans*fac[n]%MO);
}

