    for (int i = 1; i < (int)fak.size(); i++) {
        fak[i] = (fak[i - 1] * i) % MD;
        ofak[i] = bak(fak[i]);
    }

    ll ans = 0;
    for (int x = 0; x <= n; x++) {
        if (a * x > k) continue;
        if ((k - a * x) % b != 0) continue;
        int y = (k - a * x) / b;

        ll cnx = (fak[n] * ((ofak[x] * ofak[n - x]) % MD)) % MD;
        ll cny = (fak[n] * ((ofak[y] * ofak[n - y]) % MD)) % MD;
        ans = (ans + cnx * cny) % MD;
    }

    cout << ans << "\n";
}

