        j = (K-A*i)/B;
        while(i <= N && j >= 0) {
            ans = (ans+(fact.comb(N,i)*fact.comb(N,j)%MOD))%MOD;
            i += ca; j -= cb;
        }
    }
    cout << ans << endl;
	return 0;
}

