template <long long Mod = MOD>
class Factorial {
 private:
  int n;

 public:
  vector<long long> fac, inv;

 public:
  Factorial(long long n) : n(n), fac(n + 1), inv(n + 1) {
    fac[0] = 1;
    for (int i = 0; i < n; ++i) fac[i + 1] = fac[i] * (i + 1) % Mod;
    inv[n] = modpow(fac[n], Mod - 2);
    for (int i = n - 1; i >= 0; --i) inv[i] = inv[i + 1] * (i + 1) % Mod;
  };
  long long modpow(long long a, long long n, long long mod = Mod) {
    long long i = 1, ret = 1, p = a;
    while (i <= n) {
      if (i & n) {
        ret = (ret * p) % mod;
      }
      i = (i << 1);
      p = (p * p) % mod;
    }
    return ret;
  }
  long long comb(int a, int b) {
    return (fac[a] * inv[b] % Mod) * inv[a - b] % Mod;
  }
};

class Solver {
 public:
  LL n, a, b, k;
  Factorial<> fac;
  Solver(LL n) : n(n), fac(1000000){};
  vector<LL> extgcd(LL a, LL b) {
    vector<LL> ret(4);
    ret[0] = 1;
    ret[3] = 1;
    LL p, q, r, s;
    while (a % b != 0) {
      p = a / b;
      q = a % b;
      r = ret[2];
      s = ret[3];
      ret[2] = ret[0] - p * ret[2];
      ret[3] = ret[1] - p * ret[3];
      ret[0] = r;
      ret[1] = s;
      a = b;
      b = q;
    }
    ret.erase(ret.begin(), ret.begin() + 2);
    return ret;
  }
  void solve() {
    cin >> a >> b >> k;
    //赤と青を独立に塗ると考えて，両方塗られていたマスがあったらそこを緑とみなす
    LL g = gcd(a, b);
    if (k % g != 0) {
      cout << 0 << endl;
      return;
    }
    if (k == 0) {
      cout << 1 << endl;
      return;
    }
    a /= g, b /= g, k /= g;
    if (a < b) swap(a, b);
    vector<LL> coeff = extgcd(a, b);
    auto x = (coeff[0] % b + b) % b, y = (x - coeff[0]) / b;
    coeff[0] += y * b;
    coeff[1] -= y * a;
    coeff[0] *= k, coeff[1] *= k;
    x = (coeff[0] % b + b) % b, y = (x - coeff[0]) / b;
    coeff[0] += y * b;
    coeff[1] -= y * a;
    Modint<> ans(0);
    for (; coeff[0] <= n; coeff[0] += b, coeff[1] -= a) {
      if (coeff[1] < 0 or n < coeff[1]) continue;
      ans += Modint<>(fac.comb(n, coeff[0])) * fac.comb(n, coeff[1]);
    }
    cout << ans << endl;
  }
};
