		if ((k - re * a) % b == 0) {
			int bl = (k - re * a) / b;
			llint now = (((fact[n] * invfact[re]) % MOD) * invfact[n - re]) % MOD;
			now *= (((fact[n] * invfact[bl]) % MOD) * invfact[n - bl]) % MOD;
			now %= MOD;
			ans += now;
			ans %= MOD;
		}
	}
