// 繰り返し２乗法による冪乗(x^n)計算 O(log(n))
int exponentiation(ll x, int n) {
  int res = 1;
  while (0 < n) {
    if (n & 1) {
      res = x * res % MOD;
    }
    x = x * x % MOD;
    n >>= 1;
  }
  return res;
}

// 組み合わせ nCr の計算 O(1)
ll combination(int n, int r) {
  if (n-r==0 || r==0) return 1;
  static bool flag = true;
  if (flag) {
    // 階乗と階乗の逆数の初期化 O(n)
    factorial[0] = 1; inverse[0] = 1;
    for (int i=1; i<=MAX_N; i++) {
      factorial[i] = factorial[i-1] * i % MOD;
      inverse[i] = exponentiation(factorial[i], MOD-2);
    }
    flag = false;
  }
  return factorial[n] * inverse[n-r] % MOD * inverse[r] % MOD;
}

