ll answer = 0;
ll n, a, b, k;
vpl ns;
ll facts[300005], facts_inv[300005], inv[300005];

void fact_memo(ll n, ll mod){
    facts[0] = facts[1] = 1;
    facts_inv[0] = facts_inv[1] = 1;
    inv[1] = 1;

    For(i, 2, n + 1){
        facts[i] = (i * facts[i - 1]) % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        facts_inv[i] = facts_inv[i - 1] * inv[i] % mod;
    }
}

ll nCk(ll n, ll r){
    if (n == r && n == 0) return 1;
    else if (n <= 0 || r < 0 || r > n) return 0;
    ll val = (facts[n] * facts_inv[n - r]) % MOD;
    val *= facts_inv[r];
    return val % MOD;
}

void solve(){
    rep(i, n + 1){
        ll res = k - i * a;
        if (res < 0) break;
        if (res / b <= n && res % b == 0) ns.pb({i, res / b});
    }

    fact_memo(n, MOD);
    answer = 0;
    rep(i, ns.size()){
        ll n1 = ns[i].e1, n2 = ns[i].e2;
        answer += (nCk(n, n1) * nCk(n, n2)) % MOD;
        answer %= MOD;
    }
    prl(answer);
}

