	for(ll i = 2; i <= N; ++i) inv[i] = (P - P / i) * 1ll * inv[P % i] % P;
	for(ll i = 1; i <= N; ++i) fac[i] = fac[i - 1] % P * i % P, fnv[i] = fnv[i - 1] % P * inv[i] % P;
} 

ll C(ll a, ll b) {
	if(a < 0 or b < 0 or b > a) return 0;
	return fac[a] % P * fnv[b] % P  * fnv[a - b] % P;
}

