inline int Power(int n,int e,int mod){
	long long res=1;
	long long pow=n;
	while(e){
		if(e&1) res=(res*pow)%mod;
		pow=(pow*pow)%mod;
		e>>=1;
	}
	return res;
}

inline int Comb(int n,int r,int mod){
	if(n<r||min(n,r)<0) return 0;
	long long den=1,num=1;
	rep(i,r){ den=den*(i+1)%mod; num=num*(n-i)%mod; }
	long long rev=Power(den,mod-2,mod);
	return (num*rev)%mod;
}


