template<int N, typename T, T M>
struct ModFact {
    T fact[N+1];
    T ifact[N+1];
    ModFact() : fact(), ifact() {
        fact[0] = 1;
        for (int i=0; i<N; ++i)
            fact[i+1] = (fact[i] * (i+1)) % M;
        ifact[N] = power(fact[N], M-2);
        for (int i= N-1; i>=0; --i)
            ifact[i] = (ifact[i+1] * (i+1)) % M;
    }
    T power(T a, T b) {
        T r = 1;
        while (b > 0) {
            if ((b&1) != 0) r = (r*a) % M;
            a = (a*a) % M;
            b >>= 1;
        }
        return r;
    }
    T comb(T n, T r) {
        return (((fact[n] * ifact[r]) % M) * ifact[n - r]) % M;
    }
};


