	map<T,long>* getFactoringMap(T n) { // 素因数分解 key->因数 val->因数の数
		map<T,long> factoring;
		T copy_n = n;
		T maxiter = sqrt(n);
		for (T i = 2;i < maxiter+1;i ++) {
			if (copy_n == 1) break;
			while (!(copy_n % i)) {
				factoring[i]++;
				copy_n /= i;
			}
		}
		if (copy_n != 1) factoring[copy_n]++;
		return (&factoring);
	}

