long long mod_div(long long a, long long b)
{
	if(a % b == 0)
	{
		return a / b;
	}
	long long tmp = MOD - 2, c = b, ret = 1;
	while(tmp > 0)
	{
		if(tmp & 1)//tmp%2==1
		{
			ret *= c;
			ret %= MOD;
		}
		c *= c;
		c %= MOD;
		tmp >>= 1;
	}
	return a * ret % MOD;
}

#define MAX_K 333333
long long combination(long long n, long long r)
{
	if(n < r || n < 0 || r < 0)
	{
		return -1;
	}
	static std::vector<long long>kaijo(MAX_K);
	if(kaijo[0] != 1)
	{
		kaijo[0] = 1;
		for(long long i = 1; i < MAX_K; i++)
		{
			kaijo[i] = (kaijo[i - 1] * i) % MOD;
		}
	}
	long long numerator = kaijo[n];
	long long denominator = (kaijo[r] * kaijo[n - r]);
	return mod_div(numerator, denominator);
}

