        for(;green>=0;green--){

            long long no=n-red-blue+green;
            if(no<0 || no>n) break;
            long long cnt=COM(n,green)*COM(n-green,red-green);
            cnt%=mod;
            cnt*=COM(n-red,blue-green);
            cnt%=mod;
            ans+=cnt;
            ans%=mod;
        }

