            long long bnum = (K - A * rnum) / B;
            if (bnum <= N) {
                long long tmp = (combi_num.calc(N, rnum) * combi_num.calc(N, bnum)) % MOD;
                ret = (ret + tmp) % MOD;
            }
        }
    }

    std::cout << ret << std::endl;

    return 0;
}

