        while (b > 0) {
            if ((b & 1) != 0) r = (r * a) % M;
            a = (a * a) % M;
            b >>= 1;
        }
        return r;
    }
    T comb(T n, T r) {
        return (((fact[n] * ifact[r]) % M) * ifact[n - r]) % M;
    }
};


