//階乗のMOD逆元を利用した組合せの数の計算
class Comb_mod{
public:
	int n;
	vector<long long> fact, fact_rev;
	//1～nまでの階乗のmodを求める．fact[i]，fact_rev[i]はそれぞれ(iの階乗)%MOD，iの階乗のMOD逆元を格納

	Comb_mod(int _n){
		fact=vector<long long>(_n+1, 1);
		fact_rev=vector<long long>(_n+1, 1);
		n=_n;
	}

	//i=1～nについてfact[i]，fact_rev[i]を計算
	void factorial_mod()
	{
		long long temp=1;

		//factの計算
		for(int i=1; i<n+1; i++){
			temp*=i;
			if(temp>=MOD) temp%=MOD;
			fact[i]=temp;
		}

		//フェルマーの小定理:a/b≡a*b^(MOD-2) (mod MOD)
		fact_rev[n]=repeat_pow(fact[n], (int)MOD-2);

		//n!^-1=(n+1)!^-1*(n+1)
		for(int i=n; i>=1; i--){
			fact_rev[i-1]=(fact_rev[i]*i)%MOD;
			//cout<<fact_rev[i]<<endl;
		}
	}
	//組合せの数の計算(nCr，結果をMODで割った余りを返す)
	long long Comb(long long n, long long r)
	{
		//n, rが負またはn<rの時は失敗
		if(n<0||r<0||n<r) return 0;

		//r=0,1の時は計算する必要がない
		if(r==0) return 1;
		if(r==1) return n;

		return (((fact[n]*fact_rev[n-r])%MOD)*fact_rev[r])%MOD;
	}
};

int main(void)
{
	ll n, a, b, k, anssum=0;

	cin>>n>>a>>b>>k;

	Comb_mod cmd(4e5);

	cmd.factorial_mod();

	rep(i, n){
		if((k-a*i)%b) continue;
		ll tempa=i, tempb=(k-a*i)/b, tempans;
		tempans=(cmd.Comb(n, tempa)*cmd.Comb(n, tempb))%MOD;
		anssum=(anssum+tempans)%MOD;

	}
	cout<<anssum<<endl;
}

