int L = 998244353;

unsigned int pairPattern(unsigned int m, unsigned int n,unsigned int K) {
	if (m == 0 && n == 0) {
		return 1;
	}
	else if (m == 0 && n > 0) {
		return pairPattern(0, n - 1, K - 1);
	}
	else if (n == 0 && m > 0) {
		return pairPattern(m - 1, 0, K - 1);
	}
	else {
		return pairPattern(m - 1, n, K - 1) + pair(m, n - 1, K - 1);
	}
}

long long pattern(int i, int j, int N) {
	int l, m, n, min;
	if (i > j) {
		min = i;
	}
	else {
		min = j;
	}
	long long ans = 0;
	for (m = 0; m <= min; m++) {
		l = i - m;
		n = j - m;
		if (l + m + n <= N) {
			ans += pairPattern(l, N - l, N) + pairPattern(m, N - l - m, N - l) + pairPattern(n, N - l - m - n, N - l - m);
		}
	}
	return ans;
}

int main()
{
	long long N,A,B,K;
	cin >> N >> A >> B >> K;
	if (K == 0) {
		cout << 1 << endl;
		return 0;
	}
	int i = 0;
	long long ans = 0;
	while (K - A*i > 0) {
		if ((K - A*i) % B == 0) {
			ans += pattern(i, (K - A*i) / B, N);
		}
		if (ans > L) {
			ans %= L;
		}
		i++;
	}
	cout << ans << endl;
	return 0;
}

