		return pow(n, MOD - 2);
	}
	// 冪乗
	T pow(T n, int a) {
		T res = 1;
		while (a > 0) {
			if (a & 1) (res *= n) %= MOD;
			(n *= n) %= MOD;
			a >>= 1;
		}
		return res;
	}
	// 順列
	T perm(T n, T r) {
		if (r < 0 || n < r) return 0;
		return fc[n] * ifc[n - r] % MOD;
	}
	// 組み合わせ
	T comb(T n, T r) {
		if (r < 0 || n < r) return 0;
		return fc[n] * ifc[r] % MOD * ifc[n - r] % MOD;
	}
	// 重複組み合わせ
	T homo(T n, T r) {
		if (n < 0 || r < 0) return 0;
		return r == 0 ? 1 : comb(n + r - 1, r);
	}
};

