template<typename T>
bool is_prime(T n){
  bool f = true;
  if(n == 1) {
    return 0;
  }
  if(n == 2)
    return true;
  if(n % 2 == 0)
    return false;
  for(int i = 3;i <= (int)(sqrt(n) + 0.1);i += 2){
    if(n % i == 0){
      f = false;
      break;
    }
  }
  return f;
}

template<typename T>
T extend_gcd(T a,T b,T &x,T &y) {
  if (b == 0) {
    x = 1;y = 0;
    return a;
  }
  T r = a % b;
  T d = extend_gcd(b,r,y,x);
  y -= (a / b) * x ;

  return d;
}

template<typename T>
T mod_pow(T x, T n, T mod) {
  T res = 1;
  while (n > 0) {
    if (n & 1) res = res * x % mod; // 最下位ビットが立っているときにx^(2^i)を掛ける
    x = x * x % mod; // xを順次二乗していく
    n >>= 1;
  }
  return res;
}

template<typename T = long long>
struct Zp {
  T n;//数
  T p;// mod p

  Zp() {
    set(0,1000000007);
  }

  Zp(T n_,T p_) {
    set(n_,p_);
  }

  void set(T n_,T p_ = 1000000007) {
    p = p_;
    n = n_ % p;
    if (n < 0) n = p + n;
  }

  T get() const {
    return n;
  }

  Zp operator +() const {
    return Zp(n,p);
  }

  Zp operator -() const {
    return Zp(-n,p);
  }

  Zp operator + (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う";
    return Zp(n+m.n,m.p);
  }

  Zp operator - (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n-m.n,m.p);
  }

  Zp operator * (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n*m.n,m.p);
  }

  Zp operator / (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    if (m.n == 0) cerr << "warning! 0わり" << endl;
    T x,y;
    extend_gcd(m.n,m.p,x,y);
    return n * Zp(x,m.p);
  }

  Zp operator % (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う";
    if (m.n == 0) cerr << "warning! 0剰余" << endl;
    return Zp(n%m.n,m.p);
  }

	Zp& operator +=(const Zp& m){
    return *this = *this + m;
	}

	Zp& operator -=(const Zp& m){
    return *this = *this - m;
	}

	Zp& operator *=(const Zp& m){
		return *this = *this * m;
	}

	Zp& operator /=(const Zp& m){
		return *this = *this / m;
	}

	Zp& operator %=(const Zp& m){
		return *this = *this % m;
	}

  Zp pow(const T m) const { //m乗を計算
    return Zp(mod_pow(n,m,p),p);
  }

  Zp inverse() const {
    T x,y;
    extend_gcd(n,p,x,y);
    return Zp(x,p);
  }

  Zp operator & (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n&m.n,m.p);
  }

  Zp operator | (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n|m.n,m.p);
  }

  Zp operator ^ (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n^m.n,m.p);
  }

  Zp operator ~() const {
    return Zp(~n,p);
  }

  Zp operator << (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n<<m.n,m.p);
  }

  Zp operator >> (const Zp &m) const {
    if (p != m.p) cerr << "warning! 法が違う" << endl;
    return Zp(n>>m.n,m.p);
  }

	Zp& operator &=(const Zp& m){
    return *this = *this & m;
	}

	Zp& operator |=(const Zp& m){
    return *this = *this | m;
	}

	Zp& operator ^=(const Zp& m){
