	long long int bv = B / gcdv;

	combination cb(N);
	while( i >= 0 ){
		if( i <= N && j <= N ){
			ans += cb.cb(N, i, mod)*cb.cb(N, j, mod) % mod;
		}
		i -= bv;
		j += av;
	}
	cout << ans << endl;
}

