  lint ret = 1;
  while(n > 0) {
    if(n & 1) (ret *= x) %= mod;
    (x *= x) %= mod;
    n >>= 1;
  }
  return ret;
}
lint ncr(lint n, lint r, lint mod, vector<lint> frac) {
  return frac[n]*power(frac[r], mod-2, mod)%mod*power(frac[n-r], mod-2, mod)%mod;
