            q[i] += nCr(i,r0+A*j) * nCr(i-r0-A*j,b0-j) % MOD;
            q[i] %= MOD;
        }
    }
    ll ans = 0;
    for(ll i = 1;i<=N;i++){
        ans += q[i] * nCr(N,i) % MOD;
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

