const int N = 3e5 + 10;
const long long MOD = 998244353;

long long n, A, B, K, f[N], inv_f[N];

inline long long add(long long a, long long b) {
  long long c = a + b;
  while (c < 0) c += MOD;
  return c % MOD;
}
inline long long sub(long long a, long long b) { return add(a, -b); }
inline long long mul(long long a, long long b) {
  long long c = (a * b) % MOD;
  while (c < 0) c += MOD;
  return c;
}
inline long long inv(long long x) {
  // should work for non-prime MOD if gcd(x, MOD) = 1
  long long a = x, b = MOD, u = 1, v = 0;
  while (b != 0) {
    int t = a / b;
    a -= t * b;
    u -= t * v;
    swap(a, b);
    swap(u, v);
  }
  return u;
}

int main() {
  ios::sync_with_stdio(0), cin.tie(0), cout.setf(ios::fixed), cout.precision(9);
  cin >> n >> A >> B >> K;

  if (B > A) swap(A, B);

  f[0] = 1;
  for (int i = 1; i <= n; ++i) f[i] = mul(f[i - 1], i);
  for (int i = 0; i <= n; ++i) inv_f[i] = inv(f[i]);

  long long ans = 0;
  for (long long i = 0; i <= n; ++i) {
    if (B * i > K) continue;
    long long tmp = K - B * i;
    if (tmp % (A - B)) continue;
    long long nA = tmp / (A - B);
    long long nB = i - nA;

    if (nB < 0) {
      long long gcd = __gcd(A, B);
      long long tt = A * B / gcd;
      while (nB < 0) {
        nA -= tt / A;
        nB += tt / B;
      }
    }
    long long nAB = min(nA, nB);

    // cerr << "nA + nB: " << nA + nB << endl;
    if (0 <= nA + nB and nA + nB <= n and nA + nB != i) continue;

    // cerr << "now: " << i << endl;
    // cerr << nA << ' ' << nB << ' ' << nAB << endl;
    // cerr << "tmp: " << tmp << ' ' << (A - B) << endl;
    // cerr << "value: " << nA * A + B * nB << endl;
    // lb = nA + nB - nAB, rb = nA + nB
    for (long long j = 0; j <= nAB; ++j) {
      long long tmpA = nA - j;
      long long tmpB = nB - j;
      long long total = tmpA + tmpB + j;
      if (total < 0 or total > n) continue;
      ans = add(ans,
                mul(f[n], mul(inv_f[n - total],
                              mul(inv_f[tmpA], mul(inv_f[tmpB], inv_f[j])))));
    }
  }
  cout << ans << '\n';
}

