using namespace std;
using lint = int64_t;

const int mod = 998244353;
struct ModInt {
    lint x;
    ModInt (lint a) : x((a % mod + mod) % mod) {}
    ModInt operator - () const {
        return ModInt(-x);
    }
    ModInt &operator += (const ModInt &a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    ModInt &operator -= (const ModInt &a) {
        if ((x -= a.x) < 0) x += mod;
        return *this;
    }
    ModInt &operator *= (const ModInt &a) {
        (x *= a.x) %= mod;
        return *this;
    }
    ModInt operator + (const ModInt &a) const {
        ModInt res(*this);
        return res += a;
    }
    ModInt operator - (const ModInt &a) const {
        ModInt res(*this);
        return res -= a;
    }
    ModInt operator * (const ModInt &a) const {
        ModInt res(*this);
        return res *= a;
    }
    ModInt pow(lint t) const {
        if (!t) return 1;
        ModInt a = pow(t / 2);
        a *= a;
        if (t % 2) a *= *this;
        return a;
    }
    ModInt inv() const {
        return pow(mod - 2);
    }
    ModInt &operator /= (const ModInt &a) {
        return (*this) *= a.inv();
    }
    ModInt operator / (const ModInt &a) const {
        ModInt res(*this);
        return res /= a;
    }
    friend ostream &operator << (ostream &os, const ModInt &a){
        os << a.x;
        return os;
    }
};

vector<ModInt> fact;
ModInt combination(int n, int k) {
    if (k < 0 || n < k) return ModInt{0};
    else return fact[n] / fact[k] / fact[n - k];
}

int main() {
    int N;
    lint A, B, K;
    cin >> N >> A >> B >> K;
    ModInt now(1);
    fact.push_back(now);
    rep(i, N) {
        ModInt M(i + 1);
        now *= M;
        fact.push_back(now);
    }
    ModInt ans(0);
    rep(i, N + 1) {
        if (K - A * i >= 0 && (K - A * i) % B == 0 && (K - A * i) / B <= N) {
            ans += combination(N, i) * combination(N, (K - A * i) / B);
        }
    }
    cout << ans << "\n";
    return 0;
}

