		Bin[i] = Bin[i - 1] * 1LL * i % MOD;
}

LL C (LL N, LL M) {
	LL res = (Bin[N] * qwr(Bin[M], MOD - 2) % MOD) * qwr(Bin[N - M], MOD - 2) % MOD;
	return res;
}

int main()
{
	Prepare();
	while(scanf("%d %d %d %lld", &N, &A, &B, &K) != EOF)
	{
		LL ans = 0LL;
		for(int i = 0; i <= N; i++) {
			LL x = (LL)i;
			LL y = (K - A * x) / B;
			if(x >= 0 && (y >= 0 && y <= N) && A * x + B * y == K) 
				ans = (ans + C(N, x) * C(N, y)) % MOD;
		}
		printf("%lld\n", ans);
	}
    return 0;
}

