  long long g = gcd(a, b);
  if (k % g != 0) {
    cout << 0;
    return 0;
  }

  a /= g;
  b /= g;
  k /= g;

  pair<long long, long long> v = euclid(a, b);

  v.fi *= k;
  v.se *= k;

  if (v.fi > 0) {
    long long rem = v.fi / b;
    v.fi = v.fi - rem * b;
    v.se = v.se + rem * a;
  } else {
    long long rem = (abs(v.fi) + b - 1) / b;
    v.fi = v.fi + rem * b;
    v.se = v.se - rem * a;
  }

  long long ans = 0;
  rep(i, -1000000, 1000001) {
    long long x = v.fi - i * b;
    long long y = v.se + i * a;
    if (x < 0 || y < 0 || x > n || y > n) continue;
    (ans += C(n, x) * C(n, y) % mod) %= mod;
  }

  cout << ans;

  return 0;
}

