ll binpow(ll x, ll p) {
    if (p == 0) {
        return 1;
    }

    if (p % 2 == 1) {
        ll b = binpow(x, p - 1) * x;
        if (b > MOD) {
            b %= MOD;
        }
        return b;
    } else {
        ll b = binpow(x, p / 2);
        if (b > MOD) {
            b %= MOD;
        }
        return b * b % MOD;
    }
}

int main() {
    cin >> n >> a >> b >> k;

    fac[0] = 1;
    rfac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = fac[i - 1] * i;
        if (fac[i] > MOD) {
            fac[i] %= MOD;
        }
        rfac[i] = binpow(fac[i], MOD - 2) % MOD;
    }

    ll ans = 0, sqn = (fac[n] * fac[n]) % MOD;
    for (ll x = 0; x <= n; x++) {
        if (k < a * x) {
            break;
        }

        ll r = k - x * a;
        if (r % b == 0) {
            ll y = r / b;
            if (y > n) {
                continue;
            }

            ans += (((sqn *
                    rfac[x] % MOD) *
                    rfac[n - x] % MOD) *
                    rfac[y] % MOD) *
                    rfac[n - y] % MOD;
        }
    }

    cout << ans;

    return 0;
}

