using namespace std;
const int mod = 998244353, N = 3 * 1e5 + 1;
long long fact[N], invfact[N];

int fp(long long a, int p)
{
    long long ans = 1;
    while(p)
    {
        if(p % 2)
            ans *= a, ans %= mod;
        a *= a;
        a %= mod;
        p /= 2;
    }
    return ans;
}

long long cnt(int k, int n)
{
    return fact[n] * invfact[k] % mod * invfact[n - k] % mod;
}

int main()
{
    int n, a, b;
    long long ans(0), k;
    cin >> n >> a >> b >> k;
    if(!k)
        return cout << 1, 0;
    fact[1] = 1; invfact[1] = 1;
    for(int i = 2; i <= N; i++)
        fact[i] = fact[i - 1] * i % mod;
    for(int i = 2; i <= N; i++)
        invfact[i] = fp(fact[i], mod - 2);
    for(int i = 0; i <= n && 1LL * a * i <= k; i++)
    {
        long long left = k - 1LL * a * i;
        if(left % b != 0 || left / b > n)
            continue;
        //cout << i << " " << cnt(i, n) << " " << left / b << " " << cnt(left / b, n) << '\n';
        ans += cnt(i, n) * cnt(left / b, n) % mod;
        ans %= mod;
    }
    cout << ans;
}

