typedef long long ll;

const int MOD = 998244353;

int mod_sum(int a, int b) {
	int res = a + b;
	if (res >= MOD)
		res -= MOD;
	return res;
}
int mod_mult(int a, int b) {
	return (a * 1LL * b) % MOD;
}

int mod_power(int a, int b) {
	int res = 1;
	while (b > 0) {
		if (b % 2 == 1)
			res = mod_mult(res, a);
		a = mod_mult(a, a);
		b = b / 2;
	}
	return res;
}

int inverse(int x) {
	return mod_power(x, MOD-2);
}

const int MX = 300000 + 10;
int fact[MX], in_fact[MX];

void pre() {
	fact[0] = 1;
	for (int i = 1; i < MX; i++)
		fact[i] = mod_mult(fact[i-1], i);

	in_fact[MX-1] = inverse(fact[MX-1]);
	for (int i = MX-2; i >= 0; i--) {
		in_fact[i] = mod_mult(in_fact[i+1], i+1);
	}
}

int main() {

	pre();



	int n, a, b;
	ll k;

	ignore = scanf("%d %d %d %lld", &n, &a, &b, &k);

