	//cout << "K = " << k << endl;

	for (int i = 0; i <= n; i++) {
		int x = i;
		ll tmp = x * 1LL * a;
		if (k >= tmp) {
			ll tmp2 = k - tmp;
			if (tmp2 % b == 0) {
				int y = tmp2 / b;

				//cout << k << " = " << x << " * " << a << " + " << y << " * " << b << endl;


				if (x <= n and y <= n) {
					int free = n - x - y;
