					if (free < 0) {
						int zz = -free;
						x -= zz;
						y -= zz;
						dbl += zz;
						free += zz;
					}


					//cout << x << " " << y << " " << free << " " << dbl << endl;

					while (x >= 0 and y >= 0) {
						int down = mod_mult(in_fact[x], mod_mult(in_fact[y], mod_mult(in_fact[dbl], in_fact[free])));
						int cnt = mod_mult(fact[n], down);

						//cout << "+=" << cnt << endl;

						ans = mod_sum(ans, cnt);

						x--;
						y--;
						dbl++;
						free++;
					}

				}


			}
		}
	}

	printf("%d\n", ans);

