	rep(i, N) {
		fact[i + 1] = fact[i] * (i + 1) % MOD;
		fact_inv[i + 1] = mod_inverse(fact[i + 1]);
	}
	ll ans = 0;
	for(ll a = 0; a <= N; a++) {
		ll K_ = K - a * A;
		if(K_ % B != 0) continue;
		ll b = K_ / B;
		if(b < 0 || N < b) continue;
		ans += comb(N, a) * comb(N, b) % MOD;
	}
	cout << ans << endl;
	return 0;
}

