  LL K;
  scanf("%d%lld%lld%lld", &N, &A, &B, &K);

  LL result = 0;
  REP(a,N+1) {
    if (K >= a * A && (K - a*A) % B == 0 && (K - a*A) / B <= N) {
      int b = (K - a * A) / B;

      result += C(N,a) * C(N,b) % MOD;
    }
  }

  printf("%lld\n", result % MOD);
}

