  else{
    if (N % 2 == 0) {
      return AN(A * A % mod, N / 2) % mod;
    }else{
      return A * AN(A * A % mod, N / 2) % mod;
    }
  }
}


int main(){

  ll N; cin >> N;
  vector <ll> dir(N + 1), rev(N + 1);
  dir[0] = 1;
  for (ll i = 1; i < N + 1; i++){
    dir[i] = dir[i - 1] * i % mod;
  }
  for (ll i = 0; i < N + 1; i++){
    rev[i] = AN(dir[i], mod - 2);
  }

  ll ans = 0;
  ll A, B, K; cin >> A >> B >> K;

  for (ll i = 0; i <= N; i++){
    ll rest = K - A * i;
    if (rest >= 0 && rest % B == 0){
      ll a = i, b = rest / B;
      ll c = N - (a + b);
      ll m = min(a, b);
      for (ll j = 0; j <= m; j++){
        if (c >= 0){
          ll now = dir[N];
          now *= rev[a]; now %= mod;
          now *= rev[b]; now %= mod;
          now *= rev[j]; now %= mod;
          now *= rev[c]; now %= mod;
          ans += now; ans %= mod;
        }
        a--; b--; c++;
      }
    }
  }

  cout << ans << endl;

  return 0;
}

