const int mod = 998244353;

int mod_inv(int a) {
  int b = mod, s = 1, t = 0;
  while (b) {
    int q = a / b;
    swap(a -= q * b, b);
    swap(s -= q * t, t);
  }
  return s < 0 ? s + mod : s;
}

int add_mod(int a, int b) {
  return (a += b - mod) < 0 ? a + mod : a;
}

int mul_mod(int a, int b) {
  return i64(a) * b % mod;
}

void solve() {
  i64 N, A, B, K;
  scanf("%lld %lld %lld %lld", &N, &A, &B, &K);
  vector<int> binom(N + 1); // binom(n, i)
  binom[0] = 1;
  for (int i = 1; i <= N; ++i) {
    binom[i] = mul_mod(binom[i - 1], mul_mod(mod_inv(i), N - i + 1));
  }

  int ans = 0;
  for (i64 x = 0; x <= N; ++x) {
    i64 r = K - A * x;
    if (r < 0 || r % B != 0) continue;
    i64 y = r / B;
    if (0 <= y && y <= N) {
      ans = add_mod(ans, mul_mod(binom[x], binom[y]));
    }
  }
  printf("%d\n", ans);
}

