const int mod = 998244353, MAX = 3e5+5;
int fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i-1]*i%mod;
        inv[i] = mod-inv[mod%i]*(mod/i)%mod;
        finv[i] = finv[i-1]*inv[i]%mod;
    }
}

// 二項係数計算
int COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n]*(finv[k]*finv[n-k]%mod)%mod;
}

signed main(){
  COMinit();
  int n, a, b, k;
  scanf("%lld%lld%lld%lld", &n, &a, &b, &k);
  int ans = 0;
  rep(i,n+1){
    int x = i, last = k-a*i;
    if(last < 0 or last%b)continue;
    int y = last/b;
    ans = (ans+COM(n, x)*COM(n, y))%mod;
  }
  printf("%lld\n", ans);
	return 0;
}

