long long int powmod(long long int a, long long int b)
{
    a %= mod;
    long long int res = 1;
    for (; b > 0; b >>= 1)
    {
        if (b & 1)
            res = (res * a) % mod;

        a = (a * a) % mod;
    }

    return res;
}

