        long long int bs = left / b;

        long long int first = factorial[n] * powmod(((factorial[n - i] * factorial[i]) % mod), mod - 2);
        long long int second = factorial[n] * powmod(((factorial[n - bs] * factorial[bs]) % mod), mod - 2);
        first %= mod;
        second %= mod;

        ans += (first * second) % mod;
        ans %= mod;
    }

    std::cout << ans;
}

