class ModuloCombination {
    using ll = long long;
    ll mod, len;
    std::vector<ll> f, rf;

    ll inv(ll x) {
        ll res = 1;
        ll k = mod - 2;
        ll y = x;
        while (k) {
            if (k & 1) res = (res * y) % mod;
            y = y * y % mod;
            k /= 2;
        }
        return res;
    }

public:
    ModuloCombination(ll mod_)
        : mod(mod_),
          len(1010101),
          f(std::vector<ll>(len)),
          rf(std::vector<ll>(len)) {
        f[0] = 1;
        for (int i = 0; i < len - 1; i++) f[i + 1] = f[i] * (i + 1) % mod;
        for (int i = 0; i < len; i++) rf[i] = inv(f[i]);
    }
    ll c(int n, int k) {
        ll a = f[n];
        ll b = rf[n - k];
        ll c = rf[k];
        ll bc = (b * c) % mod;
        return (a * bc) % mod;
    }
    ll getMod() { return mod; }
};

signed main() {
    cin.tie(0), cout.tie(0), ios::sync_with_stdio(false);
    int n, a, b, k;
    cin >> n >> a >> b >> k;
    ModuloCombination comb(MOD);

    int sum = 0;
    rep (i, n + 1) {
        if ((k - a * i) % b != 0) continue;
        int bi = (k - a * i) / b;
        sum += comb.c(n, i) * comb.c(n, bi);
        sum %= MOD;
    }
    print(sum);

    return 0;
}

