long long power(long long a, int n) {
	if(n == 0) return 1;
	if(n == 1) return a;
	long long b = power(a, n/2);
	b = (b*b) % mod;
	if(n&1) b = (b*a) % mod;
	return b;
}

long long C(int k, int n) {
	if(n < k) return 0;
	return (fact[n] * power(fact[k] * fact[n-k] % mod, mod - 2)) % mod;
}

