ll fac[MAXN],inv[MAXN];
ll fsp(ll x,int y){
	ll res=1;
	while(y){
		if(y&1)
			res=res*x%MOD;
		x=x*x%MOD;
		y>>=1;
	}
	return res;
}
ll query(ll x,ll y){
	ll res=0;
	for(ll s=min(x,y);s>=0;s--){
		if(x-s+y>n)
			break;
		res+=fac[n]*inv[s]%MOD*inv[x-s]%MOD*inv[y-s]%MOD*inv[n-x-y+s]%MOD;
		res%=MOD;
	}
	return res;
}
int main(){
	SF("%d%lld%lld%lld",&n,&a,&b,&m);
	fac[0]=1;
	for(int i=1;i<=n;i++)
		fac[i]=fac[i-1]*i%MOD;
	inv[n]=fsp(fac[n],MOD-2);
	ll ans=0;
	for(int i=n;i>=1;i--)
		inv[i-1]=inv[i]*i%MOD;
	for(ll i=0;i<=n;i++){
		ll sa=a*i;
		if((m-sa)%b==0){
			ll j=(m-sa)/b;
			if(max(i,j)>n)
				continue;
			ans=(ans+query(i,j))%MOD;
		}
	}
	PF("%lld",ans);
}

