#define MOD   (998244353LL)

S ll perms[600010];
S ll perm_invs[600010];

ll calc(ll n, ll a, ll b, ll k, ll acnt, ll bcnt)
{
    ll cnt1 = 1LL;
    cnt1 *= perms[n];
    cnt1 %= MOD;
    cnt1 *= perm_invs[acnt];
    cnt1 %= MOD;
    cnt1 *= perm_invs[n-acnt];
    cnt1 %= MOD;

    ll cnt2 = 1LL;
    cnt2 *= perms[n];
    cnt2 %= MOD;
    cnt2 *= perm_invs[bcnt];
    cnt2 %= MOD;
    cnt2 *= perm_invs[n-bcnt];
    cnt2 %= MOD;

    debug_printf("---- acnt=%lld bcnt=%lld cnt1=%lld cnt2=%lld\n",
                 acnt, bcnt, cnt1, cnt2);

    ll ret = cnt1 * cnt2;
    return ret % MOD;
}

void _main();
int main()
{
    cout << setprecision(12);
#if 0
    ios::sync_with_stdio(false);
    cin.tie(0);
#endif

    _main();
    return 0;
