void _main()
{
    ll n; llin(n);
    ll a; llin(a);
    ll b; llin(b);
    ll k; llin(k);

    make_perms(perms, perm_invs, 600010, MOD);

    ll ans = 0LL;
    rep (acnt, n+1) {
        ll ascore = a * acnt;
        ll bscore = k - ascore;
        if (bscore < 0) continue;
        if (bscore % b) continue;
        ll bcnt = bscore / b;
        if (bcnt < 0) continue;
        if (bcnt > n) continue;
        ans += calc(n, a, b, k, acnt, bcnt);
        ans %= MOD;
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

