ll sq(ll a) { return a*a; }

ll modpow(ll b, ll p) 
{
    if(p == 0)  
        return 1; 
    if(p % 2 == 0) 
        return sq(modpow(b, p/2)) % mod; 
    else 
        return b * modpow(b, p-1) % mod; 
}

ll fa[MAX], fi[MAX]; // fa: factorial, fi: inverse factorial

void init()
{
    fa[0] = fi[0] = 1;
    for(int i = 1; i < MAX; i++)
    {
        fa[i] = fa[i-1] * i % mod;
        fi[i] = modpow(fa[i], mod - 2);
    }
}

ll comb(ll n, ll k) { return fa[n] * fi[k] % mod * fi[n-k] % mod; }

iii egcd(ll a, ll b) 
{ 
    if(!b) return {a,{1,0}};
    iii p = egcd(b, a%b);  
    ll x = p.second.first, y = p.second.second;
    return {p.first, {y, x - (a/b)*y}};
}

ll solve(ll n, ll a, ll b, ll c)
{
    iii ans = egcd(a,b); 
    ll x = ans.second.first, y = ans.second.second, d = ans.first;
    if(c % d != 0) return 0; 
    ll t1 = ceil(-c*x/b), t2 = floor(c*y/a);
    ll sum = 0;
    for(ll t = t1; t <= t2; t++)
    {
        ll x1 = (x*c/d) + (b/d) * t, y1 = (y*c/d) - (a/d)*t;
        if(x1 >= 0 && y1 >= 0 && x1 <= n && y1 <= n)
            sum = (sum + comb(n,x1) * comb(n,y1) % mod) % mod;
    }
    return sum;
}

