lld expo(lld a, lld b)
{
	a %= mod;
	lld ans = 1LL;
	while(b)
	{
		if(b&1)
		{
			ans = (ans%mod)*(a%mod);
			ans %= mod;
		}
		a *= a;
		a %= mod;
		b>>=1;
	}
	return ans;
}

void init()
{
	int i;
	fact[0] = fact[1] = 1;
	fu(i, 2, 300005)
		fact[i] = (fact[i-1] * i) % mod;
