		factinv[i] = expo(fact[i], mod-2);
}



lld comb(lld n, lld r)
{
	lld ans = 0LL;
	if(n-r>=0 and r>=0)
	{

		ans = fact[n]%mod * factinv[r]%mod * factinv[n-r]%mod;
		ans %= mod;
		ans+= mod;
	}
	return ans;
}

