const ll MOD = 998244353;

ll powmod(ll n, ll k, ll mod) {
	ll res = 1;
	while(k > 0) {
		if(k % 2) res = (res * n) % mod;
		n = (n * n) % mod;
		k /= 2;
	}
	return res;
}

ll invmod(ll n, ll mod) {
	return powmod(n, mod - 2, mod);
}

ll fact[3000010], invfact[3000010];

ll comb(ll n, ll m) {
	if(m > n) return 0;
	return (fact[n] * invfact[n - m]) % MOD * invfact[m] % MOD;
}

void solve(long long N, long long A, long long B, long long K){
	fact[0] = invfact[0] = 1;
	for(int i = 1; i < 3000010; ++i) {
		fact[i] = (fact[i-1] * i) % MOD;
		invfact[i] = invmod(fact[i], MOD);
	}
	ll res = 0;
	for(int nA = 0; nA <= N; ++nA) {
		ll nB = (K - A * nA) / B;
		if(nA * A + nB * B != K) continue;
		res += comb(N, nA) * comb(N, nB) % MOD;
		res %= MOD;
	}
	cout << res << endl;
}

