            if (((k - i * a) % b) == 0) // ax + by = n
            {
                ret = (ret + combination_mod(n, i, mod) * combination_mod(n, (k - i * a) / b, mod) % mod) % mod;
            }
        }
    }
    cout << ret % mod << endl;
}

