static ll const P = 998244353;

ll facts[300001];

ll mod_power(ll a, ll b) {
  if (b == 0) {
    return 1;
  }

  if (b % 2 == 0) {
    auto d = mod_power(a, b/2);
    return (d*d) % P;
  }

  auto ret = (a * mod_power(a, b-1)) % P;

  return ret;
}

ll mod_comb(ll n, ll k) {
  if (n<0 || k<0 || n<k) return 0;
  if (n==0 || k==0) return 1;

  auto a=facts[n];
  auto b=facts[k];
  auto c=facts[n-k];
  auto ret=a*mod_power(b, P-2);
  ret %= P;
  ret *= mod_power(c, P-2);
  ret %= P;

  return ret;
}

int main() {
