vector<mint> f{1}, iv{1};
mint fact(int n) {
    assert(0 <= n);
    int sz = f.size();
    if(sz <= n) {
        f.resize(n * 2);
        iv.resize(n * 2);
        for(int i = sz; i < n * 2; i++)
            f[i] = f[i - 1] * i;
        iv[n * 2 - 1] = f[n * 2 - 1].inverse();
        for(int i = n * 2 - 1; i > sz; i--)
            iv[i - 1] = iv[i] * i;
    }
    return f[n];
}
mint fact_inv(int n) {
    fact(n);
    return iv[n];
}

mint P(int n, int k) {
    if(n < k || k < 0) return 0;
    return fact(n) * fact_inv(n - k);
}
mint C(int n, int k) {
    if(n < k || k < 0) return 0;
    return fact(n) * fact_inv(k) * fact_inv(n - k);
}
mint H(int n, int k) { return C(n + k - 1, k); }

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    ll n, a, b, k;
    mint ans;

    cin >> n >> a >> b >> k;

    for(int i = 0; i <= n && a * i <= k; i++) {
        if((k - a * i) % b == 0 && a * i + b * n >= k) {
            int j = (k - a * i) / b;
            ans += C(n, i) * C(n, j);
        }
    }

    cout << ans << endl;

    return 0;
}

