	if(p <= 0)
		return 1;
	ll ans = 1;
	while(p){
		if(p%2)
			ans = (ans*b)%bp;
		p >>= 1;
		b = (b*b)%bp;
	}
	return ans;
}

ll ncr(ll n, ll r){
	return (fact[n] * ((fexp(fact[r], bp-2)*fexp(fact[n-r], bp-2))%bp) )%bp;
}

