typedef long long LL;
const LL MOD = 998244353;
LL mod_pow(LL a, LL n) {
	if (n == 0) return 1;
	if (n % 2 == 0) {
		LL t = mod_pow(a, n / 2);
		return (t*t) % MOD;
	}
	return (a*mod_pow(a, n - 1)) % MOD;
}
LL fact[300001];
LL inv_fact[300001];
LL comb(LL n, LL k) {
	if (n < k) return 0;
	LL ret = fact[n];
	(ret *= inv_fact[k]) %= MOD;
	(ret *= inv_fact[n - k]) %= MOD;
	return ret;
}
int main() {
	int N;
	cin >> N;
	LL A, B, K;
	cin >> A >> B >> K;
	fact[0] = inv_fact[0] = 1;
	for (int i = 1; i <= N; i++) {
		fact[i] = fact[i - 1];
		inv_fact[i] = inv_fact[i - 1];
		(fact[i] *= i) %= MOD;
		(inv_fact[i] *= mod_pow(i, MOD - 2)) %= MOD;
	}
	LL ans = 0;
	for (int i = 0; i <= N; i++) {
		if (A*i > K) break;
		if ((K - A*i) % B != 0) continue;
		LL j = (K - A*i) / B;
		if (j > N) continue;
		LL add = comb(N, i);
		(add *= comb(N, j)) %= MOD;
		(ans += add) %= MOD;
	}
	cout << ans << endl;
}

