int bp (int a, int b) {
	int res = 1;
	while (b) {
		if (b & 1) {
			res = (res * a) % mod;
		}
		b >>= 1;
		a = (a * a) % mod;
	}
	return res;
}

int C (int n ,int k) {
	if (k > n) return 0;
	return (f[n] * ((inv[k] * inv[n - k]) % mod)) % mod;
}

int solve (int a, int b, int n) {
	return (C (n, a) * C (n, b)) % mod;
}

