  void Add(int &x, int y) {x = add(x + y);}
  void Sub(int &x, int y) {x = sub(x - y);}
  int Pow(int x, int y = mod - 2) {
	int res = 1;
	for(; y; y >>= 1, x = x * x % mod) {
	  if(y & 1) {
		res = res * x % mod;
	  }
	}
	return res;
  }
}

