  for (int x = 0, y; x <= n; x++)
    if ((k - a * x) % b == 0) {
      y = (k - a * x) / b;
      ans += M(1ll * C(n, x) * C(n, y));
    }
  printf("%lld\n", M(ans));
  return 0;
}

