ll bin(ll a, ll b)
{
    ll ret = 1;
    while (b)
    {
        if (b & 1)
            ret = (ret * a) % MOD;
        a = (a * a) % MOD;
        b /= 2ll;
    }
    return ret;
}

ll ncr(ll n, ll k)
{
    return (fac[n] * inv[n - k] % MOD) * inv[k] % MOD;
}

