        for (ll al = max(0ll, x - y); al <= min(n - y, x); al++)
        {
            ll be = y - x + al;
            ll ga = x - al;
            ans = (ans + (ncr(n, al) * ncr(n - al, be) % MOD) * ncr(n - al - be, ga) % MOD) % MOD;
        }
    }
