const int MOD = 998244353;

int pw(int a, int b) {
	long long ans = 1;
	for(int i = 63; i >= 0; i --) {
		ans *= ans;
		ans %= MOD;
		if((b >> i) & 1)
			ans *= a;
		ans %= MOD;
	}
	return ans;
}

int choose(int nn, int kk) {
	if(kk > nn || kk < 0)
		return 0;
	long long sur = 1, makh = 1;
	for(int i = 1; i <= kk; i ++) {
		makh *= 1LL * i;
		makh %= MOD;
	}
	for(int i = 0; i < kk; i ++) {
		sur *= 1LL * (nn - i);
		sur %= MOD;
	}
	return (sur * pw(makh, MOD - 2)) % MOD;
}

