	{
		if((k - i * a) % b || k - i * a < 0 || (k - i * a) / b > n)
			continue;
		ans += choose(n, i) * choose(n, (k - i * a) / b) % MOD;
		ans %= MOD;
	}
	cout << ans << "\n";

	return 0;
}

