  init();

  ll ans = 0;
  for (ll i = 0; i <= n; ++i) {
    ll remain = k - a * i;
    if (remain >= 0 and remain % b != 0) continue;
    ll j = remain / b;
    if (j > n) continue;
    ll tmp = comb(n, i) * comb(n, j) % MOD;
    ans += tmp;
    ans %= MOD;
  }

  cout << ans << endl;
}

