ll inf = 998244353;
ll func[300010] = {0};
ll inv[300010] = {0};

ll mult(ll n, ll m){
	if(m==1) return n%inf;
	else if(m%2==0){
		ll t = mult(n,m/2);
		return (t*t)%inf;
	}else{
		ll t = mult(n,m-1);
		return (t*n)%inf;
	}
}

void functional(int N){
	for(ll i=0;i<=N;i++){
		if(i==0){
			func[i] = 1;
			inv[i] = 0;
		}
		else{
			func[i] = (i*func[i-1])%inf;
			inv[i] = mult(func[i],inf-2);
		}
	}
}

ll comb(ll n,ll k){
	if(k==0 || n==k) return 1;
	else return (((func[n]*inv[k])%inf)*inv[n-k])%inf;
}

ll N,A,B,K;
int main(){
	cin >> N >> A >> B >> K;
	functional(N);
	ll ans = 0;
	for(ll i=0;i<=N;i++){
		if((K-i*B)%A==0 && K-i*B>=0){
			ll j = (K-i*B)/A;
			ans += (comb(N,i)*comb(N,j))%inf;
		}
	}
