        c = c * (a - i) % m;
        c = c * modinv(i + 1, m) % m;
    }
    return c;
}

void solve() {
    // K = A * a + B * b, 0 <= a,b <= N
    // answer = N C a + N C b

    ll answer = 0;

    REP(a,0,N) {
        if (K - A * a < 0 || (K - A * a) % B != 0) continue;

        ll b = (K - A * a) / B;

        answer += modc(N, a, MOD_N) * modc(N, b, MOD_N) % MOD_N;
