        fact[i] = 1LL * fact[i - 1] * i % kModulo;
        ifact[i] = pow(fact[i], kModulo - 2);
    }

    auto comb = [&](int N, int K) {
        int aux = 1LL * fact[N] * ifact[K] % kModulo;
        return 1LL * aux * ifact[N - K] % kModulo;
    };

    int answer = 0;
    for (int x = 0; x <= N; ++x) {
        int64_t left = K - 1LL * x * A;
        if (left < 0)
