typedef long long LL;
const int MOD = 998244353,MaxN = 300003;
LL n,a,b,k;

template<typename T> inline T gcd(T a,T b) {
    T r;
    while (b) {r=a%b;a=b;b=r;}
    return a;
}
template<typename T> inline LL lcm(const T& a,const T& b) { return (LL)a*b/gcd(a,b); }
template<typename T> T exgcd(const T& a,const T& b,T& x,T& y) {
    if (!b) return x=1,y=0,a;
    T g=exgcd(b,a%b,y,x);
    y=y-(a/b)*x;
    return g;
}
inline LL fastpow(LL a,LL p) {
    LL ret=1;
    while (p) {
        if (p&1) ret=ret*a%MOD;
        p>>=1;a=a*a%MOD;
    }
    return ret;
}
inline LL inv(const LL& x) {return fastpow(x,MOD-2);}

LL fac[MaxN],ifac[MaxN];

inline LL C(const int& n,const int& m) {return fac[n]*ifac[m]%MOD*ifac[n-m]%MOD;}

int main() {
    scanf("%lld%lld%lld%lld",&n,&a,&b,&k);
    if (n*a+n*b<k) return puts("0"),0;
    LL x,y,g;
    g=exgcd(a,b,x,y);
    if (k%g) return puts("0"),0;
    x*=k/g;y*=k/g;
    LL t=lcm(a,b),dx=t/a,dy=t/b;
    if (x<y) swap(a,b),swap(x,y),swap(dx,dy);
    if (y<0) {
        LL d=(-y+dy-1)/dy;
        y+=dy*d;
        x-=dx*d;
    }
    if (x>n) {
        LL d=(x-n+dx-1)/dx;
        x-=dx*d;
        y+=dy*d;
    }
    if (x>n || y>n) return puts("0"),0;
    fac[0]=fac[1]=1;
    for (int i=2;i<=n;++i) fac[i]=(fac[i-1]*i)%MOD;
    ifac[n]=inv(fac[n]);
    for (int i=n-1;i>=0;--i) ifac[i]=(ifac[i+1]*(i+1))%MOD;
    LL ans=0;
    while (x>=0 && y<=n) {
        ans+=C(n,x)*C(n,y)%MOD;
        ans%=MOD;
        x-=dx,y+=dy;
    }
    printf("%lld\n",ans);
    return 0;
}

