ll ex(ll x, ll e) {
	if (e == 0) {
		return 1;
	}
	if (e == 1) {
		return x;
	}
	ll y = ex(x, e / 2);
	if (e % 2 == 0) {
		return y * y % MOD;
	}
	return y * y % MOD * x % MOD;
}

