using namespace std;

long long mpower(long long x, long long y, long long mod) {
  long long ans = 1;
  while (y>0) {
    int r = y % 2;
    if(r==1) {
      ans = x * ans % mod;
    }
    x = x * x % mod;
    y /= 2;
  }
  return ans;
}

long long minv(long long x, long long mod){
  long long ans;
  ans = mpower(x, mod-2, mod);
  return ans;
}

int main() {
  long long N,A,B,K;
  long long mod = 998244353;
  cin >> N >> A >> B >> K;
  //make factorial and invFactorial Table
  vector<long long> fact(N+1);
  vector<long long> invfact(N+1);
  fact.at(0)=1;
  for(int i=1; i<=N; i++){
    fact.at(i) = i * fact.at(i-1) % mod;
  }
  invfact.at(N) = minv(fact.at(N),mod);
  for(int i=N-1; i>=0; i--) {
    invfact.at(i) = (i+1) * invfact.at(i+1) % mod;
  }
  //solve Ax + By = K
  //put C = K - Ax
  long long ans = 0;
  for(int x=0;x<=N;x++){
    long long C = K - A*x;
    if(C>=0 && C%B==0) {
      long long y = C/B;
      if(y>=0 && y<=N) {
        long long nCx = fact.at(N) * invfact.at(x) % mod * invfact.at(N-x) % mod;
        long long nCy = fact.at(N) * invfact.at(y) % mod * invfact.at(N-y) % mod;
        long long patternNum = nCx * nCy % mod;
        ans += patternNum;
      }

    }
  }

  cout << ans % mod << endl;
}

