// 前処理
void preCalcCombinationMod(ll N){
	ll i;
	fact[0] = 1;
	fact[1] = 1;
	for (i = 2; i <= N; i++){
		fact[i] = 1LL * fact[i - 1] * i % MOD;
	}
	ll nFactInv = bpow(fact[N], MOD - 2);
	inv[N] = nFactInv;
	for (i = N - 1; i > 0; i--){
		inv[i] = 1LL * inv[i + 1] * (i + 1) % MOD;
	}
	inv[0] = 1;
}

ll calcCombinationMod(ll n, ll m){
	ll ans = fact[n];
	ans = 1LL * ans * inv[m] % MOD;
	ans = 1LL * ans * inv[n - m] % MOD;
	return ans;
}

int main(){
	ll N, A, B, K;
	cin >> N >> A >> B >> K;
	ll i, j;
	ll ans = 0;
	preCalcCombinationMod(N);
	for (i = 0; i <= N; i++){
		if (i*A > K){
			break;
		}
		ll resi = K - i*A;
		if (resi%B == 0){
			j = resi / B;
			ll atmp = calcCombinationMod(N, i);
			ll btmp = calcCombinationMod(N, j);
			ans = (ans + 1LL * atmp * btmp % MOD) % MOD;
		}
	}
	cout << ans << endl;

	return 0;
}

