}

long long int congruence(long long int a, long long int b, long long int m)
{
    long long int c, d, e, f;
    long long int q, r;
    long long int tmp;

    if (m == 0) return -1;

    c = a;
    e = b;
    d = m;
    f = 0;
    while ((r = c % d) != 0) {
        q = c / d;
        c = d;
        d = r;
        tmp = f;
        f = e - q * f;
        e = tmp;
    }
    if (b % d != 0) return -1;
    q = (f/d) % (m/d);
    if (q < 0) q += m/d;
    return q;
}


