	modint ans = 0;

	for (int i = 0; i <= N; ++i) {
		const int red = A*i;
		if (K < red) {
			break;
		}
		const int blue = K - red;
		if (blue % B)continue;
		int j = blue / B;
		if (j > N)continue;
		ans += C.get_combi(N - i, i)*C.get_combi(N - j, j);
	}
	cout << ans.get() << endl;


	return 0;
}

