ll extend_gcd(ll a,ll b,ll &x,ll &y) {
    if(b == 0) {
        x = 1;y = 0;
        return a;
    }
    ll r = a % b;
    ll d = extend_gcd(b,r,y,x);
    y -= (a / b) * x ;

    return d;
}

void precompute_for_combination(ll n,ll k,ll p) {
    combination_n[0] = 1;

    for(int i = 1;i <= k;i++) {
        ll x,y;
        extend_gcd(i,p,x,y);

        x %= p;

        if(x < 0) x = p + x;

        combination_n[i] = 
            combination_n[i - 1] * (n - i + 1) % p * x % p;
    }
}


