ll calc_pow(ll n, ll k) {
    if (k == 0) return 1;
    if (k == 1) return n;

    if (k % 2 > 0) {
        return calc_pow(n, k - 1) * n % MOD;
    } else {
        return calc_pow(n * n % MOD, k / 2);
    }
}

void precalc() {
