llong binpow(llong a, llong b){
	if(b == 0){
		return 1;
	}if(b % 2 == 1) return binpow(a, b - 1) * a % MOD;
	else{
		llong x = binpow(a, b / 2);
		return x * x % MOD;
	}
}

llong C(llong n, llong k){
	llong x = f[k] * f[n - k] % MOD;
	return f[n] * binpow(x, MOD - 2) % MOD;
}

llong solve(llong cntA, llong cntB){
	llong C1 = C(n, cntA);
	llong C2 = C(n, cntB);
	return C1 * C2 % MOD;
}

