    mint ans=0;
    for(lint i=0;i<=n;i++){
        lint j=(k-a*i)/b;
        if (a*i+b*j!=k)continue;
        ans+=fact.binom(n,i)*fact.binom(n,j);
    }
    std::cout<<ans<<'\n';
}

