ll int pot (ll int x, int p) {
	if (p == 0) {
		return 1;
	}
	if (p == 1) {
		return x;
	}
	if (p%2 == 0) {
		ll int y = pot(x, p/2);
		return put(y, y);
	}
	return put(pot(x, p-1), x);
}

ll int divajd (ll int x, ll int y) {
	y = pot(y, MOD-2);
	x*=y;
	return x%MOD;
}

