    make_factorial_tableMOD();

    for(int i = 0; i < n; i++){
        ll anum = (ll)i;
        ll r = k - anum*a;
        ll bnum = r/b;
        if(r % b == 0 && bnum <= n){
            ans += (nCrMOD(n,anum)*nCrMOD(n,bnum))%MOD;
        }
    }

    cout << ans%MOD << endl;
    return 0;
}

