    while (1) {
        if (*it / A + (K - *it) / B <= n) {
            f = cnk(n, *it / A) % mod;
            f = f * cnk(n - *it / A, (K - *it) / B) % mod;
            c += f;
            if (c >= mod) c -= mod;
        }
        if (it == good[x].begin()) break;
        it--;

    }
    return c;
