// [L,R]
ll calc(ll L,ll  R) {
  ll ret = mfactrs[R];
  if( L-1LL >= 0LL ) ret -= mfactrs[L-1];
  while( ret < 0LL ) ( ret += mod ) %= mod;
  return ret;
}

void expt2() {
  ll sp_a=-1, sp_b;
  rep(a,N+1) {
    ll Av = A * a;
    if( Av > K ) continue;
    if( ( K - Av ) % B ) continue;
    ll b = ( K - Av ) / B;
    ll Bv = B * b;
    assert( Av + Bv == K );
    sp_a = a, sp_b = b;
  }
  if( sp_a == -1 ) {
    puts("0");
    return;
  }
  ll sum = 0;
  ll a = sp_a, b = sp_b;
  //cout << "sp_a = " << sp_a << ", sp_b = "<< sp_b << endl;
  //cout << "N = " << N << " A = " << A << " B = " << B << " K = " << K <<endl;
  //while( a <= N && b >= 0 ) {
  /*
  while( !( 0 <= b && b <= N && 0 <= a && a <= N ) ) {
    a -=B, b += A;
  }
  */
  //cout << "a = " << a << ", b = "<< b << endl;
  //puts("--");
  while( b <= N && a >= 0 ) {
    //cout << a << " " << b << endl;
    assert( A * a + B * b == K );
    if( min(a,b) + (a-min(a,b)) + (b-min(a,b)) > N ) {
      //a += B, b -= A;
      a -= B, b += A;
      continue;
    }
    // in6 705022534

    ll ua = a - 0, ub = b - 0, uc = 0;
    ll ur = N - ua - ub - uc;

    if( ur < 0LL ) {
      ua += ur;
      ub += ur;
      uc -= ur;
      ur = 0;
    }

    ll costa = 0, costb=0;
    costa = ( mfact[N] * mfactr[N-ua] ) % mod;
    costa = ( costa * mfactr[ua] ) % mod;
    costb = ( mfact[N] * mfactr[N-ub] ) % mod;
    costb = ( costb * mfactr[ub] ) % mod;
    ( sum += ( ( costa * costb) % mod ) ) %= mod;
    //a += B, b -= A;
    a -= B, b += A;
  }
  cout << sum << endl;
}

void compute() {
  mfact[0] = 1 % mod;
  REP(i,1,N+1) mfact[i] = ( mfact[i-1] * (ll)i ) % mod;
  rep(i,N+1) mfactr[i] = mod_inv(mfact[i],mod);
  mfactrs[0] = mfactr[0];
  REP(i,1,N+1) mfactrs[i] = ( mfactrs[i-1] + mfactr[i] ) % mod;
  expt2();
}

