void ensure_fact(int n) {
    while (n >= fact_precalc.size()) {
        fact_precalc.push_back(mult(fact_precalc.back(), fact_precalc.size()));
        inv_fact_precalc.push_back(inv(fact_precalc.back()));
    }
}

long fact(int n) {
