long long powmod(long long b, long long p) {
  long long r = 1;
  for (; p; p >>= 1, b = b * b % mod)
    if (p & 1)
      r = r * b % mod;
  return r;
}
long long fac[N], inv[N];
long long C(long long n, long long k) {
  return (fac[n] * inv[k] % mod) * inv[n-k] % mod;
}

