ll rui(ll a,ll b){
    if(b==1) return a%MOD;
    else if(b==0) return 1;
    else if(b%2==0) return (rui(a,b/2)*rui(a,b/2))%MOD;
    else return (rui(a,b-1)*a)%MOD;
}

ll comb(ll a,ll b){
    ll ans=1;
    for(ll i=a;i>a-b;i--){
        ans=ans*i%MOD;
    }
    for(ll i=1;i<=b;i++){
        ans=(ans*rui(i,MOD-2))%MOD;
    }
    return ans;
}

int main(){

