    Ret = (Ret * InvFact(n-p)) % MOD;
    return Ret;
}

ll Gcd;

pll Dioph(ll A, ll B)
{
    if (B==0) {
        Gcd = A;
        return {K/A, 0};
    }
    pll Tmp = Dioph(B, A%B);
    return {Tmp.second, Tmp.first - A/B * Tmp.second};
}

int main(int argc, const char * argv[]) {
    cin >> N >> A >> B >> K;

    if (K == 0) {cout << 1 << endl; return 0;}
    if (A < B) swap(A, B);
    pll P = Dioph(A, B);
    if (K%Gcd != 0) {cout << 0 << endl; return 0;}
    ll dp = abs(B/Gcd);
    ll dq = - A * dp / B;
    ll tmp = P.first/dp;
    P.first = P.first - tmp * dp;
    P.second = P.second - tmp * dq;
    if (P.first < 0) {P.first += dp; P.second += dq;}

    ll Res = 0;
    while (P.first <= N) {
        if (P.second <= N) {
            Res = (Res + (Comb(N, P.first) * Comb(N, P.second)) % MOD) % MOD;
        }
        P.first += dp;
        P.second += dq;
    }

    cout << Res << endl;

    return 0;
}

