template<typename T>
bool is_prime(T n){
  bool f = true;
  if(n == 1) {
    return 0;
  }
  if(n == 2)
    return true;
  if(n % 2 == 0)
    return false;
  for(int i = 3;i <= (int)(sqrt(n) + 0.1);i += 2){
    if(n % i == 0){
      f = false;
      break;
    }
  }
  return f;
}

template<typename T>
T extend_gcd(T a,T b,T &x,T &y) {
  if (b == 0) {
    x = 1;y = 0;
    return a;
  }
  T r = a % b;
  T d = extend_gcd(b,r,y,x);
  y -= (a / b) * x ;

  return d;
}

template<typename T>
T mod_pow(T x, T n, T mod) {
  T res = 1;
  while (n > 0) {
    if (n & 1) res = res * x % mod; // 最下位ビットが立っているときにx^(2^i)を掛ける
    x = x * x % mod; // xを順次二乗していく
    n >>= 1;
  }
  return res;
}

template<typename T = long long>
struct Zp {
