    set(n_,p_);
  }

  void set(T n_,T p_ = 1000000007) {
    p = p_;
    n = n_ % p;
    if (n < 0) n = p + n;
  }

  T get() const {
    return n;
  }

  Zp operator +() const {
    return Zp(n,p);
  }

  Zp operator -() const {
    return Zp(-n,p);
  }

