const ll MOD = 998244353;

ll N, A, B;
ll K;

void solve() {
  init_fact(N, MOD);
  ll ans = 0;
  for (ll xy = 0; xy <= min(K / A, N); xy++) {
    ll v = K - A * xy;
    if (v % B > 0) continue;
    ll yz = v / B;
    ll m = mod_comb_fast(N, xy, MOD);
    m = m * mod_comb_fast(N, yz, MOD) % MOD;
    ans = (ans + m) % MOD;
  }
  printf("%lld\n", ans);
}

