public:
	CNK(int max){
		mx = max;

		fac.resize(max + 1);
		ifac.resize(max + 1);

		fac[0] = ifac[0] = 1;

		for(int i = 1 ; i <= max ; ++i){
			fac[i] = 1LL * fac[i - 1] * i % mod;
			ifac[i] = fpow(fac[i], mod - 2);
		}
