	ll fpow(ll a , ll b){
		ll ans = 1;
		while(b > 0){
			if(b & 1){
				ans = (1LL * ans * a) % mod;
			}
			a = (1LL * a * a) % mod;
			b /= 2;
		}
		return ans;
	}

	ll cnk(int n , int k){
		assert(mx >= n);
		if (n < 0 || k < 0 || k > n) return 0;
		return 1LL * fac[n] * ifac[n - k] % mod * ifac[k] % mod;
	}
};


