#endif

  cin >> N >> A >> B >> K;
  ll p = 0;
  ll q = 0;
  ll g = eGCD(A, B, p, q);
  if (K % g != 0) {
    cout << 0 << endl;
    return 0;
  }
  ll c = K / g;
  if (p < 0) {
    swap(A, B);
    swap(p, q);
  }

  fact.resize(N+1);
  invFact.resize(N+1);
  fact.at(0) = invFact.at(0) = 1;
  for (int i = 1; i <= N; i++) {
    fact.at(i) = fact.at(i-1) * Fp(i);
    invFact.at(i) = fact.at(i).inv();
  }

  // Apc + Bqc = K, p > 0, q < 0
  // A(pc-Bt) + B(qc+At) = K, t \in [ (A - 1 - qc) / A, pc / B ]
  Fp cnt = 0;
  for (ll t = (A-1 - q*c) / A; t <= p*c / B; t++) {
