{
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, a, b, k;
  cin >> n >> a >> b >> k;

  int ret = 0;
  REP(i, n) {
    if((k - a*i) % b) continue;
    int j = (k - a*i) / b;
    if(j < 0) continue;
    (ret += combi(n, i) * combi(n, j) % MOD) %= MOD;
  }

  cout << ret << endl;

  return 0;
}

