        if( A*r <= K && (K-A*r)%B == 0 ){
            long long b = (K - A*r) / B; // 青の数

            if(!(0 <= b && b <= N)) continue;
            long long r_c = C(N , r)%MOD;
            long long b_c = C(N , b)%MOD;
            count +=  (r_c * b_c)%MOD;
            count %=MOD;
        }
    }

    cout << count<< endl;
}

