pair<i64, i64> extended_euclid(i64 a, i64 b) {
    if (b == 0)
        return {1, 0};
    else {
        i64 x, y;
        tie(y, x) = extended_euclid(b, a % b);
        return {x, y - (a / b) * x};
    }
}

