long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

void solve() {
    mod = 998244353;
    int n, a, b, k; cin >> n >> a >> b >> k;
    int c = GCD(a, b);
    if (k % c) {
        cout << 0 << endl; return 0;
    }
    int x, y;
    if (a < b) swap(a, b);
    extGCD(a, b, x, y);
    x *= k / c; y *= k / c;
    if (x < 0) {
        int cnt = ceili(-x, (b / c));
        // cout << -x << endl;
        // cout << b / c * cnt << endl;
        x += b / c * cnt;
        y -= a / c * cnt;
        // if (y < 0) {
        //     cout << 0 << endl;
        //     return 0;
        // }
    } else {
        int cnt = x / (b / c);
        x -= b / c * cnt;
        y += a / c * cnt;
        // if (y < 0) {
        //     cout << 0 << endl;
        //     return 0;
        // }
    }

    fact fac(300005, 998244353);
    int ans = 0;
    while (x <= n) {
        if (y < 0) break;
        if (y <= n) {
            ans += fac.nCr(n, x) * fac.nCr(n, y) % mod;
            ans %= mod;
        }
        x += b / c, y -= a / c;
    }
    cout << ans << endl;
    return;
}

int ceili(int x, int y) {
    if (x % y == 0) return x / y;
    else return x / y + 1;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

