lli kaijo[MAX];
lli finv[MAX];
lli inv[MAX];

void calcKaijo(){

	REP(i,MAX){
		if(i==0 || i==1){
			kaijo[i]=1;
			finv[i]=1;
			inv[i]=1;
		}

		else {
			kaijo[i] = kaijo[i-1]*i;
			kaijo[i] %= MOD;
			inv[i] = MOD - inv[MOD%i]*(MOD/i)%MOD;
			finv[i] = finv[i-1]*inv[i] % MOD;
		}
	}
}

lli nCr(lli n,lli r){
	if(n<r)return 0;
	if(n<0 || r<0)return 0;
	return kaijo[n]*(finv[r]*finv[n-r]%MOD)%MOD;
}

