ll pw(ll a, int e){
	if(e==0) return 1;
	ll t=pw(a, e/2); t=(t*t)%MOD;
	return (e%2==0) ? t : t*a%MOD;
}

ll inv(ll a){
	return pw(a, MOD-2);
}

ll C(int n, int r){
	return F[n]*inv(F[n-r])%MOD*inv(F[r])%MOD;
}

ll count(ll a, ll b){
	return (C(n, a) * C(n, b))%MOD;
}

