class rep {
	const std::size_t f, l;

public:
	using value_type = std::size_t;
	using reference = value_type;
	class repitr {
		friend rep;
		value_type i;
		repitr(value_type x) noexcept : i(x) {}

	public:
		void operator++() noexcept { ++i; }
		reference operator*() const noexcept { return i; }
		bool operator!=(const repitr x) const noexcept { return i != x.i; }
	};
	explicit rep(value_type first, value_type last) noexcept
		: f(first), l(last) {}
	repitr begin() const noexcept { return repitr(f); }
	repitr end() const noexcept { return repitr(l); }
};
class Rrep {
	const std::size_t f, l;

public:
	using value_type = std::size_t;
	using reference = value_type;
	class Rrepitr {
		friend Rrep;
		value_type i;
		Rrepitr(value_type x) noexcept : i(x) {}

	public:
		void operator++() noexcept { --i; }
		reference operator*() const noexcept { return i - 1; }
		bool operator!=(const Rrepitr x) const noexcept { return i != x.i; }
	};
	explicit Rrep(value_type first, value_type last) noexcept
		: f(first), l(last) {}
	Rrepitr begin() const noexcept { return Rrepitr(l); }
	Rrepitr end() const noexcept { return Rrepitr(f); }
};
