using namespace std;
typedef long long li;

const li mod = 998244353;

li pow(li x, li n) {
    if (n == 0) {
        return 1;
    }
    if (n == 1) {
        return x;
    }

    li sq = pow(x, n / 2);
    if (n & 1) {
        return sq * sq % mod * x % mod;
    }
    return sq * sq % mod;
}

li inv(li x) {
    return pow(x, mod - 2);
}

li solve(li n, li a, li b, li k) {
    li g = __gcd(a, b);

    if (k % g != 0) {
        return 0;
    }

    a /= g;
    b /= g;
    k /= g;

    vector<li> facts(n + 1);
    facts[0] = 1;
    for (li i = 1; i <= n; ++i) {
        facts[i] = facts[i-1] * i % mod;
    }

    auto comb = [&](li x, li y) {
        if (y < 0 || y > x || x < 0) {
            return 0LL;
        }
        return facts[x] * inv(facts[y]) % mod * inv(facts[x - y]) % mod;
    };

    li ans = 0;
    for (li p = 0; p <= n; p++) {
        li v = k - p * a;
        if (v % b != 0) {
            continue;
        }
        li q = v / b;
        if (q < 0 || q > n) {
            continue;
        }
        ans += comb(n, p) * comb(n, q) % mod;
        ans %= mod;

    }

    return ans;
}

int main() {
    li n, a, b, k;
    cin >> n >> a >> b >> k;
    cout << solve(n, a, b, k) << endl;
    return 0;
}

