ll mpow(ll x, ll n){ //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
  ll ans = 1;
  while(n != 0){
    if(n&1) ans = ans*x % MOD;
      x = x*x % MOD;
      n = n >> 1;
    }
  return ans;
}

void init() {
  fac[0] = 1;
  ifac[0] = 1;
  for (ll i = 0; i < 510000; ++i) {
    fac[i+1] = fac[i]*(i+1) % MOD; // n!(mod M)
    ifac[i+1] = ifac[i]*mpow(i+1, MOD-2) % MOD; // k!^{M-2} (mod M) ←累乗にmpowを採用
  }
}

ll comb(ll a, ll b){ //aCbをmod計算
  if(a == 0 && b == 0)return 1;
  if(a < b || a < 0)return 0;
  ll tmp = ifac[a-b]* ifac[b] % MOD;
  return tmp * fac[a] % MOD;
}

ll perm(ll a, ll b){ // aPb
  if(a < b) return 0;
  ll tmp = ifac[a-b] % MOD;
  return tmp * fac[a] % MOD;
}

ll hcomb(ll n,ll k){
	if(n==0 && k==0) return 1;
	return comb(n+k-1,k);
}

int main() {
  ll n, a, b, k;
  cin >> n >> a >> b >> k;
  init();

  ll ans = 0;
  for (ll i = 0; i <= n; ++i) {
    ll remain = k - a * i;
    if (remain % b != 0) continue;
    ll j = remain / b;
    if (j > n) continue;
    ll tmp = comb(n, i) * comb(n, j) % MOD;
    ans += tmp;
    ans %= MOD;
  }

  cout << ans << endl;
}

