const int MOD = 998244353;

int mul_inv(int a, int b = MOD) {
	int t1 = a, t2 = b, t3;
	int v1 = 1, v2 = 0, v3;
	while (t2 != 1) {
		int x = t1 / t2;
		t3 = t1 - x*t2;
		v3 = v1 - x*v2;
		t1 = t2, t2 = t3;
		v1 = v2, v2 = v3;
	}
	return (v2 + b) % b;
}
int F[300050];
int Finv[300050];
int Co(int a, int b) {
	int rv = F[a] * Finv[b] % MOD;
	return rv * Finv[a - b] % MOD;
}

signed main()
{
	int N, A, B, K, ans = 0;
	cin >> N >> A >> B >> K;

	F[0] = 1;
	for (int i = 1; i <= 300000; i++) F[i] = F[i - 1] * i % MOD;
	for (int i = 0; i <= 300000; i++) Finv[i] = mul_inv(F[i]);
	// K = red*A + blue*B
	for (int red = 0; red <= N; ++red) {
		if ((K-red*A) % B == 0) {
			int blue = (K-red*A)/B;
			ans += Co(N, red)*Co(N, blue);
			ans %= MOD;
		}
	}
	cout << ans << endl;
}

