struct Combinations {

    long long mod;
    vector< long long > inv;
    vector< long long > fact;
    vector< long long > inv_fact;

    Combinations (int n, int m) : inv(n), fact(n), inv_fact(n), mod(m) {
        inv[1] = 1;
        for (long long i = 2; i < n; i++) {
            inv[i] = inv[mod%i] * (mod - mod / i) % mod;
        }
        fact[0] = inv_fact[0] = 1;
        for (long long i = 1; i < n; i++) {
            fact[i] = (fact[i-1] * i) % mod;
            inv_fact[i] = (inv_fact[i-1] * inv[i]) % mod;
        }
    }

    long long nPr(long long n, long long r) {
        if (n < r || r < 0) return 0;
        return fact[n] * inv_fact[n-r] % mod;
    }

    long long nCr(long long n, long long r) {
        if (n < r || r < 0) return 0;
        return nPr(n,r) * inv_fact[r] % mod;
    }

    long long nHr(long long n, long long r) {
        return nCr(n+r-1,r);
    }

};

const ll MOD = 998244353LL;

int main ()
{

    ll N,A,B,K;
    cin >> N >> A >> B >> K;

    Combinations inst(500000, MOD);

    ll ans = 0;
    for (ll cnta = 0; cnta <= K / A; cnta++) {
        ll le = K - A * cnta;
        if (le % B == 0) {
            ll a = cnta;
            ll b = le / B;
            ans += (inst.nCr(N, a) * inst.nCr(N, b)) % MOD;
            ans %= MOD;
        }
    }

    cout << ans << endl;

    return 0;
}

