void Init()
{
	fac[0]=inv[0]=1;
	for(int i=1;i<=n;i++)
		fac[i]=i*fac[i-1]%MO;
	inv[n]=powmod(fac[n],MO-2);
	for(int i=n-1;i>=1;i--)
		inv[i]=(i+1)*inv[i+1]%MO;
}
LL Solve(int i,int j)
{
	return inv[i]*inv[j]%MO*inv[n-i]%MO*inv[n-j]%MO;
}
