int pw ( int x , int y ) {
	int ret = 1 ;
	for ( ; y ; y >>= 1 , ( x *= x ) %= mod )
		if ( y & 1 )
			( ret *= x ) %= mod ;
	return ret ; 
}

int comb ( int n , int r ) {
	if ( r > n ) return 0 ; 
	return fact [ n ] * inv [ r ] % mod * inv [ n - r ] % mod ; 
}

