ll pow_mod(ll x, ll n, ll mod) {
	ll ans = 1;
	while (n > 0) {
		if ((n & 1) == 1) {
			ans = ans * x % mod;
		}
		x = x * x % mod;
		n >>= 1;
	}
	return ans % mod;
}

ll f(ll N, ll x, ll y, ll z) {
	ll ret = fact[N] * fact_inv[x - z] % mod;
	ret *= fact_inv[z];
	ret %= mod;
	ret *= fact_inv[y - z];
	ret %= mod;
	ret *= fact_inv[N - (x + y - z)];
	ret %= mod;
	return ret;
}

void init() {
	fact[0] = fact_inv[0] = 1;

	for(ll i = 1; i <= 300010; i++) {
		fact[i] = (fact[i - 1] * i) % mod;
		fact_inv[i] = pow_mod(fact[i], mod - 2, mod) % mod; // フェルマーの小定理で逆元を求める
	}
}

ll comb(ll n, ll r) {
	return ((fact[n] * fact_inv[n - r] % mod) * fact_inv[r]) % mod;
}

ll inv(ll x) {
	return pow_mod(x, mod - 2, mod) % mod;
}


int main() {
	ll N, A, B, K;
	cin >> N >> A >> B >> K;

