	ll ans = 0;
	for(ll x = 0; x <= N; x++) {
		if (K < A * x) continue;
		if ((K - A * x) % B != 0) continue;

		ll y = (K - A * x) / B;
		if (y > N) continue;
		ans += comb(N, x) * comb(N, y) % mod;
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

