#define MAX_FACT 300001
ll fact[MAX_FACT];

ll nCk(int n, int k){
    //　n_C_kの計算, 蟻本p.263
    ll ans = fact[n] * Inverse(fact[k] * fact[n-k] % mod);
    ans %= mod;
    return ans;
}

int main() {
    ll N, A, B, K;
    cin >> N >> A >> B >> K;

    // 階乗計算
    fact[0]=1;
    for(int i = 1; i < MAX_FACT; ++i) {
        fact[i] = fact[i-1] * i % mod;
    }

    ll ans = 0;
    // A点加点するブロックの数
    for (int i = 0; i <= N; ++i) {
        ll rem = K - A * i;
        if(rem % B != 0 || rem / B > N) continue;
        ll k = rem / B;
        ans += nCk(N, i) * nCk(N, k);
        ans %= mod;
    }
    cout << ans;
    return 0;
}

