    make_factorial_tableMOD();

    for(int i = 0; i < n; i++){
        ll remain = k - ll(i)*a;
        if(remain % b == 0 && remain / b <= n){
            ans += (nCrMOD(n,ll(i))*nCrMOD(n,remain/b))%MOD;
        }
    }

    cout << ans%MOD << endl;
    return 0;
}

