void solve(){
	int N;
	LL A,B,K;
	cin>>N>>A>>B>>K;

	const LL mod = (LL)998244353;//prime
	LL ans = 0;

	vector<LL> kai_inv(N+1);
	kai_inv[0] = 1;
	for(int i=1;i<=N;++i){
		kai_inv[i] = kai_inv[i-1] * powMod(i,mod-2,mod);
		kai_inv[i] %= mod;
	}
	/*乗算でなく加算
	vector<LL> kai_kai_inv(N+1);
	kai_kai_inv[0] = 1;
	for(int i=1;i<=N;++i){
		kai_kai_inv[i] = kai_kai_inv[i-1] * kai_inv[i];
		kai_kai_inv[i] %= mod;
	}*/

	//Nから[i]i個とる
	vector<LL> inv(N+2);
	for(int i=0;i<N+2;++i){
		inv[i] = powMod(i,mod-2,mod);
	}
	vector<LL> nckMemo(N+1);
	nckMemo[0] = 1;
	nckMemo[1] = 1;
	for(int i=1;i<=N;++i){
		nckMemo[i] = nckMemo[i-1]*(N-i+1);
		nckMemo[i] %= mod;
		nckMemo[i] = (nckMemo[i] * inv[i]) % mod;
	}

	LL kai_N=1;
	for(int i=1;i<=N;++i){
		kai_N*=i;
		kai_N%=mod;
	}
	for(LL a=0;a<=N;++a){//3*10^5
		LL nokori = K - A*a;
		if(nokori<0){
			break;
		}
		if( nokori%B ){//割り切れない
			continue;
		}
		LL b = nokori/B;
		if(b>N){
			continue;
		}
		//Aがa個,Bがb個

		LL res = nckMemo[a] * nckMemo[b];
		res %= mod;
		ans = (ans + res) % mod;
	}
	cout << ans << endl;
}

