	template<std::uint64_t Mod>struct modnum;
	template<std::uint64_t Mod>auto inverse(modnum<Mod> const&);

	template<std::uint64_t Mod>struct modnum
	{
		static constexpr auto mod = Mod;
		std::uint64_t val;
		modnum() = default;
		constexpr modnum(std::uint64_t v):val(v%Mod) {}
		auto& clamp()
		{
			val %= mod;
			return *this;
		}
		auto& operator+=(modnum const& v)
		{
			val += v.val;
			return clamp();
		}
		auto& operator-=(modnum const& v)
		{
			val += mod - v.val;
			return clamp();
		}
		auto& operator*=(modnum const& v)
		{
			val *= v.val;
			return clamp();
		}
		auto& operator/=(modnum const& v)
		{
			return operator*=(inverse(v));
		}
	};
#define MAKE_MODNUM_OPERATOR(op)\
template<std::uint64_t Mod>auto operator op(modnum<Mod> lhs, modnum<Mod>const& rhs)\
{\
	return lhs BOOST_PP_CAT(op,=) rhs;\
}
	MAKE_MODNUM_OPERATOR(+);
