void Main()
{
	std::int64_t N, A, B, K;
	std::cin >> N >> A >> B >> K;
	auto x = lib::gcd(A, B);
	if (K%x != 0)
	{
		out::write_line(0);
		return;
	}
	auto fact = lib::factorial_array<lib::mod_t>(N);
	auto comb = [&](int r, int t)
	{
		return fact[r] / (fact[t] * fact[r - t]);
	};
	lib::mod_t sum = 0;
	for (int a : boost::irange<int>(0, N + 1))
	{
		if ((K - a * A) % B != 0)
		{
			continue;
		}
		auto b = (K - a * A) / B;
		if (b < 0 || N < b)
		{
			continue;
		}
		sum += comb(N, a)*comb(N, b);
	}
	out::write_line(sum);
}

