ll pwr (ll a, ll b) {
  ll res = 1;
  while (b > 0) {
    if (b & 1) res = (res * a) % mod;
    a = (a * a) % mod;
    b >>= 1;
  }
  return res;
}

ll inv (ll a) {
  return pwr(a, mod - 2);
}

ll comb (int n, int r) {
  if (r > n) return 0;
  return ((((fact[n] * inv(fact[n - r])) % mod) * inv(fact[r])) % mod);
}

