long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a%b, y, x);
    y -= a/b * x;
    return d;
}

vector<long long> inv,fact,invfact;

long long choose(long long n, long long k){
    if(k<0||k>n)return 0;
    long long res = fact[n];
    res *= invfact[k];
    res %= M;
    res *= invfact[n-k];
    res %= M;
    return res;
}

