        inv[i] += M;
        inv[i] %= M;
    }
    for(long long i=1;i<=n;++i){
        fact[i] = (fact[i-1]*i)%M;
        invfact[i] = (invfact[i-1]*inv[i])%M;
    }
    long long x,y;
    long long g = extGCD(a,b,x,y);
    if(k%g!=0){
        cout<<0<<endl;
