inline ll Lucas(ll n,ll m){
    ll Ans = 1 ;
    while(n&&m&&Ans){
        Ans = (Ans*C(n%mod,m%mod))%mod ;
        n/=mod ; m/=mod ;
    }
    return Ans ;
