ll Combination(ll n, ll r){
    if (n <= 0 || r < 0 || r > n) return 0;
    if (n - r < r) r = n - r;
    if (r == 0) return 1;
    if (r == 1) return n;

    ll numerator[r];
    ll denominator[r];

    for (ll k = 0; k < r; k++)
    {
        numerator[k] = n - r + k + 1;//分子
        denominator[k] = k + 1;//分母
    }

    for (ll p = 2; p <= r; p++)
    {
        ll pivot = denominator[p - 1];
        if (pivot > 1)
        {
            ll offset = (n - r) % p;
            for (ll k = p - 1; k < r; k += p)
            {
                numerator[k - offset] /= pivot;
                denominator[k] /= pivot;
            }
        }
    }

    ll result = 1;
    for (ll k = 0; k < r; k++)
    {
        if (numerator[k] > 1){
        	result *= numerator[k];
        	result %= mod;
        }
    }

    return result;
}

