	scanf("%lld%lld%lld%lld",&N,&A,&B,&K);
	ll fact[300010]={},inv[300010]={};
	fact[0]=1;
	reg(i,1,300000)fact[i]=(fact[i-1]*i) % mod;
	inv[300000] = test(fact[300000],mod-2);
	ireg(i,0,300000-1)inv[i]=(inv[i+1]*(i+1)) % mod;
	// reg(i,0,300000)if((fact[i]*inv[i])%mod!=1){
	// 	printf("破綻\n");
	// 	break;
	// }
	ll g = gcd(A,B);
	if(K%g!=0){
		printf("0\n");
	}else{
		K/=g;
		A/=g;
		B/=g;
		//1=aN+bM;
		ll n,m;
		reg(i,1,B){
			if((A*i)%B==1){
				n=i;
				break;
			}
		}
		m = -(A*n-1)/B;
		//K=aN+bM;
		n*=K;
		m*=K;
		if(n>0){
			ll offset = n/B+1;
			if(B>0){
				n -= offset*B;
				m += offset*A;
			}else{
				n += offset*B;
				m -= offset*A;
			}
		}
		//N<=0にして，増やしていき，M<=0になるまでやる
		while(m>0){
			ll com = (fact[N]*inv[n]) % mod;
			com = (com*inv[N-n]) % mod;
			com = (com*fact[N]) % mod;
			com = (com*inv[m]) % mod;
			com = (com*inv[N-m]) % mod;
			ans = (ans+com) % mod;
			n+=B;
			m-=A;
		}
	}
	if(ans==0)ans=1;
	printf("%lld\n",ans);
	return 0;
}

