/* Mod must be a prime. */
template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::Inverse() const {
	assert(value_m != 0);
	return Pow(Mod - 2);
}

template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::Pow(uint64_t exp) const {
	IntMod product(1);
	IntMod factor(*this);
	while (exp > 0) {
		if (exp& 1) {
			product *= factor;
		}
		factor *= factor;
		exp >>= 1;
	}
	return product;
}

