	ll ans = 0;
	for (ll i = 0; i <= N; i++) {
		if ((K - i * A) % B == 0) {
			ll j = (K - i * A) / B;
			ans += (comb::combination(N, i) * comb::combination(N, j)) % comb::MOD;
		}
		ans %= comb::MOD;
	}
	cout << ans << endl;
	return 0;
}

