    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll COM3(ll N, ll R, ll G, ll B) {
   ll ans = 1;
   ll tmp1 = COM(N, R) % MOD;
   ll tmp2 = COM(N - R, G) % MOD;
   ll tmp3 = COM(N - R - G, B) % MOD;
   ans *= tmp1;
   ans *= tmp2;
   ans %= MOD;
   ans *= tmp3;
   ans %= MOD;
   return ans;
}

ll gcd (ll a , ll b) {
   if (b == 0) return a;
   return gcd(b, a % b);
}

