inline int ksm(int p, int k)
{
	if(k<0)return 0;
	v[0]=p;
	for(int i=1; i<=29; ++i)v[i]=(long long)v[i-1]*v[i-1]%MO;
	int s=1;
	for(int i=29; i>=0; --i) {
		if(1<<i <= k) {
			k-=1<<i;
			s=(long long)s*v[i]%MO;
		}
	}
	return s;
}

int gcd(int a, int b)
{
	if(!b)return a;
	return gcd(b,a%b);
}

int exgcd(int a, int b, long long &x, long long &y) 
{
	if(!b) {
		x=1; y=0;
		return a;
	}
	int f=exgcd(b,a%b,y,x);
	y-=(a/b)*x;
	return f;
}

inline int C(int n, int m)
{
	if(m<0 || m>n)return 0;
	return (long long)op[n]*inv[n-m]%MO*inv[m]%MO;
}

int main()
{
	n=read(); a=read(); b=read();



//	assert(a!=b);

	cin>>k;

	if(!k){
		puts("1");
		exit(0);
	}

	t=gcd(a,b);
	if(k%t){
		puts("0");
		return 0;
	}

	k/=t;
	a/=t;
	b/=t;	

	op[0]=1;
	for(int i=1; i<=n; ++i)op[i]=(long long)op[i-1]*i%MO;
	for(int i=0; i<=n; ++i)inv[i]=ksm(op[i],MO-2);

	exgcd(a,b,x,y);

	x*=k; y*=k;

	t=x/b;
	x%=b;
	y+=t*a;

	if(x<0)x+=b,y-=a;
	if(y<0){
		puts("0");
		return 0;
	}

	if(a==b){
		cc=x+y;
		if((cc+1)/2>n){
		    puts("0");
		    return 0;
		}
		for(int i=cc/2; i>=0; --i) {
			ans=((long long)ans+(long long)C(n,cc-i-i)*C(n-cc+i+i,i)%MO*ksm(2,cc-i-i))%MO;
		}
		cout<<ans;
		return 0;
	}

	if(a>b)
	{
		swap(a,b),swap(x,y);
		t=x/b;
		x%=b;
		y+=t*a;
	}

	while(y>=0){
		if(x+y>n*2)break;
		if(x+y-min(x,y)>n)
		{
			y-=a;
			x+=b;
		    continue;
		}
		for(int i=min(x,y); i>=0; --i) {
			ans=((long long)ans+(long long)C(n,x-i)*C(n-x+i,y-i)%MO*C(n-x-y+i+i,i))%MO;
		}

		y-=a;
		x+=b;
	}
	cout<<ans;
}

