#define MOD 998244353
#define MAXN 300010

int n;
ll A,B,k;
ll ans = 0;

ll frac[MAXN];
ll inv[MAXN];
void Calfrac(){
	frac[0] = 1;
	For(i,MAXN-1)
		frac[i] = frac[i-1]*i%MOD;
}
ll Pow( ll a , ll b ){
	ll ret = 1;
	while(b){
		if(b&1){
			ret = ret*a%MOD;
		}
		a = a*a%MOD;
		b >>= 1;
	}
	return ret;
}
ll Inv( ll a ){
	return Pow(a,MOD-2);
}
void Calinv(){
	inv[0] = 0;
	inv[1] = 1;
	Forx(i,2,MAXN-1)
		inv[i] = Inv(frac[i]);
}

ll C( ll b , ll a ){
	ll ret = frac[a];
	ret = ret * inv[b] % MOD;
	ret = ret * inv[a-b] % MOD;
	if(!ret) ret = 1;
	return ret;
}

ll Solve( ll a , ll b ){
	ll ret = 0;
	Forx(c,0,min(a,b)){
		if( a+b-c > n ) continue;
		//cout << a-c << " " << c << " " << b-c << endl;
		ll tret = 1;
		tret *= C(a-c,n); tret %= MOD;
		tret *= C(b-c,n-a+c); tret %= MOD;
		tret *= C(c,n-a+c-b+c); tret %= MOD;
		ret += tret;
		Mymod(ret,MOD);
	}
	return ret;
}

int main(){
	FILEIO();
	Calfrac();
	Calinv();

	Read(n);
