#define DIV 998244353

long long N, A, B, K;

long long fact[300005];

long long modpow(long long ori, long long po){
	long long res = 1;
	while(po > 0){
		if(po&1){
			res *= ori;
			res %= DIV;
		}
		ori *= ori;
		ori %= DIV;
		po >>= 1;
	}
	return res;
}

long long comb(long long m, long long n){
	long long ret = fact[m];
	ret *= modpow(fact[m-n], DIV - 2);
	ret %= DIV;
	ret *= modpow(fact[n], DIV - 2);
	ret %= DIV;
	return ret;
}

int main(){
	cin >> N >> A >> B >> K;

	fact[0] = 1;
	for(long long i = 1; i <= N; i++){
		fact[i] = fact[i-1] * i;
		fact[i] %= DIV;
	}

	long long ans = 0;
	for(long long i = 0; i <= N; i++){
		long long rest = K - A * i;
		if(rest % B != 0)
			continue;
		long long j = rest/B;
		if(j > N)
			continue;
		ans += (comb(N, i) * comb(N, j))%DIV;
		ans %= DIV;
	}
	cout << ans << endl;
}

