ll pot(ll base, ll exponent) {
    ll result = 1;
    while (exponent>0) {
        if (exponent & 1)
            result=mul(result, base);
        exponent=exponent/2;
        base=mul(base, base);
    }
    return result;
}

ll povrh(ll n, ll k) {
    if (k==0) return 1LL;
    return mul(fakt[n], pot(mul(fakt[n-k], fakt[k]), MOD-2));
