map<pair<int,int>,int> mp;

long long modpow(long long a,long long p){
    if(p==0)return 1;
    if(p%2==0){
      long long halfP=p/2;
      if(mp.count(make_pair(a,halfP)))return mp[make_pair(a,halfP)];
      long long half=modpow(a,halfP);
      return mp[make_pair(a,halfP)]=half*half%mod;
    }else{
      if(mp.count(make_pair(a,p-1)))return mp[make_pair(a,p-1)];
      return mp[make_pair(a,p-1)]=a*modpow(a,p-1)%mod;
    }
}

long long comb(int a,int b){
  if(b>a-b)return comb(a,a-b);
  long long ansMul=1;
  long long ansDiv=1;
  for(int i=0;i<b;i++){
    ansMul*=(a-i);
    ansDiv*=(i+1);
    ansMul%=mod;
    ansDiv%=mod;
  }
  long long ans=ansMul*modpow(ansDiv,mod-2)%mod;
  return ans;
}

