using namespace std;

typedef long long int lli;

lli fact[300001];

lli extgcd(lli a, lli b, lli &x, lli &y) {
        lli g = a; x = 1; y = 0;
        if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
        return g;
}

lli mod_inverse(lli a, lli m) {
        lli x, y;
        extgcd(a, m, x, y);
        return (m + x % m) % m;
}

lli mod_fact(lli n, lli p, lli& e) {
        e = 0;
        if (n == 0) return 1;

        int res = mod_fact(n / p, p, e);
        e += n / p;

        if (n / p % 2 != 0) return res * (p - fact[n % p]) % p;
        return res * fact[n % p] % p;
}

lli mod_comb(lli n, lli k, lli p) {
        if (n < 0 || k < 0 || p < 0) return 0;

        lli e1, e2, e3;
        lli a1 = mod_fact(n, p, e1),
            a2 = mod_fact(k, p, e2),
            a3 = mod_fact(n - k, p, e3);

        if (e1 > e2 + e3) return 0;
        return a1 * mod_inverse(a2 * a3 % p, p) % p;
}

int main() {
        lli p = 998244353;
        lli n, a, b, k;
        cin >> n >> a >> b >> k;

        fact[1] = 1;
        for (lli i = 2; i <= 300000; i++) {
                fact[i] = fact[i - 1] * i % p;
        }

        lli sum = 0;
        for (lli i = 0; i <= n; i++) {
                double y = (double)(k - a * i) / (double)(b - a);
                double x = (double)(i)-y;

                if (y != (lli)(y) || (lli)y > n) continue;
                if (x != (lli)(x) || (lli)x > n) continue;

                sum += mod_comb(n, x, p) * mod_comb(n, y, p) % p;
                sum %= p;
        }

        cout << sum << endl;

        return 0;
}

