#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ld = long double;

const int mod = 998244353;
template<typename T>
T add(T x) {
  return x;
}
template<typename T, typename... Ts>
T add(T x, Ts... y) {
  T res = x + add(y...);
  if (res >= mod)
    res -= mod;
  return res;
}
template<typename T, typename... Ts>
T sub(T x, Ts... y) {
  return add(x, mod - add(y...));
}
template<typename T, typename... Ts>
void udd(T& x, Ts... y) {
  x = add(x, y...);
}
template<typename T, typename... Ts>
void uub(T& x, Ts... y) {
  x = sub(x, y...);
}
template<typename T>
T mul(T x) {
  return x;
}
template<typename T, typename... Ts>
T mul(T x, Ts... y) {
  return (x * 1ll * mul(y...)) % mod;
}
template<typename T, typename... Ts>
void uul(T& x, Ts... y) {
  x = mul(x, y...);
}
int bin(int a, ll deg) {
  int r = 1;
  while (deg) {
    if (deg & 1)
      uul(r, a);
    deg >>= 1;
    uul(a, a);
  }
  return r;
}
int inv(int x) {
  assert(x);
  return bin(x, mod - 2);
}

signed main() {
#ifdef LOCAL
  assert(freopen("b.in", "r", stdin));
#endif
  ll n, a, b, k;
  cin >> n >> a >> b >> k;
  vector<int> c(n + 1);
  int x = c[0] = 1;
  for (int i = 1; i <= n; ++i) {
    uul(x, inv(i));
    uul(x, n - i + 1);
    c[i] = x;
  }
  int res = 0;
  for (ll na = 0; na <= n; ++na) {
    ll nb = k - na * a;
    if (nb % b) {
      continue;
    }
    nb /= b;
    if (nb < 0 || nb > n) {
      continue;
    }
    udd(res, mul(c[na], c[nb]));
  }
  cout << res << '\n';
}

