//階乗を返す関数
int Fact(int n) {
    int sum = 1;
    for (int i = 1; i <= n; i++) {
        sum *= i;
    }
    return sum;
}

//組み合わせを返す関数
int Com(int n, int k) {
    return (Fact(n)/(Fact(k)*Fact(n-k)));
}


//Aの数とBの数がそれぞれ分かっている時、塗り方の数を返す関数
int Num(int a,int b,int n) {
    if (a == 0 && b == 0)return 1;

    int sum = 0;
    //必ずa>=bとなるように入れ替える
    if (a < b) { int c = a; a = b; b = c; }

    for (int i = 0; i <= b; i++) {
        //AとBが重なり合う場所を選ぶ
        sum += Com(n, i)*Com(n - i, a - i)*Com(n - a, b - i);
    }
    return sum;    
}

