// factorials{{{
struct factorials {
    std::vector<mint> fact, finv;

    factorials(std::size_t n) : fact(n, 1), finv(n)
    {
        for(std::size_t i=1;i<n;i++){
            fact.at(i) = fact.at(i-1) * i;
        }

        finv.at(n-1) = fact.at(n-1).inved();
        for(std::size_t i=n-1;i;i--){
            finv.at(i-1) = finv.at(i) * i;
        }
    }

    // member functions
    std::size_t size() const { return fact.size(); }
    std::size_t max() const { return fact.size() - 1; }

    mint at(std::size_t i) const { return fact.at(i); }
    mint inv(std::size_t i) const { return finv.at(i); }

    template <class T, class U>
        auto binom(T n, U k)
        -> std::enable_if_t<std::is_integral_v<T> && std::is_integral_v<U>, mint>
        {
            assert(0<=n);
            if(k<0||n<k)return 0;
            assert(k<=n && static_cast<std::size_t>(n)<size());
            return fact.at(n) * finv.at(k) * finv.at(n-k);
        }

    template <class T, class U>
        auto deal(T n, U k)
        -> std::enable_if_t<std::is_integral_v<T> && std::is_integral_v<U>, mint>
        {
            if(n==0&&k==0)return 1;
            return binom(n+k-1, k-1);
        }
};
/*}}}*/

int main(){
    std::cin.tie(nullptr);
