ll extgcd(ll a, ll b, ll &x, ll &y) {
    ll g = a; x = 1; y = 0;
    if (b != 0){
        g = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }
    return g;
}
ll invmod(ll a, ll m) { // 1/a (mod m)
    ll x, y;
    if (extgcd(a, m, x, y) == 1) return (x + m) % m;
    else                         return 0; // unsolvable
}
