long long po(long long b, int p) {
	long long re = 1;
	while (p) {
		if (p & 1)
			re = re * b % MOD;
		b = b * b % MOD;
		p >>= 1;
	}
	return re;
}

long long ncr(int a, int b) {
	return fac[a] * inv[b] % MOD * inv[a - b] % MOD;
}

int main() {
	fac[0] = inv[0] = 1;
	for (int i = 1; i < 300005; i++)
		inv[i] = po(fac[i] = fac[i - 1] * i % MOD, MOD - 2);
	scanf("%d%lld%lld%lld", &n, &a, &b, &k);
	for (int i = 0; i * a <= k && i <= n; i++) {
		ta = k - i * a;
		if (ta % b == 0) {
			ta /= b;
			if (ta <= n)
				ans = (ans + ncr(n, i) * ncr(n, ta)) % MOD;
		}
	}
	printf("%lld\n", ans);
