        if((1 << i) & p) ans = (1LL * ans * aux) % MOD;
        aux = (1LL * aux * aux) % MOD;
    }
    return ans;
}
inline int comb(int n, int k){
    int ans = fact[n];
    int c1 = invmod(fact[n - k]);
