ll modinv(ll a, ll n) {
  // 法nにおけるaの逆元 (ax≡1 mod nのx)を求める関数
  // modinv(a, MOD)でaの逆元(=a^(-1))が求まる
  ll q, s, t, u, v, w;
  s = a; t = n; u = 1; v = 0;
  while (s > 0) {
    q = t/s;
    w = t - q*s;
    t = s;
    s = w;
    w = v - q*u;
    v = u;
    u = w;
  }
  return (v + n) % n;
}

ll nCk(ll n, ll k) {
  if (n-k < k) k = n-k;
  ll cc = 1;
  for (ll i=0; i<k; i++) {
    cc *= n;
    cc %= MOD; n--;
  }
  for (ll i=2; i<=k; i++) {
    cc *= modinv(i, MOD);
    cc %= MOD;
  }
  return cc;
}

