ll factmemo[SIZE+1];
void initFact(int n, int M){
  factmemo[0] = 1;
  for(int i=1;i<=n;i++) factmemo[i] = (factmemo[i-1] * i) % mod;
}

ll factorial(int n,int M){
  if(n<=1) return 1;
  return factmemo[n];
}

ll power(int k,int n,int M){
  if(n==0) return 1;
  if(n==1) return (ll)k;

  ll ret = power(k,n/2,M);

  ret=(ret*ret)%M;

  if(n%2==1)
    ret=(ret*k)%M;

  return ret;
}


//nCm nPm nHm (mod M)

int counter = 0;

/*Combination*/
int combmemo[SIZE];
bool visitedComb[SIZE];
int C(int n,int m,int M){
  if(n<m) return 0;
  if(m==0 || n==m) return 1;
  if(visitedComb[m]) return combmemo[m];

  ll chi = factorial(n,M);
  ll mot = (factorial(m,M) * factorial(n-m,M))%M;

  mot = power((int)mot,M-2,M);

  ll ret = (chi*mot)%M;

  visitedComb[m] = true;
  return combmemo[m] = (int)ret;
}

int main(){
  int n;
  ll a, b, k, ans = 0;

  cin >> n >> a >> b >> k;

  initFact(n, mod);

  for(int i=0;i<=n;i++){
    if (k >= i*a && (k - i*a)%b == 0 && (k-i*a)/b <= n) {
      ll p = (k - i*a)/b;
      ans = (ans + (ll)C(n, i, mod) * C(n, p, mod) % mod) % mod;
    }
  }

  cout << ans << endl;

  return 0;
}

