struct Mod {
	static ll BASE;
	ll value = 0;
	static ll residue(ll value) { return (value % BASE + BASE) % BASE; }
	Mod()
	: value(0) {}
	Mod(ll value)
	: value(residue(value)) {}
	Mod operator+(const Mod& rhs) const { return Mod(value + rhs.value); }
	void operator+=(const Mod& rhs) { *this = *this + rhs; }
	Mod operator-(const Mod& rhs) const { return Mod(value - rhs.value); }
	void operator-=(const Mod& rhs) { *this = *this - rhs; }
	Mod operator*(const Mod& rhs) const { return Mod(value * rhs.value); }
	void operator*=(const Mod& rhs) { *this = *this * rhs; }
	Mod operator/(const Mod& rhs) const { return *this * rhs.inv(); }
	void operator/=(const Mod& rhs) { *this = *this / rhs; }
	Mod inv() const {
		if (value == 0) {
			assert(false);
			throw "[Mod::inv] div by zero";
		}
		ll ans, sub;
		ll d = Mod::gcd_with_coef(value, BASE, ans, sub);
		if (d != 1) {
			assert(false);
			throw "[Mod::inv] not invertible";
		}
		return ans;
	}
	static ll gcd_with_coef(ll x, ll y, ll& out_cx, ll& out_cy) {
		if (x < 0) {
			ll d = gcd_with_coef(-x, y, out_cx, out_cy);
			out_cx *= -1;
			return d;
		}
		if (y < 0) {
			ll d = gcd_with_coef(x, -y, out_cx, out_cy);
			out_cy *= -1;
			return d;
		}
		if (x > y) {
			return gcd_with_coef(y, x, out_cy, out_cx);
		}
		if (x == 0) {
			out_cx = 0;
			out_cy = 1;
			return y;
		}
		ll q = y / x;
		ll r = y % x;
		ll d = gcd_with_coef(r, x, out_cy, out_cx);
		out_cx -= q * out_cy;
		return d;
	}
};
ll Mod::BASE = 998244353;

int main() {
	ll N, A, B, K;
	cin >> N >> A >> B >> K;
	vector<Mod> fact(N+1, 1);
	rep(i,1,N+1) {
		fact[i] = Mod(i) * fact[i-1];
	}
	vector<Mod> binom(N+1);
	rep(i,0,N+1) {
		binom[i] = fact[N] / fact[N-i] / fact[i];
	}
	Mod ans = 0;
	rep(a,0,N+1) {
		ll b = (K - a * A) / B;
		if ((K - a * A) % B != 0 || !(0 <= b && b <= N)) {
			continue;
		}
		ans += binom[a] * binom[b];
	}
	cout << ans.value << endl;
}

