LL ksm(LL base,LL k)
{
	LL sum=1;
	while(k)
	{
		if(k&1) sum=sum*base%mod;
		base=base*base%mod;
		k>>=1;
	}
	return sum;
}
LL C(LL a,LL b)
{
	return fac[a]*invl[b]%mod*invl[a-b]%mod;
}
