        (gya[i]=gya[i-1]*inv(i,mod))%=mod;
    }
    FOR(i,1,N){
        (nck[i]=kai[N+1-i]*gya[i])%=mod;
    }
    nck[0]=1;nck[N]=1;
}
int main(){
  cin>>N>>A>>B>>K;
  nCk(N,mod);
  ll ans=0;
  FOR(i,0,N+1){
    if((K-A*i)%B==0&&(K-A*i)/B>=0&&(K-A*i)/B<=N){
      (ans+=nck[i]*nck[(K-A*i)/B])%=mod;
    }
  }
  cout<<ans<<endl;
  return 0;
}

