	fact();
	ll ans = 0;
	rep(N+1, n) {
		if ((K - (A * n)) % B) continue;
		ll m = (K - (A * n)) / B;
		if (0 > m || m >= N) continue;
		ans += nck(N, n) * nck(N, m) % MOD;
	}
	cout << ans << endl;

}

