const ll MD = 998244353;
ll step(ll a, ll st) {
    if (st == 0) return 1;
    if (st % 2 == 1) return (a * step(a, st - 1)) % MD;
    ll q = step(a, st / 2);
    return (q * q) % MD;
}
ll bak(ll x) {
    return step(x, MD - 2);
}

void solve() {
    ll n, a, b, k;
    cin >> n >> a >> b >> k;

    vector<ll> fak(n + 3), ofak(n + 3);
    fak[0] = ofak[0] = 1;
    for (int i = 1; i < (int)fak.size(); i++) {
        fak[i] = (fak[i - 1] * i) % MD;
        ofak[i] = bak(fak[i]);
    }

    ll ans = 0;
    for (int x = 0; x <= n; x++) {
        if (a * x > k) continue;
        if ((k - a * x) % b != 0) continue;
        ll y = (k - a * x) / b;
        if (y > n) continue;

        ll cnx = (fak[n] * ((ofak[x] * ofak[n - x]) % MD)) % MD;
        ll cny = (fak[n] * ((ofak[y] * ofak[n - y]) % MD)) % MD;
        ans = (ans + cnx * cny) % MD;
    }

    cout << ans << "\n";
}

