//二項係数nCrをdivisorで割った余りを求めるクラス
class combination_mod
{
private:
	std::vector<long long>factorial_mod;
	long long divisor;
public:
	combination_mod(long long div, long long sup_n) :divisor(div), factorial_mod(std::vector<long long>(sup_n + 1))
	{
		//階乗をdivisorで割ったあまりを計算する
		if (factorial_mod[0] != 1)
		{
			factorial_mod[0] = 1;
			for (long long i = 1; i < sup_n; i++)
			{
				factorial_mod[i] = factorial_mod[i - 1] * i % divisor;
			}
		}
	}
	long long operator()(long long n, long long r)
	{
		//分母、分子
		long long numerator = factorial_mod[n];
		long long denominator = factorial_mod[r] * factorial_mod[n - r] % divisor;//積はdivisorを超えているかもしれないからもう一回剰余算する

		/*
		 * nCr ≡ (n! % p) * ((n-r)! r! % p)^(p-2) (mod p) (但しpは素数)
		 *
		 * 証明:
		 * nCrを変形して
		 * nCr * (n-r)! * r! = n!
		 * 任意の整数は自分自身と合同だから
		 * nCr * (n-r)! * r! ≡ n! (mod p)
		 * 両辺に(n-r)!とr!のモジュラ逆数をかけて
		 * nCr ≡ n! * ((n-r)!)^(-1) * (r!)^(-1) (mod p)
		 * ---------------------------------------------------------------
		 * 補題1:
		 * pが素数のとき
		 * a^(p-1) ≡ 1 (mod p) (ただしaとpは互いに素)
		 * が成立する(フェルマーの小定理)。
		 * 上式を変形して
		 * a * a^(p-2) ≡ 1 (mod p)
		 * 即ちa^(p-2)がaのモジュラ逆数である。
		 * ---------------------------------------------------------------
		 * pは十分大きい素数だから(n-r)!とr!はそれぞれpと互いに素
		 * よって補題1より
		 * ((n-r)!)^(-1) = ((n-r)!)^(p-2)
		 * (r!)^(-1) = (r!)^(p-2)
		 * よって
		 * nCr ≡ n! * ((n-r)!)^(p-2) * (r!)^(p-2) (mod p)
		 *     =  n! * ((n-r)! * (r!))^(p-2)
		 * ---------------------------------------------------------------
		 * 補題2:
		 * a ≡ b1 * b2 * b3...(mod c)
		 * のとき
		 * a ≡ (b1 % c) * (b2 % c) * (b3 % c)...(mod c)
		 * ---------------------------------------------------------------
		 * 補題2より
		 * nCr ≡ (n! % p) * ((n-r)! r! % p)^(p-2) (mod p)
		 * Q.E.D.
		 */

		 //power = denominator^(divisor - 2)を計算する
		long long index = divisor - 2, power = 1;
		while (index > 0)
		{
			if (index & 1 == 1)
			{
				power *= denominator;
				power %= divisor;
			}
			denominator *= denominator;
			denominator %= divisor;
			index >>= 1;
		}
		return numerator * power % divisor;
	}
};
int main()
{
	const long long divisor = 998244353;
	const long long sup_n = 333333;
	combination_mod cm(divisor, sup_n);
	long long n, a, b, k;
	std::cin >> n >> a >> b >> k;
	std::vector<std::pair<long, long>>pairs;
	pairs.reserve(n);
	for (long long x = 0; x <= n; x++)
	{
		if ((k - a * x) % b == 0)
		{
			long long y = (k - a * x) / b;
			if (0 <= y && y <= n)
			{
				pairs.push_back(std::make_pair(x, y));
			}
		}
	}
	long long ans = 0;
	for (auto i : pairs)
	{
		ans += cm(n, i.first) * cm(n, i.second) % divisor;
		ans %= divisor;
	}
	std::cout << ans << std::endl;
	return 0;
}

