const uint32_t MOD = 998244353;
const uint32_t MAX_N = 3e5 + 12;

uint32_t fast_pow(uint32_t a, uint32_t b) {
	if (b == 0) {
		return 1;
	}
	uint64_t ans = fast_pow(a, b / 2);
	ans = ans * ans % MOD;
	if (b % 2) {
		ans = ans * a % MOD;
	}
	return ans;
}

uint64_t fact[MAX_N];
uint64_t iFact[MAX_N];

void precalc() {
	fact[0] = 1;
	for (uint32_t i = 1;i < MAX_N;i++) {
		fact[i] = fact[i - 1] * i % MOD;
	}
	iFact[MAX_N - 1] = fast_pow(fact[MAX_N - 1], MOD - 2);
	for (uint32_t i = MAX_N - 2;i < MAX_N;i--) {
		iFact[i] = iFact[i + 1] * (i + 1) % MOD;
	}
}

uint64_t comb(uint32_t a, uint32_t b) {
	return fact[a] * iFact[a - b] % MOD * iFact[b] % MOD;
}

int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr);
	precalc();

	uint64_t n, a, b, k;
