		}
		uint64_t sB = k - sA;
		if (sB % b) {
			continue;
		}
		uint32_t bCnt = sB / b;
		if (bCnt > n) {
			continue;
		}

		ans += comb(n, i) * comb(n, bCnt) % MOD;
		ans %= MOD;
	}
	std::cout << ans << "\n";
}

