#include <bits/stdc++.h>

using namespace std;

using Value = int64_t;

constexpr Value mod = 998244353;

Value combinations(Value a, Value b) {
  if (a == b) {
    return 1;
  }
  if (b < a) {
    std::swap(a, b);
  }
  if (a == 1 || a == b - 1) {
    return b % mod;
  }
  Value ret = 1;
  if (a > b / 2) {
    a = b - a;
  }
  for (Value i = 1; i <= a; ++i) {
    ret *= (b - i + 1);
    ret /= i;
    ret %= mod;
  }
  return ret;
}

Value calc(Value const n, Value r, Value b, Value const k) {
  if (k == 0) {
    return 0;
  }

  if (r < b) {
    std::swap(r, b);
  }
  Value const g = r + b;
  Value ret = 0;
  Value const gCountMin = std::max(
      static_cast<Value>(ceil((k - r * n) / (1.0 * g - r))), INT64_C(0));
  for (Value gCount = gCountMin; gCount <= n; ++gCount) {
    Value const kG = gCount * g;
    if (kG > k) {
      break;
    }
    Value rCountMin = 0;
    if (r > b) {
      rCountMin = std::max(static_cast<Value>(ceil(
                               ((k - kG) - b * (n - gCount)) / (1.0 * r - b))),
                           INT64_C(0));
    }
    for (Value rCount = rCountMin; rCount <= n; ++rCount) {
      Value const kRG = kG + rCount * r;
      if (kRG > k) {
        break;
      }
      if ((k - kRG) % b) {
        continue;
      }
      Value const bCount = (k - kRG) / b;
      if (rCount + gCount + bCount > n) {
        continue;
      }
      Value const cCount = n - rCount - gCount - bCount;
      Value v = 1;
      Value rest = n;
      if (gCount) {
        v *= combinations(gCount, rest);
        v %= mod;
        rest -= gCount;
      }
      if (rCount) {
        v *= combinations(rCount, rest);
        v %= mod;
        rest -= rCount;
      }
      if (bCount) {
        v *= combinations(bCount, rest);
        v %= mod;
        rest -= bCount;
      }
      if (cCount) {
        v *= combinations(cCount, rest);
        v %= mod;
      }
      ret += v;
      ret %= mod;
    }
  }
  return ret;
}

int main() {
  Value n, a, b, k;
  std::cin >> n >> a >> b >> k;
  auto ret = calc(n, a, b, k);
  std::cout << ret << std::endl;
  return 0;
}

