// 二分累乗法により、x^n %mod を求める
ll mod_pow(ll x, ll n){
  if (n == 0) return 1;
  ll res = mod_pow(x * x %MOD, n / 2);
  // nが奇数の場合, x^n = ((x^2)^(n/2)) * x
  if(n & 1) return res = res * x %MOD;
  // nが偶数の場合、x^n = (x^2)^(n/2)
  return res %MOD;
}

// nCk = n!/(n - k)!k!を、逆元a/b = a*b^(1e7 - 2)(mod 1e7)を用いて求める
ll comb(ll n, ll k){
  ll res = 1;
  k = min(n - k, k);
  for(ll i=n-k+1;i<=n;i++) res = (res * i) %MOD;
  for(ll i=1;i<=k;i++) res = (res * mod_pow(i, MOD-2)) %MOD;
  return res;
}

