const int P = 998244353;
const int N = 3e5 + 10;
int fact[N];
int rfact[N];
int mul(int a, int b)
{
	return (ll)a * b % P;
}
int bpow(int x, int p)
{
	int res = 1;
	for (; p > 0; p /= 2, x = mul(x, x))
		if (p % 2 == 1)
			res = mul(res, x);
	return res;
}

int cnk(int n, int k)
{
	if (k < 0 || k > n)
		return 0;
	return mul(fact[n], mul(rfact[k], rfact[n - k]));
}

ll getc(ll n, ll x, ll y)
{
	return mul(cnk(n, x), cnk(n, y));
}

void solve()
{
	fact[0] = 1;
	for (int i = 1; i < N; ++i)
		fact[i] = mul(fact[i - 1], i);
	rfact[N - 1] = bpow(fact[N - 1], P - 2);
	for (int i = N - 2; i >= 0; --i)
		rfact[i] = mul(rfact[i + 1], i + 1);
	int n, a, b;
	ll k;
	cin >> n >> a >> b >> k;
	ll ans = 0;
	for (ll x = 0; x <= n; ++x)
	{
		auto left = k - a * x;
		if (left < 0 || left % b != 0)
			continue;
		auto y = left / b;
		ans += getc(n, x, y);
		ans %= P;
	}
	cout << ans << endl;
}

