int add(int a, int b, int c) {
    int res = a + b;
    return (res >= c ? res - c : res);
}

int mod_neg(int a, int b, int c) {
    int res; if(abs(a-b) < c) res = a - b;
    else res = (a-b) % c;
    return (res < 0 ? res + c : res);
}

int mul(int a, int b, int c) {
    LL res = (LL)a * b;
    return (res >= c ? res % c : res);
}

template <typename T>T power(T e, T n, T m) {
    T x = 1, p = e;
    while(n) {
        if(n & 1) x = mul(x, p, m);
        p = mul(p, p, m);
        n >>= 1;
    }
    return x;
}

template<typename T> T extended_euclid(T a, T b, T &x, T &y) {
    T xx = 0, yy = 1; y = 0; x = 1;
    while(b) {
        T q = a / b, t = b;
        b = a % b; a = t;
        t = xx; xx = x - q * xx;
        x = t; t = yy;
        yy = y - q * yy; y = t;
    }
    return a;
}

template<typename T> T mod_inverse(T a, T n) {
    T x, y, z = 0; 
    T d = extended_euclid(a, n, x, y);
    return (d > 1 ? -1 : mod_neg(x, z, n));
}


long long ncr(int n,int r)
{
    if(n<0||r<0||r>n)
    {
        return 0ll;
    }
    return (((fac[n]*inv[r])%MOD)*inv[n-r])%MOD;
}

long long solve(int a,int b)
{
    int x=min(a,b);
    long long ans=0;
    for(int j=0;j<=x;j++)
    {
        ans+=((((ncr(n,j)*1ll*ncr(n-j,a-j))%MOD)*1ll*ncr(n-a,b-j))%MOD);
        ans%=MOD;
    }
    return ans;
}


void prec()
{
    fac[0]=1;
    inv[0]=1;
    for(int i=1;i<=n;i++)
    {
        fac[i]=(fac[i-1]*i)%MOD;
        inv[i]=mod_inverse(fac[i],1ll*MOD);
    }

}



int main()
{

    scanf("%d %d %d",&n,&a,&b);
    prec();
    long long k;
    scanf("%lld",&k);
    long long ans=0;
    for(int i=0;i<=n;i++)
    {
        if((k>=(a*i))&&(((k-(a*i))%b)==0))
        {
            ans+=solve(i,(k-(a*i))/b);
            ans%=MOD;
        }
    }
    printf("%lld\n",ans);

}

