        if ((k - red) >= 0 && (k - red) % b == 0) {
            ll ib = (k - red) / b;
            ret = (ret + nCk(n, ib) * nCk(n, i)) % MOD;
        }
    }
    cout << ret << "\n";
    return 0;
}

