using namespace std;

ll power_mod(ll x, ll n) {
  if (n == 0)
    return 1;
  else if (n % 2)
    return MODM(x, power_mod(x, n - 1));
  else
    return power_mod(MODM(x, x), n / 2);
}

ll fact_mod(ll n) {
  ll res = 1;
  for (int i = 1; i <= n; i++) {
    res = MODM(i, res);
  }
  return res;
}

ll comb_mod(ll n, ll k) {
  if (n < k) return 0;
  if (n == 0 || k == 0 || n == k) return 1;

  ll fn = fact_mod(n);
  ll fk = fact_mod(k);
  ll fn_k = fact_mod(n - k);
  ll rfk = power_mod(fk, MOD - 2);
  ll rfn_k = power_mod(fn_k, MOD - 2);

  return MODM(MODM(fn, rfk), rfn_k);
}

ll gcd(ll a, ll b) {
  if (b == 0)
    return a;
  else
    return gcd(b, a % b);
}

