ll exp(int b, ll e){
	if(e == 0)
		return 1;
	if(e % 2 == 0){
		ll r = exp(b, e/2);
		return (r*r) % MOD;
	}
	return (b*exp(b, e-1)) % MOD;
}

ll modInv(ll a){
	return exp(a, MOD-2);
}

ll BC(ll n, ll k){
	if(k == 0)
		return 1;

	ll r = 0;
	r += F[n];
	r = (r *modInv(F[k])) % MOD;
	r = (r *modInv(F[n-k])) % MOD;
	return r;
}

