const long long table_size = 1e5 + 5;
long long fact[table_size], inverse[table_size];

// 高速に n^m (mod p) を求める
long long POW(long long n, long long m, long long p){
    if(m == 0){
        return 1;
    }
    if(m % 2 == 0){
        long long tmp = POW(n, m / 2, p) % p;
        return tmp * tmp % p;
    }
    else{
        return n * POW(n, m - 1, p) % p;
    }
}

// 階乗を生成    e.g. 5! == fact[5]
void make_table(long long n, long long p) {
    fact[0] = 1;
    inverse[0] = 1;
    for (long long i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % p;
        inverse[i] = POW(fact[i], p - 2, p) % p;
    }
}

// nCr
long long nCr(long long n, long long r, long long p) {
    return fact[n] * inverse[r] % p * inverse[n - r] % p;
}

int main() {
    ll n, a, b, k;
    cin >> n >> a >> b >> k;

