    ll ans = 0;
    REP(i, n + 1){
        ll t = k - i * a;
        if(t < 0 || t > n * b || t % b != 0)continue;
        ll tt = t / b;
        ans += nCr(n, i, MOD) * nCr(n, tt, MOD) % MOD;
        ans %= MOD;
    }
    cout << ans << endl;
}

