    ll ans = 0ll;
    for(ll i = 0; i <= N; i++){
        ll x = i;
        if((K - A * x) % B == 0){
            ll y = (K - A * x) / B;

            ll tmp = com.nCk(N,x);
            tmp *= com.nCk(N,y);
            tmp %= MOD;
            ans += tmp;
            ans %= MOD;
        }
    }

    cout << ans << endl;

    return 0;
}

