const int64 MOD = 998244353LL;
const int MAX_N = 300000;

int64 fact[MAX_N + 1];

int64 powMod(int64 a, int64 b) {
    if (b == 0) return 1;
    else if (b & 1) return (a * powMod(a, b - 1)) % MOD;
    else {
        auto c = powMod(a, b / 2);
        return (c * c) % MOD;
    }
}

int64 invMod(int64 n) {
    return powMod(n, MOD - 2);
}

int64 factorialMod(int64 n) {
    // 初期化
    if (fact[n] == 0) {
        fact[0] = 1;
        for (int m = 1; m <= MAX_N; m++) {
            fact[m] = (fact[m - 1] * m) % MOD;
        }
    }
    return fact[n];
}

int64 nCkMod(int64 n, int64 k) {
    // n! / (n - k)!k!
    int64 nume = factorialMod(n),
          deno = (factorialMod(n - k) * factorialMod(k)) % MOD;
    return (nume * invMod(deno)) % MOD;
}

