    val counts = mutableListOf<Triple<Int, Int, Int>>()
    for (green in 0..n) {
        for (red in 0..(n - green)) {
            for (blue in 0..(n - green - red)) {
                val point = a * red + (a + b) * green + b * blue
                if (point == k) {
                    counts.add(Triple(red, green, blue))
                } else if (point > k) {
                    break
                }
            }
        }
    }

    val sum = counts.map {
        val red = it.first
        val green = it.second
        val blue = it.third
        c(n, red) * c(n - red, green) * c(n - red - green, blue)
    }.sum()

    println(sum % divisor)
}

