    void solve(){
        int n = ni();
        int a = ni();
        int b = ni();
        long k = nl();
        int mod = 998244353;
        int[][] fif = enumFIF(n, mod);
        long ans = 0;
        for(int i = 0; i <= n; i++){
            long a_sum = (long)a*i;
            long b_sum = k-a_sum;
            int b_num = (int)(b_sum/b);
            if((b_sum%b==0)&&b_num<=n&&b_num>=0){
                ans += C(n,i,mod,fif)*C(n,b_num,mod,fif);
                ans %= mod;
            }
        }
        out.println(ans);

    }
    public static long C(int n, int r, int mod, int[][] fif) {
        if (n < 0 || r < 0 || r > n)
            return 0;
        return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
    }


    public static int[][] enumFIF(int n, int mod) {
        int[] f = new int[n + 1];
        int[] invf = new int[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            f[i] = (int) ((long) f[i - 1] * i % mod);
        }
        long a = f[n];
        long b = mod;
        long p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d;
            d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        invf[n] = (int) (p < 0 ? p + mod : p);
        for (int i = n - 1; i >= 0; i--) {
            invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
        }
        return new int[][] { f, invf };
    }

