        int n = sc.nextInt();
        int A = sc.nextInt();
        int B = sc.nextInt();
        long K = sc.nextLong();
        long ans = 0;
        long yy = Math.max(K / n - B , 0);
        long xx = Math.min(n, K / A); 
        for(long x = yy; x <= xx; x++){
            long q = K - A * x;
            if(q % B == 0){
                long y = q / B;
