public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        ModuloArithmetic ma = new ModuloArithmetic(Const.MOD99);
        int n = In.ni();
        long a = In.nl();
        long b = In.nl();
        long k = In.nl();
        long gcd = MathUtil.gcd(a, b, k);
        a /= gcd;
        b /= gcd;
        k /= gcd;
        long[] s = MathUtil.extGCD(a, b);
        long x = s[0];
        long y = s[1];
        long d = s[2];
        long[] fact = ma.factorialArray(n);
        long[] ifact = ma.inversiveFactrialArray(fact);
        long ans = 0;
        for (int g = 0; g <= n; g++) {
            long m = k - (a + b) * g;
            if (m < 0) {
                break;
            }
            if (m % d != 0 || (n - g) * max(a, b) < m) {
                continue;
            }
            long r0 = (m / d) * x;
            long b0 = (m / d) * y;
            if (a < b) {
                if (r0 < 0) {
                    long t = Longs.cld(-r0, b);
                    r0 += t * b;
                    b0 -= t * a;
                } else {
                    long t = r0 / b;
                    r0 -= t * b;
                    b0 += t * a;
                }
                while (r0 >= 0 && b0 >= 0 && r0 + g + b0 <= n) {
                    ans += ma.prod(fact[n], ifact[(int) r0], ifact[g], ifact[(int) b0], ifact[n - (int) (r0 + g + b0)]);
                    r0 += b;
                    b0 -= a;
                }
            } else {
                if (b0 < 0) {
                    long t = Longs.cld(-b0, a);
                    r0 -= t * b;
                    b0 += t * a;
                } else {
                    long t = b0 / a;
                    r0 += t * b;
                    b0 -= t * a;
                }
                while (r0 >= 0 && b0 >= 0 && r0 + g + b0 <= n) {
                    ans += ma.prod(fact[n], ifact[(int) r0], ifact[g], ifact[(int) b0], ifact[n - (int) (r0 + g + b0)]);
                    r0 -= b;
                    b0 += a;
                }
            }
            ans = ma.mod(ans);
        }
        out.append(ans);
    }
}



