            fact[i] = fact[i-1]*i;
            fact[i]%=998244353;
        }
    }
    private static long c(long g, long gg){

        return fact[(int)g]/(fact[(int)gg] * fact[(int)(g-gg)]);
    }
	public static void main (String[] args) {
