public class Main{

	static Scanner s=new Scanner(System.in);

	static int mod=998244353;

	public static void main(String[] $){
		long n=s.nextInt(),a=s.nextInt(),b=s.nextInt(),k=s.nextLong(),r=0;
		for(int i=0;i<=n;++i){
			if((k-a*i)%b==0){
				long j=(k-a*i)/b;
				r+=nPr(n,i)*nPr(n,j);
				r%=mod;
			}
		}
		System.out.println(r);
	}
	static long nPr(long n,long a){
		if(a==0)
			return 1;
		long r=1;
		for(long i=n-a+1;i<=n;++i){
			r*=i;
			r%=mod;
		}
		for(int i=2;i<=a;++i) {
			r*=pow(i,mod-2);
			r%=mod;
		}
		return r;
	}
	static long pow(long n,long a){
		if(a==1)
			return n;
		if(a%2==0){
			long d=pow(n,a/2);
			return d*d%mod;
		}
		return n*pow(n,a-1)%mod;
	}
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long N = sc.nextLong();
        long A = sc.nextLong();
        long B = sc.nextLong();
        long K = sc.nextLong();

        long ret = 0;
        long mod = 998244353;

        for (long a = 0; a <= N; a++) {
            long b = (K - A * a) / B;
            if (b >= 0 && b <= N && a * A + b * B == K) {
                ret += ((choose(N, a) % mod) * (choose(N, b) % mod)) % mod;
            }
        }

        System.out.println(ret % mod);
    }

    static long choose(long x, long y) {
        if (y < 0 || y > x) return 0;
        if (y > x / 2) {
            y = x - y;
        }

        double answer = 1.0;
        for (int i = 1; i <= y; i++) {
            answer *= (x + 1 - i);
            answer /= i;
        }

        return (long) answer;
    }
}

