			if (rest < 0) {
				break;
			}
			if (rest % b != 0) {
				continue;
			}
			long cb = rest / b;
			if (cb > b) {
				continue;
			}
			ans += (int)((long)mc.choose(n, ca) * mc.choose(n, (int) cb) % P);
			if (ans >= P) {
				ans -= P;
			}
		}

		out.println(ans);
	}

