	static void solve()
	{
		// C(n,na)^2
		int n = ni();
		int A = ni(), B = ni();
		long K = nl();
		int mod = 998244353;
		int[][] fif = enumFIF(700000, mod);
		long ans = 0;
		for(int i = 0;i <= n;i++){
			long rem = K-(long)i*A;
			if(rem >= 0 && rem % B == 0 && rem / B <= n){
				int na = i, nb = (int)(rem / B);
				// k:green
				// na-k:red
				// nb-k:blue
				// n!/k!/(na-k)!/(nb-k)!/(n-(na+nb-k))!

				long ret = C(n, na, mod, fif) * C(n, nb, mod, fif) % mod;
//				long ret = 0;
//				for(int k = 0;k <= na && k <= nb;k++){
//					if(n-(na+nb-k) >= 0){
//						ret += 
//						(long)fif[0][n]
//								*fif[1][k]%mod
//								*fif[1][na-k]%mod
//								*fif[1][nb-k]%mod
//								*fif[1][n-(na+nb-k)]%mod;
//					}
//				}
//				tr(na, nb, n, ret);
				ans += ret;
			}
		}
		out.println(ans%mod);
	}

	public static long C(int n, int r, int mod, int[][] fif) {
		if (n < 0 || r < 0 || r > n)
			return 0;
		return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
	}


	public static int[][] enumFIF(int n, int mod) {
		int[] f = new int[n + 1];
		int[] invf = new int[n + 1];
		f[0] = 1;
		for (int i = 1; i <= n; i++) {
			f[i] = (int) ((long) f[i - 1] * i % mod);
		}
		long a = f[n];
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		invf[n] = (int) (p < 0 ? p + mod : p);
		for (int i = n - 1; i >= 0; i--) {
			invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
		}
		return new int[][] { f, invf };
	}


