		for (long aa = 0; aa <= n && k - aa * a >= 0; aa++) {
			if ((k - aa * a) % b != 0) {
				continue;
			}
			long bb = (k - aa * a) / b;

//			pr.println(aa);

//			for (long c = Math.max(0, aa + bb - n); c <= Math.min(aa, bb); c++) {
//				pr.printf("  %d\n", c);

//				if (n - aa - bb + c < 0) {
