	static final int P = 998244353;

	void submit() {
		int n = nextInt();
		int a = nextInt();
		int b = nextInt();
		long k = nextLong();

		ModuloCombinatorics mc = new ModuloCombinatorics(n, P);

		int ans = 0;

		for (int ca = 0; ca <= n; ca++) {
			long rest = k - (long)a * ca;
			if (rest < 0) {
				continue;
			}
			if (rest % b != 0) {
				continue;
			}
			long cb = rest / b;
			if (cb > n) {
				continue;
			}
			ans += (int)((long)mc.choose(n, ca) * mc.choose(n, (int) cb) % P);
			if (ans >= P) {
				ans -= P;
			}
		}

		out.println(ans);
	}

