public class Main {
  private static long solve(int n, long a, long b, long k) {
    ModCalculator mc = new ModCalculator(998244353L);
    ModCombinationCache mcc = new ModCombinationCache(mc);

    long answer = 0;
    for (long i = 0; i <= Math.min(n, k / a); i++) {
      long j = (k - a * i) / b;
      if (j > n || a * i + b * j != k) {
        continue;
      }
      long v = mc.mul(mcc.getC(n, (int)i), mcc.getC(n, (int)j));
      answer = mc.add(answer, v);
    }
    return answer;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    long a = reader.nextLong();
    long b = reader.nextLong();
    long k = reader.nextLong();
    out.println(solve(n, a, b, k));
