/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int a = in.nextInt();
            int b = in.nextInt();
            long k = in.nextLong();

            long ans = 0;
            long MOD = 998244353;
            Combination comb = new Combination(n, MOD);
            for (int red = 0; red <= n; red++) {
                long redSum = (long) a * red;
                if (k < redSum || (k - redSum) % b != 0) continue;
                long blue = (k - redSum) / b;
                if (blue < 0 || n < blue) continue;

                ans = (ans + comb.combMod(n, red) * comb.combMod(n, (int) blue)) % MOD;
            }

            out.println(ans);
        }

    }

    static class Combination {
        Modulo modulo;
        long[] nors;
        long[] revs;

        public Combination(int n, long m) {
            nors = new long[n + 1];
            revs = new long[n + 1];
            modulo = new Modulo(m);

            nors[0] = 1;
            for (int i = 1; i <= n; i++) {
                nors[i] = modulo.mlt(nors[i - 1], i);
            }

            revs[n] = modulo.rev(nors[n]);
            for (int i = n - 1; i >= 0; i--) {
                revs[i] = (revs[i + 1] * (i + 1)) % m;
            }
        }

        public long combMod(int n, int k) {
            long ret = nors[n];
            ret = modulo.mlt(ret, revs[k]);
            ret = modulo.mlt(ret, revs[n - k]);
            return ret;
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public long nextLong() {
            return Long.parseLong(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }

    static class Modulo {
        long m;

        public Modulo(long m) {
            this.m = m;
        }

        public long mlt(long a, long b) {
            return (a * b) % m;
        }

        public long rev(long a) {
            return pow(a, m - 2);
        }

        public long pow(long a, long x) {
            long ans = 1;
            while (x > 0) {
                if ((x & 1) != 0) {
                    ans = (ans * a) % m;
                }
                x >>= 1;
                a = (a * a) % m;
            }
            return ans;
        }

    }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {

    long q[] = new long[N+1];
    long invq[] = new long[N+1];
    long MAGIC = 998244353;
    q[0] = 1;
    invq[0] = 1;
    for (int i=1; i<=N; i++) {
      q[i] = q[i-1] * i % MAGIC;
      invq[i] = inv(q[i], MAGIC);
      if (invq[i] == 0) {
        throw new RuntimeException("zero inv: " + q[i]);
      }
    }

    long ans = 0;

    for (int numA=0; numA<=N; numA++) {
      long remain = K - (A*numA);
      if (remain >= 0 && remain % B == 0) {
        int numB = (int) (remain / B);
        if (numB <= N) {
          long tmp = (q[N]*q[N])%MAGIC;
          tmp = (tmp*invq[numA])%MAGIC;
          tmp = (tmp*invq[N-numA])%MAGIC;
          tmp = (tmp*invq[numB])%MAGIC;
          tmp = (tmp*invq[N-numB])%MAGIC;
          ans = (ans + tmp)%MAGIC;
        }
      }
    }
    System.out.println(ans % MAGIC);
  }

  private static long inv(long a, long MOD) {
    long x0 = 1, x1 = 0;
    long y0 = 0, y1 = 1;
    long b = MOD;
    while (b != 0) {
      long q = a / b;
      long r = a % b;
      long x2 = x0 - q * x1;
      long y2 = y0 - q * y1;
      a = b;
      b = r;
      x0 = x1;
      x1 = x2;
      y0 = y1;
      y1 = y2;
    }
    return (MOD+x0%MOD)%MOD;
  }
}

