class UnionFind {
	int[] parent;
	int[] rank;
	UnionFindRoot[] root;

	UnionFind(int n) {
		parent = new int[n];
		root = new UnionFindRoot[n];
		rank = new int[n];

		for (int i = 0; i < n; i++) {
			parent[i] = i;
			root[i] = new UnionFindRoot(i);
		}
	}

	int rootIndex(int i) {
		int p = parent[i];
		if (i == p) {
			return i;
		}
		return parent[i] = rootIndex(p);
	}

	UnionFindRoot root(int i) {
		int p = parent[i];
		if (i == p) {
			return root[i];
		}
		return root[parent[i] = rootIndex(p)];
	}

	void union(int i, int j) {
		int root1 = rootIndex(i);
		int root2 = rootIndex(j);

		if (root2 == root1)
			return;

		UnionFindRoot newRoot = root[root1].combine(root[root2]);

		if (rank[root1] > rank[root2]) {
			parent[root2] = root1;
			root[root1] = newRoot;
		} else if (rank[root2] > rank[root1]) {
			parent[root1] = root2;
			root[root2] = newRoot;
		} else {
			parent[root2] = root1;
			root[root1] = newRoot;
			rank[root1]++;
		}
	}

	int size(int x) {
		return root(x).size;
	}

	class UnionFindRoot {
		int size;

		UnionFindRoot(int index) {
			size = 0;
		}

		UnionFindRoot combine(UnionFindRoot another) {
			UnionFindRoot newRoot = new UnionFindRoot(0);
			newRoot.size = size + another.size;
			return newRoot;
		}
	}
}

final class IO {
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out, false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static char nextChar() {
		if (!hasNext())
			throw new NoSuchElementException();
		return (char) readByte();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static double nextDouble() {
		return Double.parseDouble(next());
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {

    long q[] = new long[300001];
    long MAGIC = 998244353;
    q[0] = 1;
    for (int i=1; i<=N; i++) {
      q[i] = q[i-1] * i % MAGIC;
    }

    long ans = 0;

    for (int numA=0; numA<=N; numA++) {
      long remain = K - (A*numA);
      if (remain % B == 0) {
        int numB = (int) (remain / B);
        int minAB = (numA > numB) ? numA : numB;
        for (int finC = 0; finC <= minAB; finC++) {
          int finA = numA - finC;
          int finB = numB - finC;
          int finD = N - finA - finB - finC;
          if (finD >= 0 && finB >= 0 && finA >= 0) {
            long tmp = (((((q[finA]*q[finB]) % MAGIC) * q[finC]) % MAGIC) * q[finD]) % MAGIC;
            ans += q[N]/tmp;
          }
        }
      }
    }
    System.out.println(ans % MAGIC);
  }
}

import java.util.Scanner;

public class Main {

  private static final long MOD = 998244353;
  private static long FACT[];
  private static long IFACT[];

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {
    FACT = new long[N+1];
    IFACT = new long[N+1];
    FACT[0] = 1;
    IFACT[0] = 1;
    for (int i=1; i<=N; i++) {
      FACT[i] = FACT[i-1] * i % MOD;
      IFACT[i] = mod_inverse(FACT[i]);
    }

    long ans = 0;
    for (int numA=0; numA<=N; numA++) {
      if ((K - numA*A)%B != 0) {
        continue;
      }
      int numB = (int)((K - numA*A)/B);
      if (numB < 0 || numB > N) {
        continue;
      }
      ans += comb(N, numA)*comb(N, numB)%MOD;
      ans %= MOD;
      /** 
      long rem = K - A*numA;
      if (rem < 0) {
        break;
      }
      int numB = (int)(rem/B);
      if ((long)A*numA+(long)B*numB == K && numB <= N) {
        ans = (ans + comb(N, numA) * comb(N, numB))%MOD;
      }*/
    }
    System.out.println(ans);
  }

  private static long comb(int n, int r) {
    if (n < 0 || r < 0 || n < r) {
      return 0;
    }
    if (r > n/2) {
      r = n - r;
    }
    return FACT[n]*IFACT[n-r]%MOD*IFACT[r]%MOD;
  }

  private static long inv(long a) {
    long b = MOD;
    long p = 1, q = 0;
    while (b > 0) {
      long c = a / b;
      long d;
      d = a;
      a = b;
      b = d % b;
      d = p;
      p = q;
      q = d - c * q;
    }
    return p < 0 ? p + MOD : p;
  }

  public static long mod_inverse(long a){
    long x0 = 1, x1 = 0;
    long y0 = 0, y1 = 1;
    long b = MOD;
    while (b != 0) {
      long q = a / b;
      long r = a % b;
      long x2 = x0 - q * x1;
      long y2 = y0 - q * y1;

      a = b; b = r;
      x0 = x1; x1 = x2;
      y0 = y1; y1 = y2;
    }
    return (MOD+x0%MOD)%MOD;
  }
}

