		// tmax = floor(x0/b2)
		// tmin = ceil(-y0/a2) = -floor(y0/a2)
		long tmax = x0 < 0 ? (x0 - b2 + 1) / b2 : x0 / b2;
		long tmin = -(y0 < 0 ? (y0 - a2 + 1) / a2 : y0 / a2);

		long num = 0;

		long mod = 998244353;

		long[] fact = new long[(int) n + 1];
		long[] factInv = new long[(int) n + 1];
		fact[0] = 1;
		fact[1] = 1;
		for (int i = 2; i <= n; i++) {
			fact[i] = fact[i - 1] * i % mod;
		}
		for (int i = 0; i <= n; i++) {
			factInv[i] = modinv(fact[i], mod);
		}

		for (long t = tmin; t <= tmax; t++) {
			long x = x0 - t * b2;
			long y = y0 + t * a2;
			long gmin = max(0, x + y - n);
			long gmax = min(x, y);
			if (gmin > gmax)
				continue;
			long comb1 = fact[(int) n] * factInv[(int) x] % mod * factInv[(int) (n - x)] % mod;
			long comb2 = fact[(int) n] * factInv[(int) y] % mod * factInv[(int) (n - y)] % mod;
			num += comb1 * comb2 % mod;
			num %= mod;
		}
		out(num);
	}

	// returns (x, y, d) s.t. ax + by = d
	static long[] exgcd(long a, long b) {
		long x = 1;
		long y = 0;
		long z = 0;
		long w = 1;
		while (b > 0) {
			long q = a / b;
			long t = z;
			z = x - q * z;
			x = t;
			t = w;
			w = y - q * w;
			y = t;
			t = b;
			b = a - q * b;
			a = t;
		}
		return new long[] { x, y, a };
	}

	static int[] lis(int[] s) {
		int n = s.length;
		int[] dp = new int[n];
		int[] ids = new int[n];
		int[] pids = new int[n];
		dp[0] = s[0];
		int len = 1;
		int lidx = 0;
		for (int i = 1; i < n; i++) {
			int idx = bs(s[i], dp, 0, len);
			dp[idx] = s[i];
			ids[idx] = i;
			if (idx == len) {
				lidx = i;
				len++;
			}
			if (idx > 0)
				pids[i] = ids[idx - 1];
		}
		int[] lis = new int[len];
		lis[len - 1] = s[lidx];
		for (int i = len - 1; i >= 0; i--) {
			lis[i] = s[lidx];
			lidx = pids[lidx];
		}
		return lis;
	}

	static int bs(int a, int[] as, int from, int num) {
		int min = from;
		int max = from + num - 1;
		while (min < max) {
			int mid = min + max >> 1;
			if (as[mid] < a)
				min = mid + 1;
			else if (as[mid] > a)
				max = mid;
			else
				return mid;
		}
		return as[min] < a ? min + 1 : min;
	}

	static int gcd(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		int z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static long gcd(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		long z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static long modinv(long a, long mod) {
		return BigInteger.valueOf(a).modInverse(BigInteger.valueOf(mod)).longValueExact();
	}

	static int lcm(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		return x / gcd(x, y) * y;
	}

	static long lcm(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		return x / gcd(x, y) * y;
	}

