		return result;
	}

	static long permutation(int a, int b, int c, int d){
		int n = a + b + c + d;

		long result = fact[n];
		if(a != 0) //result = result * repeatablePow((int)fact[a], mod - 2, mod) % mod;
			result = (result * revFact[a])%mod; //
//		System.out.println("p1 "+result);
		if(b != 0) result = (result * revFact[b])%mod; //result * repeatablePow((int)fact[b], mod - 2, mod) % mod;
//		System.out.println("p2 "+result);
		if(c != 0) result = (result * revFact[c])%mod; //result * repeatablePow((int)fact[c], mod - 2, mod) % mod;
//		System.out.println("p3 "+result);
		if(d != 0) result = (result * revFact[d])%mod; //result * repeatablePow((int)fact[d], mod - 2, mod) % mod;
//		System.out.println("p4 "+result);

		return result;
	}

	static long repeatablePow(int x, int n, int mod){
        if(n == 0){
            return 1;
        }
        long result = repeatablePow((int)((long)x*x%mod), n/2, mod);
        if(n % 2 == 1){
            result = result*x%mod;
        }
        return result;
    }

}

import java.util.Scanner;

public class Main {
  static final long M = 998244353L;

  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int A = scanner.nextInt();
    int B = scanner.nextInt();
    long K = scanner.nextLong();

    System.out.println(solve(N, A, B, K));
  }

  private static long solve(int N, long A, long B, long K) {
    if (A > B) return solve(N, B, A, K);

    long[] fact = new long[N + 1];
    fact[0] = 1;
    for (int i = 0; i < N; i++) {
      fact[i + 1] = fact[i] * (N - i) % M;
    }
    long[] factinv = new long[N + 1];
    factinv[0] = 1;
    for (int i = 1; i <= N; i++) {
      factinv[i] = factinv[i - 1] * inverse(i, M) % M;
    }

    long res = 0;
    for (int i = 0; i <= Math.min(N, K / B); i++) {
      if ((K - B * i) % A == 0) {
        long j = (K - B * i) / A;
        if (j > N) continue;
        int jj = (int) j;
        long c = fact[i] * factinv[i] % M;
        c *= fact[jj] * factinv[jj] % M;
        res += c % M;
        res %= M;
      }
    }
    return res;
  }

  public static long inverse(long a, long mod) {
    return modpow(a, mod - 2, mod);
  }

  public static long modpow(long a, long n, long mod) {
    long res = 1;
    while (n > 0) {
      if (n % 2 == 1) res = (res * a) % mod;
      a = (a * a) % mod;
      n >>= 1;
    }
    return res % mod;
  }
}

