public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        ModuloArithmetic ma = new ModuloArithmetic(Const.MOD99);
        int n = In.ni();
        long a = In.nl();
        long b = In.nl();
        long k = In.nl();
        long[] s = MathUtil.extGCD(a, b);
        long[] fact = ma.factorialArray(n);
        long[] ifact = ma.inversiveFactrialArray(fact);
        long ans = 0;
        for (int g = 0; g <= n; g++) {
            long m = k - (a + b) * g;
            if (m < 0) {
                break;
            }
            if (m % s[2] != 0) {
                continue;
            }
            long r0 = (m / s[2]) * s[0];
            long b0 = (m / s[2]) * s[1];
            assert a * r0 + b * b0 == m;
            if (a < b) {
                if (r0 < 0) {
                    long t = Longs.cld(-r0, b);
                    r0 += t * b;
                    b0 -= t * a;
                    assert a * r0 + b * b0 == m;
                } else {
                    long t = r0 / b;
                    r0 -= t * b;
                    b0 += t * a;
                    assert a * r0 + b * b0 == m;
                }
                while (r0 >= 0 && b0 >= 0 && r0 + g + b0 <= n) {
                    ans += ma.prod(fact[n], ifact[(int) r0], ifact[g], ifact[(int) b0], ifact[n - (int) (r0 + g + b0)]);
                    r0 += b;
                    b0 -= a;
                    assert a * r0 + b * b0 == m;
                }
            } else {
                if (b0 < 0) {
                    long t = Longs.cld(-b0, a);
                    r0 -= t * b;
                    b0 += t * a;
                    assert a * r0 + b * b0 == m;
                } else {
                    long t = b0 / a;
                    r0 += t * b;
                    b0 -= t * a;
                    assert a * r0 + b * b0 == m;
                }
                while (r0 >= 0 && b0 >= 0 && r0 + g + b0 <= n) {
                    ans += ma.prod(fact[n], ifact[(int) r0], ifact[g], ifact[(int) b0], ifact[n - (int) (r0 + g + b0)]);
                    r0 -= b;
                    b0 += a;
                    assert a * r0 + b * b0 == m;
                }
            }
            ans = ma.mod(ans);
        }
        out.append(ans);
    }
}



