class Main
{
    static int MOD = 998244353;

    public static void main (String[] args)
    {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int A = sc.nextInt();
        int B = sc.nextInt();
        long K = sc.nextLong();
        long ans = 0;
        long yy = Math.max(K / n - B , 0);
        long xx = Math.min(n, K / A); 
        for(long x = yy; x <= n; x++){
            long q = K - A * x;
            if(q % B == 0){
                long y = q / B;
                if(y > n ) continue;
                if(y < 0 ) break;
                ans = (ans + calc(n, x) * calc(n, y) % MOD) % MOD;
            }
        }
        System.out.println(ans);
    }
    public static long calc(int n, long a)
    {
        long MulSumN = 1;
        long MulSumA = 1;
        for(int i = 1; i <= a; i++){
            MulSumN *= n - i + 1;
            MulSumN %= MOD;
            MulSumA *= i;
            MulSumA %= MOD;
        }
        return MulSumN * pow(MulSumA, MOD - 2) % MOD;
    }
    public static long pow(long a, int b){
        if(b == 1) return a;
        if(b % 2 == 0){
            long d = pow(a, b / 2);
            return d * d % MOD;
        }
        return a * pow(a, b - 1) % MOD;
    }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {

    long q[] = new long[N+1];
    long invq[] = new long[N+1];
    long MAGIC = 998244353;
    q[0] = 1;
    invq[0] = 1;
    for (int i=1; i<=N; i++) {
      q[i] = q[i-1] * i % MAGIC;
      invq[i] = inv(q[i], MAGIC);
    }

    long ans = 0;

    for (int numA=0; numA<=N; numA++) {
      int numB = (int)((K - (A*numA))/B);
      if (numB >= 0 && numB <= N && A*numA + B*numB == K) {
        long tmp1 = q[N]*invq[numA]%MAGIC*invq[N-numA]%MAGIC;
        long tmp2 = q[N]*invq[numB]%MAGIC*invq[N-numB]%MAGIC;
        ans += tmp1*tmp2;
        ans %= MAGIC;
      }
    }
    System.out.println(ans);
  }

  private static long inv(long a, long MOD) {
    long x0 = 1, x1 = 0;
    long y0 = 0, y1 = 1;
    long b = MOD;
    while (b != 0) {
      long q = a / b;
      long r = a % b;
      long x2 = x0 - q * x1;
      long y2 = y0 - q * y1;
      a = b;
      b = r;
      x0 = x1;
      x1 = x2;
      y0 = y1;
      y1 = y2;
    }
    return (MOD+x0%MOD)%MOD;
  }
}

