abstract class PropertyHolder {
    private final EnumSet<Property> properties;

    public PropertyHolder(final EnumSet<Property> properties) {
        this.properties = properties;
    }

    public PropertyHolder(final TypicalPropertySets typicalSet) {
        this(typicalSet.getProperties());
    }

    public final EnumSet<Property> getProperties() {
        return properties;
    }

    public final void addProperties(final Property... props) {
        for (Property prop : props) {
            properties.add(prop);
        }
    }

    public final void addProperties(final EnumSet<Property> props) {
        for (Property prop : props) {
            properties.add(prop);
        }
    }

    public final void addProperties(final TypicalPropertySets props) {
        addProperties(props.getProperties());
    }

    public final boolean hasProperties(final Property... props) {
        for (final Property prop : props) {
            if (!properties.contains(prop)) {
                return false;
            }
        }
        return true;
    }

    public final boolean hasProperties(final EnumSet<Property> props) {
        for (final Property prop : props) {
            if (!properties.contains(prop)) {
                return false;
            }
        }
        return true;
    }

    public final boolean hasProperties(final TypicalPropertySets props) {
        return hasProperties(props.getProperties());
    }

    public final void requireProperties(final EnumSet<Property> props, final Property... ps) {
        final ArrayList<Property> unmet = new ArrayList<>();
        for (final Property prop : props) {
            if (!properties.contains(prop)) {
                unmet.add(prop);
            }
        }
        for (final Property prop : ps) {
            if (!properties.contains(prop)) {
                unmet.add(prop);
            }
        }
        if (unmet.size() > 0) {
            throw new UnsatisfiedRequiredPropertiesException(unmet);
        }
    }

    public final void requireProperties(final TypicalPropertySets props, final Property... ps) {
        requireProperties(props.getProperties(), ps);
    }

    private static final class UnsatisfiedRequiredPropertiesException extends RuntimeException {
        private static final long serialVersionUID = 1L;

        private UnsatisfiedRequiredPropertiesException(final Collection<Property> props) {
            for (final Property prop : props) {
                System.err.println(prop.name() + "should be satisfied.");
            }
        }
    }
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main {

  private static final long MOD = 998244353;
  private static long FACT[];
  private static long IFACT[];

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {

    FACT = new long[N+1];
    IFACT = new long[N+1];
    FACT[0] = 1;
    IFACT[0] = 1;
    for (int i=1; i<=N; i++) {
      FACT[i] = FACT[i-1] * i % MOD;
      IFACT[i] = inv(FACT[i]);
    }

    long ans = 0;

    for (int numA=0; numA<=N; numA++) {
      long rem = K - A*numA;
      if (rem < 0) {
        break;
      }
      int numB = (int)(rem/B);
      if ((long)A*numA+(long)B*numB == K && numB <= N) {
        ans = (ans + comb(N, numA) * comb(N, numB))%MOD;
      }
    }
    System.out.println(ans);
  }

  private static long comb(int n, int r) {
    if (n < 0 || r < 0 || n < r) {
      return 0;
    }
    if (r > n/2) {
      r = n - r;
    }
    return FACT[n]*IFACT[n-r]%MOD*IFACT[r]%MOD;
  }

  private static long inv(long a) {
    long b = MOD;
    long p = 1, q = 0;
    while (b > 0) {
      long c = a / b;
      long d;
      d = a;
      a = b;
      b = d % b;
      d = p;
      p = q;
      q = d - c * q;
    }
    return p < 0 ? p + MOD : p;
  }
}

import java.util.*;

public class Main {
    public static final long DIV = 998244353;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long a = sc.nextLong();
        long b = sc.nextLong();
        long k = sc.nextLong();
        sc.close();

        long[] comb = new long[(int)n+1];

        comb[0] = 1;
        for(int i=0; i<n; i++){
            comb[i+1] = comb[i] * (n-i);
            if(comb[i+1] > DIV) comb[i+1] = comb[i+1] % DIV;
            comb[i+1] = comb[i+1] * modinv(i+1, DIV);
            if(comb[i+1] > DIV) comb[i+1] = comb[i+1] % DIV;
        }

        long ans = 0;

        for(int i=0; i<=n; i++){
            if((k-a*i) % b != 0) continue;

            long tmp = (k-a*i) / b;
            if(tmp > n || tmp < 0) continue;
            int bi = (int)tmp;
            ans += comb[i] * comb[bi];
            if(ans >= DIV) ans = ans % DIV;
        }

        System.out.println(ans);
    }

    public static long modinv(long a, long n){
        long b = n, u=1, v=0;
        while(b > 0) {
            long t = a/b;
            a -= t*b;
            u -= t*v;
            t = a;
            a = b;
            b = t;
            t = u;
            u = v;
            v = t;
        }
        u = u % n;
        if(u < 0) u += n;
        return u;
    }
}

import java.util.Scanner;

public class Main {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    int N = Integer.parseInt(sc.next());
    long A = Long.parseLong(sc.next());
    long B = Long.parseLong(sc.next());
    long K = Long.parseLong(sc.next());

    final long p = 998244353;

    combination nC = new combination(N, p);

    long ans = 0;
    long b = 0;
    for (int a = 0; a <= N; a++) {
      b = (K - A * a) / B;
      if (A * a > K) {
        break;
      } else if ((K - A * a) % B != 0 || b > (long) N) {
        continue;
      } else {
        ans = (nC.C(a, p) * nC.C((int) b, p)) % p;
      }
    }
    System.out.println(ans % p);
  }

  static class combination {
    public int n;
    public long nfact;
    public long reverceTable[];

    public combination(int n, long p) {
      this.n = n;
      reverceTable = new long[n + 1];
      reverceTable[0] = 1;
      nfact = 1;
      for (int i = 1; i < n + 1; i++) {
        nfact = nfact * i % p;
      }
      long sum = 1;
      long x = nfact;
      long m = p - 2;
      while (m > 0) {
        if ((m & 1) == 1) {
          sum = sum * x % p;
        }
        x = x * x % p;
        m >>= 1;
      }
      reverceTable[n] = sum;
      for (int i = n - 1; i > 0; i--) {
        reverceTable[i] = reverceTable[i + 1] * (i + 1) % p;
      }
    }

    public long C(int r, long p) {
      if (r < 0 || r > n) {
        return 0;
      } else {
        return (nfact * reverceTable[r] % p) * reverceTable[n - r] % p;
      }
    }
  }
}

