class Main {
    public static long comb(long a, long b, long mod, long[] pw, long[] ipw) {
        return (((pw[(int)a] * ipw[(int)a - (int)b]) % mod ) * ipw[(int)b]) % mod;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int max = 400000;
        int mod = 998244353;
        long[] pw  = new long[max];
