        long[] ipw = new long[max];
        BigInteger modb = new BigInteger(String.valueOf(mod));

        for(int i = 1; i < max; i++) {
            pw[i] = (i * pw[i-1]) % mod;
        }
        for(int i = 0; i < max; i++) {
