public class Main {

    // global
    static long fact[];
    static long inverse[];
    static int mod = 998244353;

    static long pow(long a,int n) {
        long res=1;
        while (n>0) {
            if ((n-n/2*2)==1) {
                res=res*a%mod;
            }
            a=a*a%mod;
            n>>=1;
        }
        return res;
    }

    static long modinv(long n) {
        return pow(n, mod-2);
    }

    static long comb(int n,int k){
        if(n<0 || k<0 || n<k)return 0;
        return fact[n]*(inverse[k]*inverse[n-k]%mod) %mod;
    }

    static long gcd(long a,long b) {
        long temp;
        while ((temp=a%b)!=0) {
            a=b;
            b=temp;
        }
        return b;
    }

    public static void main(String[] args) {

        // main method
        fact=new long[2000000];
        fact[0]=1;
        inverse=new long[2000000];
        inverse[0]=1;
        for(int i=1;i<2000000;i++){
            fact[i]=(fact[i-1]*(long)i)%mod;
            inverse[i]=modinv(fact[i]);
        }

        Scanner sc = new Scanner(System.in);
        long N = Long.parseLong(sc.next());
        long A = Long.parseLong(sc.next());
        long B = Long.parseLong(sc.next());
        long K = Long.parseLong(sc.next());

        // divide by gcd(A, B)
        long gcd = gcd(A, B);
        if (K%gcd!=0) {
            System.out.println(0);
            return;
        }
        A/=gcd;
        B/=gcd;
        K/=gcd;

        // solve Ax+By=K
        ArrayList<ArrayList<Long>> list = new ArrayList<ArrayList<Long>>();
        for (int i=0;i<=N;i++) {
            if ((K-A*i)%B==0) {
                long j = (K-A*i)/B;
                if (0<=j && j<=N) {
                    ArrayList<Long> add = new ArrayList<Long>();
                    add.add((long)i);
                    add.add(j);
                    list.add(add);
                }
            }
        }

        long ans = 0L;
        for (int i=0;i<list.size();i++) {
            long x = list.get(i).get(0);
            long y = list.get(i).get(1);
            long min = Math.min(x, y);
            for (int j=(int)min;j>=0;j--) {
                int green = j;
                int red = (int)x-j;
                int blue = (int)y-j;
                if (x+y-j>N) break;
                ans = (ans + ((((fact[(int)N]*inverse[green])%mod*inverse[red])%mod*inverse[blue])%mod*inverse[(int)N-green-red-blue])%mod)%mod;
            }
        }
        // System.out.println(list);
        System.out.println(ans);
    }
}

