public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BRGBColoring solver = new BRGBColoring();
        solver.solve(1, in, out);
        out.close();
    }

    static class BRGBColoring {
        static final int MOD = 998244353;

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            long a = in.nextInt(), b = in.nextInt();
            long k = in.nextLong();

            long count = 0;
            int y = n;
            for (int x = 0; x <= n; x++) {
                long val;
                while ((val = (a * x) + (b * y)) > k) {
                    y--;
                }
                if (y < 0) {
                    break;
                }
                if (val != k) {
                    continue;
                }
                count += (nCk(n, x) * nCk(n, y) % MOD);
            }
            out.println(count);
        }

        public long modPow(long x, long y) {

            if (y == 0) {
                return 1;
            } else if (y == 1) {
                return x;
            } else if (y % 2 == 0) {
                long z = modPow(x, y / 2);
                return z * z % MOD;
            } else {
                return (modPow(x, y - 1) * x) % MOD;
            }
        }

        public long nCk(int n, int k) {
            long a = 1;
            for (int i = 0; i < k; i++) {
                a *= (n - i);
                a %= MOD;
            }

            long b = 1;
            for (int i = k; i >= 2; i--) {
                b *= i;
                b %= MOD;
            }
            return (a * modPow(b, MOD - 2) % MOD) % MOD;
        }

    }
}

