public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        long dx;
        long dy;
        long MOD = 998244353;
        long[] f;
        long[] fi;

        private void initFactorials(int N) {
            int MAX = N;
            f = new long[MAX + 1];
            f[0] = 1;
            for (int i = 1; i <= MAX; i++) {
                f[i] = (f[i - 1] * i) % MOD;
            }

            //lets find fi[p]
            //p*X === 1 % MOD;
            fi = new long[MAX + 1];

            long x[] = new long[1];
            long y[] = new long[1];
            long g = gcd(f[MAX], MOD, x, y);
            if (g != 1) {
                throw new RuntimeException("Impossible");
            }
            fi[MAX] = (x[0] % MOD + MOD) % MOD;
            for (int i = MAX - 1; i >= 0; i--) {
                fi[i] = (fi[i + 1] * (i + 1)) % MOD; // (i-1)!^-1 == i!^-1 * i
            }
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int A = in.nextInt();
            int B = in.nextInt();
            long K = in.nextLong();
            long AB = A + B;

            // G = x*A + y*B;
            initFactorials(N);
            dx = dy = 0;

            long G = gcd(A, B);
            if (K % G != 0) {
                out.println(0);
                return;
            }

            long[] XA = new long[1];
            long[] YY = new long[1];


            gcd(A, B, XA, YY);

            long x1 = XA[0] * (K / G);
            long y1 = YY[0] * (K / G);

            long rs1 = G * (x1 - K) / B;
            long re1 = x1 * G / B;

            long rs2 = -1L * y1 * G / A;
            long re2 = G * (K - y1) / A;

            long rs = Math.max(rs1, rs2);
            long re = Math.min(re1, re2);

            if (rs > re) {
                out.println(0);
                return;
            }

            long ans = 0;

            for (long r = rs; r <= re; r++) {
                long x = x1 - r * B / G;
                long y = y1 + r * A / G;

                ans = add(ans, ways(N, K, A, B, x, y));
            }

            out.println(ans);

        }

        private long C(int n, int k) {
            return f[n] * fi[n - k] % MOD * fi[k] % MOD;
        }

        private long ways(int N, long K, int A, int B, long X, long Y) {
            long ans = 0;

            for (long c = 0; c <= N; c++) {
                long a = X - c;
                long b = Y - c;

                if (a >= 0 && b >= 0) {
                    long w = ways(N, a) * ways(N - a, b) % MOD * ways(N - a - b, c) % MOD;
                    ans = add(ans, w);
                }
            }
            return ans;
        }

        private long ways(long N, long K) {
            if (N < K) return 0L;
            return C((int) N, (int) K);
        }

        private long add(long A, long B) {
            return (A + B) % MOD;
        }

        private long gcd(long a, long b) {
            if (b == 0) return a;
            return gcd(b, a % b);
        }

        private long gcd(long a, long b, long x[], long y[]) {
            if (a == 0) {
                x[0] = 0;
                y[0] = 1;
                return b;
            }
            long x1[] = new long[1];
            long y1[] = new long[1];

            long d = gcd(b % a, a, x1, y1);
            x[0] = y1[0] - (b / a) * x1[0];
            y[0] = x1[0];
            return d;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {

    long q[] = new long[N+1];
    long invq[] = new long[N+1];
    long MAGIC = 998244353;
    q[0] = 1;
    invq[0] = 1;
    for (int i=1; i<=N; i++) {
      q[i] = q[i-1] * i % MAGIC;
      invq[i] = inv(q[i], MAGIC);
      if (invq[i] == 0) {
        throw new RuntimeException("zero inv: " + q[i]);
      }
    }

    long ans = 0;

    for (int numA=0; numA<=N; numA++) {
      long remain = K - (A*numA);
      if (remain >= 0 && remain % B == 0) {
        int numB = (int) (remain / B);
        if (numB <= N) {
          long tmp1 = q[N]*invq[numA]%MAGIC*invq[N-numA]%MAGIC;
          long tmp2 = q[N]*invq[numB]%MAGIC*invq[N-numB]%MAGIC;
          long tmp = tmp1*tmp2%MAGIC;
          ans = ans + tmp;
        }
      }
    }
    System.out.println(ans % MAGIC);
  }

  private static long inv(long a, long MOD) {
    long x0 = 1, x1 = 0;
    long y0 = 0, y1 = 1;
    long b = MOD;
    while (b != 0) {
      long q = a / b;
      long r = a % b;
      long x2 = x0 - q * x1;
      long y2 = y0 - q * y1;
      a = b;
      b = r;
      x0 = x1;
      x1 = x2;
      y0 = y1;
      y1 = y2;
    }
    return (MOD+x0%MOD)%MOD;
  }
}

import java.io.*;
import java.util.*;

public class Main {

    private static FastReader in = new FastReader(System.in);
    private static PrintWriter out = new PrintWriter(System.out);

    // private static final long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        solve();
        out.flush();
    }

    private static void solve() {
        long n = in.nextLong();
        long a = in.nextLong();
        long b = in.nextLong();
        long k = in.nextLong();

        ModCalculator calc = new ModCalculator(998244353L);
        calc.populate((int) n);

        long ans = 0;
        for (int reds = 0; reds <= n; reds++) {
            if ((k - reds * a) % b != 0) {
                continue;
            }
            long blues = (k - reds * a) / b;
            if (blues > n || blues < 0) {
                continue;
            }

            ans = calc.add(ans, calc.multiply(
                    calc.combination((int) n, reds),
                    calc.combination((int) n, (int) blues)
            ));
        }

        out.println(ans);
    }

    private static class ModCalculator {
        private final long mod;

        // factorial in mod
        // factMod[1] = 1, factMod[2] = 2, ...
        private List<Long> factorial;
        // inverse factorial in mod
        private List<Long> inverseFactorial;

        ModCalculator(long mod) {
            this.mod = mod;
            factorial = new ArrayList<>();
            inverseFactorial = new ArrayList<>();
            factorial.add(1L);
            inverseFactorial.add(1L);
        }

        /**
         * Quickly populate factorial and inverse factorial up to n
         */
        private void populate(int n) {
            // i == next index
            int start = factorial.size();
            for (int i = start; i <= n; i++) {
                factorial.add(
                        multiply(factorial.get(i - 1), i)
                );
                // temporarily add
                inverseFactorial.add(0L);
            }
            // avoid inverse calculation by filling inverseFactorial in the inverse direction
            inverseFactorial.set(n, inverse(factorial.get(n)));
            for (int i = n; i > start; i--) {
                inverseFactorial.set(i - 1, multiply(inverseFactorial.get(i), i));
            }
        }

        // a + b (mod m)
        long add(long a, long b) {
            return (a + b) % mod;
        }

        // a - b (mod m)
        long subtract(long a, long b) {
            return add(add(a, -b), mod);
        }

        // a * b (mod m)
        long multiply(long a, long b) {
            return (a * b) % mod;
        }

        // x^-1 (mod m)
        long inverse(long x) {
            return power(x, mod - 2);
        }

        // x^n (mod m)
        long power(long x, long n) {
            long ans = 1;
            while (n != 0) {
                if ((n & 1) == 1L) ans = multiply(ans, x);
                x = multiply(x, x);
                n = n >> 1;
            }
            return ans;
        }

        /**
         * Calculates factorial value in mod.
         */
        long factorial(int n) {
            populate(n);
            return factorial.get(n);
        }

        /**
         * Calculates inverse factorial value in mod.
         */
        long inverseFactorial(int n) {
            populate(n);
            return inverseFactorial.get(n);
        }

        /**
         * Calculates combination value in mod.
         * <br>a.k.a
         * <br>aCb
         * <br> = n! / (n - r)! r!
         */
        long combination(int n, int r) {
            if (n == 0 && r == 0) return 1;
            if (n < r || n < 0) return 0;

            populate(n);
            return multiply(factorial.get(n), multiply(inverseFactorial.get(n - r), inverseFactorial.get(r)));
        }

        /**
         * Calculates multi-choose, or combination with repetition in mod.
         * <br>a.k.a
         * <br>nHr
         */
        long multiChoose(int n, int r) {
            return combination(n + r - 1, r);
        }

        /**
         * Calculates permutation value in mod.
         * <br>a.k.a
         * <br>aPb
         * <br> = n! / (n - r)!
         */
        long permutation(int n, int r) {
            if (n == 0 && r == 0) return 0;
            if (n < r || n < 0) return 0;

            populate(n);
            return multiply(factorial.get(n), inverseFactorial.get(n - r));
        }
    }


    // https://www.geeksforgeeks.org/fast-io-in-java-in-competitive-programming/
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream inputStream) {
            br = new BufferedReader(new
                    InputStreamReader(inputStream));
        }

        String next() {
