import java.util.Scanner;

public class Main {

  private static final long MOD = 998244353;
  private static long FACT[];
  private static long IFACT[];

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int A = sc.nextInt();
    int B = sc.nextInt();
    long K = sc.nextLong();
    solve(N, A, B, K);
  }

  private static void solve(int N, int A, int B, long K) {

    FACT = new long[N+1];
    IFACT = new long[N+1];
    FACT[0] = 1;
    IFACT[0] = 1;
    for (int i=1; i<=N; i++) {
      FACT[i] = FACT[i-1] * i % MOD;
      IFACT[i] = inv(FACT[i]);
    }

    long ans = 0;

    for (int numA=0; numA<=N; numA++) {
      long numB = (K - (A*numA))/B;
      if (numB <= N && (A*numA + B*numB) == K) {
        // System.out.println("numA: " + numA + "numB: " + numB);
        ans += (comb(N, numA) * comb(N, (int)numB))%MOD;
        ans %= MOD;
      }
    }
    System.out.println(ans);
  }

  private static long comb(int n, int r) {
    if (n < 0 || r < 0 || n < r) {
      return 0;
    }
    if (r > n/2) {
      r = n - r;
    }
    return FACT[n]*IFACT[n-r]%MOD*IFACT[r]%MOD;
  }

  private static long inv(long a) {
    long x0 = 1, x1 = 0;
    long y0 = 0, y1 = 1;
    long b = MOD;
    while (b != 0) {
      long q = a / b;
      long r = a % b;
      long x2 = x0 - q * x1;
      long y2 = y0 - q * y1;
      a = b;
      b = r;
      x0 = x1;
      x1 = x2;
      y0 = y1;
      y1 = y2;
    }
    return (MOD+x0%MOD)%MOD;
  }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static int N,A,B;
    static long K;
    static final int MOD = 998244353;
    static List<Long> fac;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        A = sc.nextInt();
        B = sc.nextInt();
        K = sc.nextLong();

        fac = new ArrayList<>();
        fac.add(1L);
        for (int n=1; n<N+10; n++) {
            long f = mul(fac.get(n-1),n);
            fac.add(f);
        }

        long ans = 0;
        for (int a = 0; a <= N; a++) {
            if(a*A > K) break;
            long rem = K-a*A;
            if(rem%B > 0) continue;
            int b = (int)(rem/B);
            for (int green = 0; green <= Math.min(a,b); green++) {
                int red = a - green;
                int blue = b - green;
                if(red + green + blue > N) continue;
                long tmp = 1;
                tmp = mul(tmp, ncr(N, red+green+blue));
                tmp = mul(tmp, ncr(red+green+blue, green+blue));
                tmp = mul(tmp, ncr(green+blue, blue));
                ans += tmp;
            }
        }
        System.out.println(ans % MOD);
    }

    static long mul(long a, long b) {
        return (a*b) % MOD;
    }
    static long pow(long a, long n) {
        long ret = 1;
        long mag = a;
        while(n > 0) {
            if(n%2 == 1) {
                ret = mul(ret,mag);
            }
            mag = mul(mag, mag);
            n >>= 1;
        }
        return ret;
    }
    static long inv(long a) {
        return pow(a, MOD-2);
    }
    static long ncr(int n, int r) {
        return mul(mul(fac.get(n), inv(fac.get(n-r))), inv(fac.get(r)));
    }
}

