		for (long r = 0; r < n; r++) {
			long bb = k - r * a;
			if (bb >= 0 && bb % b == 0 && bb / b < n ) {
//				System.out.println(" "+r+" "+bb/b);
				res += pat((int)r, (int) (bb / b)) % MOD;
				res = res % MOD;
			}
		}

		System.out.println(res);

	}

	int[] m = new int[312345];

	void p2(int x) {

		for (int i = 1; i < x; i++) {
			m[i] = m[i - 1] * i % MOD;
		}

	}

	long div(long a, long b){
	    return (((a%MOD) * ( pow(b, MOD-2)))%MOD);
	}

	long pow(long x, long y) {
