			return 1;
		}
		if (y == 1) {
			return x % MOD;
		}
		if (y % 2 == 0) {
			long p2 = pow(x, y / 2)  % MOD;
			return (p2*p2 %MOD);
		}
		long p2 = pow(x, y / 2)  % MOD;
		return ((((p2*p2)%MOD) * x) % MOD);
	}

