public class Program
{
    private int N;
    private long A, B, K;

    private ModInt[] C;
    private ModInt[] F;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.NextLong();
        B = sc.NextLong();
        K = sc.NextLong();

        F = new ModInt[N + 1];
        F[0] = 1;
        for (int i = 1; i <= N; i++)
        {
            F[i] = F[i - 1] * i;
        }

        // N個中k個塗るパターン
        // NCk

        C = new ModInt[N + 1];
        for (int k = 0; k <= N; k++)
        {
            C[k] = F[N] * ModInt.Inverse(F[k] * F[N - k]);
        }

        ModInt ans = 0;
        for (int a = 0; a <= N; a++)
        {
            // A点追加がa個

            // B点追加はいくつ?
            int ok = N + 1;
            int ng = -1;
            while (ok - ng > 1)
            {
                int mid = (ok + ng) / 2;
                if (A * a + mid * B >= K) ok = mid;
                else ng = mid;
            }

            if (ok > N) continue;
            if (A * a + ok * B != K) continue;
            ans += C[a] * C[ok];
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}


