static class Program{
	const int mod=998244353;
	static long[] s,r;
	static long ans=0;
	static void Main(){
		Sc sc=new Sc();
		s=sc.La;
		r=new long[s[0]+1];
		r[0]=1;
		for(int i = 1;i<=s[0];i++) {r[i]=(r[i-1]*i)%mod;}
		for(int i = 0;i<=s[0];i++) {
			if(s[1]*i<=s[3]&&(s[3]-s[1]*i)%s[2]==0&&(s[3]-s[1]*i)/s[2]<=s[3]){
				int q=(int)((s[3]-s[1]*i)/s[2]);
				ans+=(((r[s[0]]*Mi(r[i]*r[s[0]-i]))%mod)*((r[s[0]]*Mi(r[q]*r[s[0]-q]))%mod))%mod;
			}
		}
		Console.WriteLine(ans);
	}
	static long Mi(long a){
		long b=mod,u=1,v=0;
		while(b>0){
			long t=a/b;
			a-=t*b;a^=b;b^=a;a^=b;
			u-=t*v;u^=v;v^=u;u^=v;
		}
		u%=mod;
		if(u<0){u+=mod;}
		return u%mod;
	}
}

