namespace ExpressionQiita
{
    class Program
    {
        static void Main(string[] args)
        {
            var inAry = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
            // タワーの高さ
            var N = inAry[0];
            // 赤点
            var A = inAry[1];
            // 青点
            var B = inAry[2];
            // 合計点
            var K = inAry[3];

            const long wari = 998244353;

            var listtup = new List<long[]>();

            for (int i = 0; i <= N; i++)
            {
                for (int k = 0; k <= N; k++)
                {
                    if (i + k > N)
                    {
                        break;
                    }
                    if ((A-B)*i + B * N + A * k >= K)
                    {
                        var ary = new long[] { i, k};
                        listtup.Add(ary);
                    }
                }
            }

            var listtup2 = new List<long[]>();

            foreach(var x in listtup)
            {
                for(int j = 0; j <= N; j++)
                {
                    if (N-x[0]-x[1] >= j)
                    {
                        if(A * x[0] + B * j + (A + B) * x[1] == K)
                        {
                            var ary = new long[] { x[0], j, x[1] };
                            listtup2.Add(ary);
                        }
                    }
                    else
                    {
                        break;
                    }
                }
            }


            long sum = listtup2.Sum(x => Factorial(N) / (Factorial(x[0]) * Factorial(x[1]) * Factorial(x[2]) * Factorial(N - x[0] - x[1] - x[2])));

            Console.WriteLine(sum % wari);
            Console.ReadLine();
        }

        public static long Factorial(long n)
        {
            if (n == 0)
                return 1;
            return n * Factorial(n - 1);
        }
    }
}

