    class MyMath
    {
        public static long Pow(long a, long b)
        {
            long res = 1;
            while (b > 0)
            {
                if (b % 2 == 1)
                {
                    res *= a;
                    res %= Mod;
                }

                a *= a;
                a %= Mod;
                b /= 2;
            }

            return res;
        }

        private const long Mod = 998244353;

        static MyMath()
        {
            _factorial = new long[500001];
            _factorial[0] = 1;
            for (int i = 1; i <= 500000; i++)
            {
                _factorial[i] = (_factorial[i - 1] * i) % Mod;
            }
        }

        private static long[] _factorial;



        private static long Factorial(long n)
        {
            return _factorial[n];
        }

        public static long Combination(long n, long m)
        {
            long bunsi = _factorial[n];
            long bunbo = (_factorial[m] * _factorial[n - m]) % Mod;
            long gyakugen = Pow(bunbo, Mod - 2);
            return (bunsi * gyakugen) % Mod;
        }
    }

    class Program
    {
        private int N, A, B;
        private long K;
        private const long Mod = 998244353;
        private void Scan()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            A = sc.NextInt();
            B = sc.NextInt();
            K = sc.NextLong();
        }

        public void Solve()
        {
            Scan();
            long ans = 0;
            for (int r = 0; r <= N; r++)
            {
                long bb = K - (long)r * A;
                long b;
                if (bb < 0) continue;
                if (bb % B == 0)
                {
                    b = bb / B;
                }
                else
                {
                    continue;
                }
                ans += MyMath.Combination(N, r) * MyMath.Combination(N, b);
                ans %= Mod;

            }
            Console.WriteLine(ans);
        }

        static void Main() => new Program().Solve();
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{
	static void Main()
	{
	 string[] input = Console.ReadLine().Split(' ');
	 long n = long.Parse(input[0]);
	 long a = long.Parse(input[1]);
   long b = long.Parse(input[2]);
	 long k = long.Parse(input[3]);
   long p = 998244353;
   long answer = 0;
   long memoB = 0;

   for(long i = 0; i < n; i++)
   {
      if((k-a*i)%b != 0) continue;//aに対するbが存在しないとき
      else
      {
        memoB = (k-a*i)/b;
        long memo = Comb(n, i, p);
        memo *= Comb(n, memoB, p);
        memo %= p;
        answer += memo;
        answer %= p;
      }
   }

	 Console.WriteLine(answer);
	}

  static long DivideMod(long x, long a, long p)//戻り値はx^a(mod p)
  {
    long num = 2;
    long answer = 1;
    long check = a;
    long memo = x%p;

    while(check > 0)
    {
      if(check % num == num / 2)
      {
        check -= num / 2;
        answer *= memo;
        answer %= p;
      }
    memo *= memo;
    memo %= p;
    num *= 2;
    }
    return answer;
  }

  static long DivideModReverse(long x, long p)//戻り値はx^-1(mod p), pは素数
  {
    long answer = DivideMod(x, p-2, p);
    return answer;
  }

  static long DivideModFactorial(long x, long p)//戻り値はx!^-1(mod p), pは素数
  {
    long answer = 1;
    for(long i = x; i >= 2; i--)
    {
      answer *= DivideModReverse(i, p);
      answer %= p;
    }
    return answer;
  }

  static long Comb(long a, long b, long p)//戻り値は組み合わせC(a,b)のmod p
  {
    long answer = 1;
    for(long i = a; i > a-b; i--)
    {
      answer *= i;
      answer %= p;
    }
    answer *= DivideModFactorial(b, p);
    answer %= p;
    return answer;
  }

}

