using System;
class Program
{
    static void Main(string[] args)
    {
        var line = Console.ReadLine().Split(' ');
        var N = long.Parse(line[0]);
        var A = long.Parse(line[1]);
        var B = long.Parse(line[2]);
        var K = long.Parse(line[3]);
        long sum = 0;
        for (int r = 0; r <= N; r++)
        {
            for (int b = 0; r + b <= N; b++)
            {
                if (r * A + b * B == K)
                {
                    sum += (Comb(N, r) * Comb(N, b)) % 998244353;
                }
            }
        }
        Console.WriteLine(sum % 998244353);
    }
    static long Comb(long i1, long i2)
    {
        long res = 1;
        for(long i=i1;i>i2;i--){
            res *= i;
        }
        for(long i=i1-i2;i>0;i--){
            res /= i;
        }
        return res;
    }
}

