    public class Combination
    {
        readonly ModInt[] facts;
        readonly ModInt[] invs;

        public Combination(int max)
        {
            facts = new ModInt[max + 1];
            facts[0] = 1;
            for (var i = 1; i <= max; i++) facts[i] = facts[i - 1] * i;

            invs = new ModInt[max + 1];
            invs[max] = facts[max].Inverse;
            for (var i = max - 1; i >= 0; i--) invs[i] = invs[i + 1] * (i + 1);
        }

        public ModInt NCK(int n, int k)
        {
            if (n < k) return 0;
            return facts[n] * invs[k] * invs[n - k];
        }
    }

    public struct ModInt
    {
        public static int Mod = 1000000007;

        readonly long value;
        public int Value { get { return (int)value; } }
        public ModInt Inverse { get { return GetInverse(); } }

        public ModInt(long value)
        {
            value %= Mod;
            this.value = value < 0 ? value + Mod : value;
        }

        ModInt GetInverse()
        {
            int x, y;
            if (MathX.GcdEx(Value, Mod, out x, out y) != 1)
            {
                throw new InvalidOperationException("'Value' and 'Mod' must be disjoint.");
            }
            return x;
        }

        public ModInt Square()
        {
            return this * this;
        }

        public ModInt Pow(long exp)
        {
            if (exp == 0) return 1;
            if (exp % 2 == 0) return Pow(exp / 2).Square();
            return this * Pow(exp - 1);
        }

        public static ModInt Parse(string str)
        {
            return long.Parse(str);
        }

        public static implicit operator ModInt(long value)
        {
            return new ModInt(value);
        }

        public static ModInt operator +(ModInt left, ModInt right)
        {
            return left.value + right.value;
        }

        public static ModInt operator -(ModInt left, ModInt right)
        {
            return left.value - right.value;
        }

        public static ModInt operator *(ModInt left, ModInt right)
        {
            return left.value * right.value;
        }

        public static ModInt operator /(ModInt left, ModInt right)
        {
            return left * right.Inverse;
        }

        public override bool Equals(object obj)
        {
            if (!(obj is ModInt)) return false;
            return value == ((ModInt)obj).value;
        }

        public override int GetHashCode()
        {
            return value.GetHashCode();
        }

        public override string ToString()
        {
            return value.ToString();
        }
    }

    public class StreamScanner
    {
        static readonly char[] Sep = {' '};
        readonly Queue<string> buffer = new Queue<string>();
        readonly TextReader textReader;

        public StreamScanner(TextReader textReader)
        {
            this.textReader = textReader;
        }

        public T Next<T>(Func<string, T> parser)
        {
            if (buffer.Count != 0) return parser(buffer.Dequeue());
            var nextStrings = textReader.ReadLine().Split(Sep, StringSplitOptions.RemoveEmptyEntries);
            foreach (var nextString in nextStrings) buffer.Enqueue(nextString);
            return Next(parser);
        }

        public T[] Next<T>(Func<string, T> parser, int x)
        {
            var ret = new T[x];
            for (var i = 0; i < x; ++i) ret[i] = Next(parser);
            return ret;
        }

        public T[][] Next<T>(Func<string, T> parser, int x, int y)
        {
            var ret = new T[y][];
            for (var i = 0; i < y; ++i) ret[i] = Next(parser, x);
            return ret;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class Combination
{
    private readonly long[] Fact;
    private readonly long[] InvFact;  // モジュラ逆数
    private readonly long Mod;

    public Combination(long n, long mod)
    {
        Mod = mod;
        Fact = new long[n + 1];
        InvFact = new long[n + 1];

        long f = 1;
        Fact[0] = f;
        for (long i = 1; i <= n; i++)
        {
            f *= i;
            f %= mod;
            Fact[i] = f;
        }

        // フェルマーの小定理 a^(-1) = a^(mod-2)
        long inv = Power(f, mod - 2, mod);

        InvFact[n] = inv;
        for (long i = n - 1; i >= 0; i--)
        {
            InvFact[i] = (InvFact[i + 1] * (i + 1)) % mod;
        }
    }

    public long GetCombination(long n, long r)
    {
        var comb = (Fact[n] * InvFact[r]) % Mod;
        comb = (comb * InvFact[n - r]) % Mod;
        return comb;
    }

    // x^n
    static long Power(long x, long n, long mod)
    {
        long pow = 1;
        while (n > 0)
        {
            if (n % 2 == 0)
            {
                x *= x;
                x %= mod;
                n /= 2;
            }
            else
            {
                pow *= x;
                pow %= mod;
                n--;
            }
        }

        return pow;
    }
}

class Solution
{

    static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
        var n = vals[0];
        var a = vals[1];
        var b = vals[2];
        var k = vals[3];

        const long mod = 998244353;
        var comb = new Combination(n, mod);

        long pattern = 0;
        for (int an = 0; an <= n; an++)
        {
            var bk = k - a * an;
            if (bk < 0)
            {
                break;
            }
            if (bk % b == 0)
            {
                var bn = bk / b;
                if (bn <= n)
                {
                    pattern += (comb.GetCombination(n, an) * comb.GetCombination(n, bn)) % mod;
                    pattern %= mod;
                }
            }
        }

        Console.WriteLine(pattern);
    }
}

