                for (int i = 1; i < fact.Count(); i++) fact[i] = fact[i - 1] * i % mod;
                long mintimes = 0;
                mintimes = Math.Max(mintimes, (0 - a + (small / gcd - 1)) / (small / gcd));
                mintimes = Math.Max(mintimes, (b - x[0] + (big / gcd - 1)) / (big / gcd));
                a += (small / gcd) * mintimes;
                b -= (big / gcd) * mintimes;
                long ret = 0;
                while (0 <= a && a <= x[0] &&
                       0 <= b && b <= x[0])
                {
                    ret += combination(x[0], a) * combination(x[0], b) % mod;
                    ret %= mod;
                    a += small / gcd; b -= big / gcd;
                }
                if (x[3] == 0) ret++;
