class Comb
{
    long n;
    int mod;
    long[] fac;
    long[] finv;
    long[] inv;
    public Comb(long n, int mod)
    {
        this.n = n;
        this.mod = mod;

        fac = new long[n + 1];
        finv = new long[n + 1];
        inv = new long[n + 1];
        fac[0] = 1;
        fac[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i <= n; i++)
        {
            inv[i] = mod - inv[mod % i] * (mod / i) % mod;
            fac[i] = fac[i - 1] * i % mod;
            finv[i] = finv[i - 1] * inv[i] % mod;
        }
    }
    public long comb(int i)
    {
        return fac[n] * (finv[i] * finv[n - i] % mod) % mod;
    }
}
