namespace agc025_b
{
    class Program
    {
        static long gcd = 0;
        static long[] exgcd(long x, long y)
        {
            long r0 = x, r1 = y;
            long a0 = 1, a1 = 0;
            long b0 = 0, b1 = 1;
            while (r1 > 0)
            {
                long q1 = r0 / r1;
                long r2 = r0 % r1;
                long a2 = a0 - q1 * a1;
                long b2 = b0 - q1 * b1;
                r0 = r1; r1 = r2;
                a0 = a1; a1 = a2;
                b0 = b1; b1 = b2;
            }
            gcd = r0;
            return new long[] { a0, b0 };
        }
        const long mod = 998244353;
        public static long calc(long x, long pow)
        {
            if (pow == 0) return 1;
            long a = calc(x, pow / 2);
            a = a * a % mod;
            if (pow % 2 == 1) a *= x;
            return a % mod;
        }
        static long[] fact;
        public static long combination(long n, long r)
        {
            return fact[n] * calc((fact[r] * fact[n - r]) % mod, mod - 2) % mod;
        }
        static void Main(string[] args)
        {
            long[] x = Console.ReadLine().Split().Select(long.Parse).ToArray();
            long big = Math.Max(x[1], x[2]), small = Math.Min(x[1], x[2]);
            long[] y = exgcd(big, small);
            if (x[3] % gcd != 0) Console.WriteLine(x[3] == 0 ? 1 : 0);
            else
            {
                long a = y[0] * (x[3] / gcd), b = y[1] * (x[3] / gcd);
                fact = new long[x[0] + 100];
                fact[0] = 1;
                for (int i = 1; i < fact.Count(); i++) fact[i] = fact[i - 1] * i % mod;
                long mintimes = 0;
                mintimes = Math.Max(mintimes, (0 - a + (small / gcd - 1)) / (small / gcd));
                mintimes = Math.Max(mintimes, (b - x[0] + (big / gcd - 1)) / (big / gcd));
                a += (small / gcd) * mintimes;
                b -= (big / gcd) * mintimes;
                long ret = 0;
                while (0 < a && a <= x[0] &&
                       0 < b && b <= x[0])
                {
                    ret += combination(x[0], a) * combination(x[0], b) % mod;
                    ret %= mod;
                    a += small / gcd; b -= big / gcd;
                }
                if (x[3] == 0) ret++;
                Console.WriteLine(ret);
            }
        }
    }
