class P
{
    const int mod = 998244353;
    static void Main()
    {
        checked
        {
            long[] nabk = Console.ReadLine().Split().Select(long.Parse).ToArray();
            int n = (int)nabk[0];
            int a = (int)Max(nabk[1], nabk[2]);
            int b = (int)Min(nabk[1], nabk[2]);
            long k = nabk[3];
            //n個縦一列
            //赤緑青で塗る
            //ブロックの和

            //得点lを構成するようなa,bの組を列挙し、それぞれの個数を引っ張り出す

            //a,bがあって、Max(0,n-(a+b))個重複からMin(a,b)個重複までそれぞれの場合の数
            //並び替えの場合の数は、n!/r!*g!*b!*w!
            //0!~n!までを前計算
            long[] pows = new long[n + 1];
            pows[0] = 1;
            for (int i = 1; i < pows.Length; i++)
            {
                pows[i] = (pows[i - 1] * i) % mod;
            }

            long acount = 0;
            long bcount = 0;

            long ab = (long)a * b;

            for (long i = 0; i < a; i++)
            {
                if ((k - (b * i)) % a == 0)
                {
                    acount = ((k - (b * i)) / a);
                    bcount = i;
                }
            }

            if (acount >= n)
            {
                long minus = (acount - n) / b + ((acount - n) % b != 0 ? 1 : 0);
                acount -= b * minus;
                bcount += a * minus;
            }

            long count = 0;
            while (true)
            {
                long max = Min(n, Min(acount, bcount));
                for (long j = Min(int.MaxValue, Max(0, acount + bcount - n)); j <= max; j++)
                {
                    int den = (int)((((pows[(acount - j)] * pows[(bcount - j)]) % mod) * ((pows[n - (acount + bcount - j)] * pows[j]) % mod)) % mod);
                    count = ((count + (pows[n] * power(den, mod - 2))) % mod);
                }
                acount -= b;
                bcount += a;
                if (acount < 0 || bcount > n) break;
            }
            Console.WriteLine(count);
        }
    }



    static int combination(int n, int r)
    {
        long res = 1;
        long den = 1;
        for (int i = 1; i <= n; i++)
        {
            res = (res * i) % mod;
            if (i == n - r || i == r)
            {
                den = (den * res) % mod;
                if (n - r == r) den = (den * res) % mod;
            }
        }
        long rev = power((int)den, mod - 2);
        return (int)((res * rev) % mod);
    }

    static int power(int n, int m)
    {
        long pow = n;
        long res = 1;
        while (m > 0)
        {
            if ((m & 1) == 1) res = (res * pow) % mod;
            pow = (pow * pow) % mod;
            m >>= 1;
        }
        return (int)res;
    }
}

