class Solver
{
    public void Solve(Scanner sc)
    {
        int N;long A, B, K;
        sc.Make(out N, out A, out B, out K);
        ModInt.Build(N);
        ModInt res = 0;
        for(int i = 0; i <= N; i++)
        {
            if (i * A > K) break;
            var d = K - i * A;
            if (d % B != 0) continue;
            d /= B;
            res += ModInt.Comb(N, i) * ModInt.Comb(N, d);
        }
        WriteLine(res);
    }
