namespace ExpressionQiita
{
    class Program
    {
        static void Main(string[] args)
        {
            var inAry = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
            // タワーの高さ
            var N = inAry[0];
            // 赤点
            var A = inAry[1];
            // 青点
            var B = inAry[2];
            // 合計点
            var K = inAry[3];

            const long wari = 998244353;

            var listtup = new List<(int,int,int)>();

            for(int i = 0; i <= N; i++)
            {
                for(int j = 0; j <= N; j++)
                {
                    if (i + j  > N)
                    {
                        break;
                    }
                    for (int k = 0; k <= N; k++)
                    {
                        if (i + j + k > N)
                        {
                            break;
                        }
                        if(A*i+B*j+(A+B)*k == K)
                        {
                            listtup.Add((i, j, k));
                        }
                    }
                }
            }

            long sum = listtup.Sum(x => Factorial(N) / (Factorial(x.Item1) * Factorial(x.Item2) * Factorial(x.Item3) * Factorial(N - x.Item1 - x.Item2 - x.Item3)));

            Console.WriteLine(sum%wari);
            Console.ReadLine();
        }

        public static long Factorial(long n)
        {
            if (n == 0)
                return 1;
            return n * Factorial(n - 1);
        }
    }
}

