namespace AGC025B
{
    public class Program
    {
        void Solve(StreamScanner ss, StreamWriter sw)
        {
            //---------------------------------
            var N = ss.Next(int.Parse);
            var A = ss.Next(long.Parse);
            var B = ss.Next(long.Parse);
            var K = ss.Next(long.Parse);

            ModInt.Mod = 998244353;
            var comb = new Combination(1000000);

            var ans = new ModInt(0);
            for (var i = 0; i < N; i++)
            {
                var bp = K - A * i;
                if (bp < 0 || bp % B != 0) continue;
                var j = (int)(bp / B);

                var min = Math.Min(i, j);
                for (var k = 0; k <= min; k++)
                {
                    var red = i - k;
                    var blue = j - k;
                    var green = k;
                    var space = N - (red + blue + green);
                    if (space < 0) continue;

                    ans += comb.Fact(N) * comb.Inverse(red) * comb.Inverse(blue) * comb.Inverse(green) * comb.Inverse(space);
                }
            }

            sw.WriteLine(ans);
            //---------------------------------
        }

        static void Main()
        {
            var ss = new StreamScanner(new StreamReader(Console.OpenStandardInput()));
            var sw = new StreamWriter(Console.OpenStandardOutput()) {AutoFlush = false};
            new Program().Solve(ss, sw);
            sw.Flush();
        }

