    {
        return int.Parse(NextString());
    }

    private static long NextLong()
    {
        return long.Parse(NextString());
    }

    #endregion

    private struct Key : IEquatable<Key>
    {
        public bool Equals(Key other)
        {
            return N == other.N && K == other.K;
        }

        public override bool Equals(object obj)
        {
            if (ReferenceEquals(null, obj)) return false;
            return obj is Key && Equals((Key)obj);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                return (N * 397) ^ K.GetHashCode();
            }
        }

        public static bool operator ==(Key left, Key right)
        {
            return left.Equals(right);
        }

        public static bool operator !=(Key left, Key right)
        {
            return !left.Equals(right);
        }

        public int N;

        public long K;
    }

    private static Dictionary<Key, long> Cache = new Dictionary<Key, long>();

    private static int A;
    private static int B;


    private static void Main(string[] args)
    {
        StartReading();

        var n = NextInt();
        A = NextInt();
        B = NextInt();
        long K = NextLong();

        var result = Solve(n, K);
        Console.WriteLine(result);

    }

    private static long Solve(int N, long K)
    {
        if (N == 0)
        {
            if (K == 0) return 1;
            return 0;
        }

        var cacheKey = new Key() { K = K, N = N };
        long result;
        if (Cache.TryGetValue(cacheKey, out result))
        {
            return result;
        }

        result = 0;
        if (K >= A) result += Solve(N - 1, K - A);
        if (K >= A+B) result += Solve(N - 1, K - A-B);
        if (K >= B) result += Solve(N - 1, K - B);
        result += Solve(N - 1, K);


        Cache.Add(cacheKey, result);
        return result;
    }

}

