        {
            long res = 1;
            while (b > 0)
            {
                if (b % 2 == 1)
                {
                    res *= a;
                    res %= Mod;
                }

                a *= a;
                a %= Mod;
                b /= 2;
            }

            return res;
        }

        private const long Mod = 998244353;

        static MyMath()
        {
            _factorial = new long[700001];
            _factorial[0] = 1;
            for (int i = 1; i <= 700000; i++)
            {
