            var K = ss.Next(long.Parse);

            ModInt.Mod = 998244353;
            var comb = new Combination(N * 2);

            var ans = (ModInt)0;
            for (var a = 0; a <= N; a++)
            {
                var b = (K - a * A) / B;
                if (0 > b || b > N || a * A + b * B != K) continue;
                ans += comb.NCK(N, a) * comb.NCK(N, (int)b);
