	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		long N = long.Parse(str[0]);
		long A = long.Parse(str[1]);
		long B = long.Parse(str[2]);
		long K = long.Parse(str[3]);
		long greenab = K/(A+B);
		long green = 0;
		long blue = 0;
		long red = 0;
		long white = 0;
		long count = 0;
		long pt2a = 1;
		long pt2b = 1;
		long pt2c = 1;
		long nai = 1;
		long mod = 998244353;
		long [] NA = new long[N+1];
		long [] INA = new long[N+1];
		NA[0] = 1;
		long inai = 1;
		INA[0] = 1;
		for(var i=1;i<NA.Length;i++){
			NA[i] = NA[i-1] * i % mod;
			inai = 1;
			long mm = mod-2;
			long mmx = i;
			while(mm > 0){
				if(mm % 2 == 1){
					inai = inai * mmx % mod;
					mm -= 1;
				}
				mmx = mmx * mmx % mod;
				mm /= 2;
			}
			INA[i] = INA[i-1] * inai % mod;	
		}
		long dt = 1;
		while(greenab >= 0){
			long bluep = K - (A+B) * greenab;
			if(bluep % B == 0 && bluep / B >= 1){
				for(var i=0;i<=greenab;i++){
					green = greenab - i;
					blue = bluep / B + i;
					red = i;
					white = N - green - blue - red;
					if(white >= 0){
						pt2a = NA[N] * INA[N-green] % mod * INA[green] % mod;
						pt2b = NA[N-green] * INA[N-green-red] % mod * INA[red] % mod;
						pt2c = NA[N-green-red] * INA[N-green-red-blue] % mod * INA[blue] % mod;
						pt2a = pt2a * pt2b % mod * pt2c % mod;
						count += pt2a;
						count %= mod;
					} else {
						break;
					}
				}
				dt = B / Gcd(A+B,B);
			}
			greenab -= dt;
		}
		dt = 1;
		greenab = K/(A+B);
		while(greenab >= 0){
			long redp = K - (A+B) * greenab;
			if(redp % A == 0){
				for(var i=0;i<=greenab;i++){
					green = greenab - i;
					blue = i;
					red = redp / A + i;
					white = N - green - blue - red;
					if(white >= 0){
						pt2a = NA[N] * INA[N-green] % mod * INA[green] % mod;
						pt2b = NA[N-green] * INA[N-green-red] % mod * INA[red] % mod;
						pt2c = NA[N-green-red] * INA[N-green-red-blue] % mod * INA[blue] % mod;
						pt2a = pt2a * pt2b % mod * pt2c % mod;
						count += pt2a;
						count %= mod;
					} else {
						break;
					}
				}
				dt = A / Gcd(A+B,A);
			}
			greenab -= dt;
		}
		Console.WriteLine(count);
	}

	public static long Gcd(long a, long b) {
		if (a < b)
			return Gcd(b, a);
		while (b != 0) {
			var remainder = a % b;
			a = b;
			b = remainder;
		}
		return a;
	}
}

