class Comb
{
    int n;
    int mod;
    int fac;
    int[] finv;
    int[] inv;
    public Comb(int n, int mod)
    {
        this.n = n;
        this.mod = mod;
        finv = new int[n + 1];
        inv = new int[n + 1];
        fac = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i <= n; i++)
        {
            inv[i] = mod - (int)((long)inv[mod % i] * (mod / i) % mod);
            fac = (int)((long)fac * i % mod);
            finv[i] = (int)(((long)finv[i - 1] * inv[i]) % mod);
        }
    }
    public long comb(int i)
    {
        return fac * ((long)finv[i] * finv[n - i] % mod) % mod;
    }
}

