        long B = cin.nextInt();
        long K = cin.nextLong();

        setFact(N + 1);

        long ans = 0;
        for (long a = 0; a <= N; a++)
        {
            long b = (K - (a * A)) / B;
            if (b < 0 || b > N) continue;
            if (a * A + b * B != K) continue;


            long tmp = getC(N, (int)a) * getC(N, (int)b);
            ans += tmp % mod;
            ans %= mod;
        }

        Console.WriteLine(ans);
    }

    long mod = 998244353;
    long powmod(long a, long p)
    {
        long ans = 1;
        long mul = a;
        for (; p > 0; p >>= 1, mul = (mul * mul) % mod)
        {
            if ((p & 1) == 1) ans = (ans * mul) % mod;
        }
        return ans;
    }


    long[] fact; //階乗
    long[] revFact; //階乗の逆元
    void setFact(int N)
    {
        fact = new long[N];
        revFact = new long[N];
        fact[0] = 1;
        for (int i = 1; i < N; i++)
        {
            fact[i] = fact[i - 1] * i;
            fact[i] %= mod;
        }
        revFact[N - 1] = powmod(fact[N - 1], mod - 2);
        for (int i = N - 2; i >= 0; i--)
        {
            revFact[i] = revFact[i + 1] * (i + 1);
            revFact[i] %= mod;
        }
    }


    long getC(int a, int b)
    {
        return (((fact[a] * revFact[b]) % mod) * revFact[a - b]) % mod;
    }

}






