class Comb
{
    long n;
    int mod;
    List<long> c;
    public Comb(long n, int mod)
    {
        this.n = n;
        this.mod = mod;
        c = new List<long>();
        c.Add(1);
        for (int i = 1; i <= n; i++)
        {
            c.Add((c[i - 1] * i) % mod);
        }
        foreach (var i in c)
            C.WriteLine(i);
    }
    public long comb(int i)
    {
        return (c[(int)n] / (c[i] * c[(int)n - i])) % mod;
    }
