    partial class Solver
    {
        const int MOD = 998244353;

        public int nod(int a, int b)
        {
            if (a > b)
                return nod(b, a);
            if (a == 0)
                return b;
            return nod(b % a, a);
        }

        public Tuple<long, long> Solve(long a, long b, long k)
        {
            if (a > b)
            {
                var temp1 = Solve(b, a, k);
                if (temp1 != null)
                {
                    var y = temp1.Item1;
                    var x = temp1.Item2;
                    if (y < 0)
                    {
                        var net = (-y + a - 1) / a;
                        x -= b * net;
                        y += a * net;
                    }
                    temp1 = Tuple.Create(x, y);
                }
                return temp1;
            }
            if (a == 0)
            {
                if (k % b == 0)
                    return Tuple.Create(0L, k / b);
                return null;
            }
            var temp = Solve(b % a, a, k);
            if (temp == null)
                return null;
            var x1 = temp.Item2 - temp.Item1 * (b / a);
            var y1 = temp.Item1;
            if (x1 < 0)
            {
                var net = (-x1 + b - 1) / b;
                x1 += b * net;
                y1 -= a * net;
            }
            if (y1 < 0)
            {
                var net = (-y1 + a - 1) / a;
                x1 -= b * net;
                y1 += a * net;
            }
            return Tuple.Create(x1, y1);
        }

        static int pow(int m, int e, int mod)
        {
            var res = 1;
            while (e > 0)
            {
                if ((e & 1) == 1)
                {
                    res = (int)(1L * res * m % mod);
                }
                e >>= 1;
                m = (int)(1L * m * m % mod);
            }
            return res % mod;
        }

        static int inverse_prime(int num, int prime)
        {
            return pow(num, prime - 2, prime);
        }

        public void Run()
        {            
            var n = read.Int();
            var a = read.Int();
            var b = read.Int();
            var k = read.Long();
            var dc = nod(a, b);
            var answer = 0L;
            if (k % dc == 0)
            {
                a /= dc;
                b /= dc;
                k /= dc;
                var res = Solve(a, b, k);

                if (res != null)
                {
                    var x = res.Item1;
                    var y = res.Item2;
                    if (y > n)
                    {
                        var net = (y - n + a - 1) / a;
                        y -= a * net;
                        x += b * net;
                    }
                    while (y + a <= n)
                    {
                        y += a;
                        x -= b;
                    }
                    var array = new long[n + 1];
                    array[0] = 1;
                    for (int i = 1; i <= n; ++i)
                    {
                        array[i] = array[i - 1];
                        array[i] = array[i] * (n - i + 1) % MOD;
                        array[i] = array[i] * inverse_prime(i, MOD) % MOD;
                    }
                    while (y >= 0 && x <= n)
                    {
                        if (x >= 0)
                        {
                            answer += array[x] * array[y] % MOD;
                            answer %= MOD;
                        }
                        y -= a;
                        x += b;
                    }
                }
            }
            write.WriteLine(answer);
        }
    }
}

