    class Program
    {
        static long gcd = 0;
        static long[] exgcd(long x, long y)
        {
            long r0 = x, r1 = y;
            long a0 = 1, a1 = 0;
            long b0 = 0, b1 = 1;
            while (r1 > 0)
            {
                long q1 = r0 / r1;
                long r2 = r0 % r1;
                long a2 = a0 - q1 * a1;
                long b2 = b0 - q1 * b1;
                r0 = r1; r1 = r2;
                a0 = a1; a1 = a2;
                b0 = b1; b1 = b2;
            }
            gcd = r0;
            return new long[] { a0, b0 };
        }
        const long mod = 998244353;
        public static long calc(long x, long pow)
        {
            if (pow == 0) return 1;
            long a = calc(x, pow / 2);
            a = a * a % mod;
            if (pow % 2 == 1) a *= x;
            return a % mod;
        }
        static long[] fact;
        public static long combination(long n, long r)
        {
            return fact[n] * calc((fact[r] * fact[n - r]) % mod, mod - 2) % mod;
        }
