                mintimes = Math.Max(mintimes, (b - x[0] + (big / gcd - 1)) / (big / gcd));
                a += (small / gcd) * mintimes;
                b -= (big / gcd) * mintimes;
                long ret = 0;
                while (0 <= a && a <= x[0] &&
                       0 <= b && b <= x[0])
                {
                    ret += combination(x[0], a) * combination(x[0], b) % mod;
