function Main(s){
  s = s.split(" ").map(a=>+a);
  var n = s[0];
  var a = s[1];
  var b = s[2];
  var k = s[3];
  var ans = 0;
  for(var i = 0; i <= n; i++){
    var x = k - i * a;
    if(x < 0)break;
    if(x % b === 0 && x / b <= n){
      ans += abmod(nCrmod(n, i), nCrmod(n, x / b));
      ans %= mod;
    }
  }
  console.log(ans);
