class LinearEq
	attr_accessor :a, :b, :gcd, :lcm, :sol
	# ax+by=k where 1<=x,y<=n
	def initialize(a,b,k,n)
		@n = n
		@k = k
		# adjust as a >= b
		# must be here cause find_solution also uses these fields
		if(a < b)
			@a = b
			@b = a
		else
			@a = a
			@b = b
		end
		@gcd = nil
		@sol = nil
		self.set
		@sol = self.find_solution
	end
	def set
		# a * x0 + b * y0 = k
		# set gcd
		@x0, @y0, @gcd = calc_gcd(@a,@b,@k)
		# start with smallest positive x0, and positive y0
		# TODO
		@lcm = @a * @b / @gcd
		@x = @x0
		@y = @y0
		[@x, @y, @gcd]
	end
	def find_solution
		if(@x >= 0)
			da = @lcm/@a
			db = @lcm/@b
			d = @x/da
			@x -= d*da
			@y += d*db
		end
		if(@x <= 0)
			da = @lcm/@a
			db = @lcm/@b
			d = (-@x)/da+1
			@x += d*da
			@y -= d*db
		end
		if(@y <= 0)
			return nil
		end
		@x -= @lcm/@a
		@y += @lcm/@b
		{:x=>@x,:y=>@y}
	end
	def next_solution
		@x += @lcm/@a
		@y -= @lcm/@b
		if(@y <= 0)
			return nil
		end
		@sol = {:x=>@x,:y=>@y}
		return @sol
	end
	# returns [x0, y0, gcd]
	def calc_gcd(a,b,k)
		dputs "calc_gcd:(a,b)=(#{a},#{b})"
		if(a % b == 0)
			if(k % b != 0)
				return nil
			else
				return [0,k/b,b]
			end
		else
			sol = calc_gcd(b,a%b,k)
			if(sol.nil?)
				return nil
			else
				# a x + b y = k
				# y' = a/b x + y
				# sol : b y' + a%b x = k
				return [sol[1], sol[0]-a/b*sol[1], sol[2]]
			end
		end
	end
end

