var lp2 int = 998244353

func main() {
	buf := make([]byte, 0)
	sc.Buffer(buf, lp1)
	sc.Split(bufio.ScanWords)
	n, a, b, k := iScan(), iScan(), iScan(), iScan()
	ans := 0
	f := make([]int, n+1)
	inv := make([]int, n+1)
	f[0], inv[0] = 1, 1
	for i := 1; i <= n; i++ {
		f[i] = f[i-1] * i % lp2
		inv[i] = modinv(f[i], lp2)
	}
	for i := 0; i <= n; i++ {
		if a*i <= k && (k-a*i)%b == 0 && (k-a*i)/b <= n {
			j := (k - a*i) / b
			ans += (f[n] * inv[n-i] % lp2 * inv[i] % lp2) * (f[n] * inv[n-j] % lp2 * inv[j] % lp2) % lp2
			ans %= lp2
		}
	}
	fmt.Println(ans)
}
func modinv(a, m int) int {
	b, u, v := m, 1, 0
	for {
		t := a / b
		a -= t * b
		u -= t * v
		a, b, u, v = b, a, v, u
		if b == 0 {
			break
		}
	}
	u %= m
	if u < 0 {
		u += m
	}
	return u
}

