	var ans int64
	for i := 0; i <= n; i++ {
		if (k-a*int64(i))%b != 0 {
			continue
		}
		j := (k - a*int64(i)) / b
		if int64(n) < j {
			continue
		}
		ans = mod(ans + mod(cm.calc(n, i)*cm.calc(n, int(j))))
	}

	fmt.Fprintln(writer, ans)
}

