func gcd(x,y int64) int64 {
  if x%y == 0 { return y }
  return gcd(y,x%y)
}
func comb(n,a,b,c int64) int64 {
  if a < 0 || a > n { return 0 }
  if b < 0 || b > n-a { return 0 }
  if c < 0 || c > n-a-b { return 0 }
  if n == 0 && a == 0 && b == 0 && c == 0 { return 1 }
  if n == 0 { return 0 }
  return (f[n]*((((finv[a]*finv[b])%mod)*((finv[c]*finv[n-a-b-c])%mod))%mod))%mod
}
func inv(n int64) int64 {
  if n == 1 { return 1 }
  k := make([]int64,size)
  a,b,u := mod,n,size
  for i:=0;i<size;i++ {
    k[i],a,b = a/b,b,a%b
    if b == 0 { u = i;break }
  }
  var y0,y1 int64 = 1,-k[0]
  for i:=1;i<u;i++ { y0,y1 = y1,y0-k[i]*y1 }
  for y1 < 0 { y1 += mod }
  return y1%mod
}

