import "fmt"

var MOD = 998244353

func gcd(a, b int) int {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func exGcd(a, b int) (int, int, int) {
	r0 := a
	x0 := 1
	y0 := 0
	r1 := b
	x1 := 0
	y1 := 1
	for r1 != 0 {
		// Calc
		r2 := r0 % r1
		q := r0 / r1 // quotient
		x2 := x0 - q*x1
		y2 := y0 - q*y1

		// Update
		r0 = r1
		r1 = r2
		x0 = x1
		x1 = x2
		y0 = y1
		y1 = y2
	}

	return r0, x0, y0
}

func prepare(fac []int, fInv []int, inv []int, upper int) {
	fac[0] = 1
	fac[1] = 1
	fInv[0] = 1
	fInv[1] = 1
	inv[1] = 1
	for i := 2; i <= upper; i++ {
		fac[i] = fac[i-1] * i % MOD
		inv[i] = MOD - inv[MOD%i]*(MOD/i)%MOD
		fInv[i] = fInv[i-1] * inv[i] % MOD
	}
}

func calcCombination(fac []int, fInv []int, n, a int) int {
	if n < a {
		return 0
	}
	if n < 0 || a < 0 {
		return 0
	}
	return fac[n] * (fInv[a] * fInv[n-a] % MOD) % MOD
}

func main() {
	var N, A, B, K int
	fmt.Scanf("%d %d %d %d", &N, &A, &B, &K)

	ans := 0

	// Calc NCx * NCy
	// nCa = (n)!/(n-a)!(a)! = (n!)(a!)^-1((n-a)!)^-1
	// n >= a   -->   Prepare (n!), (a!)^-1
	fac := make([]int, N+1)
	fInv := make([]int, N+1)
	inv := make([]int, N+1)
	prepare(fac, fInv, inv, N)

	// xA + yB = K
	for x := 0; x <= N; x++ {
		r := K - x*A
		if r%B != 0 {
			continue
		}
		y := r / B
		if y > N {
			continue
		}
		ans += (calcCombination(fac, fInv, N, x) * calcCombination(fac, fInv, N, y) % MOD)
		ans %= MOD
	}

	fmt.Println(ans)
}

