type Comb struct {
	l, mod     int
	fa, in, fi []int
}

func NewComb(sz, mod int) *Comb {
	comb := &Comb{
		l: sz, fa: make([]int, sz), in: make([]int, sz), fi: make([]int, sz), mod: mod}
	comb.init()
	return comb
}
func (c *Comb) init() {
	c.fa[0], c.fa[1] = 1, 1
	c.in[1] = 1
	c.fi[0], c.fi[1] = 1, 1
	for i := 2; i < c.l; i++ {
		c.fa[i] = c.fa[i-1] * i % c.mod
		c.in[i] = c.mod - c.in[c.mod%i]*(c.mod/i)%c.mod
		c.fi[i] = c.fi[i-1] * c.in[i] % c.mod
	}
}
func (c *Comb) NCK(n, k int) int {
	if n < 0 || k < 0 || n < k || c.l <= n {
		return 0
	}
	return c.fa[n] * (c.fi[k] * c.fi[n-k] % c.mod) % c.mod
}
func (c *Comb) NPK(n, k int) int {
	if n < 0 || k < 0 || n < k || c.l <= n {
		return 0
	}
	return c.fa[n] * (c.fi[n-k]) % c.mod
}
func (c *Comb) NHK(n, k int) int { return c.NCK(n+k-1, k) }
func (c *Comb) Len() int         { return c.l }

