	inv := make([]int, N+1)
	prepare(fac, fInv, inv, N)

	// xA + yB = K
	for x := 0; x <= N; x++ {
		r := K - x*A
		if r%B != 0 {
			continue
		}
		y := r / B
		if y > N {
			continue
		}
		ans += (calcCombination(fac, fInv, N, x) * calcCombination(fac, fInv, N, y) % MOD) % MOD
	}

	fmt.Println(ans)
}

