func factorial(N, p int) (F, Finv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  inv := make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  inv[0] = 1
  inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    inv[i] = p - inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * inv[i] % p
  }
  return
}

func comb(F, Finv *[]int, N, a, p int) (ret int) {
  ret = (*F)[N] * ((*Finv)[a] * (*Finv)[N - a] % p) % p
  return
}

func main() {
  var N, A, B, K int
  fmt.Scan(&N, &A, &B, &K)
  p := 998244353
  F, Finv := factorial(N, p)
  var cnt int
  for a := 0; a < N + 1; a++ {
    _A := A * a
    if _A > K {
      continue
    }
    if (K - _A) % B > 0 {
      continue
    }
    b := (K - _A) / B
    if b > N {
      continue
    }
    cnt += comb(&F, &Finv, N, a, p) * comb(&F, &Finv, N, b, p) % p
    cnt %= p
  }
  fmt.Println(cnt)
}

