sub fac2($$$$$){
        my @NUM;
        my $n;
        ($NUM[0], $NUM[1], $NUM[2], $NUM[3], $n) = @_;
        @NUM = sort {$b <=> $a} @NUM;
        my $fact = reduce { $a * $b } $NUM[0]+1 .. $n;
        foreach my $i (1..3) {
                my $f = reduce { $a * $b } 1 .. $NUM[$i];
                if (defined($f)) {
                        $fact /= $f;
                }
        }
        return $fact;
}

