// mod p における階乗
Finite perm(ulong x){
	static Finite[] _perm = [];
	if(_perm.length == 0) _perm ~= Finite(1);
	while(x >= _perm.length)
			_perm ~= _perm[$ - 1] * _perm.length;
	return _perm[x];
}

// mod p における階乗の逆元 ※階乗で割るときは必ずこれを使うこと
Finite invperm(ulong x){
	static Finite[] _invperm = [];
	if(_invperm.length == 0) _invperm ~= Finite(1);
	while(x >= _invperm.length)
			_invperm ~= _invperm[$ - 1] / _invperm.length;
	return _invperm[x];
}

// mod p における二項係数（定義に注意：(a + b)! / a! / b! ）
Finite pascal(ulong a, ulong b){
	Finite res = perm(a + b) * invperm(a) * invperm(b);
	return res;
}

