auto solve( long n, long a, long b, long k )
{
	// 緑は赤＋青と同じ
	// つまり、緑は気にせずに赤と青の組み合わせだけ考えればよい
	auto ans = 0L;
	foreach( na; 0L .. n + 1 )
	{
		// na個を赤に塗ったときの点数を計算
		auto ka = na * a;
		if( k < ka ) break;

		// 不足している点数を青で補完する場合の必要な点数と個数を計算
		auto kb = k - ka;
		if( kb % b != 0 ) continue;
		auto nb = kb / b;
		if( n < nb ) continue;

		// 赤パターンと青パターンの組み合わせ数を計算
		ans = ans.addMod( n.combinationMod( na ).mulMod( n.combinationMod( nb ) ) );
	}
	return ans;
}

