auto solve( long n, long a, long b, long k )
{
	// 緑は赤＋青と同じ
	// つまり、緑は気にせずに赤と青の組み合わせだけ考えればよい
	auto ans = 0L;
	foreach( na; 0L .. n + 1 )
	{
		// na個を赤に塗ったときの点数を計算
		auto ka = na * a;
		if( k < ka ) break;

		// 不足している点数を青で補完する場合の必要な点数と個数を計算
		auto kb = k - ka;
		if( kb % b != 0 ) continue;
		auto nb = kb / b;
		if( n < nb ) continue;

		// 赤パターンと青パターンの組み合わせ数を計算
		ans = ( ans + n.combinationMod( na ) * n.combinationMod( nb ) ) % MOD;
	}
	return ans;
}

const MOD = 998244353L;

// 割り算
auto divMod( long n, long d )
{
	return n * d.powMod( MOD - 2 ) % MOD;
}

// べき乗
long powMod( long n, long p )
{
	static long[ long ][ long ] memo;
	if( n !in memo      ) memo[ n ][ 0 ] = 1;
	if( p !in memo[ n ] ) memo[ n ][ p ] = ( n.powMod( p / 2 ) ^^ 2 % MOD ) * ( n ^^ ( p % 2 ) ) % MOD;
	return memo[ n ][ p ];
}

// 階乗
auto factorialMod( long n )
{
	static memo = appender( [ 1L, 1L ] );
	while( memo.data.length <= n ) memo.put( memo.data[ $ - 1 ] * memo.data.length % MOD );
	return memo.data[ n ];
}

// 組み合わせ数
auto combinationMod( long n, long r )
{
	return n.factorialMod.divMod( r.factorialMod * ( n - r ).factorialMod % MOD );
}

