const MOD = 998244353;
long[] f; // 階乗
long[] finv; // 階乗の逆元

long modPow(long x, long k, long m) {
    if (k == 0) return 1;
    if (k % 2 == 0) return modPow(x * x % m, k / 2, m);
    return x * modPow(x, k - 1, m) % m;
}

void init(long n) {
    f = new long[n + 1];
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = (i * f[i - 1]) % MOD;
    }

    finv = new long[n + 1];
    finv[n] = modPow(f[n], MOD - 2, MOD);
    for (long i = n - 1; i >= 0; i--) {
        finv[i] = (finv[i + 1] * (i + 1)) % MOD;
    }
}

long calc(long n, long a, long b, long k) {

    long nck(long n, long k) {
        return (f[n] * finv[k] % MOD) * finv[n - k] % MOD;
    }

    // ax + by = k
    long ans = 0;
    for (int x = 0; x <= n; x++) {
        if (k - a * x < 0) break;
        if ((k - a * x) % b != 0) continue;

        long y = (k - a * x) / b;
        ans += nck(n, x) * nck(n, y) % MOD;
    }

    return ans;
}

