ll exgcd(ll a,ll b,ll &x,ll &y)
{
    if(b==0)
    {
        x=1;
        y=0;
        return a;
    }
    else
    {
        ll d=exgcd(b,a%b,y,x);
        y-=a/b*x;
        /*ll d=exgcd(b,a%b,x,y);
        ll t=y;
        y=x-a/b*y;
        x=t;*/
        return d;
    }
}
ll inv(ll a,ll p)//拓展欧几里得求逆元
{
    ll x,k;
    ll d=exgcd(a,p,x,k);
    if(d!=1) return -1;
    else return (x%p+p)%p;
}
ll fac[1000002];
void factorial()//求maxn以内的数的阶乘%p
{
    fac[0] = fac[1] = 1;
    for(ll i = 2; i < maxn; i++)
        fac[i] = fac[i - 1] * i % mod;
}
ll C(ll a, ll b)//计算C(a, b)
{
    return fac[a] * inv(fac[b], mod) % mod* inv(fac[a - b], mod) % mod;
}
