proc combM(n, r: Natural): Natural =
    if r > n:
        return 0
    if r > n div 2:
        return combM(n, n - r)
    return factM(n).divM(factM(r)).divM(factM(n - r))

proc multCombM(n, r: Natural): Natural = combM(n + r - 1, n - 1)

