import math
import fractions

def egcd(a, b):
    (x, lastx) = (0, 1)
    (y, lasty) = (1, 0)
    while b != 0:
        q = a // b
        (a, b) = (b, a % b)
        (x, lastx) = (lastx - q * x, x)
        (y, lasty) = (lasty - q * y, y)
    return (lastx, lasty, a)

def modinv(a, m):
    inv, _, _ = egcd(a, m)
    return inv % m

def modc(a,b,m):
    c = 1
    for i in range(b):
        c = c * (a - i) % m
        c = c * modinv(i + 1,m) % m
    return c

def LCM(a, b):
    return a*b//fractions.gcd(a, b)

def indefinite_eq(n, a, b, k):
    na, nb = (-1, -1)
    for i in range(k//a+1):
        if (k-a*i)%b == 0:
            na = i
            nb = (k-a*i)//b
            break

    lcm = LCM(a, b)
    while True:
        if 0 <= na <= n and 0 <= nb <= n:    
            yield na, nb
            na += lcm // a
            nb -= lcm // b
        else: 
            break

