fn fact(m: i64, n: i64) -> i64 {
	let mut ret = 1;
    for i in 1..n+1 {
    	ret = (ret * i) % m;
    }
    ret
}

fn bin(m: i64, n: i64, k: i64) -> i64 {
	if n < 0 || k < 0 || n < k {
    	return 0;
    }
    if n == 1 || k == 1 {
    	return 1;
    }
    let a = fact(m,n);
    let b = fact(m,k);
    let c = fact(m,n-k);
    (((a*pow(m,b,m-2))%m)*pow(m,c,m-2))%m
}

fn pow(m: i64, a: i64, b: i64) -> i64 {
	if b == 0 { return 0; }
    if b % 2 == 0 {
    	let d = pow(m, a, b /  2);
        return (d * d) % m;
    } else{
    	return (a*pow(m, a,b-1)) %m;
    }
}

