// a x + b y = gcd(a, b)
fn extgcd(a:i64, b:i64, x: &mut i64, y: &mut i64)->i64 {
    let mut g = a;
    if a**x+b**y==1{
        return 1;
    }
    if a**y+b**x==1{
        let t = *x;
        *x = *y;
        *y = t;
        return 1;
    }
    if b != 0{
        g = extgcd(b, a % b, y, x);
        *y -= (a / b) * *x;
    }
    return g;
}

fn inv_mod(a: i64, m: i64)->i64 {
    let mut x:i64=1;
    let mut y:i64=0;
    if extgcd(a, m, &mut x, &mut y) == 1{
        // println!("{:?}", (a*x+y*m));
        (x + m) % m
    } else{
        0 // unsolvable
    }
}



