fn fact_table_mod(n:i64, m:i64)->Vec<i64>{
    let mut table = vec![1;(n+1) as usize];
    for i in 2..n+1{
        table[i as usize] = (table[(i-1) as usize]*i)%m;
    }
    return table
}

fn solver(n:i64, a:i64, b:i64, k:i64)->i64{
    let mut sum:i64 = 0;
    let m:i64 = 998244353;
    // let mut table: CombTable = CombTable{table: vec![vec![1]]};
    let table: Vec<i64> = fact_table_mod(n, m);
    for n_a in 0..min(n, k/a+1){
        if (k-n_a*a)%b==0 {
            let n_b = (k-n_a*a)/b;
            let mut c = 1;
            c *= table[n as usize]%m;
            c %= m;
            c *= (inv_mod(table[(n-n_a) as usize], m)*inv_mod(table[n_a as usize], m))%m;
            c %= m;
            c *= table[n as usize]%m;
            c %= m;
            c *= (inv_mod(table[(n-n_b) as usize], m)*inv_mod(table[n_b as usize], m))%m;
            c %= m;
            sum += c;
            sum %= m;
        }
    }
    return sum;
}

