#[derive(Clone, Debug)]
pub struct MemorizedFactorial {
    n: usize,
    fact: Vec<Modi64>,
    inv_fact: Vec<Modi64>,
}
impl MemorizedFactorial {
    pub fn new(max_n: usize) -> MemorizedFactorial {
        let mut fact = vec![1.into(); max_n + 1];
        let mut inv_fact = vec![1.into(); max_n + 1];
        for i in 1..(max_n + 1) {
            fact[i] = fact[i - 1] * (i as i64).into();
            inv_fact[i] = inv_fact[i - 1] / (i as i64).into();
        }
        MemorizedFactorial {
            n: max_n + 1,
            fact: fact,
            inv_fact: inv_fact,
        }
    }
    pub fn combination(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[r] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    pub fn permutation(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    pub fn homogeneous_product(&self, n: usize, r: usize) -> Modi64 {
        if n != 0 && r != 0 {
            self.combination(n + r - 1, r)
        } else {
            1.into()
        }
    }
}
use std::cmp::{max, min};
fn main() {
    input! { n: i64, a: i64, b: i64, k: i64 };
    let (g, i, j) = extgcd(a, b);
    if k % g != 0 {
        println!("0");
        return;
    }
    let (i, j) = (k / g * i, k / g * j);
    let (a, b) = (a / g, b / g);
    let (mint, maxt) = (max((i - n) / b, -j / a), min(i / b, (n - j) / a));
    let mut ans = Modi64(0);
    let cmb = MemorizedFactorial::new(n as usize);
    for t in mint..maxt + 1 {
        let (x, y) = (-b * t + i, a * t + j);
        if 0 <= x && x <= n && 0 <= y && y <= n {
            let (n, x, y) = (n as usize, x as usize, y as usize);
            ans += cmb.combination(n, x) * cmb.combination(n, y);
        }
    }
    println!("{}", ans);
}

