    if n < m {
        return 0;
    }

    FACT.with(|fact| {
        RFACT.with( |rfact| {
            fact[n] * rfact[n-m] % MOD * rfact[m] % MOD
        })
    })
}

fn solve(n: u64, a: u64, b: u64, k: u64) ->  u64 {

    let mut ans = 0;

    for i in 0..n {

        if k < i*a {
            continue
        }

        if (k - (i*a)) % b > 0 {
            continue
        }

        let j = (k-(i*a)) / b;
        ans += (combi(n as usize ,i as usize) * combi(n as usize,j as usize)) % MOD;
        ans %= MOD;
    }

    ans as u64
}

