    for i in 1 as usize..(n+1) as usize{
        let mut v: Vec<u64> = vec![1];
        for j in 1 as usize..i as usize{
            let x: u64 = table.table[i-1][j-1];
            let y: u64 = table.table[i-1][j];
            v.push((x+y)%m);
        }
        v.push(1);
        table.table.push(v);
    }
}

