struct ModFact{
    n: usize,
    m: isize,
    fac: Vec<ModInt>,
    inv_fac: Vec<ModInt>
}

impl ModFact{
    fn new(n:usize,m:isize) -> ModFact{
        let f = vec![ModInt::new(1,m)];
        let inv_f = vec![ModInt::new(1,m)];
        let mut ret = ModFact{n:0,m:m,fac:f,inv_fac:inv_f};
        ret.update(n);
        ret
    }
    fn get_fact(&mut self,n:usize) -> ModInt{
        if n > self.n {self.update(n);}
        self.fac[n]
    }
    fn get_inv_fact(&mut self,n:usize) -> ModInt{
        if n > self.n {self.update(n);}
        self.inv_fac[n]
    }
    fn update(&mut self,goal:usize){
        let start = self.n+1;
        let mut new_fac = (start..goal+1).map(|_| ModInt::new(1,self.m)).collect::<Vec<_>>();
        self.fac.append(&mut new_fac);
        for i in start..goal+1{
            self.fac[i] = self.fac[i-1] * i as isize ;
        }
        let mut new_inv = (start..goal+1).map(|_| ModInt::new(1,self.m)).collect::<Vec<_>>();
        self.inv_fac.append(&mut new_inv);
        self.inv_fac[goal] = self.fac[goal].inv();
        for j in (start..goal).rev(){
            self.inv_fac[j] = self.inv_fac[j+1]*(j+1) as isize;
        }
        self.n = goal;
    }
    fn comb(&mut self,n:usize,r:usize) -> ModInt{
        self.get_fact(n)*self.get_inv_fact(r)*self.get_inv_fact(n-r)
    }
}

