const MOD: i64 = 998244353;

fn modpow(mut x: i64, mut n: i64) -> i64 {
    let mut ret: i64 = 1;
    while n > 0 {
        if (n & 1) == 1 {
            ret = ret * x % MOD;
        }
        x = x * x % MOD;
        n >>= 1;
    }
    return ret;
}

fn main(){
    input!{
        N: i64,
        A: i64,
        B: i64,
        K: i64,
    }

    let mut fact = vec![];
    let mut inv = vec![];
    fact.push(1i64);
    inv.push(1i64);

    for i in 0..N {
        fact.push(fact[i as usize] * (i + 1) % MOD);
        inv.push(modpow(fact[(i + 1) as usize], MOD - 2));
    }

    let mut ans: i64 = 1;

    for a in 0..N+1 {
        if (K - a * A) % B != 0 {
            continue;
        }
        let b = (K - a * A) / B;
        if b < 0 || N < b {
            continue;
        }

        ans = ans * fact[N as usize] % MOD * inv[a as usize] % MOD * inv[(N - a) as usize] % MOD;
        ans = ans * fact[N as usize] % MOD * inv[b as usize] % MOD * inv[(N - b) as usize] % MOD;
    }

    println!("{}", ans);
}

fn main() {
    let (n, a, b, k): (usize, usize, usize, usize) = readln();
    let mut answer: Mint = 0.into();
    let mut fact: Vec<Mint> = vec![1.into()];
    let mut inv_fact: Vec<Mint> = vec![1.into()];
    for i in 1..300010 {
        let next = fact[fact.len()-1] * i;
        fact.push(next);
    }
    for i in 1..300010 {
        let next = inv_fact[inv_fact.len()-1] / i;
        inv_fact.push(next);
    }
    for x in 0..n+1 {
        let rest = k as isize - (a * x) as isize;
        if rest >= 0 && (rest as usize) % b == 0 {
            let y = (rest as usize) / b;
            let ri = n as isize - (x + y) as isize;
            let lb = if ri >= 0 { 0 } else { -ri as usize };
            let ub = min(x, y);
            for z in lb..ub+1 {
                let r = (ri + z as isize) as usize;
                answer += inv_fact[x-z] * inv_fact[y-z] * inv_fact[z] * inv_fact[r];
            }
        }
    }
    println!("{}", answer * fact[n]);
}

