#[allow(dead_code)]
fn pow_mod(base: i64, power: i64, modulo: i64) -> i64 {
    let mut base = base;
    let mut power = power;
    let mut ans = 1;
    while power > 0 {
        if power & 1 == 1 {
            ans = ans * base % modulo;
        }
        power >>= 1;
        base = base * base % modulo;
    }
    ans
}

#[allow(dead_code)]
fn combi(n: usize, m: usize, modulo: i64) -> i64 {
    let mut fac: Vec<i64> = vec![1; n+1];

    for i in 1..n+1 {
        fac[i] = (fac[i-1] * i as i64) as i64 % modulo;
    }

    let mut rfac = vec![1; n+1];
    rfac[n] = pow_mod(fac[n], modulo-2, modulo);

    for i in (1..n).rev() {
        rfac[i] = (rfac[i+1] * (i+1) as i64) % modulo;
    }

    fac[n] * rfac[n-m] % modulo * rfac[m] % modulo
}

fn solve(n: u64, a: u64, b: u64, k: u64) ->  u64 {

    let r = 998244353;
    let mut ans = 0;

    for i in 0..n {

        if k < i*a {
            continue
        }

        if (k - (i*a)) % b > 0 {
            continue
        }

        let j = (k-(i*a)) / b;
        ans += (combi(n as usize ,i as usize ,r) * combi(n as usize,j as usize,r)) % r
    }

    ans as u64 % r as u64
}

