fn extgcd(a:i64, b:i64, x: &mut i64, y: &mut i64)->i64 {
    let mut g = a;
    if a**x+b**y==1{
        return 1;
    }
    if a**y+b**x==1{
        let t = *x;
        *x = *y;
        *y = t;
        return 1;
    }
    if b != 0{
        g = extgcd(b, a % b, y, x);
        *y -= (a / b) * *x;
    }
    return g;
}

