const D: usize = 998244353;

fn pow_mod(n: usize, mut m: usize) -> usize {
    let mut ret = 1;
    let mut k = n;
    while m > 0 {
        if m % 2 == 1 {
            ret = ret * k % D;
        }
        m /= 2;
        k = k * k % D;
    }
    ret
}

fn inv_mod(n: usize) -> usize {
    pow_mod(n,D-2)
}

fn main() {
