use std::cmp::{min};

// a x + b y = gcd(a, b)
fn extgcd(a:u64, b:u64, x: &mut u64, y: &mut u64)->u64 {
    let mut g = a;
    if a**x+b**y==1{
        return 1;
    }
    if a**y+b**x==1{
        let t = *x;
        *x = *y;
        *y = t;
        return 1;
    }
    if b != 0{
        g = extgcd(b, a % b, y, x);
        *y -= (a / b) * *x;
    }
    return g;
}

fn inv_mod(a: u64, m: u64)->u64 {
    let mut x:u64=1;
    let mut y:u64=0;
    if extgcd(a, m, &mut x, &mut y) == 1{
        // println!("{:?}", (a*x+y*m));
        (x + m) % m
    } else{
        0 // unsolvable
    }
}



