fn fact_table_mod(n:u64, m:u64)->Vec<u64>{
    let mut table = vec![1;(n+1) as usize];
    for i in 2..n+1{
        table[i as usize] = (table[(i-1) as usize]*i)%m;
    }
    return table
}

fn solver(n:u64, a:u64, b:u64, k:u64)->u64{
    let mut sum:u64 = 0;
    let m:u64 = 998244353;
    // let mut table: CombTable = CombTable{table: vec![vec![1]]};
    let table: Vec<u64> = fact_table_mod(n, m);
    for n_a in 0..min(n, k/a+1){
        if (k-n_a*a)%b==0 {
            let n_b = (k-n_a*a)/b;
            let mut c = 1;
            c *= (table[n as usize]*table[n as usize])%m;
            c *= (inv_mod(table[(n-n_a) as usize], m)*inv_mod(table[n_a as usize], m))%m;
            c %= m;
            c *= (inv_mod(table[(n-n_b) as usize], m)*inv_mod(table[n_b as usize], m))%m;
            c %= m;
            sum += c;
            sum %= m;
        }
    }
    return sum;
}

