    }

    input!{
      n: i64,
      a: i64,
      b: i64,
      k: i64,
    }

    const MOD: usize = 998244353;
    let fact = ModFactorial::new(n as _, MOD);
    let mut ans = 0;

    for i in 0..n+1 {
        let rem = k - a * i;

        if rem < 0 {
            continue;
        }

        if rem%b != 0 {
            continue;
        }
        let j = rem/b;
        if j > n {
            continue;
        }
        let temp = fact.combination(n as _, i as _) * fact.combination(n as _, j as _) % MOD;
        ans += temp;
        ans %= MOD;
    }
    puts!("{}\n", ans);
}

fn main() {
    let (n, a, b, k): (usize, usize, usize, usize) = readln();
