    let mut fact: Vec<Mint> = vec![1.into()];
    let mut inv_fact: Vec<Mint> = vec![1.into()];
    for i in 1..1000000 {
        let next = fact[fact.len()-1] * i;
        fact.push(next);
    }
    for i in 1..1000000 {
        let next = inv_fact[inv_fact.len()-1] / i;
        inv_fact.push(next);
    }
    for x in 0..n+1 {
        let rest = k as isize - (a * x) as isize;
        if rest >= 0 && (rest as usize) % b == 0 {
            let y = (rest as usize) / b;
            let ri = n as isize - (x + y) as isize;
            let lb = if ri >= 0 { 0 } else { -ri as usize };
            let ub = min(x, y);
            for z in lb..ub+1 {
                let r = (ri + z as isize) as usize;
                answer += fact[n] * inv_fact[x-z] * inv_fact[y-z] * inv_fact[z] * inv_fact[r];
            }
        }
    }
