fn combi(n: usize, m: usize, modulo: i64) -> i64 {
    if n < m || m < 0 {
        return 0;
    }

    let mut fac: Vec<i64> = vec![1; n+1];

    for i in 1..n+1 {
        fac[i] = (fac[i-1] * i as i64) as i64 % modulo;
    }

    let mut rfac = vec![1; n+1];
