fn count_tower(n:i64, n_a:i64, n_b:i64)->i64{
    let greater = max(n_a, n_b);
    let lesser = min(n_a, n_b);
    let mut sum:i64 = 0;
    for i in 0..lesser+1{
        let n1 = lesser-i;
        let n2 = greater-i;
        let n3 = i;
        let n4 = n-n1-n2-n3;
        let x = (((comb(n, n1)*comb(n-n1,n2)%998244353)*comb(n-n1-n2,n3)%998244353)*comb(n-n1-n2-n3,n4)%998244353);
        sum += x;
        // println!("p{} {}",x,i)
    }
    return sum;
}

