fn solve(n: u64, a: u64, b: u64, k: u64) ->  u64 {

    let r = 998244353;
    let mut ans = 0;

    for i in 0..n {

        if k < i*a {
            continue
        }

        if (k - (i*a)) % b > 0 {
            continue
        }

        let j = (k-(i*a)) / b;
        ans += (combi(n as usize ,i as usize) * combi(n as usize,j as usize)) % r;
        ans %= r;
    }

    ans as u64
}

