fn choose(n: u64, m: u64, fs: &[ModP]) -> ModP {
    fs[n as usize] / (fs[(n-m) as usize] * fs[m as usize])
}

fn calc(a: u64, b: u64, n: u64, fs: &[ModP]) -> ModP {
    choose(n, a, fs) * choose(n, b, fs)
}

