    let ans: ModP = (0..n+1).map(|i_a| {
        k.checked_sub(i_a * a).map_or(modp(0), |rest| {
            if rest % b != 0 {
                return modp(0);
            }
            let i_b = rest / b;
            if i_b > n { modp(0) } else { calc(i_a, i_b, n, &fs) }
        })
    }).sum();
    println!("{}", ans);
}

