const MOD: usize = 998244353;

fn main() {
    input!(n: usize, a: usize, b: usize, k: usize);

    let mut candidates = vec![];
    for x in 0..(n + 1) {
        if a * x > k {
            break;
        }
        let rest = k - a * x;
        if rest % b != 0 {
            continue;
        }
        let y = rest / b;
        if y > n {
            continue;
        }
        candidates.push((x, y));
    }

    let combination = Combination::new(n + 1, MOD);
    let mut ans = 0;
    for &(x, y) in candidates.iter() {
        let x = combination.get(n, x);
        let y = combination.get(n, y);
        ans = (ans + (x * y) % MOD) % MOD;
    }
    println!("{}", ans);
}

pub struct Combination {
    fact: Vec<usize>,
    inv_fact: Vec<usize>,
    modulo: usize,
}

impl Combination {
    pub fn new(max: usize, modulo: usize) -> Combination {
        let mut inv = vec![0; max + 1];
        let mut fact = vec![0; max + 1];
        let mut inv_fact = vec![0; max + 1];
        inv[1] = 1;
        for i in 2..(max + 1) {
            inv[i] = inv[modulo % i] * (modulo - modulo / i) % modulo;
        }
        fact[0] = 1;
        inv_fact[0] = 1;
        for i in 0..max {
            fact[i + 1] = fact[i] * (i + 1) % modulo;
        }
        for i in 0..max {
            inv_fact[i + 1] = inv_fact[i] * inv[i + 1] % modulo;
        }
        Combination {
            fact: fact,
            inv_fact: inv_fact,
            modulo: modulo,
        }
    }

    pub fn get(&self, x: usize, y: usize) -> usize {
        assert!(x >= y);
        self.fact[x] * self.inv_fact[y] % self.modulo * self.inv_fact[x - y] % self.modulo
    }
}

fn main() {
    let (n, mut a, mut b, k): (usize, usize, usize, usize) = readln();
    let mut answer: Mint = 0.into();
    let mut fact: Vec<Mint> = vec![1.into()];
    let mut inv_fact: Vec<Mint> = vec![1.into()];
    for i in 1..300010 {
        let next = fact[fact.len()-1] * i;
        fact.push(next);
    }
    for i in 1..300010 {
        let next = inv_fact[inv_fact.len()-1] / i;
        inv_fact.push(next);
    }
    if a < b {
        std::mem::swap(&mut b, &mut a);
    }
    for x in 0..n+1 {
        let rest = k as isize - (a * x) as isize;
        if rest < 0 {
            break;
        }
        if (rest as usize) % b == 0 {
            let y = (rest as usize) / b;
            let ri = n as isize - (x + y) as isize;
            let lb = if ri >= 0 { 0 } else { (-ri) as usize };
            let ub = min(x, y);
            for z in lb..ub+1 {
                let r = (ri + z as isize) as usize;
                let mut f: Mint = 1.into();
                f *= inv_fact[x-z];
                f *= inv_fact[y-z];
                f *= inv_fact[z];
                f *= inv_fact[r];
                answer += f;
            }
        }
    }
    println!("{}", answer * fact[n]);
}

