    let mut res = ModInt::new(0);
    let comb = Comb::new(n);
    for i in 0..n+1 {
        if i*a > k {
            break;
        }
        if (k-i*a)%b > 0 {
            continue;
        }
        let j = (k-i*a)/b;
        if i > n || j > n {
            continue;
        }
        let mn = max!(0, i as isize + j as isize - n as isize) as usize;
        for l in mn..min!(i,j)+1 {
            res += ModInt::new(comb.compute(n,i-l))
                * ModInt::new(comb.compute(n+l-i,j-l))
                * ModInt::new(comb.compute(n+2*l-i-j, l));
        }
    }
    println!("{}", res);
}

