const D: usize = 998244353;

fn gcd(x: usize,y: usize) -> usize {
    let mut a = cmp::max(x,y);
    let mut b = x + y - a;
    while a % b != 0 {
        let c = a % b;
        a = b;
        b = c;
    }
    b
}

fn fact_mod(n: usize) -> usize {
    (2..n+1).fold(1,|c,x| c * x % D)
}

fn pow_mod(n: usize,m: usize) -> usize {
    let mut ret = 1;
    if m % 2 == 1 {
        ret = ret * n % D;
    }
    if m > 0 {
        ret = pow_mod(n,m/2).pow(2) % D * ret % D;
    }
    ret
}

fn inv_mod(n: usize) -> usize {
    pow_mod(n,D-2)
}

fn combi_mod(n: usize, r: usize) -> usize {
    fact_mod(n) * inv_mod(fact_mod(n-r)) % D * inv_mod(fact_mod(r)) % D
}



