fn solver(n:i64, a:i64, b:i64, k:i64)->i64{
    let mut sum:i64 = 0;
    for n_a in 0..min(n, k/a+1){
        if (k-n_a*a)%b==0 {
            let n_b = (k-n_a*a)/b;
            // println!("{} {}", n_a, n_b);
            let c = count_tower(n, n_a, n_b);
            // println!("c{}", c);
            sum += c;
            sum %= 998244353;
        }
    }
    return sum;
}

fn comb(n:i64, r:i64)->i64{
    let nr=min(r,n-r);
    if nr==0{
        return 1;
    }
    let mut ans:i64=1;
    for i in 1..nr+1{
        ans*=n-i+1;
        ans/=i;
        ans%=998244353;
    }
    return ans%998244353;
}

fn count_tower(n:i64, n_a:i64, n_b:i64)->i64{
    return comb(n, n_a)%998244353*comb(n, n_b)%998244353;
}

