fn mod_pow(x: i64, n: i64, mod_: i64) -> i64 {
    if n > 0 {
        mod_pow(x * x % mod_, n >> 1, mod_) * if n & 1 == 1 { x } else { 1_i64 } % mod_
    } else {
        1_i64
    }
}

struct ModCulc {
    fact: Vec<i64>,
    fact_inv: Vec<i64>,
    mod_: i64,
}

impl ModCulc {
    fn new(n: usize, mod_: i64) -> Self {
        let mut f: Vec<i64> = vec![1; n];
        let mut f_i: Vec<i64> = vec![1; n];
        for i in 1..n {
            f[i] = (f[i - 1] * i as i64) % mod_;
            f_i[i] = mod_pow(f[i], mod_ - 2, mod_);
        }
        ModCulc {
            fact: f,
            fact_inv: f_i,
            mod_: mod_,
        }
    }

    fn nCr(&self, n: usize, r: usize) -> i64 {
        ((self.fact[n] * self.fact_inv[r]) % self.mod_ * self.fact_inv[n - r]) % self.mod_
    }
}

