    let mc = ModCulc::new(n + 1, mod_);

    let mut ans = 0;
    for i in 0..std::cmp::min(n, k / a) + 1 {
        let po = k - i * a;
        if po % b == 0 && po / b <= n {
            ans += (mc.nCr(n, i) * mc.nCr(n, po / b)) % mod_;
            ans %= mod_;
        }
    }
    println!("{}", ans);
}

