fn extgcd(a: i64, b: i64, x: &mut i64, y: &mut i64) -> i64 {
    let mut d = a;
    if b == 0 {
        *x = 1;
        *y = 0;
    } else {
        d = extgcd(b, a % b, y, x);
        *y -= (a / b) * (*x);
    }
    return d;
}

fn mod_inverse(a: i64, m: i64) -> i64 {
    let mut x: i64 = 0;
    let mut y: i64 = 0;
    extgcd(a, m, &mut x, &mut y);
    (m + x % m) % m
}

struct ModFactorial {
    fact: Vec<i64>
}

impl ModFactorial {
    fn new(n: i64, m: i64) -> ModFactorial {
        let mut fact = vec![1; n as usize + 1];
        for i in 2..fact.len() {
            fact[i] = (i as i64 * fact[i - 1]) % m;
        }
        ModFactorial { fact: fact }
    }
}

struct ModBinominal {
    bin: Vec<i64>
}

impl ModBinominal {
    fn new(n: i64, m: i64) -> ModBinominal {
        let mod_factorial = ModFactorial::new(n, m);
        let mut bin = vec![1; n as usize + 1];
        for i in 1..mod_factorial.fact.len() - 1 {
            let a2 = mod_factorial.fact[i] % m;
            let a3 = mod_factorial.fact[n as usize - i] % m;
            bin[i] = mod_factorial.fact[n as usize] * mod_inverse(a2 * a3 % m, m) % m;
        }
        ModBinominal { bin: bin }
    }
}

const big_int: i64 = 998244353;

fn main() {
    let v = read_vec::<i64>();
    let (n, a, b, k) = (v[0], v[1], v[2], v[3]);

    let comb = ModBinominal::new(n, big_int).bin;

    let mut ans = 0i64;

    let mut a_coef = 0i64;
    while a * a_coef <= k && a_coef <= n {
        let cur_a_sum = a * a_coef;
        if (k - cur_a_sum) % b == 0 {
            let b_coef = (k - cur_a_sum) / b;
            if b_coef > n {
                a_coef += 1;
                continue;
            }
            ans += comb[a_coef as usize] * comb[b_coef as usize];
            ans %= big_int;
        }
        a_coef += 1;
    }
    println!("{:?}", ans);
}
